Future<ProcessResult> defaultProcessRunner(
  String executable,
  List<String> arguments, {
  String? workingDirectory,
  Map<String, String>? environment,
}) {
  return Process.run(
    executable,
    arguments,
    workingDirectory: workingDirectory,
    environment: environment,
  );
}

Future<ProcessResult> runBoundedProcess(
  String executable,
  List<String> arguments, {
  String? workingDirectory,
  Map<String, String>? environment,
  required Duration timeout,
}) async {
  final process = await Process.start(
    executable,
    arguments,
    workingDirectory: workingDirectory,
    environment: environment,
    mode: ProcessStartMode.normal,
  );
  final stdoutFuture = process.stdout.transform(utf8.decoder).join();
  final stderrFuture = process.stderr.transform(utf8.decoder).join();
  try {
    final exitCode = await process.exitCode.timeout(timeout);
    return ProcessResult(
      process.pid,
      exitCode,
      await stdoutFuture,
      await stderrFuture,
    );
  } on TimeoutException {
    if (Platform.isWindows) {
      try {
        final killResult = await Process.run('taskkill.exe', [
          '/PID',
          '${process.pid}',
          '/T',
          '/F',
        ]).timeout(const Duration(seconds: 5));
        if (killResult.exitCode != 0) process.kill();
      } catch (_) {
        process.kill();
      }
    } else {
      process.kill(ProcessSignal.sigkill);
    }
    try {
      await process.exitCode.timeout(const Duration(seconds: 5));
      await Future.wait([
        stdoutFuture,
        stderrFuture,
      ]).timeout(const Duration(seconds: 5));
    } catch (_) {
      // The original timeout remains the user-facing failure.
    }
    rethrow;
  }
}

Future<ProcessResult> defaultLocalChatRunner(
  String executable,
  List<String> arguments, {
  String? workingDirectory,
  Map<String, String>? environment,
}) {
  return defaultProcessRunner(
    executable,
    arguments,
    workingDirectory: workingDirectory,
    environment: environment,
  );
}

String sanitizeEngelChatTextForWorker(String value) {
  final buffer = StringBuffer();
  for (var index = 0; index < value.length; index++) {
    final codeUnit = value.codeUnitAt(index);
    final allowedControl = codeUnit == 9 || codeUnit == 10 || codeUnit == 13;
    if (!allowedControl && codeUnit < 32) continue;
    if (codeUnit >= 0xD800 && codeUnit <= 0xDBFF) {
      if (index + 1 < value.length) {
        final next = value.codeUnitAt(index + 1);
        if (next >= 0xDC00 && next <= 0xDFFF) {
          buffer.writeCharCode(codeUnit);
          buffer.writeCharCode(next);
          index++;
          continue;
        }
      }
      buffer.write('\uFFFD');
      continue;
    }
    if (codeUnit >= 0xDC00 && codeUnit <= 0xDFFF) {
      buffer.write('\uFFFD');
      continue;
    }
    buffer.writeCharCode(codeUnit);
  }
  return buffer.toString();
}

String cleanEngelChatTextForWorker(String value) =>
    sanitizeEngelChatTextForWorker(value).trim();

/// Thrown into the awaiting chat turn when the operator presses Stop.
class EngelChatCancelled implements Exception {
  const EngelChatCancelled();
  @override
  String toString() => 'EngelChatCancelled';
}

class EngelLocalModelProcessService {
  Process? _process;
  Future<Process>? _starting;
  StreamSubscription<String>? _stdoutSubscription;
  StreamSubscription<String>? _stderrSubscription;
  DateTime? _workerScriptModified;
  var _sequence = 0;
  final _pending = <String, Completer<ProcessResult>>{};
  final _stderrTail = <String>[];
  String? _activeId;

  /// Called with each worker log line as it streams in, so the UI can show the
  /// live activity of a chat turn before the final reply lands.
  void Function(String line)? onActivity;

  /// Called with (id, token) for each streamed token chunk, so the UI can render
  /// the reply as it is generated (SSE end-to-end from the GPU through CT246).
  void Function(String id, String delta)? onDelta;

  /// Human working sentence from the worker heartbeat. Not a token and not a
  /// receipt dump — Josh should see that Engel is still on the job.
  void Function(String id, String statusText)? onProgress;

  /// True while a chat turn is in flight (used to gate the Stop button).
  bool get hasActiveRequest => _activeId != null;

  DateTime? _workerScriptModifiedStamp() {
    try {
      return File(longLivedLocalModelWorkerScriptPath).lastModifiedSync();
    } catch (_) {
      return null;
    }
  }

  Future<Process> _ensureStarted({
    required String executable,
    required Map<String, String> environment,
  }) async {
    final current = _process;
    final scriptModified = _workerScriptModifiedStamp();
    if (current != null) {
      final knownModified = _workerScriptModified;
      final workerFileChanged =
          _pending.isEmpty &&
          knownModified != null &&
          scriptModified != null &&
          scriptModified.isAfter(knownModified);
      if (workerFileChanged) {
        current.kill();
        _process = null;
        _workerScriptModified = null;
        _rememberStderrLine(
          'restarted stale Engel chat worker after worker script update',
        );
      } else {
        return current;
      }
    }
    final starting = _starting;
    if (starting != null) return starting;
    final future = Process.start(
      executable,
      const [longLivedLocalModelWorkerScriptPath],
      workingDirectory: appRoot,
      environment: {
        ...environment,
        'ENGEL_MAIN_LONG_LIVED_LOCAL_MODEL_SERVICE': '1',
      },
    );
    _starting = future;
    final process = await future;
    _process = process;
    _workerScriptModified = scriptModified ?? _workerScriptModifiedStamp();
    _starting = null;
    _stdoutSubscription = process.stdout
        .transform(utf8.decoder)
        .transform(const LineSplitter())
        .listen(_handleStdoutLine, onError: _handleStreamError);
    _stderrSubscription = process.stderr
        .transform(utf8.decoder)
        .transform(const LineSplitter())
        .listen(_rememberStderrLine, onError: _handleStreamError);
    unawaited(
      process.exitCode.then((code) {
        if (!identical(_process, process)) {
          // A superseded worker (killed after a script update; it had no
          // pending requests by the workerFileChanged guard) exiting must not
          // fail requests already running on its replacement.
          return;
        }
        _process = null;
        _workerScriptModified = null;
        final error = 'Engel local model worker exited with code $code';
        for (final completer in _pending.values) {
          if (!completer.isCompleted) {
            completer.completeError(StateError(error));
          }
        }
        _pending.clear();
      }),
    );
    return process;
  }

  void _handleStdoutLine(String line) {
    final trimmed = line.trim();
    if (trimmed.isEmpty) return;
    // (2026-07-07 audit Res-1) any worker output (a streamed token or progress
    // line) means the turn is alive — reset the idle watchdog so an actively
    // streaming or genuinely long reply is never hard-killed mid-token.
    _resetIdleWatchdog?.call();
    Map<String, dynamic> parsed;
    try {
      final decoded = jsonDecode(trimmed);
      if (decoded is! Map<String, dynamic>) {
        _rememberStderrLine('non-object worker stdout: $trimmed');
        return;
      }
      parsed = decoded;
    } catch (_) {
      _rememberStderrLine('non-json worker stdout: $trimmed');
      return;
    }
    final id = parsed['id']?.toString() ?? '';
    if (id == 'startup') {
      _rememberStderrLine(parsed['status']?.toString() ?? 'worker started');
      return;
    }
    // Streaming token chunk: {"id":..., "delta":"..."} with no receipt. Push it
    // to the UI and keep the request pending for the final {done, receipt} line.
    if (!parsed.containsKey('receipt') &&
        (parsed.containsKey('delta') || parsed.containsKey('status_text'))) {
      if (_pending.containsKey(id)) {
        final statusText = parsed['status_text']?.toString() ?? '';
        if (statusText.trim().isNotEmpty) {
          onProgress?.call(id, statusText.trim());
        }
        if (parsed.containsKey('delta')) {
          onDelta?.call(id, parsed['delta']?.toString() ?? '');
        }
      }
      return;
    }
    final completer = _pending.remove(id);
    if (completer == null || completer.isCompleted) return;
    final receipt = parsed['receipt'];
    // Kernel runs nest a rendered agent summary on the wrapper
    // (assistant_reply from render_agent_result). Completing with
    // receipt-only drops that text and leaves Tasks on the generic
    // "usable reply" dead-end while status/problems sit unused.
    final String stdoutPayload;
    if (receipt is Map<String, dynamic>) {
      final schema = receipt['schema']?.toString() ?? '';
      final keepWrapper =
          schema == 'engel_agent_kernel_run_v1' ||
          schema == 'engel_ui_agent_task_result_v1' ||
          parsed['engel_agent_kernel_used'] == true ||
          receipt['engel_agent_kernel_used'] == true;
      stdoutPayload = jsonEncode(keepWrapper ? parsed : receipt);
    } else {
      stdoutPayload = jsonEncode(parsed);
    }
    final ok =
        parsed['ok'] == true ||
        (receipt is Map<String, dynamic> && receipt['ok'] == true);
    completer.complete(
      ProcessResult(
        _process?.pid ?? 0,
        ok ? 0 : 1,
        stdoutPayload,
        _stderrTail.join('\n'),
      ),
    );
  }

  void _rememberStderrLine(String line) {
    final trimmed = line.trim();
    if (trimmed.isEmpty) return;
    _stderrTail.add(trimmed);
    if (_stderrTail.length > 120) {
      _stderrTail.removeRange(0, _stderrTail.length - 120);
    }
    onActivity?.call(trimmed);
  }

  void _handleStreamError(Object error) {
    _rememberStderrLine(error.toString());
  }

  // (2026-07-07 audit Res-1) reset hook for the per-turn idle watchdog; set in
  // runChat, invoked from _handleStdoutLine on every worker line.
  void Function()? _resetIdleWatchdog;

  Future<ProcessResult> runChat({
    required String executable,
    required String prompt,
    required String conversationId,
    required int timeoutSeconds,
    required int maxTokens,
    required Map<String, String> environment,
    List<Map<String, Object?>> attachments = const [],
    List<Map<String, Object?>> contextItems = const [],
    String provider = '',
    String model = '',
    String selectedModelId = '',
    String selectedModelName = '',
    String selectedCreationModelId = '',
    bool thinkingEnabled = true,
    String reasoningEffort = 'low',
    Map<String, Object?>? inboxMetadata,
  }) async {
    final process = await _ensureStarted(
      executable: executable,
      environment: environment,
    );
    final id = 'engel-main-chat-${++_sequence}';
    final completer = Completer<ProcessResult>();
    _pending[id] = completer;
    final payload = {
      'id': id,
      'command': 'chat',
      'prompt': prompt,
      'conversation_id': conversationId,
      'timeout': timeoutSeconds,
      'max_tokens': maxTokens,
      'temperature': 0.15,
      'stream': true,
      // Provider picker: an intentional dropdown choice rides the CT246
      // force contract; 'auto'/empty keeps the local-first default route.
      if (provider.isNotEmpty && provider != 'auto') ...{
        'provider': provider,
        'force_provider': true,
      },
      if (model.trim().isNotEmpty) 'model': model.trim(),
      if (selectedModelId.trim().isNotEmpty)
        'selected_model_id': selectedModelId.trim(),
      if (selectedModelName.trim().isNotEmpty)
        'selected_model_name': selectedModelName.trim(),
      if (selectedCreationModelId.trim().isNotEmpty)
        'selected_creation_model_id': selectedCreationModelId.trim(),
      'thinking_enabled': thinkingEnabled,
      'reasoning_effort': reasoningEffort,
      if (attachments.isNotEmpty) 'attachments': attachments,
      if (contextItems.isNotEmpty) 'context_items': contextItems,
      // Trusted local inbox metadata (training turns): the worker clamps it
      // through engel_governor before forwarding, and it may only ever narrow.
      if (inboxMetadata != null && inboxMetadata.isNotEmpty)
        'metadata': inboxMetadata,
    };
    process.stdin.writeln(jsonEncode(payload));
    _activeId = id;
    // (2026-07-07 audit Res-1) Idle watchdog instead of one fixed whole-turn
    // deadline: kill only if NOTHING arrives (no token, no worker line) for
    // `timeoutSeconds`. Every worker stdout line resets it (see _handleStdoutLine),
    // so an actively-streaming or long reply is never cut mid-token, while a hung
    // CT still surfaces within one idle window and lets the worker fail over.
    Timer? watchdog;
    void arm() {
      watchdog?.cancel();
      watchdog = Timer(Duration(seconds: timeoutSeconds), () {
        if (!completer.isCompleted) {
          _pending.remove(id);
          process.kill();
          _process = null;
          completer.completeError(
            TimeoutException(
              'Engel worker idle',
              Duration(seconds: timeoutSeconds),
            ),
          );
        }
      });
    }

    _resetIdleWatchdog = arm;
    arm();
    try {
      return await completer.future;
    } finally {
      watchdog?.cancel();
      _resetIdleWatchdog = null;
      if (_activeId == id) _activeId = null;
    }
  }

  /// Cancels the in-flight chat turn (if any). A local generation can't be
  /// interrupted mid-call, so the worker is killed and reset — the awaiting
  /// turn throws [EngelChatCancelled] and the worker is lazily restarted on the
  /// next chat. Returns false when there was nothing to cancel.
  bool cancelActive() {
    final id = _activeId;
    if (id == null) return false;
    _activeId = null;
    final completer = _pending.remove(id);
    final proc = _process;
    _process = null;
    _workerScriptModified = null;
    proc?.kill();
    if (completer != null && !completer.isCompleted) {
      completer.completeError(const EngelChatCancelled());
    }
    return true;
  }

  void dispose() {
    _stdoutSubscription?.cancel();
    _stderrSubscription?.cancel();
    for (final completer in _pending.values) {
      if (!completer.isCompleted) {
        completer.completeError(
          StateError('Engel local model worker disposed'),
        );
      }
    }
    _pending.clear();
    _process?.kill();
    _process = null;
  }
}

