String _engelVaultMemoryRootFromEnv() =>
    (Platform.environment['ENGEL_VAULT_MEMORY_ROOT'] ?? '').trim();

String _joinWindowsPath(String root, String child) {
  final cleanRoot = root.trim();
  if (cleanRoot.isEmpty) return child;
  final trimmedRoot = cleanRoot.replaceAll(RegExp(r'[\\/]+$'), '');
  final trimmedChild = child.replaceAll(RegExp(r'^[\\/]+'), '');
  return '$trimmedRoot\\$trimmedChild';
}

String _engelHomeRootForRuntime() {
  final vaultRoot = _engelVaultMemoryRootFromEnv();
  if (vaultRoot.isNotEmpty) return _joinWindowsPath(vaultRoot, 'engel-home');
  return '$appRoot\\runtime\\engel-home';
}

String _engelTempRootForRuntime() {
  final vaultRoot = _engelVaultMemoryRootFromEnv();
  if (vaultRoot.isNotEmpty) {
    return _joinWindowsPath(vaultRoot, r'temp\engel-rust-rewrite');
  }
  return engelTempRoot;
}

String _engelCargoHomeForRuntime() {
  final vaultRoot = _engelVaultMemoryRootFromEnv();
  if (vaultRoot.isNotEmpty) return _joinWindowsPath(vaultRoot, 'cargo-home');
  return engelCargoHome;
}

Map<String, String> _engelMainServerRuntimeEnvironment() {
  String valueOrDefault(String key, String fallback) {
    final value = (Platform.environment[key] ?? '').trim();
    return value.isNotEmpty ? value : fallback;
  }

  return {
