class EngelChatAttachment {
  const EngelChatAttachment({
    required this.id,
    required this.path,
    required this.name,
    required this.sizeBytes,
    required this.mimeType,
    required this.kind,
    required this.inlineBase64,
    required this.inlineTruncated,
    required this.textPreview,
    required this.textPreviewTruncated,
  });

  final String id;
  final String path;
  final String name;
  final int sizeBytes;
  final String mimeType;
  final String kind;
  final String inlineBase64;
  final bool inlineTruncated;
  final String textPreview;
  final bool textPreviewTruncated;

  bool get isStillImage {
    final mime = mimeType.toLowerCase();
    final kindValue = kind.toLowerCase();
    if (mime.contains('gif') || name.toLowerCase().endsWith('.gif')) {
      return false;
    }
    return mime.startsWith('image/') ||
        kindValue == 'image' ||
        kindValue == 'screenshot';
  }

  Map<String, Object?> toPayload() => {
    'schema': 'engel_chat_attachment_v1',
    'id': id,
    'path': path,
    'name': name,
    'size_bytes': sizeBytes,
    'mime_type': mimeType,
    'kind': kind,
    'inline_base64': inlineBase64,
    'inline_truncated': inlineTruncated,
    'text_preview': textPreview,
    'text_preview_truncated': textPreviewTruncated,
    'source': 'ROG Engel AI Main Chat UI',
  };
}

