String _chatAttachmentNameFromPath(String path) {
  final normalized = path.replaceAll('\\', '/');
  final slash = normalized.lastIndexOf('/');
  return slash >= 0 ? normalized.substring(slash + 1) : normalized;
}

String _chatAttachmentExtension(String path) {
  final name = _chatAttachmentNameFromPath(path).toLowerCase();
  final dot = name.lastIndexOf('.');
  if (dot < 0 || dot == name.length - 1) return '';
  return name.substring(dot + 1);
}

String _chatAttachmentMimeType(String path) {
  switch (_chatAttachmentExtension(path)) {
    case 'png':
      return 'image/png';
    case 'jpg':
    case 'jpeg':
      return 'image/jpeg';
    case 'gif':
      return 'image/gif';
    case 'webp':
      return 'image/webp';
    case 'bmp':
      return 'image/bmp';
    case 'svg':
      return 'image/svg+xml';
    case 'pdf':
      return 'application/pdf';
    case 'json':
      return 'application/json';
    case 'jsonl':
      return 'application/x-jsonlines';
    case 'csv':
      return 'text/csv';
    case 'md':
    case 'markdown':
      return 'text/markdown';
    case 'txt':
    case 'log':
    case 'ini':
    case 'yaml':
    case 'yml':
    case 'toml':
    case 'xml':
    case 'html':
    case 'css':
    case 'js':
    case 'jsx':
    case 'ts':
    case 'tsx':
    case 'py':
    case 'rs':
    case 'go':
    case 'java':
    case 'kt':
    case 'swift':
    case 'c':
    case 'cpp':
    case 'h':
    case 'hpp':
    case 'cs':
    case 'dart':
    case 'ps1':
    case 'sh':
    case 'bat':
    case 'cmd':
    case 'sql':
      return 'text/plain';
    case 'mp3':
      return 'audio/mpeg';
    case 'wav':
      return 'audio/wav';
    case 'mp4':
      return 'video/mp4';
    case 'mov':
      return 'video/quicktime';
    case 'zip':
      return 'application/zip';
    case '7z':
      return 'application/x-7z-compressed';
    case 'rar':
      return 'application/vnd.rar';
    default:
      return 'application/octet-stream';
  }
}

String _chatAttachmentKind(String mimeType, String path) {
  if (mimeType.startsWith('image/')) return 'image';
  if (mimeType.startsWith('audio/')) return 'audio';
  if (mimeType.startsWith('video/')) return 'video';
  if (mimeType.startsWith('text/') ||
      mimeType == 'application/json' ||
      mimeType == 'application/x-jsonlines') {
    return 'text';
  }
  final ext = _chatAttachmentExtension(path);
  if (const {'zip', '7z', 'rar', 'tar', 'gz'}.contains(ext)) return 'archive';
  return 'file';
}

String _chatAttachmentSizeLabel(int bytes) {
  if (bytes < 1024) return '$bytes B';
  final kb = bytes / 1024.0;
  if (kb < 1024) return '${kb.toStringAsFixed(kb < 10 ? 1 : 0)} KB';
  final mb = kb / 1024.0;
  if (mb < 1024) return '${mb.toStringAsFixed(mb < 10 ? 1 : 0)} MB';
  final gb = mb / 1024.0;
  return '${gb.toStringAsFixed(gb < 10 ? 1 : 0)} GB';
}

bool _chatAttachmentLooksText(String mimeType, String path) {
  if (mimeType.startsWith('text/') ||
      mimeType == 'application/json' ||
      mimeType == 'application/x-jsonlines') {
    return true;
  }
  return const {
    'md',
    'txt',
    'log',
    'json',
    'jsonl',
    'csv',
    'yaml',
    'yml',
    'toml',
    'xml',
    'html',
    'css',
    'js',
    'jsx',
    'ts',
    'tsx',
    'py',
    'rs',
    'go',
    'java',
    'kt',
    'swift',
    'c',
    'cpp',
    'h',
    'hpp',
    'cs',
    'dart',
    'ps1',
    'sh',
    'bat',
    'cmd',
    'sql',
  }.contains(_chatAttachmentExtension(path));
}

IconData _chatAttachmentIcon(String kind) {
  switch (kind) {
    case 'image':
      return Icons.image_outlined;
    case 'audio':
      return Icons.graphic_eq;
    case 'video':
      return Icons.movie_outlined;
    case 'text':
      return Icons.description_outlined;
    case 'archive':
      return Icons.archive_outlined;
    case 'folder':
      return Icons.folder_outlined;
    default:
      return Icons.insert_drive_file_outlined;
  }
}

