void main(List<String> args) {
  if (args.contains('--desk-manager')) {
    runApp(const EngelDeskManagerApp());
    return;
  }
  final enableStartupTasks =
      Platform.environment['ENGEL_MAIN_STARTUP_TASKS'] == '1';
  runApp(
    EngelMainApp(
      enableStartupTasks: enableStartupTasks,
      enableMeetingRoomStartup: true,
    ),
  );
}

