/// One minimal authenticated request that proves a saved credential really
/// works against the live provider. `{KEY}` is substituted with the secret in
/// the url, header values, and body.
class _LiveVerifySpec {
  const _LiveVerifySpec({
    required this.label,
    required this.url,
    this.method = 'GET',
    this.headers = const <String, String>{},
    this.body,
    this.okBodyContains,
  });

  final String label;
  final String url;
  final String method;
  final Map<String, String> headers;
  final String? body;
  final String? okBodyContains;
}

/// Live-connection checks keyed by `provider:<DisplayName>`,
/// `channel:<id>`, or `integration:<slug>`. Providers/services without a safe
/// stateless auth-check endpoint are intentionally absent (they stay local).
