_LiveVerifySpec? _engelLiveVerifySpecForProvider(String providerName) =>
    engelLiveVerifySpecs['provider:$providerName'];

_LiveVerifySpec? _engelLiveVerifySpecForConnector(String kind, String id) {
  if (kind == 'provider') {
    final provider = engelApiProviderBySlug(id);
    if (provider == null) return null;
    return engelLiveVerifySpecs['provider:${provider.name}'];
  }
  return engelLiveVerifySpecs['$kind:$id'];
}

