EngelApiProvider? engelApiProviderBySlug(String slug) {
  for (final p in engelApiKeyProviders) {
    if (p.slug == slug) return p;
  }
  return null;
}

EngelApiProvider? engelApiProviderByName(String name) {
  for (final p in engelApiKeyProviders) {
    if (p.name == name) return p;
  }
  return null;
}

