List<EngelIntegrationOption> _buildStandaloneIntegrations() {
  return _standaloneIntegrationRows
      .trim()
      .split('\n')
      .map((line) {
        final parts = line.split('|');
        final slug = parts.first.trim();
        final name = parts.length > 1 ? parts[1].trim() : slug;
        return EngelIntegrationOption(
          slug: slug,
          name: name,
          category: _integrationCategoryFor(slug),
        );
      })
      .toList(growable: false);
}

