  if (social.contains(slug)) return 'Social';
  if (productivity.contains(slug)) return 'Productivity';
  if (platform.contains(slug)) return 'Platform';
  return 'Tools & Automation';
}

class MeetingRoomServerInfo {
  const MeetingRoomServerInfo({
    required this.ok,
    required this.status,
    required this.url,
    required this.endpoints,
    required this.serverRoot,
    required this.error,
    this.visibleParticipantCount,
    this.participantStatusError = '',
  });

  final bool ok;
  final String status;
  final String url;
  final List<String> endpoints;
  final String serverRoot;
  final String error;
  final int? visibleParticipantCount;
  final String participantStatusError;
}

int? parseMeetingRoomVisibleParticipantCount(Object? raw) {
  if (raw is! Map) return null;
  final counts = raw['participant_counts'];
  final totalVisible = counts is Map ? counts['total_visible'] : null;
  if (totalVisible is num &&
      totalVisible.isFinite &&
      totalVisible >= 0 &&
      totalVisible == totalVisible.roundToDouble()) {
    return totalVisible.toInt();
  }
  final participants = raw['participants'];
  if (participants is! List) return null;
  return participants.where((participant) {
    if (participant is! Map) return false;
    return '${participant['status'] ?? ''}'.trim().toLowerCase() == 'live';
  }).length;
}

String meetingRoomReadinessLabel(MeetingRoomServerInfo info) {
  final status = info.status.trim().toLowerCase();
  if (!info.ok && status == 'not checked') return 'Checking Meeting Room';
  if (!info.ok && status == 'starting') return 'Connecting Meeting Room';
  if (!info.ok) return 'Meeting Room needs connection';
  final visible = info.visibleParticipantCount;
  if (visible == 0) return 'No workers connected';
  if (visible == 1) return '1 worker connected';
  if (visible != null) return '$visible workers connected';
  return 'Meeting Room available';
}

String meetingRoomReadinessDetail(MeetingRoomServerInfo info) {
  final status = info.status.trim().toLowerCase();
  if (!info.ok && status == 'not checked') {
    return 'You can keep drafting while Engel checks which workers are connected.';
  }
  if (!info.ok && status == 'starting') {
    return 'Engel is connecting Meeting Room. Your draft stays here.';
  }
  if (!info.ok) {
    return 'You can keep drafting. Connect Meeting Room before you send work.';
  }
  final visible = info.visibleParticipantCount;
  if (visible == 0) {
    return 'No workers are connected right now. Keep the draft and connect a worker before sending.';
  }
  if (visible != null) {
    final workerWord = visible == 1 ? 'worker' : 'workers';
    return 'Meeting Room can go to $visible connected $workerWord. Live device readiness is the Devices list.';
  }
  return 'Meeting Room is available. Live device readiness is the Devices list, not a second worker total here.';
}

String meetingRoomConfirmationTitle(MeetingRoomServerInfo info) {
  if (!info.ok) return 'Send this task before Meeting Room is confirmed?';
  final visible = info.visibleParticipantCount;
  if (visible == 0) return 'Send this task with no connected workers?';
  if (visible == 1) return 'Send this task to 1 connected worker?';
  if (visible != null) return 'Send this task to $visible connected workers?';
  return 'Send this task to connected Meeting Room workers?';
}

String meetingRoomConfirmationDetail(MeetingRoomServerInfo info) {
  if (!info.ok) {
    return 'Meeting Room could not confirm the current worker count. You can cancel and use Check Meeting Room on Tasks. Device readiness stays on Devices.';
  }
  final visible = info.visibleParticipantCount;
  if (visible == 0) {
    return 'Meeting Room currently sees 0 connected workers. Keep the draft until a worker is connected.';
  }
  if (visible != null) {
    final workerWord = visible == 1 ? 'worker' : 'workers';
    return 'Meeting Room currently sees $visible connected $workerWord. The task goes to those participants at send time.';
  }
  return 'The task goes to whatever Meeting Room participants are connected at send time. Live device readiness is the Devices list, not a second worker total on this page.';
}

enum EngelProofResultTone { passed, attention, unavailable }

@immutable
class EngelProofResultSummary {
  const EngelProofResultSummary({
    required this.title,
    required this.detail,
    required this.tone,
  });

  final String title;
  final String detail;
  final EngelProofResultTone tone;
}

EngelProofResultSummary? summarizeEngelProofOutput(String output) {
  final trimmed = output.trim();
  if (trimmed.isEmpty) return null;
  final normalized = trimmed.toLowerCase();
  final checkName = normalized.contains('runtime-readiness verify')
      ? 'The recommended Engel check'
      : normalized.contains('workspace-verifiers verify')
      ? 'The proof-file check'
      : normalized.contains('self-test')
      ? 'The command-routing test'
      : normalized.contains('engel.whole_system.audit')
      ? 'The audit-information read'
      : 'The system check';
  final exitMatch = RegExp(
    r'Exit:\s*(-?\d+)',
    caseSensitive: false,
  ).firstMatch(trimmed);
  final exitCode = exitMatch == null ? null : int.tryParse(exitMatch.group(1)!);
  if (exitCode == 0) {
    return EngelProofResultSummary(
      title: 'Check passed',
      detail: '$checkName completed successfully. Nothing was changed.',
      tone: EngelProofResultTone.passed,
    );
  }
  if (exitCode != null) {
    return EngelProofResultSummary(
      title: 'Check needs attention',
      detail:
          '$checkName completed and found a problem. Nothing was changed. Review the technical result below.',
      tone: EngelProofResultTone.attention,
    );
  }
  if (normalized.contains('timeout') ||
      normalized.contains('error:') ||
      normalized.contains('not found') ||
      normalized.startsWith('blocked:')) {
    return EngelProofResultSummary(
      title: 'Check could not finish',
      detail:
          '$checkName did not complete. Nothing was changed. Review the technical result below.',
      tone: EngelProofResultTone.unavailable,
    );
  }
  return null;
}

