    this.evidence = '',
    this.openPorts = '',
    this.wifiGroup = 'engel-main-wifi',
    this.classification = 'unclassified',
    this.hardware = '',
    this.networkLocation = '',
    this.physicalLocation = 'Unknown',
    this.locationConfidence = 'unknown',
    this.identityConfidence = 'unknown',
    this.lastSeenUtc = '',
    this.aliases = const [],
    this.canJoinCluster = false,
  });

  final String id;
  final String name;
  final String type;
  final String status;
  final String ip;
  final String role;
  final String source;
  final String detail;
  final double x;
  final double y;
  final double z;
  final double signal;
  final double load;
  final int workers;
  final bool trusted;
  final bool autoMode;
  final String macAddress;
  final String hostName;
  final String vendor;
  final String interfaceName;
  final String deviceSummary;
  final String evidence;
  final String openPorts;
  final String wifiGroup;
  final String classification;
  final String hardware;
  final String networkLocation;
  final String physicalLocation;
  final String locationConfidence;
  final String identityConfidence;
  final String lastSeenUtc;
  final List<String> aliases;
  final bool canJoinCluster;

  SwarmDeviceNode copyWith({
    String? id,
    String? name,
    String? type,
    String? status,
    String? ip,
    String? role,
    String? source,
    String? detail,
    double? x,
    double? y,
    double? z,
    double? signal,
    double? load,
    int? workers,
    bool? trusted,
    bool? autoMode,
    String? macAddress,
    String? hostName,
    String? vendor,
    String? interfaceName,
    String? deviceSummary,
    String? evidence,
    String? openPorts,
    String? wifiGroup,
    String? classification,
    String? hardware,
    String? networkLocation,
    String? physicalLocation,
    String? locationConfidence,
    String? identityConfidence,
    String? lastSeenUtc,
    List<String>? aliases,
    bool? canJoinCluster,
  }) {
    return SwarmDeviceNode(
      id: id ?? this.id,
      name: name ?? this.name,
      type: type ?? this.type,
      status: status ?? this.status,
      ip: ip ?? this.ip,
      role: role ?? this.role,
      source: source ?? this.source,
      detail: detail ?? this.detail,
      x: x ?? this.x,
      y: y ?? this.y,
      z: z ?? this.z,
      signal: signal ?? this.signal,
      load: load ?? this.load,
      workers: workers ?? this.workers,
      trusted: trusted ?? this.trusted,
      autoMode: autoMode ?? this.autoMode,
      macAddress: macAddress ?? this.macAddress,
      hostName: hostName ?? this.hostName,
      vendor: vendor ?? this.vendor,
      interfaceName: interfaceName ?? this.interfaceName,
      deviceSummary: deviceSummary ?? this.deviceSummary,
      evidence: evidence ?? this.evidence,
      openPorts: openPorts ?? this.openPorts,
      wifiGroup: wifiGroup ?? this.wifiGroup,
      classification: classification ?? this.classification,
      hardware: hardware ?? this.hardware,
      networkLocation: networkLocation ?? this.networkLocation,
      physicalLocation: physicalLocation ?? this.physicalLocation,
      locationConfidence: locationConfidence ?? this.locationConfidence,
      identityConfidence: identityConfidence ?? this.identityConfidence,
      lastSeenUtc: lastSeenUtc ?? this.lastSeenUtc,
      aliases: aliases ?? this.aliases,
      canJoinCluster: canJoinCluster ?? this.canJoinCluster,
    );
  }

  Map<String, Object?> toJson() {
    return {
      'id': id,
      'name': name,
      'type': type,
      'status': status,
      'ip': ip,
      'role': role,
      'source': source,
      'detail': detail,
      'position': {'x': x, 'y': y, 'z': z},
      'signal': signal,
      'load': load,
      'workers': workers,
      'trusted': trusted,
      'auto_mode': autoMode,
      'mac_address': macAddress,
      'host_name': hostName,
      'vendor': vendor,
      'interface_name': interfaceName,
      'device_summary': deviceSummary,
      'evidence': evidence,
      'open_ports': openPorts,
      'wifi_group': wifiGroup,
      'classification': classification,
      'hardware': hardware,
      'network_location': networkLocation,
      'physical_location': physicalLocation,
      'location_confidence': locationConfidence,
      'identity_confidence': identityConfidence,
      'last_seen_utc': lastSeenUtc,
      'aliases': aliases,
      'can_join_cluster': canJoinCluster,
    };
  }
}

