@immutable
class _EngelTextScaler implements TextScaler {
  const _EngelTextScaler({
    required this.base,
    required this.multiplier,
    required this.minScaleFactor,
    required this.maxScaleFactor,
  }) : assert(multiplier > 0),
       assert(minScaleFactor >= 0),
       assert(maxScaleFactor >= minScaleFactor);

  final TextScaler base;
  final double multiplier;
  final double minScaleFactor;
  final double maxScaleFactor;

  @override
  double scale(double fontSize) {
    if (fontSize == 0) return 0;
    return (base.scale(fontSize) * multiplier).clamp(
      minScaleFactor * fontSize,
      maxScaleFactor * fontSize,
    );
  }

  @override
  double get textScaleFactor => scale(1);

  @override
  TextScaler clamp({
    double minScaleFactor = 0,
    double maxScaleFactor = double.infinity,
  }) {
    final nextMinimum = math.max(this.minScaleFactor, minScaleFactor);
    final nextMaximum = math.min(this.maxScaleFactor, maxScaleFactor);
    if (nextMaximum <= nextMinimum) {
      return TextScaler.linear(nextMinimum);
    }
    if (nextMinimum == this.minScaleFactor &&
        nextMaximum == this.maxScaleFactor) {
      return this;
    }
    return _EngelTextScaler(
      base: base,
      multiplier: multiplier,
      minScaleFactor: nextMinimum,
      maxScaleFactor: nextMaximum,
    );
  }

  @override
  bool operator ==(Object other) =>
      other is _EngelTextScaler &&
      other.base == base &&
      other.multiplier == multiplier &&
      other.minScaleFactor == minScaleFactor &&
      other.maxScaleFactor == maxScaleFactor;

  @override
  int get hashCode =>
      Object.hash(base, multiplier, minScaleFactor, maxScaleFactor);
}

/// One roster model's last training result, normalized for display.
///
/// The real-training cycle receipt and the older ROG mirror describe the same
/// event with different field names. Normalizing in one place keeps the panel
/// from quietly preferring whichever shape happened to parse, which is how a
/// stale mirror could otherwise be shown as if it were today's run.
class EngelSlmRosterLine {
  const EngelSlmRosterLine({
    required this.task,
    required this.displayName,
    required this.purpose,
    required this.stage,
    required this.recorded,
