    required this.status,
    required this.macroF1,
    required this.baseline,
    required this.rows,
    required this.classCounts,
    required this.minPerClass,
    this.lift,
  });

  final String task;
  final String displayName;
  final String purpose;
  final String stage;
  final bool recorded;
  final bool ok;
  final String status;
  final double? macroF1;
  final double? baseline;
  final int? rows;
  final Map<String, int> classCounts;
  final int? minPerClass;

  /// Accuracy gained over the majority-class baseline -- the quantity the roster
  /// gate actually measures. macro-F1 answers a different question, so the two are
  /// reported separately rather than compared to each other.
  final double? lift;
}

