class _EngelMainShellState extends _EngelTrainingSection {
  static const _idleOutputMessage =
      'Engel AI Main chat ready. Type a message to talk with Engel.';

  var _selectedIndex = 0;
  @override
  var _running = false;
  @override
  var _chatRunning = false;
  @override
  var _status = 'ready';
  var _outputValue = _idleOutputMessage;
  final _outputByRoute = <String, String>{};
  final _outputUpdatedAtByRoute = <String, DateTime>{};
  final _routesWithResultsPanel = <String>{};
  String? _outputValueRouteId;
  String? _activeOutputRouteId;

  String get _output => _outputValue;

  @override
  set _output(String value) {
    _outputValue = value;
    final routeId = _running
        ? (_activeOutputRouteId ??= _visibleRouteId)
        : _visibleRouteId;
    if (!_running) _activeOutputRouteId = null;
    if (value == _idleOutputMessage) {
      _outputByRoute.remove(routeId);
      _outputUpdatedAtByRoute.remove(routeId);
      if (_outputValueRouteId == routeId) _outputValueRouteId = null;
      return;
    }
    _outputByRoute[routeId] = value;
    _outputUpdatedAtByRoute[routeId] = DateTime.now();
    _outputValueRouteId = routeId;
  }

  var _backgroundVisibility = 0.78;
  var _simpleNavigation = true;
  var _interfaceTextScale = 1.0;
  Future<void> _uiPreferencesSaveChain = Future<void>.value();
  var _compactNavigationOpen = false;

  /// The scale visible to Engel's adaptive layout decisions.
  ///
  /// The shell inserts its interface preference through a descendant
  /// [MediaQuery]. Methods on this State still hold the ancestor context, so
  /// reading MediaQuery directly from them sees only the Windows scale. Keep
  /// the layout value derived from the same scaler as the rendered text.
  double get _effectiveInterfaceTextScale => _EngelTextScaler(
    base: MediaQuery.textScalerOf(context),
    multiplier: _interfaceTextScale,
    minScaleFactor: _interfaceTextScale,
    maxScaleFactor: 3,
  ).scale(1);
  var _models = <ModelInfo>[];
  var _freeModels = <FreeModelInfo>[];
  var _localModelFiles = <LocalModelFileInfo>[];
  var _serverModelInventoryStatus = 'not loaded';
  var _externalModelOptions = <EngelModelOption>[];
