  @override
  void initState() {
    super.initState();
    final deviceVisibilityOverride = widget.deviceVisibilityOverride;
    if (deviceVisibilityOverride != null) {
      _deviceVisibility = deviceVisibilityOverride;
    }
    unawaited(_bootstrapTrainingUiState());
    unawaited(_loadModelConfiguration());
    unawaited(_loadNoteDraft(_selectedNoteTitle));
    unawaited(_loadWikiBrain());
    unawaited(_refreshLiftedIntentReceipt());
    unawaited(_refreshModelTrainingReceipts());
    if (widget.enableDeviceStatusScan) {
      unawaited(_scanDeviceVisibility());
    }
    if (widget.enableTrainingRunStatusPolling) {
      _trainingRunStatusTimer = Timer.periodic(
        const Duration(seconds: 3),
        (_) => unawaited(_refreshTrainingRunStatus()),
      );
    }
    unawaited(_refreshServerModelInventory());
    unawaited(_loadDeviceIdentityAudit());
    unawaited(_refreshMainServerHealth());
    _mainServerHealthTimer = Timer.periodic(
      const Duration(seconds: 30),
      (_) => unawaited(_refreshMainServerHealth()),
    );

    // Live graphics animation for swarm (pulsing discovered nodes, subtle motion, particle phase)
    // Drives high-fidelity visuals beyond static Canvas limits
    _swarmAnimTimer = Timer.periodic(const Duration(milliseconds: 33), (_) {
      if (mounted &&
          _selectedIndex == _sectionIndexById('device_visibility') &&
          _sectionTabs['device_visibility'] == 'device_swarm_3d' &&
          !MediaQuery.disableAnimationsOf(context)) {
        setState(() {
          _swarmAnimPhase += 0.035;
          // subtle auto-orbit for "alive" 3D feel when idle (Grok-level polish)
          _swarmYaw += 0.0008;
        });
      }
    });

    // Keep the operator-visible device swarm snapshot fresh in the background so
    // runtime\device_swarm\device_swarm_state.json reflects the live fleet even
    // when nobody opens the 3D view (it previously went stale for days). Quiet:
    // no status-line takeover. First run shortly after launch, then every 2 min.
    // Cancellable Timer (not Future.delayed) so widget tests can dispose cleanly.
    _swarmSnapshotKickoffTimer = Timer(const Duration(seconds: 12), () {
      if (mounted) unawaited(_refreshDeviceSwarmQuiet());
    });
    _swarmSnapshotTimer = Timer.periodic(const Duration(minutes: 2), (_) {
      if (mounted) unawaited(_refreshDeviceSwarmQuiet());
    });

    if (widget.enableMeetingRoomStartup) {
      unawaited(_ensureMeetingRoomServer());
    }
    if (widget.enableStartupTasks) {
      _scanModels();
      _scanFreeModels();
      _scanLocalModelFiles();
      _scanDrives();
      _scanArtifacts();
      _scanRustSource();
      _scanLaunchShortcuts();
      _scanSharedAction();
      _scanWDrivePolicyAudit();
      _scanSubEngelSentWork();
      _scanSubEngelSharedRoomQueues();
      _refreshEngelBridgeStatus();
      unawaited(_loadMeetingEventState());
      unawaited(_loadSelfUpgradeLoopState());
      unawaited(_runRust(rustCommands.first));
    }
    unawaited(_maybeStartChatUiSoakFromEnvironment());
    _startUiChatInboxWatcher();
  }

  List<EngelModelOption> get _modelCatalog {
    final merged = <String, EngelModelOption>{
      for (final option in engelModelCatalog) option.id: option,
    };
    for (final option in _externalModelOptions) {
      merged.putIfAbsent(option.id, () => option);
    }
    return merged.values.toList(growable: false);
  }

  double _unit(double value) => value.clamp(0.0, 1.0).toDouble();

  int? _boundedWholeNumber(
    Object? raw, {
    required int minimum,
    required int maximum,
  }) {
    if (raw is bool) return null;
    final value = raw is num ? raw.toDouble() : double.tryParse('$raw');
    if (value == null ||
        !value.isFinite ||
        value != value.roundToDouble() ||
        value < minimum ||
        value > maximum) {
      return null;
    }
    return value.toInt();
  }

  double _lerpUnit(double start, double end, double value) {
    final unit = _unit(value);
    return start + ((end - start) * unit);
  }

  double get _backgroundWashOpacity =>
      _lerpUnit(0.48, 0.14, _backgroundVisibility);

  double get _mainShellOpacity => _lerpUnit(0.52, 0.32, _backgroundVisibility);

  double get _sideConsoleOpacity =>
      _lerpUnit(0.48, 0.28, _backgroundVisibility);

  int get _backgroundVisibilityPercent =>
      (_unit(_backgroundVisibility) * 100).round();

  File? get _uiPreferencesFile {
    final path = widget.uiPreferencesPath.trim();
    return path.isEmpty ? null : File(path);
  }

  Future<void> _bootstrapTrainingUiState() async {
    await _scanTrainingManifest();
    if (!mounted) return;
    await _loadUiPreferencesThenTrainingStatus();
  }

  Future<void> _loadUiPreferencesThenTrainingStatus() async {
    await _loadUiPreferences();
    if (!mounted || !widget.enableTrainingRunStatusPolling) return;
    await _refreshTrainingRunStatus();
  }

  Future<void> _loadUiPreferences() async {
    final file = _uiPreferencesFile;
    if (file == null) return;
    if (!await file.exists()) return;
    try {
      final parsed = jsonDecode(await file.readAsString());
      if (parsed is! Map) return;
      final raw = parsed['background_visibility'];
      final value = raw is num ? raw.toDouble() : double.tryParse('$raw');
      final rawTextScale = parsed['interface_text_scale'];
      final textScale = rawTextScale is num
          ? rawTextScale.toDouble()
          : double.tryParse('$rawTextScale');
      final simpleNavigation = parsed['simple_navigation'];
      final trainingHours = _boundedWholeNumber(
        parsed['training_hours'],
        minimum: 1,
        maximum: 8,
      );
      final trainingLevel = '${parsed['training_level'] ?? ''}'
          .trim()
          .toLowerCase();
      final trainingLevelIndex = _EngelTrainingSection._trainingLevelLabels
          .map((label) => label.toLowerCase())
          .toList(growable: false)
          .indexOf(trainingLevel);
      final trainingsPerHour = _boundedWholeNumber(
        parsed['trainings_per_hour'],
        minimum: 1,
        maximum: 10,
      );
      final trainSlmTarget = parsed['train_slm_target'];
      final trainLlmTarget = parsed['train_llm_target'];
      final preferredCurriculumId = '${parsed['training_curriculum_id'] ?? ''}'
          .trim();
      if (!mounted) return;
      setState(() {
        if (value != null) _backgroundVisibility = _unit(value);
        if (textScale != null) {
          _interfaceTextScale = textScale.clamp(1.0, 2.0).toDouble();
        }
        if (simpleNavigation is bool) {
          _simpleNavigation = simpleNavigation;
        }
        if (trainingHours != null) _trainingHours = trainingHours;
        if (trainingLevelIndex >= 0) {
          _trainingLevelIndex = trainingLevelIndex;
        }
        if (trainingsPerHour != null) {
          _trainingsPerHour = trainingsPerHour;
        }
        if (trainSlmTarget is bool || trainLlmTarget is bool) {
          final nextSlm = trainSlmTarget is bool
              ? trainSlmTarget
              : _trainSlmTarget;
          final nextLlm = trainLlmTarget is bool
              ? trainLlmTarget
              : _trainLlmTarget;
          // Preferences may be hand-edited. Keep at least one real training lane.
          if (nextSlm || nextLlm) {
            _trainSlmTarget = nextSlm;
            _trainLlmTarget = nextLlm;
          }
        }
        _preferredCurriculumId = preferredCurriculumId;
        if (preferredCurriculumId.isNotEmpty &&
            _trainingCurricula.any(
              (curriculum) => '${curriculum['id']}' == preferredCurriculumId,
            )) {
          _selectedCurriculumId = preferredCurriculumId;
        }
        // Always re-clamp after prefs land. A saved 7-hour plan against a
        // 1-hour remaining curriculum must not reach Slider(value > max).
        if (_trainingCurricula.isNotEmpty) {
          _applySelectedCurriculumCounts();
        } else {
          _trainingHours = _trainingHours.clamp(1, 8);
        }
      });
    } catch (_) {
      // Keep the built-in visual default when the optional preference is invalid.
    }
  }

  @override
  Future<void> _saveUiPreferences() {
    final file = _uiPreferencesFile;
    if (file == null) return Future<void>.value();
    const encoder = JsonEncoder.withIndent('  ');
    final payload = {
      'schema': 'engel_main_ui_preferences_v3',
      'background_visibility': _unit(_backgroundVisibility),
      'simple_navigation': _simpleNavigation,
      'interface_text_scale': _interfaceTextScale,
      'training_hours': _trainingHours,
      'training_level': _trainingLevelSlug,
      'trainings_per_hour': _trainingsPerHour,
      'training_curriculum_id': _selectedCurriculumId,
      'train_slm_target': _trainSlmTarget,
      'train_llm_target': _trainLlmTarget,
      'background_file': engelDesktopBackgroundPath,
      'updated_at_utc': DateTime.now().toUtc().toIso8601String(),
    };
    // Slider releases and target toggles can arrive before the previous Windows
    // file handle closes. Serialize writes so a later choice cannot be lost to a
    // sharing violation or be overwritten by an older snapshot.
    _uiPreferencesSaveChain = _uiPreferencesSaveChain
        .catchError((Object _) {})
        .then<void>((_) async {
          await file.parent.create(recursive: true);
          await file.writeAsString('${encoder.convert(payload)}\n');
        });
    return _uiPreferencesSaveChain;
  }

  void _setBackgroundVisibility(double value, {bool save = false}) {
    setState(() => _backgroundVisibility = _unit(value));
    if (save) unawaited(_saveUiPreferences());
  }

  void _setSimpleNavigation(bool value) {
    setState(() => _simpleNavigation = value);
    unawaited(_saveUiPreferences());
  }

  void _setInterfaceTextScale(double value, {bool save = false}) {
    setState(() {
      _interfaceTextScale = value.clamp(1.0, 2.0).toDouble();
    });
    if (save) unawaited(_saveUiPreferences());
  }

  void _toggleCompactNavigation() {
    setState(() => _compactNavigationOpen = !_compactNavigationOpen);
  }

  void _closeCompactNavigation() {
    if (!_compactNavigationOpen) return;
    setState(() => _compactNavigationOpen = false);
  }

  void _selectFromCompactNavigation(String id) {
    _closeCompactNavigation();
    _selectSectionById(id);
  }

  Future<void> _loadModelConfiguration() async {
    await _loadExternalModelRegistry();
    await _loadModelRouterConfig();
  }

  @override
  void dispose() {
    _meetingText.dispose();
    _chatText.dispose();
    _homePromptText.dispose();
    _chatInputFocus.dispose();
    _chatScroll.dispose();
    _noteTitleText.dispose();
    _noteBodyText.dispose();
    _swarmAddNameText.dispose();
    _swarmAddIpText.dispose();
    _connectorSecretText.dispose();
    _grokImaginePromptText.dispose();
    for (final controller in _providerKeyTextControllers.values) {
      controller.dispose();
    }
    _swarmAnimTimer?.cancel();
    _swarmSnapshotTimer?.cancel();
    _swarmSnapshotKickoffTimer?.cancel();
    _mainServerHealthTimer?.cancel();
    _trainingRunStatusTimer?.cancel();
    _disposeModelTrainingCycleGuard();
    _chatHeartbeatTimer?.cancel();
    _chatUiSoakTimer?.cancel();
    _uiChatInboxTimer?.cancel();
    _localModelService.dispose();
    super.dispose();
  }

  EngelModelOption _modelOptionById(String id) {
    return _modelCatalog.firstWhere(
      (option) => option.id == id,
      orElse: () => engelModelCatalog.first,
    );
  }

  String _liveProviderForModel(String id, {required bool creation}) {
    final option = _modelOptionById(id);
    if (!option.liveRoute) return creation ? 'local' : 'auto';
    final provider = option.liveProvider.trim();
    if (provider == 'xai_grok_cli' || provider == 'xai-grok-cli') {
      return 'xai';
    }
    return provider;
  }

  String _apiModelForCatalogId(String id) {
    switch (id.trim()) {
      case 'grok-4.6':
      case 'grok-4-6':
      case 'grok-4-3-max':
      case 'grok-4-3-fast':
      case 'grok-4-3-reasoning':
      case 'grok-4-3-vision':
      case 'grok-build-0-1':
        return 'grok-4.6';
      case 'openai-api-gpt-5-5':
      case 'gpt-5-5-fast':
      case 'gpt-5-5-pro':
      case 'gpt-5-5-max':
      case 'gpt-5-5-reasoning':
      case 'gpt-5-5-vision':
      case 'chatgpt-browser':
        return 'gpt-5.5';
      case 'ct-qwen25-7b-instruct':
      case 'ct-qwen25-14b-instruct':
      case 'ct-qwen3-30b-a3b':
      case 'ct-nemotron-35-lightning-30b':
      case 'ct-qwen25-1p5b-deepreason':
      case 'local-cuda-qwen-coder':
        return id.trim();
      default:
        return '';
    }
  }

  /// Chat-tools dropdown is a one-shot override. Otherwise the applied chat
  /// picker is the standing lane. Auto Best stays `auto` so CT246 remains
  /// local-first. Creation picker does not bleed into chat.
  String get _effectiveChatProvider {
    final oneShot = _chatProviderChoice.trim();
    if (oneShot.isNotEmpty && oneShot != 'auto') {
      return oneShot;
    }
    final option = _modelOptionById(_activeModelId);
    if (!option.liveRoute || option.id == 'auto-best') {
      return 'auto';
    }
    final provider = _liveProviderForModel(option.id, creation: false);
    if (provider == 'chatgpt') return 'openai';
    if (provider == 'chatgpt_browser') return 'openai';
    if (provider == 'xai' ||
        provider == 'openai' ||
        provider == 'anthropic' ||
        provider == 'gemini' ||
        provider == 'codex') {
      return provider;
    }
    return 'auto';
  }

  String get _effectiveChatModel {
    return _apiModelForCatalogId(_activeModelId);
  }

  String get _activeModelName => _modelOptionById(_activeModelId).name;

  String get _creationModelName => _modelOptionById(_creationModelId).name;

  List<EngelModelOption> get _visibleModelCatalog => _modelCatalog
      .where((option) => _enabledModelIds.contains(option.id))
      .toList(growable: false);

  EngelModelOption? _modelOptionFromJson(Object? raw) {
    if (raw is! Map) return null;
    final map = raw.cast<String, dynamic>();
    final id = map['id']?.toString().trim();
    final name = map['name']?.toString().trim();
    final provider = map['provider']?.toString().trim();
    if (id == null || id.isEmpty || name == null || name.isEmpty) {
      return null;
    }
    return EngelModelOption(
      id: id,
      name: name,
      provider: provider?.isNotEmpty == true ? provider! : 'External',
      group: map['group']?.toString().trim().isNotEmpty == true
          ? map['group'].toString().trim()
          : 'EXTERNAL REGISTRY',
      bestFor: map['best_for']?.toString().trim().isNotEmpty == true
          ? map['best_for'].toString().trim()
          : 'User-added model lane from Engel external registry.',
      liveProvider: map['live_provider']?.toString().trim().isNotEmpty == true
          ? map['live_provider'].toString().trim()
          : 'external',
      liveRoute: map['live_route'] == true,
      defaultEnabled: map['default_enabled'] != false,
    );
  }

  Future<void> _loadExternalModelRegistry() async {
    final file = File(externalModelRegistryPath);
    if (!await file.exists()) return;
    try {
      final parsed = jsonDecode(await file.readAsString());
      final rawModels = parsed is Map<String, dynamic>
          ? parsed['models']
          : parsed is List
          ? parsed
          : null;
      if (rawModels is! List) {
        throw const FormatException('registry must contain a models list');
      }
      final options = <EngelModelOption>[];
      for (final raw in rawModels) {
        final option = _modelOptionFromJson(raw);
        if (option == null) continue;
        options.add(option);
      }
      if (!mounted) return;
      setState(() {
        _externalModelOptions = options;
        _enabledModelIds.addAll(
          options.where((option) => option.defaultEnabled).map((o) => o.id),
        );
        _modelRouterStatus =
            'external registry loaded: ${options.length} models';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _modelRouterStatus = 'external registry read error: $error';
        _output =
            'External model registry failed to load:\n$externalModelRegistryPath\n\n$error';
      });
    }
  }

  Future<void> _writeExternalModelRegistryTemplate() async {
    if (_running) return;
    final file = File(externalModelRegistryPath);
    await file.parent.create(recursive: true);
    if (await file.exists()) {
      await _loadExternalModelRegistry();
      if (!mounted) return;
      setState(() {
        _status = 'model registry already exists';
        _lastCommand = 'read file $externalModelRegistryPath';
        _output = [
          'External model registry already exists:',
          externalModelRegistryPath,
          '',
          'Loaded ${_externalModelOptions.length} external model options. Existing model lists are not overwritten.',
        ].join('\n');
      });
      return;
    }
    final payload = {
      'schema': 'engel_external_model_registry_v1',
      'purpose':
          'Add future model options here without editing Flutter source. Engel merges this file into the model picker.',
      'updated_at_utc': DateTime.now().toUtc().toIso8601String(),
      'source_refresh_notes': [
        'Use provider model-list APIs or official model pages to refresh IDs.',
        'Set live_route=false until the provider connector is verified.',
        'Use live_provider values already used by Engel: chatgpt, chatgpt_browser, openrouter, anthropic, gemini, xai_grok_cli, deepseek, dashscope, moonshot, zai, minimax, local, external.',
      ],
      'aliases': standaloneIntegrationSlugAliases,
      'models': [
        {
          'id': 'future-provider-model-example',
          'name': 'Future Provider Model Example',
          'provider': 'External',
          'group': 'EXTERNAL REGISTRY',
          'best_for': 'Replace this sample with a real provider model ID.',
          'live_provider': 'external',
          'live_route': false,
          'default_enabled': true,
        },
      ],
    };
    const encoder = JsonEncoder.withIndent('  ');
    await file.writeAsString('${encoder.convert(payload)}\n');
    await _loadExternalModelRegistry();
    if (!mounted) return;
    setState(() {
      _status = 'model registry template written';
      _lastCommand = 'write file $externalModelRegistryPath';
      _output = [
        'Wrote Engel external model registry template:',
        externalModelRegistryPath,
        '',
        'Add any future model entries to the models list. Engel Main merges this file into the model picker without a code rebuild.',
      ].join('\n');
    });
  }

  Future<void> _loadModelRouterConfig() async {
    final file = File(widget.modelRouterConfigPath);
    if (!await file.exists()) {
      if (!mounted) return;
      setState(() => _modelRouterStatus = 'Using built-in model choices.');
      return;
    }
    try {
      final parsed = jsonDecode(await file.readAsString());
      if (parsed is! Map<String, dynamic>) {
        throw const FormatException('config root is not an object');
      }
      final enabled = parsed['enabled_model_ids'];
      final enabledSet = enabled is List
          ? {
              for (final value in enabled)
                if (value.toString().trim().isNotEmpty) value.toString().trim(),
              'grok-4.6',
            }
          : _enabledModelIds;
      final active = parsed['selected_model_id']?.toString().trim();
      final creation = parsed['selected_creation_model_id']?.toString().trim();
      if (!mounted) return;
      setState(() {
        if (active != null &&
            _modelCatalog.any((option) => option.id == active)) {
          _activeModelId = active;
        }
        if (creation != null &&
            _modelCatalog.any((option) => option.id == creation)) {
          _creationModelId = creation;
        }
        _modelRouterMode =
            parsed['model_router_mode']?.toString().trim().isNotEmpty == true
            ? parsed['model_router_mode'].toString().trim()
            : _modelRouterMode;
        _thinkingEnabled = parsed['thinking_enabled'] is bool
            ? parsed['thinking_enabled'] as bool
            : _thinkingEnabled;
        _reasoningEffort =
            parsed['reasoning_effort']?.toString().trim().isNotEmpty == true
            ? parsed['reasoning_effort'].toString().trim()
            : (parsed['chatgpt_reasoning_effort']
                          ?.toString()
                          .trim()
                          .isNotEmpty ==
                      true
                  ? parsed['chatgpt_reasoning_effort'].toString().trim()
                  : _reasoningEffort);
        _enabledModelIds = enabledSet.isEmpty ? _enabledModelIds : enabledSet;
        _modelRouterStatus = 'Current model choices loaded.';
      });
    } catch (error) {
      if (!mounted) return;
      setState(
        () => _modelRouterStatus =
            'Could not load saved model choices. Built-in choices remain active.',
      );
    }
  }

  Future<void> _saveModelRouterConfig({
    String? activeModelId,
    String? creationModelId,
    bool? thinkingEnabled,
    String? reasoningEffort,
  }) async {
    if (_modelRouterSaving) return;
    final nextActiveModelId = activeModelId ?? _activeModelId;
    final nextCreationModelId = creationModelId ?? _creationModelId;
    final nextThinkingEnabled = thinkingEnabled ?? _thinkingEnabled;
    final nextReasoningEffort = reasoningEffort ?? _reasoningEffort;
    setState(() {
      _modelRouterSaving = true;
      _modelRouterStatus = 'Applying model choices...';
    });
    try {
      final file = File(widget.modelRouterConfigPath);
      final current =
          widget.modelRouterConfigWriter == null && await file.exists()
          ? jsonDecode(await file.readAsString())
          : <String, dynamic>{};
      final config = current is Map<String, dynamic>
          ? Map<String, dynamic>.from(current)
          : <String, dynamic>{};
      final active = _modelOptionById(nextActiveModelId);
      final creation = _modelOptionById(nextCreationModelId);
      final selectedChatProvider = _liveProviderForModel(
        nextActiveModelId,
        creation: false,
      );
      final selectedCreationProvider = _liveProviderForModel(
        nextCreationModelId,
        creation: true,
      );
      config
        ..['schema'] = 'engel_chat_provider_config_v1'
        ..['provider'] = 'auto'
        ..['model_router_mode'] = _modelRouterMode
        ..['thinking_enabled'] = nextThinkingEnabled
        ..['reasoning_effort'] = nextReasoningEffort
        ..['chatgpt_reasoning_effort'] = nextReasoningEffort
        ..['selected_model_id'] = active.id
        ..['selected_model_name'] = active.name
        ..['selected_chat_provider'] = selectedChatProvider
        ..['selected_creation_model_id'] = creation.id
        ..['selected_creation_model_name'] = creation.name
        ..['selected_creation_provider'] = selectedCreationProvider
        ..['enabled_model_ids'] = (_enabledModelIds.toList()..sort())
        ..['model_catalog_updated_by'] = 'Engel AI Main Mac UI'
        ..['model_catalog_updated_at_utc'] = DateTime.now()
            .toUtc()
            .toIso8601String()
        ..['model_catalog'] = [
          for (final option in _modelCatalog)
            {
              'id': option.id,
              'name': option.name,
              'provider': option.provider,
              'group': option.group,
              'best_for': option.bestFor,
              'live_provider': option.liveProvider,
              'live_route': option.liveRoute,
              'enabled': _enabledModelIds.contains(option.id),
            },
        ];
      if (selectedChatProvider == 'local') {
        config['chatgpt_browser_for_natural_chat'] = false;
        config['prefer_chatgpt_browser_over_api'] = false;
      } else if (selectedChatProvider == 'chatgpt_browser' ||
          nextActiveModelId == 'auto-best') {
        config['chatgpt_browser_for_natural_chat'] = true;
        config['prefer_chatgpt_browser_over_api'] = true;
      }
      config['local_for_code'] =
          selectedCreationProvider == 'local' ||
          nextCreationModelId == 'auto-best';
      const encoder = JsonEncoder.withIndent('  ');
      final encodedConfig = '${encoder.convert(config)}\n';
      if (widget.modelRouterConfigWriter case final writer?) {
        await writer(widget.modelRouterConfigPath, encodedConfig);
      } else {
        await file.parent.create(recursive: true);
        await file.writeAsString(encodedConfig);
      }
      if (!mounted) return;
      setState(() {
        _activeModelId = nextActiveModelId;
        _creationModelId = nextCreationModelId;
        _thinkingEnabled = nextThinkingEnabled;
        _reasoningEffort = nextReasoningEffort;
        _modelRouterStatus =
            'Applied: ${active.name} for chat and ${creation.name} for creation.';
        _output =
            'Saved Engel model router config.\nChat: ${active.name} -> $selectedChatProvider\nCreation: ${creation.name} -> $selectedCreationProvider\nPath: ${widget.modelRouterConfigPath}';
      });
      unawaited(
        _publishStandingChatBrain(
          modelId: active.id,
          modelName: active.name,
          provider: selectedChatProvider,
        ),
      );
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _modelRouterStatus =
            'Could not apply model choices. Your previous choices are still active.';
        _output = 'Model router save failed:\n$error';
      });
    } finally {
      if (mounted) {
        setState(() => _modelRouterSaving = false);
      }
    }
  }

  Future<void> _publishStandingChatBrain({
    required String modelId,
    required String modelName,
    required String provider,
  }) async {
    // Discord is the same Engel brain, just another room. Fail-open if CT246
    // is briefly down so a model save on this app still succeeds.
    try {
      final client = HttpClient()
        ..connectionTimeout = const Duration(seconds: 3);
      try {
        final request = await client.postUrl(
          Uri.parse(engelMainStandingBrainUrl),
        );
        request.headers.contentType = ContentType.json;
        request.write(
          jsonEncode({
            'selected_model_id': modelId,
            'selected_model_name': modelName,
            'selected_chat_provider': provider,
            'updated_by': 'engel_flutter_main',
          }),
        );
        final response = await request.close().timeout(
          const Duration(seconds: 8),
        );
        await response.drain<void>();
      } finally {
        client.close(force: true);
      }
    } catch (_) {}
  }

  Map<String, dynamic>? _asStringMap(Object? value) {
    if (value is Map) return value.cast<String, dynamic>();
    return null;
  }

  int _intFromJson(Object? value) {
    if (value is int) return value;
    if (value is num) return value.round();
    if (value is String) return int.tryParse(value.trim()) ?? 0;
    return 0;
  }

  int _gibFromJsonToBytes(Object? value) {
    if (value is num) return (value * 1024 * 1024 * 1024).round();
    if (value is String) {
      final parsed = double.tryParse(value.trim());
      if (parsed != null) return (parsed * 1024 * 1024 * 1024).round();
    }
    return 0;
  }

  String _filenameFromServerPath(String path) {
    final trimmed = path.trim();
    if (trimmed.isEmpty) return 'server-model';
    final parts = trimmed.split(RegExp(r'[\\/]')).where((p) => p.isNotEmpty);
    return parts.isEmpty ? trimmed : parts.last;
  }

  String _slugFromServerPath(String path) {
    final name = _filenameFromServerPath(path);
    return name
        .replaceAll(RegExp(r'\.gguf$', caseSensitive: false), '')
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'^_+|_+$'), '');
  }

  Future<Map<String, dynamic>?> _fetchEngelMainServerHealth() async {
    HttpClient? client;
    try {
      final uri = Uri.parse(engelMainServerChatHealthUrl);
      client = HttpClient()..connectionTimeout = const Duration(seconds: 2);
      final request = await client.getUrl(uri);
      final response = await request.close().timeout(
        const Duration(seconds: 5),
      );
      if (response.statusCode < 200 || response.statusCode >= 300) {
        return null;
      }
      final body = await response.transform(utf8.decoder).join();
      final parsed = jsonDecode(body);
      if (parsed is Map<String, dynamic> && parsed['ok'] == true) {
        return parsed;
      }
    } catch (_) {
      // The ROG app can still render from local D: state if the CT tunnel is down.
    } finally {
      client?.close(force: true);
    }
    return null;
  }

  void _retryMainServerHealth() {
    unawaited(_refreshMainServerHealth(showChecking: true, showResult: true));
  }

  Future<void> _showChatConnectionStatus() async {
    final checking = _mainServerOnline == null;
    final online = _mainServerOnline == true;
    final accent = checking
        ? const Color(0xffffc857)
        : online
        ? const Color(0xff00e87a)
        : const Color(0xffff7777);
    final title = checking
        ? 'Checking Chat'
        : online
        ? 'Chat is ready'
        : 'Chat is unavailable';
    final detail = checking
        ? 'Engel is checking the Chat connection. You can keep using files, notes, settings, and local tools.'
        : online
        ? 'Engel Chat answered the latest connection check. You can ask questions and start tasks.'
        : 'Engel Chat did not answer the latest check. Your files and local tools still work. Try again, or open Connection help for guided repair.';
    await showDialog<void>(
      context: context,
      builder: (dialogContext) {
        final closeButton = TextButton(
          key: const Key('chat-connection-status-close'),
          onPressed: () => Navigator.of(dialogContext).pop(),
          style: TextButton.styleFrom(minimumSize: const Size(0, 48)),
          child: const Text('Close'),
        );
        final helpButton = TextButton(
          key: const Key('chat-connection-status-help'),
          onPressed: () {
            Navigator.of(dialogContext).pop();
            _selectSectionById('connection_doctor');
          },
          style: TextButton.styleFrom(minimumSize: const Size(0, 48)),
          child: const Text('Connection help'),
        );
        final checkButton = FilledButton(
          key: const Key('chat-connection-status-check'),
          onPressed: checking
              ? null
              : () {
                  Navigator.of(dialogContext).pop();
                  _retryMainServerHealth();
                },
          style: FilledButton.styleFrom(minimumSize: const Size(0, 48)),
          child: Text(
            checking
                ? 'Checking…'
                : online
                ? 'Check again'
                : 'Try again',
          ),
        );
        return AlertDialog(
          key: const Key('chat-connection-status-dialog'),
          scrollable: true,
          constraints: BoxConstraints.tightFor(
            width: math.min(
              560,
              math.max(280, MediaQuery.sizeOf(dialogContext).width - 48),
            ),
          ),
          icon: Icon(
            checking
                ? Icons.sync_rounded
                : online
                ? Icons.check_circle_outline_rounded
                : Icons.cloud_off_outlined,
            color: accent,
            size: 30,
          ),
          title: Text(title, key: const Key('chat-connection-status-title')),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Semantics(
                container: true,
                liveRegion: true,
                label: '$title. $detail',
                child: Text(
                  detail,
                  key: const Key('chat-connection-status-detail'),
                  style: const TextStyle(height: 1.4),
                ),
              ),
              const SizedBox(height: 18),
              Wrap(
                alignment: WrapAlignment.end,
                spacing: 8,
                runSpacing: 8,
                children: [closeButton, helpButton, checkButton],
              ),
            ],
          ),
        );
      },
    );
  }

  Future<void> _refreshMainServerHealth({
    bool showChecking = false,
    bool showResult = false,
  }) async {
    if (_mainServerHealthProbeRunning) return;
    _mainServerHealthProbeRunning = true;
    if (showChecking && mounted && _mainServerOnline != null) {
      setState(() => _mainServerOnline = null);
    }
    var online = false;
    try {
      final injectedProbe = widget.serverHealthProbe;
      online = injectedProbe != null
          ? await injectedProbe()
          : await _fetchEngelMainServerHealth() != null;
    } catch (_) {
      online = false;
    } finally {
      _mainServerHealthProbeRunning = false;
    }
    if (!mounted) return;
    setState(() => _mainServerOnline = online);
    if (showResult) {
      _showConnectorSnack(
        online
            ? 'Engel chat is ready.'
            : 'Engel chat is still unavailable. Open Connection help for repair tools.',
        ok: online,
      );
    }
  }

  FreeModelInfo? _serverModelRootFromHealth(Map<String, dynamic>? health) {
    final modelRuntime = _asStringMap(health?['model_runtime']);
    final inventory = _asStringMap(modelRuntime?['active_model_inventory']);
    if (inventory == null || inventory['ok'] != true) return null;
    final bytes = _gibFromJsonToBytes(inventory['model_total_gib']);
    return FreeModelInfo(
      name: 'CT 246 active models',
      root: '/opt/engel/models-active',
      path:
          inventory['active_model_root']?.toString() ??
          '/opt/engel/models-active',
      fileCount: _intFromJson(inventory['model_file_count']),
      bytes: bytes,
    );
  }

  List<LocalModelFileInfo> _serverModelFilesFromHealth(
    Map<String, dynamic>? health,
  ) {
    final modelRuntime = _asStringMap(health?['model_runtime']);
    final largeChat = _asStringMap(modelRuntime?['large_chat_llm']);
    final now = DateTime.now();
    final rows = <LocalModelFileInfo>[];
    void addModel(String? path, int bytes) {
      final cleanPath = path?.trim() ?? '';
      if (cleanPath.isEmpty) return;
      if (rows.any((row) => row.path == cleanPath)) return;
      rows.add(
        LocalModelFileInfo(
          slug: _slugFromServerPath(cleanPath),
          path: cleanPath,
          root: cleanPath.startsWith('/opt/engel')
              ? '/opt/engel/models-active'
              : '/opt/engel',
          bytes: bytes,
          modified: now,
        ),
      );
    }

    addModel(
      largeChat?['selected_model_path']?.toString(),
      _intFromJson(largeChat?['selected_model_total_bytes']),
    );
    addModel(modelRuntime?['trained_lora_base_gguf_model_path']?.toString(), 0);
    addModel(modelRuntime?['trained_lora_adapter_gguf_path']?.toString(), 0);
    addModel(modelRuntime?['local_gguf_model_path']?.toString(), 0);
    return rows;
  }

  ModelInfo? _serverCosmosRootFromHealth(Map<String, dynamic>? health) {
    final modelRuntime = _asStringMap(health?['model_runtime']);
    final inventory = _asStringMap(modelRuntime?['active_model_inventory']);
    final verification = _asStringMap(inventory?['source_target_verification']);
    final cosmos = _asStringMap(verification?['cosmos3']);
    if (cosmos == null) return null;
    final matchedFiles = _intFromJson(cosmos['matched_files']);
    final matchedBytes = _intFromJson(cosmos['matched_bytes']);
    if (matchedFiles <= 0 && matchedBytes <= 0) return null;
    return ModelInfo(
      name: 'CT 246 Cosmos3 active set',
      path: '/opt/engel/models-active/hf/cosmos3',
      fileCount: matchedFiles,
      bytes: matchedBytes,
      modified: DateTime.now(),
      configs: const ['server-owned', 'engel-fast-ssd'],
    );
  }

  List<DriveInfo> _serverDriveRowsFromHealth(Map<String, dynamic>? health) {
    if (health == null || health['ok'] != true) return const [];
    final modelRuntime = _asStringMap(health['model_runtime']);
    final inventory = _asStringMap(modelRuntime?['active_model_inventory']);
    final runtimeStorage = _asStringMap(
      _asStringMap(health['virtual_environment'])?['runtime_storage'],
    );
    return [
      DriveInfo(
        label: 'CT fast SSD',
        path:
            runtimeStorage?['active_runtime_path']?.toString() ?? '/opt/engel',
        exists: true,
        topLevelCount: _intFromJson(inventory?['model_file_count']),
        directoryCount: 0,
        fileCount: _intFromJson(inventory?['model_file_count']),
        error: 'server storage: engel-fast-ssd',
      ),
      DriveInfo(
        label: 'PowerEdge HDD archive',
        path: '/mnt/engel-hdd-vault',
        exists: true,
        topLevelCount: 0,
        directoryCount: 0,
        fileCount: 0,
        error:
            runtimeStorage?['vault_policy']?.toString() ??
            'Dell PowerEdge HDD archive; CT245 offline-vault disabled',
      ),
    ];
  }

  Future<void> _refreshMeetingRoomServer() async {
    Future<Map<String, dynamic>> readJson(Uri uri) async {
      final client = HttpClient()
        ..connectionTimeout = const Duration(seconds: 2);
      try {
        final request = await client.getUrl(uri);
        final response = await request.close().timeout(
          const Duration(seconds: 4),
        );
        if (response.statusCode < 200 || response.statusCode >= 300) {
          throw HttpException(
            '${uri.path} HTTP ${response.statusCode}',
            uri: uri,
          );
        }
        final body = await response.transform(utf8.decoder).join();
        final parsed = jsonDecode(body);
        if (parsed is! Map<String, dynamic>) {
          throw FormatException('${uri.path} response is not an object');
        }
        return parsed;
      } finally {
        client.close(force: true);
      }
    }

    try {
      final parsed = await readJson(Uri.parse(meetingRoomServerHealthUrl));
      int? visibleParticipantCount;
      var participantStatusError = '';
      if (parsed['ok'] == true) {
        try {
          final participants = await readJson(
            Uri.parse(meetingRoomServerHealthUrl).resolve('/room/participants'),
          );
          visibleParticipantCount = parseMeetingRoomVisibleParticipantCount(
            participants,
          );
          if (visibleParticipantCount == null) {
            participantStatusError =
                'Participant response did not include a usable visible count.';
          }
        } catch (error) {
          participantStatusError = error.toString();
        }
      }
      final endpoints = parsed['endpoints'];
      if (!mounted) return;
      setState(() {
        _meetingRoomServer = MeetingRoomServerInfo(
          ok: parsed['ok'] == true,
          status: parsed['status']?.toString() ?? 'unknown',
          url: meetingRoomServerHealthUrl,
          endpoints: endpoints is List
              ? [for (final item in endpoints) item.toString()]
              : const [],
          serverRoot: parsed['server_root']?.toString() ?? '',
          error: '',
          visibleParticipantCount: visibleParticipantCount,
          participantStatusError: participantStatusError,
        );
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _meetingRoomServer = MeetingRoomServerInfo(
          ok: false,
          status: 'offline',
          url: meetingRoomServerHealthUrl,
          endpoints: const [],
          serverRoot: '',
          error: error.toString(),
        );
      });
    }
  }

  Future<bool> _meetingRoomServerHealthy() async {
    try {
      final uri = Uri.parse(meetingRoomServerHealthUrl);
      final client = HttpClient()
        ..connectionTimeout = const Duration(seconds: 2);
      final request = await client.getUrl(uri);
      final response = await request.close().timeout(
        const Duration(seconds: 4),
      );
      final body = await response.transform(utf8.decoder).join();
      client.close(force: true);
      if (response.statusCode < 200 || response.statusCode >= 300) {
        return false;
      }
      final parsed = jsonDecode(body);
      return parsed is Map<String, dynamic> &&
          (parsed['ok'] == true || parsed['status'] == 'running');
    } catch (_) {
      return false;
    }
  }

  Future<void> _ensureMeetingRoomServer() async {
    if (await _meetingRoomServerHealthy()) {
      await _refreshMeetingRoomServer();
      return;
    }
    if (mounted) {
      setState(() {
        _meetingRoomServer = const MeetingRoomServerInfo(
          ok: false,
          status: 'starting',
          url: meetingRoomServerHealthUrl,
          endpoints: [],
          serverRoot: '',
          error: '',
        );
      });
    }
    try {
      await Process.start(
        'powershell.exe',
        const [
          '-NoProfile',
          '-WindowStyle',
          'Hidden',
          '-ExecutionPolicy',
          'Bypass',
          '-File',
          meetingRoomServerStartScriptPath,
          '-HostAddress',
          '127.0.0.1',
          '-Port',
          '8790',
        ],
        workingDirectory: appRoot,
        mode: ProcessStartMode.detached,
      );
      await Future<void>.delayed(const Duration(seconds: 3));
    } catch (error) {
      if (mounted) {
        setState(() {
          _meetingRoomServer = MeetingRoomServerInfo(
            ok: false,
            status: 'start failed',
            url: meetingRoomServerHealthUrl,
            endpoints: const [],
            serverRoot: '',
            error: error.toString(),
          );
        });
      }
      return;
    }
    await _refreshMeetingRoomServer();
  }

  Future<void> _openAgentMeetingRoomOffice() async {
    setState(() {
      _status = 'starting server Agent Meeting Room';
      _output =
          'Opening the server-backed Agent Meeting Room...\nEntry point: http://127.0.0.1:3000/office?engelServerRoom=1\nBacked by: CT 246 engel-ai-main';
    });
    await _ensureMeetingRoomServer();
    try {
      await Process.start(
        'powershell.exe',
        const [
          '-NoProfile',
          '-WindowStyle',
          'Hidden',
          '-ExecutionPolicy',
          'Bypass',
          '-File',
          agentMeetingRoomOfficeLauncherPath,
          '-Port',
          '3000',
          '-ChatLocalPort',
          '24680',
          '-ServerRuntimePort',
          '8765',
        ],
        workingDirectory: appRoot,
        mode: ProcessStartMode.detached,
      );
      if (mounted) {
        setState(() {
          _status = 'server Agent Meeting Room opening';
          _output =
              'Server Agent Meeting Room is opening.\nOpen: http://127.0.0.1:3000/office?engelServerRoom=1\nBacked by: CT 246 engel-ai-main\nChat, agents, phones, and office runtime are routed through the server.';
        });
      }
    } catch (error) {
      if (mounted) {
        setState(() {
          _status = 'server Agent Meeting Room start failed';
          _output = 'Failed to open the server Agent Meeting Room.\n$error';
        });
      }
    }
  }

  bool? _connectionDoctorCheckOk(Map<String, dynamic> payload, String name) {
    final checks = payload['checks'];
    if (checks is! List) return null;
    for (final rawCheck in checks) {
      final check = _asStringMap(rawCheck);
      if (check?['name'] == name && check?['ok'] is bool) {
        return check!['ok'] as bool;
      }
    }
    return null;
  }

  bool? _connectionDoctorServiceOk(
    Map<String, dynamic> payload,
    String serviceName,
    String fallbackCheckName,
  ) {
    final services = _asStringMap(payload['services']);
    final service = _asStringMap(services?[serviceName]);
    if (service?['ok'] is bool) return service!['ok'] as bool;
    return _connectionDoctorCheckOk(payload, fallbackCheckName);
  }

  String _connectionDoctorServiceText(bool? online, {required bool busy}) {
    if (busy) return 'Checking…';
    if (online == true) return 'Ready';
    if (online == false) return 'Unavailable';
    return 'Not checked';
  }

  String get _connectionDoctorTitle => switch (_connectionDoctorPhase) {
    _ConnectionDoctorPhase.idle =>
      _mainServerOnline == false
          ? 'Connection needs attention'
          : 'Ready to check',
    _ConnectionDoctorPhase.checking => 'Checking connection…',
    _ConnectionDoctorPhase.repairing => 'Repairing connection…',
    _ConnectionDoctorPhase.ready || _ConnectionDoctorPhase.readyWithNotice =>
      'Chat and Meeting Room are connected',
    _ConnectionDoctorPhase.repaired => 'Connection repaired',
    _ConnectionDoctorPhase.partial =>
      _connectionDoctorChatOnline == true ||
              _connectionDoctorMeetingRoomOnline == true
          ? 'Part of Engel is connected'
          : 'Connection is unavailable',
    _ConnectionDoctorPhase.setupRequired => 'One-time setup is needed',
    _ConnectionDoctorPhase.serverUnavailable => 'Engel server is unavailable',
    _ConnectionDoctorPhase.repairFailed =>
      'Repair did not restore the connection',
    _ConnectionDoctorPhase.failure => 'Connection check could not finish',
  };

  String get _connectionDoctorAnnouncement {
    final parts = [
      _connectionDoctorTitle,
      _connectionDoctorSummary,
      if (_connectionDoctorActionMessage.isNotEmpty)
        _connectionDoctorActionMessage,
    ];
    return parts
        .map((part) {
          final trimmed = part.trim();
          final finalRune = trimmed.runes.isEmpty ? null : trimmed.runes.last;
          final alreadyPunctuated =
              finalRune == 0x2e ||
              finalRune == 0x21 ||
              finalRune == 0x3f ||
              finalRune == 0x2026;
          return alreadyPunctuated ? trimmed : '$trimmed.';
        })
        .join(' ');
  }

  String _cappedConnectionDoctorText(String text, {int limit = 12000}) {
    if (text.length <= limit) return text;
    return '${text.substring(0, limit)}\n\n'
        '[Raw output shortened to keep this screen responsive. Open reports for the complete receipt.]';
  }

  void _clearConnectionDoctorResultState() {
    _connectionDoctorChatOnline = null;
    _connectionDoctorMeetingRoomOnline = null;
    _connectionDoctorOfficeOnline = null;
    _connectionDoctorPassedChecks = 0;
    _connectionDoctorTotalChecks = 0;
    _connectionDoctorReceiptPath = '';
    _connectionDoctorActionMessage = '';
    _connectionDoctorActionError = false;
  }

  Future<void> _confirmConnectionDoctorRepair() async {
    if (_running) return;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        key: const Key('connection-doctor-repair-dialog'),
        title: const Text('Repair connection?'),
        content: const Text(
          'This starts EngelChatLinkSvc and the local SSH tunnel, then checks Chat and Meeting Room again. It will not start providers or training.',
        ),
        actions: [
          TextButton(
            key: const Key('connection-doctor-repair-cancel'),
            autofocus: true,
            onPressed: () => Navigator.of(dialogContext).pop(false),
            style: TextButton.styleFrom(minimumSize: const Size(96, 48)),
            child: const Text('Cancel'),
          ),
          FilledButton(
            key: const Key('connection-doctor-repair-confirm'),
            onPressed: () => Navigator.of(dialogContext).pop(true),
            style: FilledButton.styleFrom(minimumSize: const Size(0, 48)),
            child: const Text('Repair connection'),
          ),
        ],
      ),
    );
    if (confirmed == true && mounted) {
      await _runConnectionLoopDoctor(fix: true);
    }
  }

  Future<void> _runConnectionLoopDoctor({required bool fix}) async {
    if (_running) return;
    final launcher = File(connectionLoopDoctorLauncherPath);
    if (widget.processRunner == null && !await launcher.exists()) {
      if (!mounted) return;
      setState(() {
        _clearConnectionDoctorResultState();
        _connectionDoctorPhase = _ConnectionDoctorPhase.failure;
        _connectionDoctorSummary =
            'The connection tool is missing. No changes were made.';
        _connectionDoctorTechnicalDetails =
            'Expected launcher:\n$connectionLoopDoctorLauncherPath';
        _status = 'connection tool missing';
        _output = '$_connectionDoctorTitle\n$_connectionDoctorSummary';
      });
      return;
    }
    final args = [
      '-NoProfile',
      '-ExecutionPolicy',
      'Bypass',
      '-File',
      connectionLoopDoctorLauncherPath,
      '-Json',
      if (fix) '-Fix',
    ];
    final environment = {
      'ENGEL_APP_ROOT': appRoot,
      'TEMP': engelTempRoot,
      'TMP': engelTempRoot,
      'TMPDIR': engelTempRoot,
    };
    setState(() {
      _clearConnectionDoctorResultState();
      _running = true;
      _connectionDoctorPhase = fix
          ? _ConnectionDoctorPhase.repairing
          : _ConnectionDoctorPhase.checking;
      _connectionDoctorSummary = fix
          ? 'Engel is starting its connection task and local SSH tunnel, then checking Chat and Meeting Room again. This repair does not start providers or training.'
          : 'Engel is checking Chat and Meeting Room. No connection changes are being made.';
      _status = fix ? 'repairing connection' : 'checking connection';
      _lastCommand = 'powershell.exe ${args.join(' ')}';
      _connectionDoctorTechnicalDetails = fix
          ? 'Repair is in progress. Technical results will appear here when it finishes.'
          : 'The connection check is in progress. Technical results will appear here when it finishes.';
      _output = '$_connectionDoctorTitle\n$_connectionDoctorSummary';
    });
    final sw = Stopwatch()..start();
    try {
      final timeout = Duration(seconds: fix ? 120 : 45);
      final result = widget.processRunner == null
          ? await runBoundedProcess(
              'powershell.exe',
              args,
              workingDirectory: appRoot,
              environment: environment,
              timeout: timeout,
            )
          : await _processRunner(
              'powershell.exe',
              args,
              workingDirectory: appRoot,
              environment: environment,
            ).timeout(timeout);
      sw.stop();
      final rawStdout = result.stdout.toString();
      final stderrText = result.stderr.toString().trim();
      final parsed = _tryJson(rawStdout);
      final schema = parsed?['schema']?.toString() ?? '';
      final validSchema =
          schema == 'engel_connection_loop_doctor_v1' ||
          schema == 'engel_connection_loop_doctor_v2';
      final explicitOk = parsed?['ok'];
      if (parsed == null || !validSchema || explicitOk is! bool) {
        final reason = parsed == null
            ? 'The tool returned unreadable results.'
            : !validSchema
            ? 'The tool returned an unsupported result format.'
            : 'The tool did not report a clear pass or fail result.';
        setState(() {
          _clearConnectionDoctorResultState();
          _connectionDoctorPhase = _ConnectionDoctorPhase.failure;
          _connectionDoctorSummary = fix
              ? '$reason Repair did not continue. No provider or training was started.'
              : '$reason No connection changes were made.';
          _connectionDoctorTechnicalDetails = _cappedConnectionDoctorText(
            [
              'Action: ${fix ? 'Repair connection' : 'Check connection'}',
              'Exit code: ${result.exitCode}',
              'Elapsed: ${sw.elapsedMilliseconds} ms',
              'Schema: ${schema.isEmpty ? 'missing' : schema}',
              if (stderrText.isNotEmpty) 'Error output:\n$stderrText',
              if (rawStdout.trim().isNotEmpty)
                'Raw output:\n${rawStdout.trim()}',
            ].join('\n\n'),
          );
          _status = 'connection check could not finish';
          _output = '$_connectionDoctorTitle\n$_connectionDoctorSummary';
        });
        return;
      }

      final checks = parsed['checks'] is List
          ? parsed['checks'] as List
          : const <dynamic>[];
      final passedChecks = checks.where((rawCheck) {
        final check = _asStringMap(rawCheck);
        return check?['ok'] == true;
      }).length;
      final services = _asStringMap(parsed['services']);
      final chatOnline = _connectionDoctorServiceOk(
        parsed,
        'chat',
        'local_chat_health',
      );
      final meetingOnline = _connectionDoctorServiceOk(
        parsed,
        'meeting_room',
        'local_meeting_room_health',
      );
      final officeOnline = _connectionDoctorServiceOk(
        parsed,
        'office',
        'local_office_tcp',
      );
      final overallState = parsed['overall_state']?.toString() ?? '';
      final partial =
          overallState == 'partial' ||
          (chatOnline != null &&
              meetingOnline != null &&
              chatOnline != meetingOnline);
      final receiptPath = parsed['receipt_path']?.toString() ?? '';
      final statusText = parsed['status']?.toString() ?? 'No status supplied';
      final diagnosis =
          parsed['diagnosis']?.toString() ?? 'No diagnosis supplied';
      final repair = _asStringMap(parsed['repair']);
      final repairOutcome = repair?['outcome']?.toString() ?? '';
      final reportWrites = _asStringMap(
        parsed['report_writes'] ?? parsed['diagnostic_report_writes'],
      );
      final simplifiedChecks = [
        for (final rawCheck in checks)
          if (_asStringMap(rawCheck) case final check?)
            {
              'name': check['name'],
              'ok': check['ok'],
              'status': check['status'],
            },
      ];
      final technicalReceipt = {
        'schema': schema,
        'overall_state': overallState,
        'mode': parsed['mode'],
        'services': services,
        'repair': repair,
        'checks': simplifiedChecks,
        'actions': parsed['actions'],
        'diagnostic_report_writes': reportWrites,
        'storage_mutation_performed': parsed['storage_mutation_performed'],
        'storage_mutation_scope': parsed['storage_mutation_scope'],
        'ssd_only': parsed['ssd_only'],
        'vault_used': parsed['vault_used'],
        'secrets_read': parsed['secrets_read'],
        'receipt_path': receiptPath,
      };
      final technicalJson = const JsonEncoder.withIndent(
        '  ',
      ).convert(technicalReceipt);

      final phase = explicitOk
          ? overallState == 'partial'
                ? _ConnectionDoctorPhase.readyWithNotice
                : fix && repairOutcome == 'succeeded'
                ? _ConnectionDoctorPhase.repaired
                : _ConnectionDoctorPhase.ready
          : overallState == 'setup_required'
          ? _ConnectionDoctorPhase.setupRequired
          : overallState == 'server_unreachable'
          ? _ConnectionDoctorPhase.serverUnavailable
          : fix
          ? _ConnectionDoctorPhase.repairFailed
          : _ConnectionDoctorPhase.partial;
      final summary = switch (phase) {
        _ConnectionDoctorPhase.ready =>
          'Chat and Meeting Room are ready. No repair is needed.',
        _ConnectionDoctorPhase.readyWithNotice =>
          'Chat and Meeting Room are ready. Office preview is unavailable. No repair is needed.',
        _ConnectionDoctorPhase.repaired =>
          'Chat and Meeting Room are ready again.',
        _ConnectionDoctorPhase.partial when partial && chatOnline == true =>
          'Chat is ready, but Meeting Room is unavailable. No connection changes were made.',
        _ConnectionDoctorPhase.partial when partial && meetingOnline == true =>
          'Meeting Room is ready, but Chat is unavailable. No connection changes were made.',
        _ConnectionDoctorPhase.partial =>
          'Chat and Meeting Room are unavailable. No connection changes were made.',
        _ConnectionDoctorPhase.setupRequired =>
          'The secure server connection needs one-time setup before Chat and Meeting Room can connect. Open the advanced doctor for guided setup.',
        _ConnectionDoctorPhase.serverUnavailable =>
          'The Engel server cannot be reached right now. Open the advanced doctor for guided server checks; your local files and tools still work.',
        _ConnectionDoctorPhase.repairFailed when partial =>
          'Repair restored only part of the connection. No provider or training was started.',
        _ConnectionDoctorPhase.repairFailed =>
          'The connection is still unavailable. No provider or training was started.',
        _ => statusText,
      };
      setState(() {
        _connectionDoctorPhase = phase;
        _connectionDoctorSummary = summary;
        _connectionDoctorChatOnline = chatOnline;
        _connectionDoctorMeetingRoomOnline = meetingOnline;
        _connectionDoctorOfficeOnline = officeOnline;
        _connectionDoctorPassedChecks = passedChecks;
        _connectionDoctorTotalChecks = checks.length;
        _connectionDoctorReceiptPath = receiptPath;
        _connectionDoctorTechnicalDetails = _cappedConnectionDoctorText(
          [
            'Last action: ${fix ? 'Repair connection' : 'Check connection'}',
            'Exit code: ${result.exitCode}',
            'Elapsed: ${sw.elapsedMilliseconds} ms',
            'Status: $statusText',
            'Diagnosis: $diagnosis',
            'Checks passed: $passedChecks of ${checks.length}',
            if (receiptPath.isNotEmpty) 'Report: $receiptPath',
            '',
            'Receipt summary:',
            technicalJson,
            if (stderrText.isNotEmpty) '\nError output:\n$stderrText',
          ].join('\n'),
        );
        if (chatOnline != null) _mainServerOnline = chatOnline;
        _status = statusText;
        _output = [
          _connectionDoctorTitle,
          _connectionDoctorSummary,
          if (checks.isNotEmpty)
            '$passedChecks of ${checks.length} technical checks passed.',
          if (receiptPath.isNotEmpty) 'Report: $receiptPath',
        ].join('\n');
      });
    } on TimeoutException {
      sw.stop();
      if (!mounted) return;
      setState(() {
        _clearConnectionDoctorResultState();
        _connectionDoctorPhase = _ConnectionDoctorPhase.failure;
        _connectionDoctorSummary = fix
            ? 'Repair took too long and was stopped. No provider or training was started.'
            : 'The connection check took too long and was stopped. No connection changes were made.';
        _connectionDoctorTechnicalDetails =
            'Action: ${fix ? 'Repair connection' : 'Check connection'}\n'
            'Timeout: ${fix ? 120 : 45} seconds\n'
            'Command: $_lastCommand';
        _status = 'connection check timed out';
        _output = '$_connectionDoctorTitle\n$_connectionDoctorSummary';
      });
    } catch (error) {
      sw.stop();
      if (!mounted) return;
      setState(() {
        _clearConnectionDoctorResultState();
        _connectionDoctorPhase = _ConnectionDoctorPhase.failure;
        _connectionDoctorSummary = fix
            ? 'Repair could not finish. No provider or training was started.'
            : 'The connection check could not finish. No connection changes were made.';
        _connectionDoctorTechnicalDetails =
            'Action: ${fix ? 'Repair connection' : 'Check connection'}\n'
            'Elapsed: ${sw.elapsedMilliseconds} ms\n'
            'Error: $error';
        _status = 'connection check error';
        _output = '$_connectionDoctorTitle\n$_connectionDoctorSummary';
      });
    } finally {
      if (mounted) {
        setState(() {
          _running = false;
        });
      }
    }
  }

  Future<void> _openConnectionLoopDoctorGui() async {
    if (_running) return;
    final gui = File(connectionLoopDoctorGuiScriptPath);
    if (widget.processRunner == null && !await gui.exists()) {
      if (!mounted) return;
      setState(() {
        _connectionDoctorActionMessage =
            'The advanced doctor could not open because its launcher is missing. Technical details show the expected file.';
        _connectionDoctorActionError = true;
        _connectionDoctorTechnicalDetails =
            '${_connectionDoctorTechnicalDetails.trim()}\n\n'
            'Advanced doctor launcher expected at:\n$connectionLoopDoctorGuiScriptPath';
        _status = 'connection doctor app missing';
        _output =
            'Engel Connection Doctor App was not found.\nExpected $connectionLoopDoctorGuiScriptPath';
      });
      _showConnectorSnack('The advanced doctor could not open.', ok: false);
      return;
    }
    setState(() {
      _running = true;
      _connectionDoctorActionMessage = 'Opening the advanced doctor…';
      _connectionDoctorActionError = false;
      _status = 'opening connection doctor app';
    });
    try {
      const args = [
        '-NoProfile',
        '-ExecutionPolicy',
        'Bypass',
        '-File',
        connectionLoopDoctorLauncherPath,
        '-App',
      ];
      final result = widget.processRunner == null
          ? await runBoundedProcess(
              'powershell.exe',
              args,
              workingDirectory: appRoot,
              timeout: const Duration(seconds: 20),
            )
          : await _processRunner(
              'powershell.exe',
              args,
              workingDirectory: appRoot,
            ).timeout(const Duration(seconds: 20));
      if (result.exitCode != 0) {
        throw StateError(
          result.stderr.toString().trim().isEmpty
              ? 'Advanced doctor launcher exited ${result.exitCode}.'
              : result.stderr.toString().trim(),
        );
      }
      if (!mounted) return;
      setState(() {
        _connectionDoctorActionMessage =
            'The advanced doctor opened in a separate window.';
        _connectionDoctorActionError = false;
        _status = 'connection doctor app opened';
        _output =
            'Opened the advanced Engel Connection Doctor.\nUse Check connection, Repair connection, Real chat test, or Repair terminal.';
      });
      _showConnectorSnack('Advanced connection help opened.', ok: true);
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _connectionDoctorActionMessage =
            'The advanced doctor could not open. Technical details include the error.';
        _connectionDoctorActionError = true;
        _connectionDoctorTechnicalDetails =
            '${_connectionDoctorTechnicalDetails.trim()}\n\n'
            'Advanced doctor open error:\n$error';
        _status = 'connection doctor app open failed';
        _output = 'Failed to open Engel Connection Doctor App:\n$error';
      });
      _showConnectorSnack('The advanced doctor could not open.', ok: false);
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  Future<void> _buildWorkspaceSystemRegistry() async {
    if (_running) return;
    final pythonExe = File(runtimePythonExe).existsSync()
        ? runtimePythonExe
        : 'python';
    setState(() {
      _running = true;
      _status = 'building workspace registry';
      _lastCommand = '$pythonExe $workspaceSystemRegistryScriptPath';
      _output = 'Building Engel workspace system registry...\n$_lastCommand';
    });
    try {
      final sw = Stopwatch()..start();
      final result = await _processRunner(
        pythonExe,
        const [workspaceSystemRegistryScriptPath],
        workingDirectory: appRoot,
        environment: {'ENGEL_APP_ROOT': appRoot},
      ).timeout(const Duration(seconds: 90));
      sw.stop();
      final stdoutText = _pretty(result.stdout.toString());
      final stderrText = result.stderr.toString().trim();
      setState(() {
        _output = [
          'Command: $_lastCommand',
          'Exit: ${result.exitCode}',
          'Elapsed: ${sw.elapsedMilliseconds} ms',
          if (stdoutText.isNotEmpty) 'stdout:\n$stdoutText',
          if (stderrText.isNotEmpty) 'stderr:\n$stderrText',
          'Report: $workspaceSystemRegistryReportPath',
        ].join('\n\n');
        _status = result.exitCode == 0
            ? 'workspace registry saved'
            : 'registry failed';
      });
    } on TimeoutException {
      setState(() {
        _output = 'TIMEOUT after 90s\nCommand: $_lastCommand';
        _status = 'timeout';
      });
    } catch (error) {
      setState(() {
        _output = 'ERROR: $error\nCommand: $_lastCommand';
        _status = 'error';
      });
    } finally {
      if (mounted) {
        setState(() {
          _running = false;
        });
      }
    }
  }

  Future<void> _scanModels() async {
    setState(() {
      _modelsBusy = true;
      _status = 'scanning server models';
    });
    final health = await _fetchEngelMainServerHealth();
    final serverCosmos = _serverCosmosRootFromHealth(health);
    final root = Directory(cosmosRoot);
    final results = <ModelInfo>[?serverCosmos];
    if (await root.exists()) {
      final dirs = await root
          .list(followLinks: false)
          .where((entity) => entity is Directory)
          .cast<Directory>()
          .toList();
      dirs.sort((a, b) => a.path.compareTo(b.path));
      for (final dir in dirs) {
        var bytes = 0;
        var count = 0;
        DateTime? modified;
        final configs = <String>[];
        await for (final entity in dir.list(
          recursive: true,
          followLinks: false,
        )) {
          if (entity is! File) continue;
          count++;
          final stat = await entity.stat();
          bytes += stat.size;
          if (modified == null || stat.modified.isAfter(modified)) {
            modified = stat.modified;
          }
          final name = entity.uri.pathSegments.last;
          if (name.endsWith('.json') || name.endsWith('.md')) {
            if (configs.length < 8) configs.add(name);
          }
        }
        results.add(
          ModelInfo(
            name: dir.uri.pathSegments.where((s) => s.isNotEmpty).last,
            path: dir.path,
            fileCount: count,
            bytes: bytes,
            modified: modified,
            configs: configs,
          ),
        );
      }
    }
    if (!mounted) return;
    setState(() {
      _models = results;
      _modelsBusy = false;
      _status = 'ready';
    });
  }

  Future<void> _refreshServerModelInventory() async {
    final health = await _fetchEngelMainServerHealth();
    final serverCosmos = _serverCosmosRootFromHealth(health);
    final serverRoot = _serverModelRootFromHealth(health);
    final serverFiles = _serverModelFilesFromHealth(health);
    if (!mounted) return;
    setState(() {
      if (serverCosmos != null) {
        _models = [
          serverCosmos,
          ..._models.where((row) => !row.path.startsWith('/opt/engel/')),
        ];
      }
      if (serverRoot != null) {
        _freeModels = [
          serverRoot,
          ..._freeModels.where((row) => row.path != serverRoot.path),
        ];
      }
      if (serverFiles.isNotEmpty) {
        _localModelFiles = [
          ...serverFiles,
          ..._localModelFiles.where(
            (row) => !row.path.startsWith('/opt/engel/'),
          ),
        ];
      }
      _serverModelInventoryStatus = health == null
          ? 'server inventory unavailable'
          : 'server inventory loaded';
    });
  }

  Future<void> _scanFreeModels() async {
    final health = await _fetchEngelMainServerHealth();
    final roots = const ['$appRoot\\models'];
    final rows = <FreeModelInfo>[?_serverModelRootFromHealth(health)];
    for (final rootPath in roots) {
      final root = Directory(rootPath);
      if (!await root.exists()) continue;
      final dirs = await root
          .list(followLinks: false)
          .where((entity) => entity is Directory)
          .cast<Directory>()
          .toList();
      dirs.sort((a, b) => a.path.compareTo(b.path));
      for (final dir in dirs) {
        var bytes = 0;
        var files = 0;
        await for (final entity in dir.list(
          recursive: true,
          followLinks: false,
        )) {
          if (entity is! File) continue;
          files++;
          if (files > 2000) break;
          try {
            bytes += (await entity.stat()).size;
          } catch (_) {
            // Keep scanning even when a staging file is temporarily locked.
          }
        }
        rows.add(
          FreeModelInfo(
            name: dir.uri.pathSegments.where((s) => s.isNotEmpty).last,
            root: rootPath,
            path: dir.path,
            fileCount: files,
            bytes: bytes,
          ),
        );
      }
    }
    if (!mounted) return;
    setState(() => _freeModels = rows);
  }

  Future<void> _scanLocalModelFiles() async {
    final health = await _fetchEngelMainServerHealth();
    final roots = const ['$appRoot\\models'];
    final rows = <LocalModelFileInfo>[..._serverModelFilesFromHealth(health)];
    for (final rootPath in roots) {
      final root = Directory(rootPath);
      if (!await root.exists()) continue;
      await for (final entity in root.list(
        recursive: true,
        followLinks: false,
      )) {
        if (entity is! File) continue;
        if (!entity.path.toLowerCase().endsWith('.gguf')) continue;
        try {
          final stat = await entity.stat();
          final name = entity.uri.pathSegments.last;
          rows.add(
            LocalModelFileInfo(
              slug: name
                  .replaceAll(RegExp(r'\.gguf$', caseSensitive: false), '')
                  .toLowerCase()
                  .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
                  .replaceAll(RegExp(r'^_+|_+$'), ''),
              path: entity.path,
              root: rootPath,
              bytes: stat.size,
              modified: stat.modified,
            ),
          );
        } catch (_) {
          // Skip locked files; model inventory is best-effort read-only.
        }
      }
    }
    rows.sort((a, b) => b.bytes.compareTo(a.bytes));
    if (!mounted) return;
    setState(() => _localModelFiles = rows);
  }

  Future<void> _rescanAllModels() async {
    setState(() {
      _status = 'rescanning model roots';
      _output =
          'Scanning Cosmos3 folders, free/local model folders, and GGUF files.';
    });
    await Future.wait([
      _scanModels(),
      _scanFreeModels(),
      _scanLocalModelFiles(),
    ]);
    if (!mounted) return;
    setState(() {
      _status = 'model scan complete';
      _output = [
        'Model scan complete.',
        'Cosmos3 folders: ${_models.length}',
        'Free/local folders: ${_freeModels.length}',
        'GGUF files: ${_localModelFiles.length}',
      ].join('\n');
    });
  }

  Future<void> _scanDrives() async {
    setState(() {
      _drivesBusy = true;
      _status = 'scanning drives';
    });
    final health = await _fetchEngelMainServerHealth();
    final roots = const [
      ['ROG workspace', appRoot],
    ];
    final rows = <DriveInfo>[..._serverDriveRowsFromHealth(health)];
    for (final root in roots) {
      final dir = Directory(root[1]);
      try {
        final exists = await dir.exists();
        var count = 0;
        var directoryCount = 0;
        var fileCount = 0;
        if (exists) {
          await for (final entity in dir.list(followLinks: false)) {
            if (entity.path.isEmpty) continue;
            count++;
            if (entity is Directory) {
              directoryCount++;
            } else if (entity is File) {
              fileCount++;
            }
            if (count >= 500) break;
          }
        }
        rows.add(
          DriveInfo(
            label: root[0],
            path: root[1],
            exists: exists,
            topLevelCount: count,
            directoryCount: directoryCount,
            fileCount: fileCount,
            error: '',
          ),
        );
      } catch (error) {
        rows.add(
          DriveInfo(
            label: root[0],
            path: root[1],
            exists: false,
            topLevelCount: 0,
            directoryCount: 0,
            fileCount: 0,
            error: error.toString(),
          ),
        );
      }
    }
    if (!mounted) return;
    setState(() {
      _drives = rows;
      _drivesBusy = false;
      _status = 'ready';
    });
  }

  Future<void> _scanArtifacts() async {
    setState(() {
      _artifactsBusy = true;
      _status = 'scanning artifacts';
    });
    final roots = const [
      ['receipt', '$appRoot\\memory', '.md'],
      [
        'screenshot',
        '$appRoot\\reports\\gui_reverse_engineering_20260606',
        '.png',
      ],
      ['report', '$appRoot\\reports\\gui_reverse_engineering_20260606', '.txt'],
    ];
    final rows = <ArtifactInfo>[];
    final receiptNames = <String>{};
    var routeCoverageReceiptExists = false;
    int? routeCoverageRegisteredCommands;
    int? routeCoverageUnreferencedCommands;
    var memoryMarkdownTotal = 0;
    var engelReceiptTotal = 0;
    var guiScreenshotTotal = 0;
    var artifactReportTotal = 0;
    for (final root in roots) {
      final dir = Directory(root[1]);
      if (!await dir.exists()) continue;
      await for (final entity in dir.list(followLinks: false)) {
        if (entity is! File) continue;
        final name = entity.uri.pathSegments.last;
        if (!name.toLowerCase().endsWith(root[2])) continue;
        if (root[0] == 'receipt') {
          receiptNames.add(name);
          memoryMarkdownTotal++;
          if (name == routeCoverageReceiptName) {
            routeCoverageReceiptExists = true;
            try {
              final text = await entity.readAsString();
              final registered = RegExp(
                r'registered Rust commands[^0-9]*(\d+)',
                caseSensitive: false,
              ).firstMatch(text);
              final unreferenced = RegExp(
                r'unreferenced registered Rust commands[^0-9]*(\d+)',
                caseSensitive: false,
              ).firstMatch(text);
              routeCoverageRegisteredCommands = registered == null
                  ? null
                  : int.tryParse(registered.group(1)!);
              routeCoverageUnreferencedCommands = unreferenced == null
                  ? null
                  : int.tryParse(unreferenced.group(1)!);
            } catch (_) {
              routeCoverageRegisteredCommands = null;
              routeCoverageUnreferencedCommands = null;
            }
          }
          if (!name.startsWith('ENGEL')) continue;
          engelReceiptTotal++;
        } else if (root[0] == 'screenshot') {
          guiScreenshotTotal++;
        } else if (root[0] == 'report') {
          artifactReportTotal++;
        }
        try {
          final stat = await entity.stat();
          rows.add(
            ArtifactInfo(
              name: name,
              path: entity.path,
              kind: root[0],
              bytes: stat.size,
              modified: stat.modified,
            ),
          );
        } catch (_) {
          // Ignore files that are being written while Engel is scanning.
        }
      }
    }
    rows.sort((a, b) => b.modified.compareTo(a.modified));
    if (!mounted) return;
    setState(() {
      _artifacts = rows.take(120).toList();
      _memoryMarkdownTotal = memoryMarkdownTotal;
      _engelReceiptTotal = engelReceiptTotal;
      _guiScreenshotTotal = guiScreenshotTotal;
      _artifactReportTotal = artifactReportTotal;
      _receiptNames = receiptNames;
      _routeCoverageReceiptExists = routeCoverageReceiptExists;
      _routeCoverageRegisteredCommands = routeCoverageRegisteredCommands;
      _routeCoverageUnreferencedCommands = routeCoverageUnreferencedCommands;
      _artifactsBusy = false;
      _status = 'ready';
    });
  }

  Future<void> _scanRustSource() async {
    final src = Directory('$rustCoreRoot\\src');
    var sourceFiles = 0;
    var sourceBytes = 0;
    final modules = <FileSystemEntity>[];
    if (await src.exists()) {
      await for (final entity in src.list(followLinks: false)) {
        if (entity is! File || !entity.path.toLowerCase().endsWith('.rs')) {
          continue;
        }
        sourceFiles++;
        final stat = await entity.stat();
        sourceBytes += stat.size;
        modules.add(entity);
      }
    }
    modules.sort((a, b) {
      final aSize = a.statSync().size;
      final bSize = b.statSync().size;
      return bSize.compareTo(aSize);
    });
    DateTime? cargoModified;
    final cargo = File('$rustCoreRoot\\Cargo.toml');
    if (await cargo.exists()) {
      cargoModified = (await cargo.stat()).modified;
    }
    if (!mounted) return;
    setState(() {
      _rustSource = RustSourceInfo(
        sourceFiles: sourceFiles,
        sourceBytes: sourceBytes,
        modules: modules
            .take(10)
            .map((entity) => entity.uri.pathSegments.last)
            .toList(),
        cargoModified: cargoModified,
      );
    });
  }

  Future<void> _scanLaunchShortcuts() async {
    setState(() => _launchShortcutsBusy = true);
    final script =
        r'''
$ErrorActionPreference='Continue'
$desktop = [Environment]::GetFolderPath('Desktop')
$canonical = '__ENGEL_APP_ROOT__\\engel_flutter_main\\build\\windows\\x64\\runner\\Release\\EngelAIMain.exe'
$stagedDist = '__ENGEL_APP_ROOT__\\dist\\EngelAI-Main-Flutter\\EngelAIMain.exe'
$shell = New-Object -ComObject WScript.Shell
Get-ChildItem $desktop -Filter '*Engel*.lnk' -ErrorAction SilentlyContinue | ForEach-Object {
  $target = ''
  $working = ''
  $err = ''
  try {
    $shortcut = $shell.CreateShortcut($_.FullName)
    $target = $shortcut.TargetPath
    $working = $shortcut.WorkingDirectory
  } catch {
    $err = $_.Exception.Message
  }
  [pscustomobject]@{
    name = $_.Name
    path = $_.FullName
    target = $target
    working_directory = $working
    matches_canonical = ($target -ieq $canonical)
    matches_staged_dist = ($target -ieq $stagedDist)
    error = $err
  }
} | ConvertTo-Json -Compress
'''
            .replaceAll('__ENGEL_APP_ROOT__', appRoot.replaceAll("'", "''"));
    final rows = <ShortcutInfo>[];
    try {
      final result = await _processRunner('powershell', [
        '-NoProfile',
        '-ExecutionPolicy',
        'Bypass',
        '-Command',
        script,
      ]);
      final text = result.stdout.toString().trim();
      if (text.isNotEmpty) {
        final decoded = jsonDecode(text);
        final items = decoded is List ? decoded : [decoded];
        for (final item in items) {
          if (item is! Map<String, dynamic>) continue;
          final target = (item['target'] ?? '').toString();
          rows.add(
            ShortcutInfo(
              name: (item['name'] ?? '').toString(),
              path: (item['path'] ?? '').toString(),
              target: target,
              workingDirectory: (item['working_directory'] ?? '').toString(),
              matchesCanonical:
                  (item['matches_canonical'] ?? false) == true ||
                  (item['matches_staged_dist'] ?? false) == true ||
                  target.toLowerCase() == flutterEngelMainExe.toLowerCase() ||
                  target.toLowerCase() == stagedDistEngelMainExe.toLowerCase(),
              error: (item['error'] ?? '').toString(),
            ),
          );
        }
      }
    } catch (error) {
      rows.add(
        ShortcutInfo(
          name: 'shortcut scan',
          path: '',
          target: '',
          workingDirectory: '',
          matchesCanonical: false,
          error: error.toString(),
        ),
      );
    }
    rows.sort((a, b) => a.name.compareTo(b.name));
    if (!mounted) return;
    setState(() {
      _launchShortcuts = rows;
      _launchShortcutsBusy = false;
    });
  }

  Future<void> _scanSharedAction() async {
    final file = File(sharedActionPath);
    if (!await file.exists()) {
      if (!mounted) return;
      setState(() {
        _sharedAction = const SharedActionInfo(
          exists: false,
          path: sharedActionPath,
          status: 'missing',
          blocker: 'Shared action file not mounted from H drive.',
          nextStep: 'Mount G:\\My Drive and rescan.',
          errorProgression: 'No action file loaded.',
          requiredFix: 'Mount G:\\My Drive and rescan.',
          verifyCommand:
              r'net use W: \\LAPTOP-0KUVK82E\EngelWorkspace "" /user:Guest /persistent:yes',
          authenticatedRoute: 'No authenticated-route note loaded yet.',
          appendWarning: '',
          busProof: '',
          busLineCount: 0,
          liveDocLineCount: 0,
          modified: null,
        );
      });
      return;
    }
    final text = await file.readAsString();
    final stat = await file.stat();
    String lineContaining(String pattern) {
      return text
          .split(RegExp(r'\r?\n'))
          .firstWhere(
            (line) => line.toLowerCase().contains(pattern.toLowerCase()),
            orElse: () => '',
          )
          .trim();
    }

    var busProof = '';
    var busLineCount = 0;
    final bus = File(sharedRoomBusPath);
    if (await bus.exists()) {
      final lines = await bus.readAsLines();
      busLineCount = lines.where((line) => line.trim().isNotEmpty).length;
      for (final line in lines) {
        try {
          final decoded = jsonDecode(line);
          if (decoded is! Map<String, dynamic>) continue;
          final message = (decoded['message'] ?? '').toString();
          final channel = (decoded['channel'] ?? '').toString();
          if (!channel.toUpperCase().contains('RESULT')) continue;
          final lower = message.toLowerCase();
          final isWProof =
              lower.contains('w: connected') ||
              lower.contains('callback complete') ||
              lower.contains('1385 blocker fixed') ||
              lower.contains('markdown memory tree install complete');
          if (isWProof) {
            final sender = (decoded['sender'] ?? 'shared room').toString();
            final stamp = (decoded['timestamp_utc'] ?? '').toString();
            busProof = '$stamp $sender: $message';
          }
        } catch (_) {
          continue;
        }
      }
    }
    var liveDocLineCount = 0;
    final liveDoc = File(sharedRoomLivePath);
    if (await liveDoc.exists()) {
      final lines = await liveDoc.readAsLines();
      liveDocLineCount = lines.where((line) => line.trim().isNotEmpty).length;
    }

    if (!mounted) return;
    setState(() {
      _sharedAction = SharedActionInfo(
        exists: true,
        path: sharedActionPath,
        status: lineContaining('Status:').isEmpty
            ? 'loaded'
            : lineContaining('Status:'),
        blocker: lineContaining('1385 means').isEmpty
            ? lineContaining('remaining blocker')
            : lineContaining('1385 means'),
        nextStep: lineContaining('Guest network-logon right granted').isEmpty
            ? 'Main must grant Guest network logon or switch to an authenticated account route.'
            : lineContaining('Guest network-logon right granted'),
        errorProgression: lineContaining('Error progression so far').isEmpty
            ? 'Error progression not found in shared action file.'
            : lineContaining('Error progression so far'),
        requiredFix:
            lineContaining('Access this computer from the network').isEmpty
            ? 'Required fix: grant Guest network logon allow right and remove Guest from deny right.'
            : lineContaining('Access this computer from the network'),
        verifyCommand: lineContaining('net use W:').isEmpty
            ? r'net use W: \\LAPTOP-0KUVK82E\EngelWorkspace "" /user:Guest /persistent:yes'
            : lineContaining('net use W:'),
        authenticatedRoute: lineContaining('Authenticated route').isEmpty
            ? 'Authenticated route note not found in shared action file.'
            : lineContaining('Authenticated route'),
        appendWarning: lineContaining('append instead').isEmpty
            ? lineContaining('overwriting')
            : lineContaining('append instead'),
        busProof: busProof,
        busLineCount: busLineCount,
        liveDocLineCount: liveDocLineCount,
        modified: stat.modified,
      );
    });
  }

  Future<void> _scanWDrivePolicyAudit() async {
    setState(() {
      _status = 'auditing W drive network-logon rights';
    });
    const script = r'''
$ErrorActionPreference='Continue'
$guestSid = ''
try {
  $guestSid = (Get-LocalUser -Name 'Guest' -ErrorAction Stop).SID.Value
} catch {
  $guestSid = ''
}
$cfg = Join-Path $env:TEMP ("engel_w_drive_rights_audit_{0}.cfg" -f $PID)
$output = ''
$exit = $null
$network = ''
$deny = ''
try {
  $raw = & secedit /export /cfg $cfg /areas USER_RIGHTS 2>&1
  $exit = $LASTEXITCODE
  $output = ($raw | Out-String).Trim()
  if (Test-Path $cfg) {
    $lines = Get-Content $cfg
    $network = ($lines | Where-Object { $_ -match '^SeNetworkLogonRight\s*=' } | Select-Object -First 1)
    $deny = ($lines | Where-Object { $_ -match '^SeDenyNetworkLogonRight\s*=' } | Select-Object -First 1)
    Remove-Item -LiteralPath $cfg -Force -ErrorAction SilentlyContinue
  }
} catch {
  $output = $_.Exception.Message
  $exit = -1
}
$guestToken = if ($guestSid) { "*" + $guestSid } else { "" }
[pscustomobject]@{
  guest_sid = $guestSid
  exit_code = $exit
  output = $output
  network_logon_line = [string]$network
  deny_network_logon_line = [string]$deny
  guest_allowed = ($guestToken -ne '' -and [string]$network -like "*$guestToken*")
  guest_denied = ($guestToken -ne '' -and [string]$deny -like "*$guestToken*")
} | ConvertTo-Json -Compress
''';

    try {
      final result = await _processRunner('powershell.exe', [
        '-NoProfile',
        '-ExecutionPolicy',
        'Bypass',
        '-Command',
        script,
      ]);
      final stdoutText = result.stdout.toString().trim();
      final stderrText = result.stderr.toString().trim();
      Map<String, dynamic> decoded = {};
      if (stdoutText.isNotEmpty) {
        decoded =
            jsonDecode(stdoutText.split(RegExp(r'\r?\n')).last)
                as Map<String, dynamic>;
      }
      final exitCode = decoded['exit_code'] is int
          ? decoded['exit_code'] as int
          : null;
      final guestAllowed = decoded['guest_allowed'] == true;
      final guestDenied = decoded['guest_denied'] == true;
      final status = exitCode == 0
          ? guestAllowed && !guestDenied
                ? 'Guest network-logon rights ready'
                : 'Guest network-logon rights incomplete'
          : 'Policy audit requires elevated Main PowerShell';
      final output = (decoded['output'] ?? stderrText).toString();
      if (!mounted) return;
      setState(() {
        _wDrivePolicyAudit = WDrivePolicyAuditInfo(
          status: status,
          guestSid: (decoded['guest_sid'] ?? '').toString(),
          networkLogonLine: (decoded['network_logon_line'] ?? '').toString(),
          denyNetworkLogonLine: (decoded['deny_network_logon_line'] ?? '')
              .toString(),
          guestAllowed: guestAllowed,
          guestDenied: guestDenied,
          exitCode: exitCode,
          message: output.isEmpty
              ? 'Audit completed.'
              : output.replaceAll(RegExp(r'\s+'), ' ').trim(),
          auditedAt: DateTime.now(),
        );
        _status = status;
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _wDrivePolicyAudit = WDrivePolicyAuditInfo(
          status: 'Policy audit failed',
          guestSid: '',
          networkLogonLine: '',
          denyNetworkLogonLine: '',
          guestAllowed: false,
          guestDenied: false,
          exitCode: null,
          message: error.toString(),
          auditedAt: DateTime.now(),
        );
        _status = 'W drive policy audit failed';
      });
    }
  }

  DateTime? _deviceUtc(Object? raw) {
    final text = raw?.toString().trim() ?? '';
    return text.isEmpty ? null : DateTime.tryParse(text)?.toUtc();
  }

  String _phoneWorkerName(String id) {
    return switch (id.trim().toLowerCase()) {
      'android_worker_alpha' => 'Alpha phone',
      'android_worker_beta' => 'Beta phone',
      'android_worker_gamma' => 'Gamma phone',
      _ => 'Phone worker',
    };
  }

  Future<void> _scanDeviceVisibility() async {
    final nowUtc = DateTime.now().toUtc();
    var lanExists = false;
    var linkStatus = 'LAN state missing';
    var receiver = 'Receiver not loaded';
    var pairedPhone = 'No paired phone loaded';
    final androidWorkers = <String>[];
    final phoneWorkers = <VisibleDeviceWorker>[];
    final expectedPhoneIds = <String>[];
    var phoneFreshness = const Duration(minutes: 5);
    DateTime? modified;

    final phoneRegistry = File(pairedPhoneRegistryPath);
    if (await phoneRegistry.exists()) {
      try {
        final decoded = jsonDecode(await phoneRegistry.readAsString());
        if (decoded is Map) {
          final seconds = decoded['freshness_limit_seconds'];
          if (seconds is int && seconds > 0) {
            phoneFreshness = Duration(seconds: seconds);
          }
          final workers = decoded['workers'];
          if (workers is List) {
            for (final worker in workers) {
              if (worker is! Map || worker['paired'] != true) continue;
              final id = '${worker['worker_id'] ?? ''}'.trim();
              if (id.isNotEmpty) expectedPhoneIds.add(id);
            }
          }
        }
      } catch (_) {
        // A malformed pairing roster must not be promoted to live readiness.
      }
    }

    final lanFile = File(lanSessionStatePath);
    if (await lanFile.exists()) {
      lanExists = true;
      final stat = await lanFile.stat();
      modified = stat.modified;
      try {
        final decoded = jsonDecode(await lanFile.readAsString());
        if (decoded is Map<String, dynamic>) {
          final status = (decoded['link_status'] ?? 'unknown').toString();
          final host = (decoded['host'] ?? '').toString();
          final port = (decoded['port'] ?? '').toString();
          final lastSeen = (decoded['last_seen_utc'] ?? '').toString();
          linkStatus = '$status on $host:$port; last seen $lastSeen';

          final receiverValue = decoded['receiver_running'];
          final receiverRunning = receiverValue == true;
          final linkRunning = status.trim().toLowerCase() == 'running';
          final bool? receiverUsable = receiverValue is bool
              ? receiverRunning && linkRunning
              : null;
          final receiverPid = (decoded['receiver_pid'] ?? '').toString();
          final runtime = (decoded['receiver_runtime'] ?? '').toString();
          receiver =
              '${receiverRunning ? 'running' : 'stopped'} pid=$receiverPid runtime=$runtime';

          final paired = decoded['paired_phone_identity'];
          if (paired is Map<String, dynamic>) {
            pairedPhone =
                '${paired['worker_id'] ?? 'phone'} at ${paired['remote_address'] ?? 'unknown'} (${paired['current_mode'] ?? 'mode unknown'})';
            pairedPhone +=
                '; last seen ${lastSeen.isEmpty ? 'unknown' : lastSeen}; '
                'receiver_running=$receiverRunning; link_status=$status';
          }

          final workers = decoded['workers'];
          if (workers is Map<String, dynamic>) {
            for (final entry in workers.entries) {
              final value = entry.value;
              if (value is! Map<String, dynamic>) continue;
              final identity = value['identity'];
              var address = 'unknown address';
              var mode = 'unknown mode';
              if (identity is Map<String, dynamic>) {
                address = (identity['remote_address'] ?? address).toString();
                mode = (identity['current_mode'] ?? mode).toString();
              }
              final observedAt = _deviceUtc(value['last_seen_utc']);
              final detail =
                  '${entry.key}: $address; last seen ${value['last_seen_utc'] ?? 'unknown'}; '
                  '$mode; auto_apply=${value['auto_apply'] == true}; '
                  'receiver_running=$receiverRunning; link_status=$status';
              androidWorkers.add(detail);
              phoneWorkers.add(
                VisibleDeviceWorker(
                  id: entry.key,
                  name: _phoneWorkerName(entry.key),
                  address: address,
                  detail: detail,
                  status: classifyEngelDeviceEvidence(
                    EngelDeviceEvidence(
                      sourceValid: true,
                      usable: receiverUsable,
                      observedAtUtc: observedAt,
                      freshness: phoneFreshness,
                    ),
                    nowUtc: nowUtc,
                  ),
                ),
              );
            }
          }
        }
      } catch (error) {
        linkStatus = 'LAN state parse error: $error';
      }
    }

    for (final id in expectedPhoneIds) {
      if (phoneWorkers.any((worker) => worker.id == id)) continue;
      phoneWorkers.add(
        VisibleDeviceWorker(
          id: id,
          name: _phoneWorkerName(id),
          address: '',
          detail: 'Paired setup found, but no current heartbeat was reported.',
          status: classifyEngelDeviceEvidence(
            const EngelDeviceEvidence(
              sourceValid: true,
              usable: null,
              observedAtUtc: null,
              freshness: Duration(minutes: 5),
            ),
            nowUtc: nowUtc,
          ),
        ),
      );
    }

    var nodeReady = 'Latest Windows Sub-Engel node-ready file missing';
    var subEngelHost = '';
    var subEngelAddress = '';
    final nodeFile = File(latestNodeReadyPath);
    if (await nodeFile.exists()) {
      try {
        final decoded = jsonDecode(await nodeFile.readAsString());
        if (decoded is Map<String, dynamic>) {
          final supervisor = decoded['supervisor'];
          final supervisorOk = supervisor is Map ? supervisor['ok'] : null;
          final timestamp =
              (decoded['timestamp'] ?? decoded['updated_at_utc'] ?? 'unknown')
                  .toString();
          subEngelHost = '${decoded['computer_name'] ?? ''}'.trim();
          subEngelAddress =
              '${decoded['node_ip'] ?? decoded['remote_addr'] ?? ''}'.trim();
          nodeReady =
              '${subEngelHost.isEmpty ? 'node' : subEngelHost} at '
              '${subEngelAddress.isEmpty ? 'unknown' : subEngelAddress}; '
              'root ${decoded['node_root'] ?? 'unknown'}; '
              'ok=${decoded['ok'] == true}; '
              'supervisor_ok=${supervisorOk is bool ? supervisorOk : 'unknown'}; '
              'last seen $timestamp';
        }
      } catch (error) {
        nodeReady = 'Node-ready parse error: $error';
      }
    }

    var subEngelWorker = VisibleDeviceWorker(
      id: 'sub-engel-node',
      name: 'Sub-Engel',
      address: subEngelAddress,
      detail:
          'No authoritative Sub-Engel session has been checked for this node.',
      status: classifyEngelDeviceEvidence(
        const EngelDeviceEvidence(
          sourceValid: false,
          usable: null,
          observedAtUtc: null,
          freshness: Duration(minutes: 30),
        ),
        nowUtc: nowUtc,
      ),
    );

    File? sessionFile;
    if (subEngelHost.isNotEmpty) {
      final candidate = File(
        '$windowsSubEngelSessionsDir\\$subEngelHost\\session.json',
      );
      if (await candidate.exists()) sessionFile = candidate;
    }
    if (sessionFile == null) {
      final directory = Directory(windowsSubEngelSessionsDir);
      if (await directory.exists()) {
        final candidates = await directory
            .list(recursive: true, followLinks: false)
            .where(
              (entity) =>
                  entity is File && entity.path.endsWith('session.json'),
            )
            .cast<File>()
            .toList();
        candidates.sort(
          (left, right) =>
              right.lastModifiedSync().compareTo(left.lastModifiedSync()),
        );
        for (final candidate in candidates) {
          try {
            final decoded = jsonDecode(await candidate.readAsString());
            if (decoded is Map &&
                decoded['disabled_for_engel_main'] != true &&
                decoded['selected_for_engel_main'] != false) {
              sessionFile = candidate;
              break;
            }
          } catch (_) {
            continue;
          }
        }
      }
    }

    if (sessionFile != null) {
      try {
        final decoded = jsonDecode(await sessionFile.readAsString());
        if (decoded is Map<String, dynamic>) {
          final host = '${decoded['hostname'] ?? subEngelHost}'.trim();
          final url = '${decoded['url'] ?? ''}'.trim();
          final expiry = _deviceUtc(decoded['expires_at_utc']);
          final expired = expiry != null && !expiry.isAfter(nowUtc);
          final reasons = <String>[
            if (decoded['disabled_for_engel_main'] == true)
              'disabled for Engel Main',
            if (decoded['session_invalid'] == true) 'session invalid',
            if (decoded['paired'] == false) 'not paired',
            if (decoded['meeting_ready'] == false) 'Meeting Room not ready',
            if (decoded['live_health_ok'] == false) 'health check failed',
            if (decoded['last_auth_probe_ok'] == false) 'authentication failed',
            if (expired) 'session expired',
          ];
          final hasPositiveContract =
              decoded['paired'] == true &&
              decoded['meeting_ready'] == true &&
              decoded['live_health_ok'] == true &&
              decoded['last_auth_probe_ok'] == true &&
              decoded['session_invalid'] != true &&
              decoded['disabled_for_engel_main'] != true &&
              !expired;
          final bool? usable = reasons.isNotEmpty
              ? false
              : hasPositiveContract
              ? true
              : null;
          final lastProbe =
              _deviceUtc(decoded['last_auth_probe_at_utc']) ??
              _deviceUtc(decoded['last_seen_utc']);
          // Invalid pairing or an expired lease is a current condition observed
          // by this scan. Positive readiness still requires a fresh live probe.
          final observedAt = reasons.isNotEmpty ? nowUtc : lastProbe;
          final status = classifyEngelDeviceEvidence(
            EngelDeviceEvidence(
              sourceValid: true,
              usable: usable,
              observedAtUtc: observedAt,
              freshness: const Duration(minutes: 30),
            ),
            nowUtc: nowUtc,
          );
          final address = _extractIp(url, fallback: subEngelAddress);
          subEngelWorker = VisibleDeviceWorker(
            id: 'sub-engel-node',
            name: host.isEmpty ? 'Sub-Engel' : 'Sub-Engel ($host)',
            address: address,
            detail: reasons.isEmpty
                ? 'Authoritative session checked; ${status.lastSeenLabel}.'
                : '${reasons.join(', ')}. Open Sub-Engel help to reconnect.',
            status: status,
          );
          subEngelHost = host;
          subEngelAddress = address;
        }
      } catch (_) {
        subEngelWorker = VisibleDeviceWorker(
          id: 'sub-engel-node',
          name: subEngelHost.isEmpty
              ? 'Sub-Engel'
              : 'Sub-Engel ($subEngelHost)',
          address: subEngelAddress,
          detail: 'The authoritative Sub-Engel session could not be read.',
          status: classifyEngelDeviceEvidence(
            const EngelDeviceEvidence(
              sourceValid: false,
              usable: null,
              observedAtUtc: null,
              freshness: Duration(minutes: 30),
            ),
            nowUtc: nowUtc,
          ),
        );
      }
    }

    final returnDirectory = Directory(subEngelTransportReturnsDir);
    if (await returnDirectory.exists()) {
      final returns = await returnDirectory
          .list(followLinks: false)
          .where(
            (entity) =>
                entity is File &&
                entity.path.toLowerCase().endsWith('.done.json') &&
                (subEngelHost.isEmpty ||
                    entity.uri.pathSegments.last.toLowerCase().startsWith(
                      '${subEngelHost.toLowerCase()}__',
                    )),
          )
          .cast<File>()
          .toList();
      returns.sort(
        (left, right) =>
            right.lastModifiedSync().compareTo(left.lastModifiedSync()),
      );
      if (returns.isNotEmpty) {
        try {
          final latestReturn = returns.first;
          final decoded = jsonDecode(await latestReturn.readAsString());
          if (decoded is Map<String, dynamic>) {
            final completedAt =
                _deviceUtc(decoded['completed_at_utc']) ??
                (await latestReturn.stat()).modified.toUtc();
            final returnStatus = classifyEngelDeviceEvidence(
              EngelDeviceEvidence(
                sourceValid: decoded['ok'] is bool,
                usable: decoded['ok'] is bool ? decoded['ok'] == true : null,
                observedAtUtc: completedAt,
                freshness: const Duration(minutes: 30),
              ),
              nowUtc: nowUtc,
            );
            if (returnStatus.readiness == EngelDeviceReadiness.ready ||
                returnStatus.readiness == EngelDeviceReadiness.offline ||
                (subEngelWorker.status.readiness ==
                        EngelDeviceReadiness.unknown &&
                    returnStatus.readiness == EngelDeviceReadiness.stale)) {
              final returnHost = '${decoded['hostname'] ?? subEngelHost}'
                  .trim();
              subEngelWorker = VisibleDeviceWorker(
                id: 'sub-engel-node',
                name: returnHost.isEmpty
                    ? subEngelWorker.name
                    : 'Sub-Engel ($returnHost)',
                address: subEngelWorker.address,
                detail:
                    'Authoritative Meeting Room return ${returnStatus.label.toLowerCase()}; '
                    '${returnStatus.lastSeenLabel}.',
                status: returnStatus,
              );
            }
          }
        } catch (_) {
          // Keep the authoritative session result when a return receipt is bad.
        }
      }
    }

    var busProof = 'No recent device result loaded from shared bus.';
    final bus = File(sharedRoomBusPath);
    if (await bus.exists()) {
      final lines = await bus.readAsLines();
      for (final line in lines) {
        try {
          final decoded = jsonDecode(line);
          if (decoded is! Map<String, dynamic>) continue;
          final channel = (decoded['channel'] ?? '').toString().toUpperCase();
          final message = (decoded['message'] ?? '').toString();
          final lower = message.toLowerCase();
          final deviceProof =
              channel.contains('RESULT') &&
              (lower.contains('w: connected') ||
                  lower.contains('callback complete') ||
                  lower.contains('node 8776 ok') ||
                  lower.contains('phones are visible') ||
                  lower.contains('android_worker_alpha') ||
                  lower.contains('android_worker_beta'));
          if (!deviceProof) continue;
          busProof =
              '${decoded['timestamp_utc'] ?? ''} ${decoded['sender'] ?? 'shared room'}: $message';
        } catch (_) {
          continue;
        }
      }
    }

    if (!mounted) return;
    setState(() {
      _deviceVisibility = DeviceVisibilityInfo(
        lanExists: lanExists,
        linkStatus: linkStatus,
        receiver: receiver,
        pairedPhone: pairedPhone,
        androidWorkers: androidWorkers,
        nodeReady: nodeReady,
        phoneWorkers: phoneWorkers,
        subEngelWorker: subEngelWorker,
        busProof: busProof,
        modified: modified,
      );
      _deviceVisibilityCheckedAt = nowUtc;
    });
  }

  List<EngelDeviceStatus> _visibleWorkerStatuses([
    DeviceVisibilityInfo? value,
  ]) {
    final visible = value ?? _deviceVisibility;
    return <EngelDeviceStatus>[
      ...visible.phoneWorkers.map((worker) => worker.status),
      visible.subEngelWorker.status,
    ];
  }

  String _deviceReadySummary([DeviceVisibilityInfo? value]) {
    final statuses = _visibleWorkerStatuses(value);
    final ready = statuses.where((status) => status.isReady).length;
    if (statuses.isEmpty) return 'No devices checked yet';
    if (ready == statuses.length) {
      return 'All ${statuses.length} workers are ready';
    }
    return '$ready of ${statuses.length} ready';
  }

  String get _deviceLastCheckedLabel {
    final checkedAt = _deviceVisibilityCheckedAt;
    if (checkedAt == null) return 'Status has not been checked yet';
    final age = DateTime.now().toUtc().difference(checkedAt);
    if (age.isNegative || age.inMinutes < 1) return 'Last checked just now';
    if (age.inHours < 1) {
      return 'Last checked ${age.inMinutes} '
          '${age.inMinutes == 1 ? 'minute' : 'minutes'} ago';
    }
    return 'Last checked ${age.inHours} '
        '${age.inHours == 1 ? 'hour' : 'hours'} ago';
  }

  Future<void> _refreshDeviceVisibilityFromUi() async {
    if (_deviceVisibilityRefreshing) return;
    setState(() {
      _deviceVisibilityRefreshing = true;
      _deviceVisibilityAnnouncement = 'Refreshing live device status…';
    });
    try {
      final python = File(runtimePythonExe);
      final probe = File(refreshSubEngelStatusScriptPath);
      if (python.existsSync() && probe.existsSync()) {
        try {
          await _processRunner(python.path, [
            probe.path,
          ], workingDirectory: appRoot).timeout(const Duration(seconds: 20));
        } catch (_) {
          // File scan still runs; a failed live probe must not hide phones.
        }
      }
      await _scanDeviceVisibility();
      if (!mounted) return;
      setState(() {
        _deviceVisibilityAnnouncement = 'Refreshed — ${_deviceReadySummary()}.';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _deviceVisibilityAnnouncement =
            'Device refresh failed. Open Connection help and try again.';
      });
    } finally {
      if (mounted) {
        setState(() => _deviceVisibilityRefreshing = false);
      }
    }
  }

  List<double> _auditedSwarmPosition(String id, int index) {
    return switch (id) {
      'engel-main-pc' => const [0, 2.2, 0],
      'engel-spine-01' => const [-4.6, 1.2, -3.8],
      'local-llm-runtime' => const [-5.4, 1.6, 3.8],
      'meeting-room-server' => const [-3.2, 1.0, -1.8],
      'sub-engel-node' => const [5.6, 1.4, 2.9],
      'android_worker_alpha' => const [6.8, 0.8, -1.8],
      'android_worker_beta' => const [7.4, 1.1, 0.5],
      'android_worker_gamma' => const [6.6, 0.7, 2.4],
      'lan-gateway' => const [0, 4.0, -5.0],
      _ => [
        math.cos(1.2 + (index * 0.58)) * 8.0,
        0.55 + (index % 4) * 0.34,
        math.sin(1.2 + (index * 0.58)) * 5.8,
      ],
    };
  }

  String _auditedSwarmType(String id, String classification, String hardware) {
    if (id.startsWith('android_worker_')) return 'android';
    if (id == 'engel-main-pc') return 'windows';
    if (id == 'sub-engel-node') return 'sub_engel';
    if (id == 'local-llm-runtime') return 'llm';
    if (id == 'lan-gateway') return 'wifi';
    if (classification == 'logical_runtime' || id == 'engel-spine-01') {
      return 'server';
    }
    if (hardware.toLowerCase().contains('tv') ||
        hardware.toLowerCase().contains('roku')) {
      return 'display';
    }
    return 'network';
  }

  String _auditedSwarmRole(String id, String classification) {
    return switch (id) {
      'engel-main-pc' => 'main-controller',
      'engel-spine-01' => 'proxmox-host',
      'local-llm-runtime' => 'model-runtime',
      'meeting-room-server' => 'meeting-room',
      'sub-engel-node' => 'worker',
      'android_worker_alpha' ||
      'android_worker_beta' ||
      'android_worker_gamma' => 'phone-worker',
      'lan-gateway' => 'network-gateway',
      _ => classification == 'lan_candidate' ? 'unassigned' : classification,
    };
  }

  SwarmDeviceNode _swarmNodeFromAudit(Map<String, dynamic> row, int index) {
    final id = '${row['id'] ?? 'audited-$index'}';
    final classification = '${row['classification'] ?? 'unclassified'}';
    final status = '${row['status'] ?? 'unknown'}';
    final hardware = '${row['hardware'] ?? ''}';
    final position = _auditedSwarmPosition(id, index);
    final evidenceRows = row['evidence'] is List
        ? (row['evidence'] as List).map((value) => '$value').toList()
        : <String>[];
    final aliases = row['aliases'] is List
        ? (row['aliases'] as List).map((value) => '$value').toList()
        : <String>[];
    final verified = status == 'verified_live';
    final stale = status.contains('stale') || status.contains('offline');
    return SwarmDeviceNode(
      id: id,
      name: '${row['name'] ?? id}',
      type: _auditedSwarmType(id, classification, hardware),
      status: status,
      ip: '${row['ip'] ?? ''}',
      role: _auditedSwarmRole(id, classification),
      source: deviceIdentityAuditStatePath,
      detail: evidenceRows.join('; '),
      x: position[0],
      y: position[1],
      z: position[2],
      signal: verified ? 92 : (stale ? 36 : 58),
      load: 0,
      workers: classification == 'cluster_member' ? 1 : 0,
      trusted:
          classification == 'cluster_member' ||
          classification == 'logical_runtime',
      autoMode: false,
      macAddress: '${row['mac_address'] ?? ''}',
      vendor: '${row['vendor'] ?? ''}',
      interfaceName: '${row['transport'] ?? ''}',
      deviceSummary: hardware,
      evidence: evidenceRows.join('; '),
      wifiGroup: classification == 'lan_candidate'
          ? 'lan-candidate'
          : 'engel-cluster',
      classification: classification,
      hardware: hardware,
      networkLocation: '${row['network_location'] ?? ''}',
      physicalLocation: '${row['physical_location'] ?? 'Unknown'}',
      locationConfidence: '${row['location_confidence'] ?? 'unknown'}',
      identityConfidence: '${row['identity_confidence'] ?? 'unknown'}',
      lastSeenUtc: '${row['last_seen_utc'] ?? ''}',
      aliases: aliases,
      canJoinCluster: row['can_join_cluster'] == true,
    );
  }

  Future<void> _loadDeviceIdentityAudit({bool refreshEvidence = false}) async {
    try {
      if (refreshEvidence) {
        final result = await _processRunner(runtimePythonExe, [
          deviceIdentityAuditScriptPath,
        ], workingDirectory: appRoot).timeout(const Duration(seconds: 90));
        if (result.exitCode != 0) {
          throw StateError(
            'identity audit exited ${result.exitCode}: ${result.stderr}',
          );
        }
      }
      final file = File(deviceIdentityAuditStatePath);
      if (!await file.exists()) {
        throw StateError('identity audit report is missing');
      }
      final parsed = jsonDecode(await file.readAsString());
      if (parsed is! Map || parsed['devices'] is! List) {
        throw const FormatException('identity audit report is invalid');
      }
      final nodes = <SwarmDeviceNode>[];
      for (final row in parsed['devices'] as List) {
        if (row is Map) {
          nodes.add(
            _swarmNodeFromAudit(Map<String, dynamic>.from(row), nodes.length),
          );
        }
      }
      if (!mounted) return;
      setState(() {
        _auditedSwarmDevices
          ..clear()
          ..addAll(nodes);
        _deviceIdentityAuditGeneratedAt = '${parsed['generated_at_utc'] ?? ''}';
        _deviceIdentityAuditError = '';
        _lanScanStatus = 'identity audit: ${nodes.length} records';
        if (!nodes.any((node) => node.id == _swarmSelectedId) &&
            nodes.isNotEmpty) {
          _swarmSelectedId = nodes.first.id;
        }
      });
    } catch (error) {
      if (!mounted) return;
      setState(() => _deviceIdentityAuditError = '$error');
    }
  }

  Future<void> _runFullDeviceIdentityAudit() async {
    if (_running) return;
    setState(() {
      _running = true;
      _status = 'auditing device identity';
      _output =
          'Collecting authenticated hardware, USB, LAN, and service evidence.';
    });
    try {
      await _loadDeviceIdentityAudit(refreshEvidence: true);
      final members = _auditedSwarmDevices
          .where((node) => node.classification == 'cluster_member')
          .length;
      final issues = _auditedSwarmDevices
          .where(
            (node) =>
                node.classification == 'cluster_member' &&
                node.status != 'verified_live',
          )
          .length;
      await _writeSwarmStateSnapshot(
        _swarmDevices(),
        reason: 'full_identity_audit',
      );
      if (!mounted) return;
      setState(() {
        _status = _deviceIdentityAuditError.isEmpty
            ? 'device identity audit complete'
            : 'device identity audit failed';
        _output = _deviceIdentityAuditError.isEmpty
            ? 'Authoritative device audit loaded.\nMembers: $members\nMember issues: $issues\nReport: $deviceIdentityAuditStatePath'
            : _deviceIdentityAuditError;
      });
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  List<SwarmDeviceNode> _swarmDevices() {
    if (_auditedSwarmDevices.isNotEmpty) {
      final nodes = <SwarmDeviceNode>[..._auditedSwarmDevices];
      for (final manual in _swarmManualDevices) {
        final duplicate = nodes.any(
          (node) =>
              node.id == manual.id ||
              (node.ip.isNotEmpty && node.ip == manual.ip),
        );
        if (!duplicate) nodes.add(manual);
      }
      return nodes
          .map(_applyLiveDeviceReadiness)
          .map(_applySwarmOverrides)
          .toList(growable: false);
    }
    final visible = _deviceVisibility;
    final nodes = <SwarmDeviceNode>[
      const SwarmDeviceNode(
        id: 'engel-main-pc',
        name: 'Engel AI Main PC',
        type: 'windows',
        status: 'online',
        ip: 'local',
        role: 'main',
        source: flutterEngelMainExe,
        detail:
            'Running the Flutter Engel AI Main shell and Rust background routes.',
        x: 0,
        y: 2.2,
        z: 0,
        signal: 100,
        load: 24,
        workers: 1,
        trusted: true,
        autoMode: false,
      ),
      SwarmDeviceNode(
        id: 'meeting-room-server',
        name: 'Meeting Room Server',
        type: 'server',
        status: _meetingRoomServer.ok ? 'online' : 'offline',
        ip: meetingRoomServerHealthUrl,
        role: 'meeting-room',
        source: meetingRoomServerStartScriptPath,
        detail: _meetingRoomServer.error.isEmpty
            ? '${_meetingRoomServer.status}; endpoints ${_meetingRoomServer.endpoints.length}'
            : _meetingRoomServer.error,
        x: -4.2,
        y: 1.0,
        z: -3.2,
        signal: _meetingRoomServer.ok ? 92 : 38,
        load: _meetingRoomServer.ok ? 18 : 0,
        workers: _meetingRoomServer.endpoints.length,
        trusted: true,
        autoMode: false,
      ),
      SwarmDeviceNode(
        id: 'wifi-main',
        name: 'Engel WiFi / LAN Hub',
        type: 'wifi',
        status: visible.lanExists ? 'online' : 'needs scan',
        ip: _extractIp(visible.linkStatus, fallback: '192.0.2.40'),
        role: 'network',
        source: lanSessionStatePath,
        detail: visible.linkStatus,
        x: 0,
        y: 4.0,
        z: -5.0,
        signal: visible.lanExists ? 88 : 48,
        load: visible.lanExists ? 16 : 0,
        workers: visible.androidWorkers.length,
        trusted: true,
        autoMode: false,
      ),
      SwarmDeviceNode(
        id: 'sub-engel-node',
        name: 'Sub-Engel Node',
        type: 'sub_engel',
        status: visible.subEngelWorker.status.label,
        ip: visible.subEngelWorker.address.isEmpty
            ? _extractIp(visible.nodeReady)
            : visible.subEngelWorker.address,
        role: 'worker',
        source: windowsSubEngelSessionsDir,
        detail: visible.subEngelWorker.detail,
        x: 5.6,
        y: 1.4,
        z: 2.9,
        signal: _deviceReadinessSignal(visible.subEngelWorker.status),
        load: _subEngelSharedRoomQueue.workOrderCount.toDouble(),
        workers: visible.subEngelWorker.status.isReady ? 1 : 0,
        trusted: false,
        autoMode: false,
      ),
      SwarmDeviceNode(
        id: 'local-llm-runtime',
        name: 'CT 246 LLM Runtime',
        type: 'llm',
        status: _localModelFiles.isEmpty && _freeModels.isEmpty
            ? 'not scanned'
            : 'ready',
        ip: '192.0.2.50:24622',
        role: 'model-runtime',
        source: '/opt/engel/models-active',
        detail:
            '${_localModelFiles.length} GGUF / ${_freeModels.length} CT model roots / ${_models.length} Cosmos3 folders',
        x: -5.4,
        y: 1.6,
        z: 3.8,
        signal: _localModelFiles.isEmpty && _freeModels.isEmpty ? 42 : 86,
        load: (_localModelFiles.length + _freeModels.length).toDouble(),
        workers: _models.length,
        trusted: true,
        autoMode: false,
        wifiGroup: 'engel-runtime',
      ),
    ];

    if (visible.phoneWorkers.isEmpty) {
      nodes.add(
        SwarmDeviceNode(
          id: 'android-worker-alpha',
          name: 'Android Worker Alpha',
          type: 'android',
          status: 'Not checked',
          ip: _extractIp(visible.pairedPhone, fallback: '192.0.2.40'),
          role: 'phone-worker',
          source: lanSessionStatePath,
          detail: 'No authoritative phone heartbeat was loaded.',
          x: -6.8,
          y: 0.8,
          z: 2.0,
          signal: 35,
          load: 0,
          workers: 1,
          trusted: false,
          autoMode: false,
        ),
      );
    } else {
      for (var i = 0; i < visible.phoneWorkers.length; i++) {
        final worker = visible.phoneWorkers[i];
        final angle = -0.8 + (i * 0.62);
        nodes.add(
          SwarmDeviceNode(
            id: worker.id,
            name: worker.name,
            type: 'android',
            status: worker.status.label,
            ip: worker.address.isEmpty ? 'LAN worker' : worker.address,
            role: 'phone-worker',
            source: lanSessionStatePath,
            detail: worker.detail,
            x: math.cos(angle) * 7.0,
            y: 0.7 + (i % 2) * 0.55,
            z: math.sin(angle) * 5.0,
            signal: _deviceReadinessSignal(worker.status),
            load: i.toDouble(),
            workers: 1,
            trusted: false,
            autoMode: worker.detail.toLowerCase().contains('auto_apply=true'),
          ),
        );
      }
    }

    nodes.addAll(_discoveredSwarmDevices);
    nodes.addAll(_swarmManualDevices);
    return nodes
        .map(_applyLiveDeviceReadiness)
        .map(_applySwarmOverrides)
        .toList(growable: false);
  }

  double _deviceReadinessSignal(EngelDeviceStatus status) {
    return switch (status.readiness) {
      EngelDeviceReadiness.ready => 90,
      EngelDeviceReadiness.offline => 25,
      EngelDeviceReadiness.stale => 42,
      EngelDeviceReadiness.unknown => 35,
    };
  }

  SwarmDeviceNode _applyLiveDeviceReadiness(SwarmDeviceNode node) {
    final normalizedId = node.id.toLowerCase().replaceAll('-', '_');
    VisibleDeviceWorker? liveWorker;
    if (normalizedId == 'sub_engel_node') {
      liveWorker = _deviceVisibility.subEngelWorker;
    } else {
      for (final worker in _deviceVisibility.phoneWorkers) {
        if (worker.id.toLowerCase().replaceAll('-', '_') == normalizedId) {
          liveWorker = worker;
          break;
        }
      }
    }
    if (liveWorker == null) return node;
    return node.copyWith(
      status: liveWorker.status.label,
      ip: liveWorker.address.isEmpty ? null : liveWorker.address,
      detail: liveWorker.detail,
      signal: _deviceReadinessSignal(liveWorker.status),
      lastSeenUtc:
          liveWorker.status.observedAtUtc?.toIso8601String() ??
          node.lastSeenUtc,
    );
  }

  SwarmDeviceNode _applySwarmOverrides(SwarmDeviceNode node) {
    return node.copyWith(
      signal: _swarmSignalOverrides[node.id],
      role: _swarmRoleOverrides[node.id],
      trusted: _swarmTrustedOverrides[node.id],
      autoMode: _swarmAutoModeOverrides[node.id],
    );
  }

  SwarmDeviceNode _selectedSwarmDevice(List<SwarmDeviceNode> devices) {
    return devices.firstWhere(
      (device) => device.id == _swarmSelectedId,
      orElse: () => devices.first,
    );
  }

  String _extractIp(String text, {String fallback = 'unknown'}) {
    final match = RegExp(r'\d{1,3}(?:\.\d{1,3}){3}').firstMatch(text);
    return match?.group(0) ?? fallback;
  }

  String _safeFileToken(String value) {
    final safe = value
        .trim()
        .replaceAll(RegExp(r'[^a-zA-Z0-9_.-]+'), '_')
        .replaceAll(RegExp(r'_+'), '_');
    return safe.isEmpty ? 'device' : safe;
  }

  List<int>? _ipv4Parts(String ip) {
    final parts = ip.trim().split('.');
    if (parts.length != 4) return null;
    final parsed = <int>[];
    for (final part in parts) {
      final value = int.tryParse(part);
      if (value == null || value < 0 || value > 255) return null;
      parsed.add(value);
    }
    return parsed;
  }

  bool _isPrivateIpv4(String ip) {
    final parts = _ipv4Parts(ip);
    if (parts == null) return false;
    final first = parts[0];
    final second = parts[1];
    return first == 10 ||
        (first == 172 && second >= 16 && second <= 31) ||
        (first == 192 && second == 168);
  }

  String _neighborStateLabel(Object? raw) {
    final text = raw?.toString().trim() ?? '';
    return switch (text.toLowerCase()) {
      '0' || 'unreachable' => 'Unreachable',
      '1' || 'incomplete' => 'Incomplete',
      '2' || 'probe' => 'Probe',
      '3' || 'delay' => 'Delay',
      '4' || 'stale' => 'Stale',
      '5' || 'reachable' => 'Reachable',
      '6' || 'permanent' => 'Permanent',
      '' => 'unknown',
      _ => text,
    };
  }

  String _normalizeMac(String value) {
    final match = RegExp(
      r'([0-9A-Fa-f]{2}[-:]){5}[0-9A-Fa-f]{2}',
    ).firstMatch(value);
    if (match == null) return '';
    final normalized = match.group(0)!.replaceAll(':', '-').toUpperCase();
    if (normalized == '00-00-00-00-00-00' ||
        normalized == 'FF-FF-FF-FF-FF-FF') {
      return '';
    }
    return normalized;
  }

  String _cleanLanIdentityName(String value) {
    var clean = value.trim();
    if (clean.isEmpty) return '';
    clean = clean.replaceAll(RegExp(r'\.$'), '');
    clean = clean.replaceAll(RegExp(r'\s+'), ' ');
    final lower = clean.toLowerCase();
    if (lower == 'unknown' ||
        lower == 'localhost' ||
        lower == 'not returned' ||
        lower == 'workgroup' ||
        _isPrivateIpv4(clean)) {
      return '';
    }
    return clean;
  }

  String _xmlAttribute(String text, String name) {
    final match = RegExp('$name="([^"]*)"').firstMatch(text);
    if (match == null) return '';
    return match
        .group(1)!
        .replaceAll('&quot;', '"')
        .replaceAll('&apos;', "'")
        .replaceAll('&amp;', '&')
        .trim();
  }

  String _deviceClassFromPorts(Set<int> ports) {
    if (ports.contains(5555)) return 'Android ADB WiFi';
    if (ports.contains(8765) || ports.contains(8776)) {
      return 'Engel LAN worker';
    }
    if (ports.contains(11434)) return 'Local LLM/Ollama node';
    if (ports.contains(445) && ports.contains(3389)) {
      return 'Windows PC/server';
    }
    if (ports.contains(445)) return 'Windows SMB device';
    if (ports.contains(3389)) return 'Windows RDP device';
    if (ports.contains(22)) return 'SSH server';
    if (ports.any((p) => {80, 443, 8080, 8000}.contains(p))) {
      return 'Web UI device';
    }
    if (ports.any((p) => {3000, 5173}.contains(p))) {
      return 'Dev server device';
    }
    return 'LAN responder';
  }

  String _deviceSummary({
    required String ip,
    required String state,
    required String mac,
    required String hostName,
    required String vendor,
    required String interfaceName,
    required String service,
    required String ports,
  }) {
    final parts = <String>[
      if (hostName.isNotEmpty) 'host=$hostName',
      'ip=$ip',
      if (mac.isNotEmpty) 'mac=$mac',
      if (vendor.isNotEmpty) 'vendor=$vendor',
      if (state.isNotEmpty) 'state=$state',
      if (interfaceName.isNotEmpty) 'interface=$interfaceName',
      if (service.isNotEmpty) 'service=$service',
      if (ports.isNotEmpty) 'ports=$ports',
    ];
    return parts.join('; ');
  }

  String _deviceDisplayName({
    required String ip,
    required String fallback,
    String hostName = '',
    String vendor = '',
    String service = '',
  }) {
    final host = _cleanLanIdentityName(hostName);
    if (host.isNotEmpty) return '$host ($ip)';
    if (service.isNotEmpty && service != 'LAN responder') {
      return '$service $ip';
    }
    if (vendor.isNotEmpty) return '$vendor device $ip';
    return fallback;
  }

  String _nmapServiceSummary(int port, String attrs) {
    final service = _xmlAttribute(attrs, 'name');
    final product = _xmlAttribute(attrs, 'product');
    final version = _xmlAttribute(attrs, 'version');
    final extra = _xmlAttribute(attrs, 'extrainfo');
    final parts = <String>[
      '$port',
      if (service.isNotEmpty) service,
      if (product.isNotEmpty) product,
      if (version.isNotEmpty) version,
      if (extra.isNotEmpty) extra,
    ];
    return parts.join(' ');
  }

  Future<Map<String, LanCandidateIdentity>> _lookupLanCandidateIdentities(
    List<String> ips,
  ) async {
    final boundedIps = ips.where(_isPrivateIpv4).toSet().take(24).toList();
    if (boundedIps.isEmpty) return const {};
    final quotedIps = boundedIps.map((ip) => "'$ip'").join(',');
    final psCmd = [
      r'$ips = @(',
      quotedIps,
      r');',
      r'$items = foreach ($ip in $ips) {',
      r'$dns = "";',
      r'try { $ptr = Resolve-DnsName -Name $ip -Type PTR -ErrorAction Stop | Select-Object -First 1; if ($ptr.NameHost) { $dns = $ptr.NameHost } } catch {}',
      r'$nb = "";',
      r'try { $lines = nbtstat -A $ip 2>$null; $line = $lines | Where-Object { $_ -match "<00>\s+UNIQUE" -and $_ -notmatch "__MSBROWSE__" } | Select-Object -First 1; if ($line) { $nb = ($line -replace "^\s*([^\s<]+).*$", "$1") } } catch {}',
      r'[pscustomobject]@{ IPAddress = $ip; DnsName = $dns; NetBIOSName = $nb }',
      r'};',
      r'$items | ConvertTo-Json -Compress',
    ].join(' ');
    try {
      final result = await _processRunner('powershell.exe', [
        '-NoProfile',
        '-Command',
        psCmd,
      ], workingDirectory: appRoot).timeout(const Duration(seconds: 28));
      if (result.exitCode != 0) return const {};
      final text = result.stdout.toString().trim();
      if (text.isEmpty || text == 'null') return const {};
      final decoded = jsonDecode(text);
      final values = decoded is List ? decoded : [decoded];
      final identities = <String, LanCandidateIdentity>{};
      for (final value in values) {
        if (value is! Map) continue;
        final ip = (value['IPAddress'] ?? '').toString().trim();
        if (!_isPrivateIpv4(ip)) continue;
        final dns = _cleanLanIdentityName((value['DnsName'] ?? '').toString());
        final netbios = _cleanLanIdentityName(
          (value['NetBIOSName'] ?? '').toString(),
        );
        if (dns.isEmpty && netbios.isEmpty) continue;
        identities[ip] = LanCandidateIdentity(
          dnsName: dns,
          netbiosName: netbios,
        );
      }
      return identities;
    } catch (_) {
      return const {};
    }
  }

  Future<List<String>> _nmapLanTargets(List<String> candidateIps) async {
    final targets = candidateIps.where(_isPrivateIpv4).toSet();
    if (targets.isEmpty) {
      try {
        final psCmd =
            r'''Get-NetIPConfiguration | Where-Object { $_.NetAdapter.Status -eq "Up" -and $_.IPv4Address } | ForEach-Object { $_.IPv4Address | ForEach-Object { $_.IPAddress } } | ConvertTo-Json -Compress''';
        final result = await _processRunner('powershell.exe', [
          '-NoProfile',
          '-Command',
          psCmd,
        ], workingDirectory: appRoot).timeout(const Duration(seconds: 12));
        if (result.exitCode == 0) {
          final text = result.stdout.toString().trim();
          if (text.isNotEmpty && text != 'null') {
            final decoded = jsonDecode(text);
            final values = decoded is List ? decoded : [decoded];
            for (final value in values) {
              final ip = value.toString().trim();
              if (_isPrivateIpv4(ip)) targets.add(ip);
            }
          }
        }
      } catch (_) {}
    }
    return targets.take(48).toList(growable: false);
  }

  String _nmapDeviceType(Set<int> ports) {
    if (ports.contains(5555)) return 'android';
    if (ports.contains(11434)) return 'llm';
    if (ports.contains(445) || ports.contains(3389)) return 'windows';
    if (ports.contains(8765) || ports.contains(8776)) return 'android';
    if (ports.contains(22)) return 'server';
    return 'wifi';
  }

  String _nmapDeviceRole(Set<int> ports) {
    if (ports.contains(5555) || ports.contains(8765) || ports.contains(8776)) {
      return 'worker';
    }
    if (ports.contains(11434)) return 'local-llm';
    if (ports.contains(445) || ports.contains(3389)) return 'sub-engel';
    return 'network';
  }

  String _nmapDeviceName(String ip, Set<int> ports, String hostname) {
    final cleanHost = hostname.trim();
    if (cleanHost.isNotEmpty) return '$cleanHost ($ip)';
    if (ports.contains(5555)) return 'android-adb-wifi-$ip';
    if (ports.contains(8765) || ports.contains(8776)) {
      return 'engel-lan-worker-$ip';
    }
    if (ports.contains(11434)) return 'local-llm-node-$ip';
    if (ports.contains(445) || ports.contains(3389)) return 'windows-node-$ip';
    if (ports.contains(22)) return 'ssh-node-$ip';
    if (ports.any((p) => {80, 443, 8000, 8080}.contains(p))) {
      return 'web-ui-device-$ip';
    }
    if (ports.any((p) => {3000, 5173}.contains(p))) {
      return 'dev-server-device-$ip';
    }
    return 'open-port-device-$ip';
  }

  List<SwarmDeviceNode> _parseNmapDiscoveryNodes(
    String xml,
    Set<String> existingIps, {
    Map<String, LanCandidateIdentity> identities = const {},
    Map<String, String> candidateMacs = const {},
    Map<String, String> candidateStates = const {},
    Map<String, String> candidateInterfaces = const {},
  }) {
    final nodes = <SwarmDeviceNode>[];
    final seenIps = existingIps.where(_isPrivateIpv4).toSet();
    final hostRe = RegExp(r'<host\b[\s\S]*?</host>');
    final addressRe = RegExp(
      r'<address\s+[^>]*addr="([^"]+)"[^>]*addrtype="ipv4"',
    );
    final hostNameRe = RegExp(r'<hostname\b[^>]*name="([^"]+)"');
    final macAddressRe = RegExp(r'<address\s+([^>]*)addrtype="mac"([^>]*)>');
    final portBlockRe = RegExp(
      r'<port\b[^>]*portid="(\d+)"[^>]*>[\s\S]*?</port>',
    );
    final openStateRe = RegExp(r'<state\b[^>]*state="open"');
    final serviceRe = RegExp(r'<service\b([^>]*)>');
    for (final hostMatch in hostRe.allMatches(xml)) {
      final block = hostMatch.group(0) ?? '';
      final ip = addressRe.firstMatch(block)?.group(1) ?? '';
      if (!_isPrivateIpv4(ip) || seenIps.contains(ip)) continue;
      final ports = <int>{};
      final serviceByPort = <int, String>{};
      for (final portMatch in portBlockRe.allMatches(block)) {
        final portBlock = portMatch.group(0) ?? '';
        if (!openStateRe.hasMatch(portBlock)) continue;
        final port = int.tryParse(portMatch.group(1) ?? '');
        if (port == null) continue;
        ports.add(port);
        final serviceAttrs = serviceRe.firstMatch(portBlock)?.group(1) ?? '';
        final serviceSummary = _nmapServiceSummary(port, serviceAttrs);
        if (serviceSummary.isNotEmpty) serviceByPort[port] = serviceSummary;
      }
      if (ports.isEmpty) continue;
      seenIps.add(ip);
      final identity = identities[ip] ?? const LanCandidateIdentity();
      final nmapHostName = _cleanLanIdentityName(
        hostNameRe.firstMatch(block)?.group(1) ?? '',
      );
      final hostname = nmapHostName.isNotEmpty
          ? nmapHostName
          : identity.bestName;
      final macMatch = macAddressRe.firstMatch(block);
      final macAttrs = macMatch == null
          ? ''
          : '${macMatch.group(1) ?? ''} ${macMatch.group(2) ?? ''}';
      final nmapMac = _normalizeMac(_xmlAttribute(macAttrs, 'addr'));
      final mac = nmapMac.isNotEmpty ? nmapMac : (candidateMacs[ip] ?? '');
      final vendor = _xmlAttribute(macAttrs, 'vendor');
      final interfaceName = candidateInterfaces[ip] ?? '';
      final state = candidateStates[ip] ?? 'open-port responder';
      final idx = nodes.length;
      final angle = -2.4 + (idx * 0.58);
      final type = _nmapDeviceType(ports);
      final sortedPorts = ports.toList()..sort();
      final portSummary = sortedPorts
          .map((port) => serviceByPort[port] ?? port.toString())
          .join(', ');
      final deviceClass = _deviceClassFromPorts(ports);
      final summary = _deviceSummary(
        ip: ip,
        state: state,
        mac: mac,
        hostName: hostname,
        vendor: vendor,
        interfaceName: interfaceName,
        service: deviceClass,
        ports: portSummary,
      );
      nodes.add(
        SwarmDeviceNode(
          id: 'nmap-${ip.replaceAll('.', '-')}',
          name: _nmapDeviceName(ip, ports, hostname),
          type: type,
          status: 'nmap-ready',
          ip: ip,
          role: _nmapDeviceRole(ports),
          source: portableNmapExe,
          detail:
              'Nmap connect/version scan: $summary; Npcap-free portable scan.',
          macAddress: mac,
          hostName: hostname,
          vendor: vendor,
          interfaceName: interfaceName,
          deviceSummary: summary,
          evidence:
              'Observed by portable Nmap connect/version scan. $summary. Hostname from Nmap: ${hostname.trim().isEmpty ? "not returned" : hostname.trim()}.',
          openPorts: portSummary,
          x: math.cos(angle) * 7.8,
          y: 1.0 + (idx % 4) * 0.38,
          z: math.sin(angle) * 5.7,
          signal: ports.contains(8765) || ports.contains(8776) ? 84 : 72,
          load: ports.length.toDouble(),
          workers: type == 'windows' || type == 'llm' ? 2 : 1,
          trusted: false,
          autoMode: false,
          wifiGroup: 'nmap-lan',
        ),
      );
    }
    return nodes;
  }

  Future<NmapDiscoveryResult> _discoverSwarmDevicesWithNmap(
    List<String> candidateIps,
    Set<String> existingIps, {
    Map<String, LanCandidateIdentity> identities = const {},
    Map<String, String> candidateMacs = const {},
    Map<String, String> candidateStates = const {},
    Map<String, String> candidateInterfaces = const {},
  }) async {
    final nmapFile = File(portableNmapExe);
    if (!await nmapFile.exists()) {
      return const NmapDiscoveryResult(
        nodes: [],
        summary: 'Nmap: portable binary missing; install under runtime\\nmap.',
        targets: [],
        exitCode: null,
      );
    }
    final targets = await _nmapLanTargets(candidateIps);
    if (targets.isEmpty) {
      return const NmapDiscoveryResult(
        nodes: [],
        summary: 'Nmap: no private LAN target found from active adapters.',
        targets: [],
        exitCode: null,
      );
    }
    try {
      final result = await _processRunner(
        portableNmapExe,
        [
          '-n',
          '-Pn',
          '-sT',
          '-sV',
          '--version-light',
          '-T4',
          '--max-retries',
          '1',
          '--host-timeout',
          '12s',
          '-p',
          swarmNmapPorts,
          '-oX',
          '-',
          ...targets,
        ],
        workingDirectory: portableNmapRoot,
      ).timeout(const Duration(seconds: 95));
      final nodes = _parseNmapDiscoveryNodes(
        result.stdout.toString(),
        existingIps,
        identities: identities,
        candidateMacs: candidateMacs,
        candidateStates: candidateStates,
        candidateInterfaces: candidateInterfaces,
      );
      final warningLines = result.stderr
          .toString()
          .trim()
          .split('\n')
          .where((line) => line.trim().isNotEmpty);
      final warning = warningLines.isEmpty ? '' : warningLines.first.trim();
      final warningText = warning.isEmpty ? '' : '\nNmap warning: $warning';
      return NmapDiscoveryResult(
        nodes: nodes,
        targets: targets,
        exitCode: result.exitCode,
        summary:
            'Nmap: exit ${result.exitCode}; targets ${targets.join(", ")}; '
            '${nodes.length} open-port responders.$warningText',
      );
    } catch (e) {
      return NmapDiscoveryResult(
        nodes: const [],
        targets: targets,
        exitCode: null,
        summary: 'Nmap: scan error on ${targets.join(", ")}: $e',
      );
    }
  }

  /// Background snapshot refresh (timer-driven) so the device swarm state file
  /// stays current for the operator/3D view and external readers without anyone
  /// opening the page. Deliberately does NOT touch _status/_output — it must not
  /// hijack the visible status line — and swallows errors so the timer survives.
  Future<void> _refreshDeviceSwarmQuiet() async {
    try {
      await Future.wait([
        _scanDeviceVisibility(),
        _scanSubEngelSentWork(),
        _scanSubEngelSharedRoomQueues(),
        _refreshMeetingRoomServer(),
      ]);
      await _loadDeviceIdentityAudit();
      await _writeSwarmStateSnapshot(_swarmDevices(), reason: 'auto_refresh');
    } catch (_) {
      // best-effort; the next tick retries
    }
  }

  Future<void> _refreshDeviceSwarm() async {
    setState(() {
      _status = 'refreshing device swarm';
      _output = 'Refreshing live device swarm inputs from local status files.';
    });
    await Future.wait([
      _scanDeviceVisibility(),
      _scanSubEngelSentWork(),
      _scanSubEngelSharedRoomQueues(),
      _refreshMeetingRoomServer(),
    ]);
    await _loadDeviceIdentityAudit(refreshEvidence: true);
    final devices = _swarmDevices();
    await _writeSwarmStateSnapshot(devices);
    if (!mounted) return;
    setState(() {
      _status = 'device swarm refreshed';
      _output =
          'Device Swarm 3D refreshed.\n'
          'Audited records visible: ${devices.length}\n'
          'Snapshot: $deviceSwarmStatePath\n'
          'This is an operator-visible swarm view; it does not mutate shared queues.';
    });
  }

  Future<void> _scanLanForSwarmDevices() async {
    if (_running) return;
    setState(() {
      _running = true;
      _lanScanStatus = 'scanning LAN/WiFi...';
      _status = 'LAN scan active';
      _output =
          'Starting real WiFi/LAN device discovery for swarm cluster...\n'
          'Probing reachable ARP neighbors + DNS/NetBIOS names + port 8765 (LAN pairing) + 5555 (ADB WiFi) + portable Nmap service scan.';
    });
    final discovered = <SwarmDeviceNode>[];
    var nmapSummary = 'Nmap: not run.';
    try {
      // Real LAN discovery via PowerShell (no C: writes). Get recent IPv4 neighbors.
      final psCmd =
          r'''Get-NetNeighbor -AddressFamily IPv4 | Where-Object { $state = $_.State.ToString(); $ip = $_.IPAddress; $state -in @("Reachable","Stale","Delay","Probe","Permanent") -and $ip -notlike "169.254.*" -and $ip -notlike "127.*" -and $ip -notlike "224.*" -and $ip -notlike "255.*" } | Sort-Object State,IPAddress | Select-Object -First 32 -Property IPAddress,LinkLayerAddress,State,InterfaceAlias | ConvertTo-Json -Compress''';
      final arpResult = await _processRunner('powershell.exe', [
        '-NoProfile',
        '-Command',
        psCmd,
      ], workingDirectory: appRoot).timeout(const Duration(seconds: 25));
      List<String> candidateIps = [];
      final candidateDetails = <String, String>{};
      final candidateMacs = <String, String>{};
      final candidateStates = <String, String>{};
      final candidateInterfaces = <String, String>{};
      if (arpResult.exitCode == 0) {
        try {
          final decoded = jsonDecode(arpResult.stdout.toString().trim());
          final list = decoded is List
              ? decoded
              : (decoded is Map && decoded['value'] is List
                    ? decoded['value']
                    : []);
          for (final item in list) {
            if (item is Map) {
              final ip = (item['IPAddress'] ?? '').toString().trim();
              if (ip.isNotEmpty &&
                  (ip.startsWith('192.168.') ||
                      ip.startsWith('10.') ||
                      ip.startsWith('172.'))) {
                candidateIps.add(ip);
                final mac = _normalizeMac(
                  (item['LinkLayerAddress'] ?? '').toString(),
                );
                final state = _neighborStateLabel(item['State']);
                final interfaceName = (item['InterfaceAlias'] ?? '')
                    .toString()
                    .trim();
                candidateMacs[ip] = mac;
                candidateStates[ip] = state;
                if (interfaceName.isNotEmpty) {
                  candidateInterfaces[ip] = interfaceName;
                }
                candidateDetails[ip] =
                    'Windows neighbor table: state=$state; MAC=${mac.isEmpty ? "not returned" : mac}; interface=${interfaceName.isEmpty ? "not returned" : interfaceName}';
              }
            }
          }
        } catch (_) {}
      }
      if (candidateIps.isEmpty) {
        // Fallback: arp -a parse
        final arp2 = await _processRunner('arp', [
          '-a',
        ], workingDirectory: appRoot).timeout(const Duration(seconds: 10));
        final lines = arp2.stdout.toString().split('\n');
        final ipRe = RegExp(r'(\d{1,3}(?:\.\d{1,3}){3})');
        for (final line in lines) {
          final m = ipRe.firstMatch(line);
          if (m != null) {
            final ip = m.group(1)!;
            if ((ip.startsWith('192.168.') ||
                    ip.startsWith('10.') ||
                    ip.startsWith('172.')) &&
                !ip.endsWith('.1') &&
                !ip.endsWith('.255')) {
              candidateIps.add(ip);
              final mac = _normalizeMac(line);
              if (mac.isNotEmpty) candidateMacs[ip] = mac;
              candidateStates[ip] = 'ARP dynamic';
              candidateDetails[ip] =
                  'Windows ARP table: MAC=${mac.isEmpty ? "not returned" : mac}; raw=${line.trim()}';
            }
          }
        }
      }
      candidateIps.addAll(
        [
          _extractIp(_deviceVisibility.linkStatus),
          _extractIp(_deviceVisibility.receiver),
          _extractIp(_deviceVisibility.pairedPhone),
          _extractIp(_deviceVisibility.nodeReady),
          for (final row in _deviceVisibility.androidWorkers) _extractIp(row),
        ].where(_isPrivateIpv4),
      );
      candidateIps = candidateIps.toSet().toList().take(64).toList(); // bounded
      final candidateIdentities = await _lookupLanCandidateIdentities(
        candidateIps,
      );

      final client = HttpClient();
      client.connectionTimeout = const Duration(seconds: 2);
      int probed = 0;
      for (final ip in candidateIps) {
        probed++;
        bool found = false;
        String label = "discovered-$ip";
        String detail = 'LAN probe';
        // Probe LAN pairing health (port 8765)
        try {
          final req = await client
              .getUrl(Uri.parse('http://$ip:8765/health'))
              .timeout(const Duration(seconds: 3));
          final resp = await req.close().timeout(const Duration(seconds: 3));
          final body = await resp.transform(utf8.decoder).join();
          if (resp.statusCode == 200 ||
              body.toLowerCase().contains('engel') ||
              body.toLowerCase().contains('ok') ||
              body.toLowerCase().contains('worker')) {
            found = true;
            label = "lan-worker-$ip";
            detail =
                'LAN pairing responder at :8765 (status ${resp.statusCode})';
          }
        } catch (_) {}
        // Probe ADB-over-wifi default if not found
        if (!found) {
          try {
            final req = await client
                .getUrl(Uri.parse('http://$ip:5555'))
                .timeout(const Duration(seconds: 2));
            final resp = await req.close().timeout(const Duration(seconds: 2));
            if (resp.statusCode < 500) {
              found = true;
              label = "adb-wifi-$ip";
              detail = 'Possible ADB WiFi device (port 5555 responded)';
            }
          } catch (_) {}
        }
        if (found) {
          final idx = discovered.length;
          final angle = 2.1 + (idx * 0.7);
          final identity =
              candidateIdentities[ip] ?? const LanCandidateIdentity();
          final hostName = identity.bestName;
          final mac = candidateMacs[ip] ?? '';
          final state = candidateStates[ip] ?? '';
          final interfaceName = candidateInterfaces[ip] ?? '';
          final openPorts = label.startsWith('adb-wifi-')
              ? '5555 adb-wifi'
              : '8765 engel-lan-health';
          final service = label.startsWith('adb-wifi-')
              ? 'Android ADB WiFi'
              : 'Engel LAN worker';
          final summary = _deviceSummary(
            ip: ip,
            state: state,
            mac: mac,
            hostName: hostName,
            vendor: '',
            interfaceName: interfaceName,
            service: service,
            ports: openPorts,
          );
          discovered.add(
            SwarmDeviceNode(
              id: "lan-${ip.replaceAll('.', '-')}-$idx",
              name: _deviceDisplayName(
                ip: ip,
                fallback: label,
                hostName: hostName,
                service: service,
              ),
              type: label.startsWith('adb-wifi-') ? 'android' : 'wifi',
              status: 'discovered',
              ip: ip,
              role: 'worker',
              source: 'lan-scan',
              detail: '$detail; $summary',
              macAddress: mac,
              hostName: hostName,
              interfaceName: interfaceName,
              deviceSummary: summary,
              evidence:
                  '${candidateDetails[ip] ?? "Candidate came from LAN scan inputs"}; service probe: $detail',
              openPorts: openPorts,
              x: math.cos(angle) * 6.8,
              y: 1.6 + (idx % 2) * 0.6,
              z: math.sin(angle) * 5.1,
              signal: 65 + (idx % 25),
              load: 5,
              workers: 1,
              trusted: false,
              autoMode: false,
              wifiGroup: 'wifi-lan-scan',
            ),
          );
        }
        if (probed % 4 == 0) {
          await Future.delayed(const Duration(milliseconds: 80));
        }
      }
      client.close();
      // Also always include any adb usb devices via adb (D: path only)
      try {
        final adbPath = '$appRoot\\tools\\platform-tools\\adb.exe';
        final adbRes = await _processRunner(adbPath, [
          'devices',
        ], workingDirectory: appRoot).timeout(const Duration(seconds: 12));
        final adbOut = adbRes.stdout.toString();
        final devRe = RegExp(r'^([A-Za-z0-9]+)\s+device', multiLine: true);
        for (final m in devRe.allMatches(adbOut)) {
          final ser = m.group(1)!;
          final idx = discovered.length;
          final angle = 0.6 + idx * 0.55;
          discovered.add(
            SwarmDeviceNode(
              id: "adb-usb-$ser",
              name: "android-adb-$ser",
              type: 'android',
              status: 'usb-online',
              ip: ser,
              role: 'worker',
              source: adbPath,
              detail: 'ADB USB device (use adb tcpip to enable WiFi)',
              x: math.cos(angle) * 7.5,
              y: 0.8 + (idx % 3) * 0.5,
              z: math.sin(angle) * 4.8,
              signal: 88,
              load: 10,
              workers: 1,
              trusted: true,
              autoMode: false,
              wifiGroup: 'adb',
            ),
          );
        }
      } catch (_) {}
      final nmapResult = await _discoverSwarmDevicesWithNmap(
        candidateIps,
        discovered.map((device) => device.ip).toSet(),
        identities: candidateIdentities,
        candidateMacs: candidateMacs,
        candidateStates: candidateStates,
        candidateInterfaces: candidateInterfaces,
      );
      nmapSummary = nmapResult.summary;
      discovered.addAll(nmapResult.nodes);
      final discoveredIps = discovered.map((device) => device.ip).toSet();
      for (final ip in candidateIps) {
        if (discoveredIps.contains(ip)) continue;
        final idx = discovered.length;
        final angle = 1.2 + idx * 0.42;
        final mac = candidateMacs[ip] ?? '';
        final state = candidateStates[ip] ?? 'unknown';
        final interfaceName = candidateInterfaces[ip] ?? '';
        final identity =
            candidateIdentities[ip] ?? const LanCandidateIdentity();
        final hostName = identity.bestName;
        final summary = _deviceSummary(
          ip: ip,
          state: state,
          mac: mac,
          hostName: hostName,
          vendor: '',
          interfaceName: interfaceName,
          service: 'no Engel/ADB service found',
          ports: '',
        );
        discovered.add(
          SwarmDeviceNode(
            id: 'neighbor-${ip.replaceAll('.', '-')}',
            name: _deviceDisplayName(
              ip: ip,
              fallback: 'unidentified-lan-neighbor-$ip',
              hostName: hostName,
            ),
            type: 'wifi',
            status: 'lan-seen',
            ip: ip,
            role: 'unassigned',
            source: 'windows-neighbor-arp',
            detail:
                '${candidateDetails[ip] ?? "Seen in Windows neighbor/ARP table"}; no Engel/ADB open service detected yet; $summary',
            macAddress: mac,
            hostName: hostName,
            interfaceName: interfaceName,
            deviceSummary: summary,
            evidence:
                'Observed locally by Windows neighbor/ARP table. $summary. No Engel/ADB open service detected in this scan.',
            x: math.cos(angle) * 8.2,
            y: 0.6 + (idx % 5) * 0.28,
            z: math.sin(angle) * 5.9,
            signal: 52,
            load: 0,
            workers: 0,
            trusted: false,
            autoMode: false,
            wifiGroup: 'lan-neighbor',
          ),
        );
        discoveredIps.add(ip);
      }
      if (!mounted) return;
      setState(() {
        _discoveredSwarmDevices
          ..clear()
          ..addAll(discovered);
        _lanScanStatus = discovered.isEmpty
            ? 'no responders found'
            : '${discovered.length} discovered';
        _status = 'LAN scan complete';
        _output =
            'Real LAN/WiFi scan complete.\nCandidates probed: ${candidateIps.length}\nAdded: ${discovered.length} visible LAN candidates to swarm.\n'
            '$nmapSummary\n'
            'Use "Add to Cluster" or manual Add for any; discovered marked in roster.\n'
            'Discovered IPs: ${discovered.map((d) => d.ip).join(", ")}\n'
            'Note: to fully pair use LAN pairing server + worker app pairing code.';
      });
      final all = _swarmDevices();
      await _writeSwarmStateSnapshot(all, reason: 'lan_scan');
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _lanScanStatus = 'scan error';
        _status = 'scan failed';
        _output =
            'LAN scan error: $e\n(Used only local net commands + bounded probes. No C: writes.)';
      });
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  Future<void> _runRealAndroidLanStatus() async {
    if (_running) return;
    final py = await _findStandaloneChatPython();
    if (py == null) {
      setState(() {
        _status = 'python runtime missing';
        _output = 'No D: runtime python310 found. Expected $runtimePythonExe';
      });
      return;
    }
    setState(() {
      _running = true;
      _status = 'python adb+lan status';
      _lastCommand = '${py.path} -c "android+lan real status"';
      _output =
          'Invoking real status via Python runtime (D: only) + ADB (D: tools)...';
    });
    try {
      // Use direct adb (D: enforced) + lan state file read + simple python probe
      final adb = '$appRoot\\tools\\platform-tools\\adb.exe';
      final adbRes = await _processRunner(adb, [
        'devices',
        '-l',
      ], workingDirectory: appRoot).timeout(const Duration(seconds: 15));
      final lanFile = File(lanSessionStatePath);
      String lanTxt = 'LAN state file missing';
      if (await lanFile.exists()) {
        lanTxt = await lanFile.readAsString();
      }
      // Call python to get more if the module exposes, else just report files + adb
      final pyRes = await _processRunner(
        py.path,
        [
          '-c',
          'import sys, os; print("PY_EXE:", sys.executable); print("APP_ROOT_OK_D_EXISTS:", os.path.isdir(r"D:\\b.WorkSpace\\Engel App")); print("LAN_STATE_PATH:", r"$lanSessionStatePath"); print("SIMPLE_STATUS_DONE")',
        ],
        workingDirectory: appRoot,
        environment: {'ENGEL_APP_ROOT': appRoot},
      ).timeout(const Duration(seconds: 25));
      if (!mounted) return;
      setState(() {
        _output =
            'Real Python+ADB+LAN status:\n\nADB:\n${adbRes.stdout}\n\nLAN_STATE:\n$lanTxt\n\nPY:\n${pyRes.stdout}\n\nstderr:${pyRes.stderr}';
        _status = 'real status done';
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _output = 'Real status error (safe, D: only): $e';
        _status = 'status error';
      });
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  Future<void> _writeSwarmStateSnapshot(
    List<SwarmDeviceNode> devices, {
    String reason = 'operator_snapshot',
  }) async {
    final file = File(deviceSwarmStatePath);
    await file.parent.create(recursive: true);
    const encoder = JsonEncoder.withIndent('  ');
    final payload = {
      'schema': 'engel_device_swarm_state_v1',
      'reason': reason,
      'written_at_utc': DateTime.now().toUtc().toIso8601String(),
      'source': 'Engel AI Main Flutter Device Swarm 3D',
      'policy':
          'operator-visible local state only; no trusted memory write; no shared queue mutation',
      'devices': [for (final device in devices) device.toJson()],
    };
    await file.writeAsString('${encoder.convert(payload)}\n');
  }

