  Future<void> _identifySwarmDevice(SwarmDeviceNode device) async {
    if (_running) return;
    if (!_isPrivateIpv4(device.ip)) {
      setState(() {
        _status = 'identify skipped';
        _output =
            'Cannot run LAN identify for ${device.name} because route "${device.ip}" is not a private IPv4 address.';
      });
      return;
    }
    setState(() {
      _running = true;
      _status = 'identifying device';
      _output =
          'Identifying ${device.name} at ${device.ip} with local Windows tools and portable Nmap.';
    });
    var netbios = 'NetBIOS lookup not run.';
    var nmap = 'Nmap lookup not run.';
    try {
      try {
        final result = await _processRunner('nbtstat', [
          '-A',
          device.ip,
        ], workingDirectory: appRoot).timeout(const Duration(seconds: 10));
        netbios =
            'nbtstat exit ${result.exitCode}\n${result.stdout}${result.stderr}'
                .trim();
      } catch (e) {
        netbios = 'nbtstat error: $e';
      }
      try {
        final result = await _processRunner(
          portableNmapExe,
          [
            '-n',
            '-Pn',
            '-sT',
            '-sV',
            '--version-light',
            '-T4',
            '--max-retries',
            '1',
            '--host-timeout',
            '8s',
            '-p',
            swarmNmapPorts,
            device.ip,
          ],
          workingDirectory: portableNmapRoot,
        ).timeout(const Duration(seconds: 18));
        nmap = 'nmap exit ${result.exitCode}\n${result.stdout}${result.stderr}'
            .trim();
      } catch (e) {
        nmap = 'nmap error: $e';
      }
      final evidence =
          'Device identify proof\n'
          'Name: ${device.name}\n'
          'IP: ${device.ip}\n'
          'Host: ${device.hostName.isEmpty ? "not known from current scan" : device.hostName}\n'
          'MAC: ${device.macAddress.isEmpty ? "not known from current scan" : device.macAddress}\n'
          'Vendor: ${device.vendor.isEmpty ? "not known from current scan" : device.vendor}\n'
          'Interface: ${device.interfaceName.isEmpty ? "not known from current scan" : device.interfaceName}\n'
          'Open ports: ${device.openPorts.isEmpty ? "not known from current scan" : device.openPorts}\n'
          'Identity summary: ${device.deviceSummary.isEmpty ? "not known from current scan" : device.deviceSummary}\n'
          'Existing evidence: ${device.evidence.isEmpty ? device.detail : device.evidence}\n\n'
          '$netbios\n\n'
          '$nmap';
      if (!mounted) return;
      setState(() {
        _swarmIdentificationEvidence[device.id] = evidence;
        _status = 'device identify complete';
        _output = evidence;
      });
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

