  Future<void> _scanSubEngelSentWork() async {
    try {
      final dir = Directory(subEngelSentWorkDir);
      if (!await dir.exists()) {
        if (!mounted) return;
        setState(() {
          _subEngelSentWork = const SubEngelSentWorkInfo(
            path: subEngelSentWorkDir,
            exists: false,
            fileCount: 0,
            latestFile: '',
            latestBytes: 0,
            latestModified: null,
            error: '',
          );
        });
        return;
      }

      final files = <File>[];
      await for (final entity in dir.list(followLinks: false)) {
        if (entity is File) files.add(entity);
      }
      files.sort((a, b) {
        final aModified = a.statSync().modified;
        final bModified = b.statSync().modified;
        return bModified.compareTo(aModified);
      });

      var latestFile = '';
      var latestBytes = 0;
      DateTime? latestModified;
      if (files.isNotEmpty) {
        final latest = files.first;
        final stat = await latest.stat();
        latestFile = latest.path;
        latestBytes = stat.size;
        latestModified = stat.modified;
      }

      if (!mounted) return;
      setState(() {
        _subEngelSentWork = SubEngelSentWorkInfo(
          path: subEngelSentWorkDir,
          exists: true,
          fileCount: files.length,
          latestFile: latestFile,
          latestBytes: latestBytes,
          latestModified: latestModified,
          error: '',
        );
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _subEngelSentWork = SubEngelSentWorkInfo(
          path: subEngelSentWorkDir,
          exists: false,
          fileCount: 0,
          latestFile: '',
          latestBytes: 0,
          latestModified: null,
          error: error.toString(),
        );
      });
    }
  }

  Future<void> _scanSubEngelSharedRoomQueues() async {
    try {
      final workOrdersDir = Directory(subEngelWorkOrdersDir);
      final sentWorkDir = Directory(subEngelSentWorkDir);
      final workOrdersExist = await workOrdersDir.exists();
      final sentWorkExist = await sentWorkDir.exists();

      final workOrders = workOrdersExist
          ? await _listFilesByModified(workOrdersDir, extension: '.json')
          : <File>[];
      final sentWork = sentWorkExist
          ? await _listFilesByModified(sentWorkDir, extension: '.json')
          : <File>[];

      final latestOrderStat = workOrders.isEmpty
          ? null
          : await workOrders.first.stat();
      final latestSentStat = sentWork.isEmpty
          ? null
          : await sentWork.first.stat();

      if (!mounted) return;
      setState(() {
        _subEngelSharedRoomQueue = SubEngelSharedRoomQueueInfo(
          workOrdersPath: subEngelWorkOrdersDir,
          sentWorkPath: subEngelSentWorkDir,
          workOrdersExist: workOrdersExist,
          sentWorkExist: sentWorkExist,
          workOrderCount: workOrders.length,
          sentWorkCount: sentWork.length,
          latestWorkOrder: workOrders.isEmpty ? '' : workOrders.first.path,
          latestSentWork: sentWork.isEmpty ? '' : sentWork.first.path,
          latestWorkOrderBytes: latestOrderStat?.size ?? 0,
          latestSentWorkBytes: latestSentStat?.size ?? 0,
          latestWorkOrderModified: latestOrderStat?.modified,
          latestSentWorkModified: latestSentStat?.modified,
          error: '',
        );
        _subEngelSentWork = SubEngelSentWorkInfo(
          path: subEngelSentWorkDir,
          exists: sentWorkExist,
          fileCount: sentWork.length,
          latestFile: sentWork.isEmpty ? '' : sentWork.first.path,
          latestBytes: latestSentStat?.size ?? 0,
          latestModified: latestSentStat?.modified,
          error: '',
        );
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _subEngelSharedRoomQueue = SubEngelSharedRoomQueueInfo(
          workOrdersPath: subEngelWorkOrdersDir,
          sentWorkPath: subEngelSentWorkDir,
          workOrdersExist: false,
          sentWorkExist: false,
          workOrderCount: 0,
          sentWorkCount: 0,
          latestWorkOrder: '',
          latestSentWork: '',
          latestWorkOrderBytes: 0,
          latestSentWorkBytes: 0,
          latestWorkOrderModified: null,
          latestSentWorkModified: null,
          error: error.toString(),
        );
      });
    }
  }

  Future<List<File>> _listFilesByModified(
    Directory dir, {
    String? extension,
  }) async {
    final files = <File>[];
    await for (final entity in dir.list(followLinks: false)) {
      if (entity is! File) continue;
      if (extension != null && !entity.path.toLowerCase().endsWith(extension)) {
        continue;
      }
      files.add(entity);
    }
    files.sort((a, b) {
      final aModified = a.statSync().modified;
      final bModified = b.statSync().modified;
      return bModified.compareTo(aModified);
    });
    return files;
  }

  // --- Engel Tool Gates: real operator permissions -------------------------
  // Each gated route runs ONLY while its switch is on. State persists to a
  // JSON policy file (read-able by backend tools) and is enforced right here
  // at the single command choke point - the switches are law, not decoration.
  static const String toolGatePolicyPath =
      '$appRoot\\runtime\\ui\\engel_tool_gates.json';
  static const Map<String, String> gatedToolCommands = {
    'bundled_git_nexus_install': 'GitNexus install',
    'bundled_jarvis_install': 'Jarvis install',
    'bundled_jarvis_start': 'Jarvis start',
    'bundled_chat_ui_start': 'Chat UI start',
    'bundled_octogent_start': 'Octogent start',
    'bundled_claw3d_start': 'Claw3D start',
    'bundled_cubesandbox_install': 'CubeSandbox install',
    'bundled_engelBridge_agent_start': 'Imported agent start',
    'bundled_localsend_install': 'LocalSend install',
    'bundled_darwinian_run': 'Darwinian evolver run',
    'minor_humanizer_invoke': 'Humanizer invoke',
    'minor_native_agent_dashboard': 'Native agent dashboard',
    'minor_ide_install': 'IDE project install',
    'minor_kg_build': 'Knowledge graph build',
    'minor_evolution_run': 'Evolution engine run',
  };
  Map<String, bool> _toolGates = {};
  var _toolGatesLoaded = false;

  void _ensureToolGatesLoaded() {
    if (_toolGatesLoaded) return;
    _toolGatesLoaded = true;
    try {
      final file = File(toolGatePolicyPath);
      if (file.existsSync()) {
        final data = jsonDecode(file.readAsStringSync());
        if (data is Map<String, dynamic>) {
          _toolGates = {
            for (final entry in data.entries)
              if (entry.value is bool) entry.key: entry.value as bool,
          };
        }
      }
    } catch (_) {
      _toolGates = {};
    }
  }

  bool _toolGateAllowed(String key) {
    _ensureToolGatesLoaded();
    return _toolGates[key] ?? false;
  }

  void _setToolGate(String key, bool allowed) {
    _ensureToolGatesLoaded();
    setState(() => _toolGates[key] = allowed);
    try {
      final file = File(toolGatePolicyPath);
      file.parent.createSync(recursive: true);
      file.writeAsStringSync(
        const JsonEncoder.withIndent(
          '  ',
        ).convert({'schema': 'engel_tool_gates_v1', ..._toolGates}),
      );
    } catch (error) {
      setState(() => _output = 'Tool gate save failed: $error');
    }
  }

  Future<void> _runRust(RustCommand command, [String text = '']) async {
    if (_running) return;
    if (gatedToolCommands.containsKey(command.key) &&
        !_toolGateAllowed(command.key)) {
      setState(() {
        _output =
            'BLOCKED: ${command.label} is gated OFF.\n'
            'Flip its switch on the Tool Gates page to allow this action.\n'
            'Gate policy: $toolGatePolicyPath';
        _status = 'gate blocked';
      });
      return;
    }
    final exe = await _findRustExe();
    if (exe == null) {
      // Portable flash-drive builds intentionally do not ship the development
      // Rust helper (it embeds this computer's absolute paths).  Keep the
      // local Terminal & Files read-only actions useful instead of surfacing a
      // dead-end "Rust executable not found" message.
      if (await _runPortableTerminalFilesFallback(command, text)) return;
      setState(() {
        _output =
            'Rust executable not found.\nSearched runtime cargo target paths.';
        _status = 'rust missing';
      });
      return;
    }
    if (command.needsText && text.trim().isEmpty) {
      setState(() {
        _output =
            '${command.label} is wired but needs operator text.\nRoute: ${exe.path} ${command.args.join(' ')} <text>\nNo fake result was generated.';
        _status = 'needs text';
      });
      return;
    }
    final args = [...command.args];
    if (command.needsText) args.add(text.trim());
    setState(() {
      _running = true;
      _status = 'running ${command.label}';
      _lastCommand = '${exe.path} ${args.join(' ')}';
      _output = 'Running real command:\n$_lastCommand';
    });
    try {
      final sw = Stopwatch()..start();
      final result = await _processRunner(
        exe.path,
        args,
        workingDirectory: appRoot,
        environment: {
          'ENGEL_APP_ROOT': appRoot,
          'ENGEL_WORKSPACE_ROOT': appRoot,
          'ENGEL_AI_RS_EXE': exe.path,
          'TEMP': engelTempRoot,
          'TMP': engelTempRoot,
          'TMPDIR': engelTempRoot,
          'CARGO_HOME': engelCargoHome,
        },
      ).timeout(const Duration(seconds: 120));
      sw.stop();
      final stdoutText = _pretty(result.stdout.toString());
      final stderrText = result.stderr.toString().trim();
      setState(() {
        _output = [
          'Command: $_lastCommand',
          'Exit: ${result.exitCode}',
          'Elapsed: ${sw.elapsedMilliseconds} ms',
          if (stdoutText.isNotEmpty) 'stdout:\n$stdoutText',
          if (stderrText.isNotEmpty) 'stderr:\n$stderrText',
        ].join('\n\n');
        _status = result.exitCode == 0 ? 'done' : 'exit ${result.exitCode}';
      });
    } on TimeoutException {
      setState(() {
        _output = 'TIMEOUT after 120s\nCommand: $_lastCommand';
        _status = 'timeout';
      });
    } catch (error) {
      setState(() {
        _output = 'ERROR: $error\nCommand: $_lastCommand';
        _status = 'error';
      });
    } finally {
      if (mounted) {
        setState(() {
          _running = false;
        });
      }
    }
  }

  Future<void> _runXaiGrokCliInstaller({required bool install}) async {
    if (_running) return;
    final script = File(xaiGrokCliInstallScriptPath);
    if (!await script.exists()) {
      setState(() {
        _status = 'xAI Grok installer missing';
        _output =
            'xAI/Grok CLI installer wrapper was not found.\nExpected $xaiGrokCliInstallScriptPath';
      });
      return;
    }
    final args = [
      '-NoProfile',
      '-ExecutionPolicy',
      'Bypass',
      '-File',
      xaiGrokCliInstallScriptPath,
      '-Mode',
      install ? 'install' : 'status',
      if (install) ...['-Approve', xaiGrokCliInstallApproval],
    ];
    setState(() {
      _running = true;
      _status = install ? 'installing xAI Grok CLI' : 'checking xAI Grok CLI';
      _lastCommand = 'powershell.exe ${args.join(' ')}';
      _output = [
        'Running real command:',
        _lastCommand,
        '',
        'Engel stores the installer receipt and binaries under its D:/runtime path.',
      ].join('\n');
    });
    try {
      final sw = Stopwatch()..start();
      final result = await _processRunner(
        'powershell.exe',
        args,
        workingDirectory: appRoot,
        environment: {
          'ENGEL_APP_ROOT': appRoot,
          'TEMP': engelTempRoot,
          'TMP': engelTempRoot,
          'TMPDIR': engelTempRoot,
          'CARGO_HOME': engelCargoHome,
        },
      ).timeout(Duration(seconds: install ? 360 : 45));
      sw.stop();
      final stdoutText = _pretty(result.stdout.toString());
      final stderrText = result.stderr.toString().trim();
      setState(() {
        _output = [
          'Command: $_lastCommand',
          'Exit: ${result.exitCode}',
          'Elapsed: ${sw.elapsedMilliseconds} ms',
          if (stdoutText.isNotEmpty) 'receipt json:\n$stdoutText',
          if (stderrText.isNotEmpty) 'stderr:\n$stderrText',
        ].join('\n\n');
        _status = result.exitCode == 0
            ? (install ? 'xAI Grok CLI installed' : 'xAI Grok CLI ready')
            : 'xAI Grok CLI exit ${result.exitCode}';
      });
    } on TimeoutException {
      setState(() {
        _output =
            'TIMEOUT while ${install ? 'installing' : 'checking'} xAI/Grok CLI\nCommand: $_lastCommand';
        _status = 'xAI Grok timeout';
      });
    } catch (error) {
      setState(() {
        _output = 'ERROR: $error\nCommand: $_lastCommand';
        _status = 'xAI Grok error';
      });
    } finally {
      if (mounted) {
        setState(() {
          _running = false;
        });
      }
    }
  }

  /// Runs the Engel CLI account helper (status / install / login) for a
  /// provider CLI (Claude Code, Codex, Grok). Install/login are approval-gated
  /// and confined to Engel's D: runtime.
  Future<void> _runCliAccountAction({
    required String provider,
    required String mode,
    String accountId = 'primary',
  }) async {
    if (_running) return;
    final script = File(engelCliAccountLoginScriptPath);
    if (!await script.exists()) {
      setState(() {
        _status = 'CLI login helper missing';
        _output =
            'Engel CLI account login helper not found.\nExpected $engelCliAccountLoginScriptPath';
      });
      return;
    }
    final args = [
      '-NoProfile',
      '-ExecutionPolicy',
      'Bypass',
      '-File',
      engelCliAccountLoginScriptPath,
      '-Provider',
      provider,
      '-Mode',
      mode,
      if (accountId.trim().isNotEmpty && accountId.trim() != 'primary')
        ...['-AccountId', accountId.trim()],
      if (mode != 'status') ...['-Approve', engelCliAccountLoginApproval],
    ];
    setState(() {
      _running = true;
      _status = '$provider CLI $mode';
      _lastCommand = 'powershell.exe ${args.join(' ')}';
      _output = 'Running real command:\n$_lastCommand';
    });
    try {
      final result = await _processRunner(
        'powershell.exe',
        args,
        workingDirectory: appRoot,
        environment: {
          'ENGEL_APP_ROOT': appRoot,
          'TEMP': engelTempRoot,
          'TMP': engelTempRoot,
          'TMPDIR': engelTempRoot,
        },
      ).timeout(Duration(seconds: mode == 'install' ? 360 : 45));
      final stdoutText = _pretty(result.stdout.toString());
      final stderrText = result.stderr.toString().trim();
      if (!mounted) return;
      setState(() {
        _output = [
          'Command: $_lastCommand',
          'Exit: ${result.exitCode}',
          if (stdoutText.isNotEmpty) 'receipt:\n$stdoutText',
          if (stderrText.isNotEmpty) 'stderr:\n$stderrText',
        ].join('\n\n');
        _status = result.exitCode == 0
            ? '$provider CLI $mode ok'
            : '$provider CLI $mode exit ${result.exitCode}';
      });
      _showConnectorSnack(
        mode == 'login'
            ? '$provider sign-in window launched — finish the browser OAuth there.'
            : mode == 'install'
            ? '$provider CLI install: exit ${result.exitCode}'
            : '$provider CLI status checked.',
        ok: result.exitCode == 0,
      );
    } on TimeoutException {
      if (mounted) {
        setState(() {
          _status = '$provider CLI timeout';
          _output = 'TIMEOUT during $provider CLI $mode.';
        });
      }
    } catch (error) {
      if (mounted) {
        setState(() {
          _status = '$provider CLI error';
          _output = 'ERROR during $provider CLI $mode:\n$error';
        });
      }
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  /// Installed/signed-in state for a CLI account, read from its newest receipt.
  ({Color color, String label, bool installed}) _cliAccountStatus(
    String provider,
  ) {
    try {
      final dir = Directory('$appRoot\\reports\\cli_accounts');
      if (!dir.existsSync()) {
        return (
          color: const Color(0xff777984),
          label: 'unknown — tap Check',
          installed: false,
        );
      }
      final prefix = 'CLI_${provider.toUpperCase()}_';
      final files =
          dir
              .listSync()
              .whereType<File>()
              .where(
                (f) => f.uri.pathSegments.last.toUpperCase().startsWith(prefix),
              )
              .toList()
            ..sort((a, b) => a.path.compareTo(b.path));
      if (files.isEmpty) {
        return (
          color: const Color(0xff777984),
          label: 'unknown — tap Check',
          installed: false,
        );
      }
      final data = jsonDecode(files.last.readAsStringSync());
      final installed = data is Map && data['installed'] == true;
      final loggedIn = data is Map && data['logged_in'] == true;
      if (loggedIn) {
        return (
          color: const Color(0xff00e87a),
          label: 'Signed in',
          installed: true,
        );
      }
      if (installed) {
        return (
          color: const Color(0xffd9a441),
          label: 'Installed · not signed in',
          installed: true,
        );
      }
      return (
        color: const Color(0xff777984),
        label: 'Not installed',
        installed: false,
      );
    } catch (_) {
      return (
        color: const Color(0xff777984),
        label: 'unknown',
        installed: false,
      );
    }
  }

  List<Map<String, dynamic>> _providerPoolAccounts(String provider) {
    try {
      final file = File(
        '$appRoot\\memory\\personality\\ENGEL_PROVIDER_ACCOUNT_POOL.json',
      );
      if (!file.existsSync()) return const [];
      final decoded = jsonDecode(file.readAsStringSync());
      if (decoded is! Map) return const [];
      final providers = decoded['providers'];
      if (providers is! Map) return const [];
      final row = providers[provider];
      if (row is! Map) return const [];
      final accounts = row['accounts'];
      if (accounts is! List) return const [];
      return [
        for (final item in accounts)
          if (item is Map)
            {
              'id': '${item['id'] ?? ''}',
              'label': '${item['label'] ?? item['id'] ?? provider}',
              'status': '${item['status'] ?? ''}',
            },
      ];
    } catch (_) {
      return const [];
    }
  }

  List<EngelCliAccount> _visibleCliAccounts() {
    final rows = <EngelCliAccount>[];
    for (final account in engelCliAccounts) {
      rows.add(account);
      for (final extra in _providerPoolAccounts(account.key)) {
        final id = extra['id'] ?? '';
        if (id.isEmpty || id == 'primary' || id == 'default' || id == 'super') {
          continue;
        }
        final status = extra['status'] ?? '';
        rows.add(
          EngelCliAccount(
            key: account.key,
            name: '${account.name} · $id',
            detail: status == 'needs_login'
                ? 'Extra sign-in slot. Tap Login, finish the browser, then Check.'
                : 'Extra ${account.key} account ($status). Engel switches here when usage runs out.',
            accountId: id,
          ),
        );
      }
    }
    return rows;
  }

