  /// Drives the Grok Imagine browser worker (real Chromium via Playwright):
  /// status / login (visible sign-in) / imagine (generate + download).
  Future<void> _runGrokImagine(String mode) async {
    if (_running) return;
    final args = <String>[grokImagineWorkerScriptPath, mode];
    if (mode == 'imagine') {
      final prompt = _grokImaginePromptText.text.trim();
      if (prompt.isEmpty) {
        setState(() => _status = 'enter a prompt for Grok Imagine');
        _showConnectorSnack('Type a prompt first.', ok: false);
        return;
      }
      args.addAll([prompt, '--type', _grokImagineMediaType]);
    }
    setState(() {
      _running = true;
      _status = 'Grok Imagine $mode';
      _lastCommand = '$browserVenvPython ${args.join(' ')}';
      _output = mode == 'login'
          ? 'Opening a real Chromium window for Grok sign-in…\n$_lastCommand'
          : 'Running real browser control:\n$_lastCommand';
    });
    try {
      final result =
          await _processRunner(
            browserVenvPython,
            args,
            workingDirectory: appRoot,
            environment: {
              'ENGEL_APP_ROOT': appRoot,
              'PLAYWRIGHT_BROWSERS_PATH': grokImagineBrowsersPath,
              'TEMP': engelTempRoot,
              'TMP': engelTempRoot,
              'TMPDIR': engelTempRoot,
            },
          ).timeout(
            Duration(
              seconds: mode == 'imagine'
                  ? 320
                  : mode == 'login'
                  ? 360
                  : 120,
            ),
          );
      final out = result.stdout.toString();
      var data = <String, dynamic>{};
      final brace = out.indexOf('{');
      if (brace >= 0) {
        try {
          final parsed = jsonDecode(out.substring(brace));
          if (parsed is Map<String, dynamic>) data = parsed;
        } catch (_) {}
      }
      if (!mounted) return;
      setState(() {
        if (data.containsKey('logged_in')) {
          _grokImagineLoggedIn = data['logged_in'] == true;
        }
        if (mode == 'imagine') {
          String? img;
          for (final d in (data['downloads'] as List?) ?? const []) {
            final p = (d is Map ? d['path'] : null)?.toString() ?? '';
            final lp = p.toLowerCase();
            if (lp.endsWith('.png') ||
                lp.endsWith('.jpg') ||
                lp.endsWith('.jpeg') ||
                lp.endsWith('.webp')) {
              img = p;
              break;
            }
          }
          img ??= data['screenshot']?.toString();
          if (img != null && img.isNotEmpty) _grokImagineImagePath = img;
        }
        _status = data['status']?.toString() ?? 'Grok Imagine $mode done';
        _output = [
          'Command: $_lastCommand',
          'Exit: ${result.exitCode}',
          _pretty(out),
          if (result.stderr.toString().trim().isNotEmpty)
            'stderr:\n${result.stderr.toString().trim()}',
        ].join('\n\n');
      });
      _showConnectorSnack(
        'Grok Imagine: ${data['status'] ?? 'done'}',
        ok: data['ok'] == true,
      );
    } on TimeoutException {
      if (mounted) {
        setState(() {
          _status = 'Grok Imagine timeout';
          _output = 'TIMEOUT during Grok Imagine $mode.';
        });
      }
    } catch (error) {
      if (mounted) {
        setState(() {
          _status = 'Grok Imagine error';
          _output = 'ERROR during Grok Imagine $mode:\n$error';
        });
      }
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

