  Map<String, String> get _engelBrowserEnv => {
    'ENGEL_APP_ROOT': appRoot,
    'PLAYWRIGHT_BROWSERS_PATH': grokImagineBrowsersPath,
    'TEMP': engelTempRoot,
    'TMP': engelTempRoot,
    'TMPDIR': engelTempRoot,
  };

  /// Resolve the optional Playwright runner without assuming the development
  /// checkout exists.  Portable copies may supply a configured interpreter
  /// through ENGEL_BROWSER_PYTHON; otherwise we make one best-effort PATH
  /// attempt and fall back to the operator's normal browser below.
  String _engelBrowserPythonExecutable() {
    if (File(browserVenvPython).existsSync()) return browserVenvPython;
    final configured = (Platform.environment['ENGEL_BROWSER_PYTHON'] ?? '')
        .trim();
    if (configured.isNotEmpty) return configured;
    return 'python.exe';
  }

  String _engelBrowserTargetUrl(
    ({String kind, String mediaType, String value}) intent,
  ) {
    if (intent.kind != 'search') return intent.value;
    return Uri.https('duckduckgo.com', '/html/', <String, String>{
      'q': intent.value,
    }).toString();
  }

  bool _engelBrowserRuntimeMissing(Object error) {
    final text = error.toString().toLowerCase();
    return text.contains('filenotfound') ||
        text.contains('cannot find the file') ||
        text.contains('no such file') ||
        text.contains('modulenotfounderror') ||
        text.contains('no module named') ||
        text.contains('python was not found') ||
        text.contains('not recognized as an internal') ||
        text.contains('exit code 9009') ||
        (text.contains('playwright') &&
            (text.contains('not found') || text.contains('no module')));
  }

  /// Keep a portable copy useful when Playwright/Python was not installed on
  /// the destination desktop.  This is a visible, operator-directed handoff:
  /// Engel opens the requested URL in the desktop's default browser and does
  /// not claim that it read or completed the page.  No login/CAPTCHA action is
  /// automated here.
  Future<void> _openEngelManualBrowserHandoff(
    ({String kind, String mediaType, String value}) intent, {
    String reason = 'The optional Engel browser runtime is unavailable.',
  }) async {
    final url = _engelBrowserTargetUrl(intent);
    _stopChatHeartbeat();
    _lastCommand = 'explorer.exe $url';
    var opened = false;
    var detail = '';
    try {
      final result = await _processRunner('explorer.exe', [
        url,
      ], workingDirectory: appRoot).timeout(const Duration(seconds: 15));
      opened = result.exitCode == 0;
      detail = result.stderr.toString().trim();
    } catch (error) {
      detail = error.toString();
    }
    final message = opened
        ? 'I opened this in your default browser so you can direct it:\n$url\n\n'
              '$reason\nEngel will not pretend it read or completed the page in manual mode. '
              'Return here with the result or install/configure the Engel browser runtime for automatic reading.'
        : 'I could not open the desktop browser for:\n$url\n\n'
              '$reason${detail.isEmpty ? '' : '\n$detail'}';
    _replaceLastAssistantBubble('Engel Browser', message);
  }

  void _replaceLastAssistantBubbleWithImage(
    String role,
    String text,
    String? imagePath,
  ) {
    if (_chatMessages.isNotEmpty) {
      final lastRole = _chatMessages.last.first;
      if (lastRole == 'Engel AI' ||
          lastRole == 'Engel Runtime' ||
          lastRole == 'Engel Thinking' ||
          lastRole == 'Thinking' ||
          lastRole == 'Engel Status' ||
          lastRole == 'Engel Error') {
        _chatMessages.removeLast();
      }
    }
    _chatMessages.add(
      imagePath != null && imagePath.isNotEmpty
          ? [role, text, imagePath]
          : [role, text],
    );
    _queueChatThreadBottomScroll();
  }

  /// Recognises when a chat turn is asking Engel to use the internet/browser so
  /// it can drive a real Chromium instead of the local chat model.
  ({String kind, String mediaType, String value})? _detectChatBrowserIntent(
    String text,
  ) {
    final t = text.trim();
    final lower = t.toLowerCase();

    // --- image / video generation (Grok Imagine) ---
    final grokImagine = RegExp(
      r'\bgrok\s*imagine\b',
      caseSensitive: false,
    ).hasMatch(lower);
    final genMedia = RegExp(
      r'\b(generate|create|make|draw|render|imagine)\b.{0,30}\b(image|images|picture|pic|photo|art|wallpaper|video|clip|animation|gif|movie)\b',
      caseSensitive: false,
    ).hasMatch(lower);
    if (grokImagine || genMedia) {
      final isVideo = RegExp(
        r'\b(video|clip|animation|gif|movie)\b',
        caseSensitive: false,
      ).hasMatch(lower);
      var prompt = t
          .replaceAll(
            RegExp(
              r'^\s*(please\s+|can you\s+|could you\s+)?(grok\s*imagine|generate|create|make|draw|render|imagine)\s+(me\s+)?(an?\s+)?(image|images|picture|pic|photo|art|wallpaper|video|clip|animation|gif|movie)?\s*(of|that says|showing|with)?\s*',
              caseSensitive: false,
            ),
            '',
          )
          .trim();
      if (prompt.isEmpty) prompt = t;
      return (
        kind: 'imagine',
        mediaType: isVideo ? 'video' : 'image',
        value: prompt,
      );
    }

    // --- explicit URL / domain anywhere in the message ---
    final url = RegExp(
      r'(https?://[^\s]+|\b[a-z0-9][a-z0-9-]*\.(?:com|org|net|io|ai|gov|edu|co|dev|app|news|tv|me)(?:/[^\s]*)?)',
      caseSensitive: false,
    ).firstMatch(t);
    if (url != null) {
      return (kind: 'open', mediaType: '', value: url.group(0)!);
    }

    // --- explicit web-search phrasing ---
    final searchFor = RegExp(
      r'(?:search the web(?: for)?|web ?search(?: for)?|google|look up online|search online for|find online)\s+(.+)$',
      caseSensitive: false,
    ).firstMatch(t);
    if (searchFor != null) {
      return (kind: 'search', mediaType: '', value: searchFor.group(1)!.trim());
    }

    // --- "use the internet/web/browser" to do something ---
    final useNet = RegExp(
      r'\b(use the (?:internet|web|browser)|on the (?:internet|web)|search the web|web ?search)\b',
      caseSensitive: false,
    ).hasMatch(lower);
    if (useNet) {
      final query = t
          .replaceAll(
            RegExp(
              r'\b(please|can you|could you|for me|use the (?:internet|web|browser)|on the (?:internet|web)|search the web(?: for)?|web ?search(?: for)?|to (?:find|search|look up|get|see))\b',
              caseSensitive: false,
            ),
            ' ',
          )
          .replaceAll(RegExp(r'\s+'), ' ')
          .trim();
      return (kind: 'search', mediaType: '', value: query.isEmpty ? t : query);
    }
    return null;
  }

  Map<String, dynamic> _parseWorkerJson(String out) {
    final brace = out.indexOf('{');
    if (brace < 0) return {};
    try {
      final parsed = jsonDecode(out.substring(brace));
      if (parsed is Map<String, dynamic>) return parsed;
    } catch (_) {}
    return {};
  }

  void _startChatHeartbeat(String label) {
    final sw = Stopwatch()..start();
    _chatHeartbeatTimer?.cancel();
    setState(
      () => _replaceLastAssistantBubble(
        'Engel Runtime',
        'Engel runtime\n● $label — 0s elapsed…',
      ),
    );
    _chatHeartbeatTimer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (!mounted || !_chatRunning) {
        _chatHeartbeatTimer?.cancel();
        return;
      }
      setState(
        () => _replaceLastAssistantBubble(
          'Engel Runtime',
          'Engel runtime\n● $label — ${sw.elapsed.inSeconds}s elapsed…',
        ),
      );
    });
  }

  void _stopChatHeartbeat() {
    _chatHeartbeatTimer?.cancel();
  }

  Future<void> _runEngelBrowse(
    String text,
    ({String kind, String mediaType, String value}) intent,
  ) async {
    final label = intent.kind == 'imagine'
        ? 'Engel is generating with Grok Imagine'
        : 'Engel opened a browser — direct it, then close it to finish';
    setState(() => _status = label);
    _startChatHeartbeat(label);
    try {
      if (intent.kind == 'imagine') {
        await _runGrokImagineForChat(intent.value, intent.mediaType);
        return;
      }
      final browserScript = File(engelBrowserControlScriptPath);
      if (!browserScript.existsSync()) {
        await _openEngelManualBrowserHandoff(
          intent,
          reason:
              'This portable copy has no Engel browser-control script in its workspace.',
        );
        return;
      }
      final browserPython = _engelBrowserPythonExecutable();
      final args = <String>[engelBrowserControlScriptPath];
      if (intent.kind == 'search') {
        args.add('search');
        args.addAll(
          intent.value.split(RegExp(r'\s+')).where((w) => w.isNotEmpty),
        );
        // Search used to be forced through a hidden Playwright context.  That
        // made human checks (and any page that needs operator direction)
        // impossible to finish.  Keep the session visible and bounded; the
        // worker returns when Josh closes the browser or the hold expires.
        args.addAll([
          '--visible',
          '--interactive',
          '--hold-seconds',
          '$engelBrowserOperatorHoldSeconds',
        ]);
      } else {
        // Open the requested page in the same visible, operator-directed mode
        // as search.  A page may require sign-in or a human check; the worker
        // never attempts to solve those and keeps the window available instead.
        args.addAll([
          'open',
          intent.value,
          '--task',
          text,
          '--visible',
          '--interactive',
          '--hold-seconds',
          '$engelBrowserOperatorHoldSeconds',
          '--signin-if-needed',
        ]);
      }
      _lastCommand = '$browserPython ${args.join(' ')}';
      // The visible session is intentionally bounded, but long enough for the
      // operator to complete a human check and close the page. The heartbeat
      // keeps the chat live while the browser is in the foreground.
      final result = await _processRunner(
        browserPython,
        args,
        workingDirectory: appRoot,
        environment: _engelBrowserEnv,
      ).timeout(const Duration(seconds: engelBrowserOperatorTimeoutSeconds));
      _stopChatHeartbeat();
      final rawStderr = result.stderr.toString().trim();
      if (result.exitCode != 0 &&
          _engelBrowserRuntimeMissing(
            rawStderr.isEmpty ? result.stdout : rawStderr,
          )) {
        await _openEngelManualBrowserHandoff(
          intent,
          reason: 'The Engel browser runtime is not installed on this desktop.',
        );
        return;
      }
      final data = _parseWorkerJson(result.stdout.toString());
      final title = data['title']?.toString() ?? intent.value;
      final pageUrl = data['url']?.toString() ?? intent.value;
      final shot = data['screenshot']?.toString();
      final signedIn = data['signed_in_during_open'] == true;
      final operatorClosed = data['operator_closed'] == true;
      final humanCheckRequired = data['human_check_required'] == true;
      final operatorActionRequired = data['operator_action_required'] == true;
      final pageText = (data['text']?.toString() ?? '').trim();
      final excerpt = pageText.length > 1400
          ? '${pageText.substring(0, 1400)}…'
          : pageText;
      if (operatorActionRequired || humanCheckRequired) {
        final status = (data['status']?.toString() ?? '').trim();
        final action = operatorClosed
            ? 'The visible browser was closed before the page was fully cleared.'
            : 'The visible browser is open for you. Complete the human check or direct the page, then close that browser window so Engel can finish.';
        _replaceLastAssistantBubbleWithImage(
          'Engel Browser',
          '$action\n\n${status.isEmpty ? 'Operator action is required.' : status}${excerpt.isEmpty ? '' : '\n\n$excerpt'}',
          shot,
        );
      } else if (data['ok'] == true && data['login_required'] != true) {
        final prefix = signedIn ? 'Signed in and opened' : 'Opened';
        final closedNote = operatorClosed
            ? ' The browser session was closed after the operator-directed step.'
            : '';
        _replaceLastAssistantBubbleWithImage(
          'Engel AI',
          '$prefix $title ($pageUrl).$closedNote\n\n${excerpt.isEmpty ? '(no readable text extracted)' : excerpt}',
          shot,
        );
      } else if (data['login_required'] == true) {
        final detail = data['signin_status'] != null
            ? ' (${data['signin_status']})'
            : '';
        _replaceLastAssistantBubbleWithImage(
          'Engel AI',
          'That page ($title) still needs sign-in. I opened it visibly but the '
              'sign-in did not finish$detail. Try again and complete the login — '
              'after that I can use it headless.',
          shot,
        );
      } else {
        _replaceLastAssistantBubble(
          'Engel Error',
          'Browser control could not open ${intent.value}.\n${data['status'] ?? rawStderr}',
        );
      }
    } catch (error) {
      _stopChatHeartbeat();
      if (_engelBrowserRuntimeMissing(error)) {
        await _openEngelManualBrowserHandoff(
          intent,
          reason: 'The Engel browser runtime is not installed on this desktop.',
        );
      } else {
        _replaceLastAssistantBubble(
          'Engel Error',
          'Browser control error: $error',
        );
      }
    } finally {
      _stopChatHeartbeat();
      if (mounted) {
        setState(() {
          _running = false;
          _chatRunning = false;
          _status = 'done';
          if (_agentTaskState == 'running') {
            _agentTaskState = 'failure';
            _agentTaskStatus = 'Opened a page, but the task was not finished';
            _agentTaskProofPath = '';
            _agentTaskProofDetails =
                'The browser session ended. Opening a page is not a finished task.';
          }
        });
      }
    }
  }

  Future<void> _runGrokImagineForChat(String prompt, String mediaType) async {
    final args = [
      grokImagineWorkerScriptPath,
      'imagine',
      prompt,
      '--type',
      mediaType,
      // If not signed in, open a visible keep-open sign-in window first, then
      // generate hidden (one-time sign-in, hidden after).
      '--signin-if-needed',
    ];
    _lastCommand = '$browserVenvPython ${args.join(' ')}';
    final result = await _processRunner(
      browserVenvPython,
      args,
      workingDirectory: appRoot,
      environment: _engelBrowserEnv,
    ).timeout(const Duration(seconds: 330));
    _stopChatHeartbeat();
    final data = _parseWorkerJson(result.stdout.toString());
    if (data['needs_login'] == true) {
      _replaceLastAssistantBubble(
        'Engel AI',
        'I need you to sign into Grok once. Opening the Grok sign-in window — after that I generate ${mediaType}s headless.',
      );
      unawaited(
        _processRunner(
          browserVenvPython,
          [grokImagineWorkerScriptPath, 'login'],
          workingDirectory: appRoot,
          environment: _engelBrowserEnv,
        ),
      );
      return;
    }
    String? media;
    for (final d in (data['downloads'] as List?) ?? const []) {
      final p = (d is Map ? d['path'] : null)?.toString() ?? '';
      final lp = p.toLowerCase();
      if (lp.endsWith('.png') ||
          lp.endsWith('.jpg') ||
          lp.endsWith('.jpeg') ||
          lp.endsWith('.webp') ||
          lp.endsWith('.mp4')) {
        media = p;
        break;
      }
    }
    media ??= data['screenshot']?.toString();
    if (media != null && media.isNotEmpty) _grokImagineImagePath = media;
    // Videos are converted to an animated GIF so the result plays RIGHT IN the
    // chat bubble (Image.file animates GIFs natively; a bare mp4 path was just
    // text the user had to chase into a folder).
    String? displayMedia = media;
    var videoNote = '';
    if (media != null && media.toLowerCase().endsWith('.mp4')) {
      try {
        final conv = await _processRunner(runtimePythonExe, [
          mediaToGifScriptPath,
          media,
        ], workingDirectory: appRoot).timeout(const Duration(seconds: 360));
        final convData = _parseWorkerJson(conv.stdout.toString());
        final gifPath = convData['gif_path']?.toString() ?? '';
        if (convData['ok'] == true && gifPath.isNotEmpty) {
          displayMedia = gifPath;
          videoNote = '\nFull video: $media';
        } else {
          displayMedia = null;
          videoNote = '\nSaved the video to $media (GIF conversion failed).';
        }
      } catch (_) {
        displayMedia = null;
        videoNote = '\nSaved the video to $media (GIF conversion timed out).';
      }
    }
    final reply = data['ok'] == true
        ? 'Made this with Grok Imagine.$videoNote'
        : (data['status']?.toString() ??
              'Grok Imagine could not complete this one.');
    _replaceLastAssistantBubbleWithImage('Engel AI', reply, displayMedia);
  }

  Future<void> _confirmBackendAutofixAgents() async {
    if (_running) return;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        key: const Key('backend-autofix-confirmation'),
        title: const Text('Run backend repair agents?'),
        content: const Text(
          'This starts a real multi-agent backend repair workflow. It can take several minutes and may create repair artifacts.\n\n'
          'Use this only when you intend to diagnose or repair the backend.',
        ),
        actions: [
          TextButton(
            key: const Key('cancel-backend-autofix'),
            autofocus: true,
            onPressed: () => Navigator.of(dialogContext).pop(false),
            style: TextButton.styleFrom(minimumSize: const Size(96, 48)),
            child: const Text('Cancel'),
          ),
          FilledButton(
            key: const Key('confirm-backend-autofix'),
            onPressed: () => Navigator.of(dialogContext).pop(true),
            style: FilledButton.styleFrom(minimumSize: const Size(0, 48)),
            child: const Text('Run repair agents'),
          ),
        ],
      ),
    );
    if (confirmed == true && mounted) {
      await _runBackendAutofixAgents();
    }
  }

  Future<void> _runBackendAutofixAgents() async {
    if (_running) return;
    final script = File(backendAutofixAgentsScriptPath);
    final python = await _findStandaloneChatPython();
    if (python == null || !await script.exists()) {
      setState(() {
        _status = 'backend agents unavailable';
        _output = [
          if (python == null)
            'Python missing. Expected $runtimePythonExe or python.exe.',
          if (!script.existsSync())
            'Backend auto-fix agent runner missing: $backendAutofixAgentsScriptPath',
        ].join('\n');
      });
      return;
    }
    final args = [backendAutofixAgentsScriptPath, '--summary'];
    setState(() {
      _running = true;
      _status = 'running backend auto-fix agents';
      _lastCommand = '${python.path} ${args.join(' ')}';
      _output = [
        'Running real command:',
        _lastCommand,
        '',
        'Agents: runtime cleanup, connector profiles, Meeting Room server, Rust backend, chat bridge.',
      ].join('\n');
    });
    try {
      final sw = Stopwatch()..start();
      final result = await _processRunner(
        python.path,
        args,
        workingDirectory: appRoot,
        environment: {
          'ENGEL_APP_ROOT': appRoot,
          'ENGEL_BACKEND_AUTOFIX_FROM_UI': '1',
          'TEMP': engelTempRoot,
          'TMP': engelTempRoot,
          'TMPDIR': engelTempRoot,
          'CARGO_HOME': engelCargoHome,
        },
      ).timeout(const Duration(seconds: 180));
      sw.stop();
      final stdoutText = _pretty(result.stdout.toString());
      final stderrText = result.stderr.toString().trim();
      if (!mounted) return;
      setState(() {
        _output = [
          'Command: $_lastCommand',
          'Exit: ${result.exitCode}',
          'Elapsed: ${sw.elapsedMilliseconds} ms',
          'Latest receipt: $backendAutofixLatestReceiptPath',
          if (stdoutText.isNotEmpty) 'summary json:\n$stdoutText',
          if (stderrText.isNotEmpty) 'stderr:\n$stderrText',
        ].join('\n\n');
        _status = result.exitCode == 0
            ? 'backend agents fixed'
            : 'backend agents need attention';
      });
    } on TimeoutException {
      setState(() {
        _output = 'TIMEOUT after 180s\nCommand: $_lastCommand';
        _status = 'backend agents timeout';
      });
    } catch (error) {
      setState(() {
        _output = 'ERROR: $error\nCommand: $_lastCommand';
        _status = 'backend agents error';
      });
    } finally {
      if (mounted) {
        setState(() => _running = false);
      }
    }
  }

  Future<void> _verifyCurrentReleaseManifest() async {
    if (_running) return;
    final python = File(runtimePythonExe);
    final verifier = File(currentReleaseManifestVerifierPath);
    if (!await python.exists() || !await verifier.exists()) {
      setState(() {
        _status = 'release verifier missing';
        _output = [
          if (!python.existsSync()) 'Python missing: $runtimePythonExe',
          if (!verifier.existsSync())
            'Verifier missing: $currentReleaseManifestVerifierPath',
        ].join('\n');
      });
      return;
    }
    final args = [
      currentReleaseManifestVerifierPath,
      currentReleaseManifestPath,
    ];
    setState(() {
      _running = true;
      _status = 'verifying current release';
      _lastCommand = '$runtimePythonExe ${args.join(' ')}';
      _output = 'Running real command:\n$_lastCommand';
    });
    try {
      final sw = Stopwatch()..start();
      final result = await _processRunner(
        runtimePythonExe,
        args,
        workingDirectory: appRoot,
        environment: {
          'ENGEL_APP_ROOT': appRoot,
          'TEMP': engelTempRoot,
          'TMP': engelTempRoot,
          'TMPDIR': engelTempRoot,
          'CARGO_HOME': engelCargoHome,
        },
      ).timeout(const Duration(seconds: 240));
      sw.stop();
      final stdoutText = _pretty(result.stdout.toString());
      final stderrText = result.stderr.toString().trim();
      if (!mounted) return;
      setState(() {
        _output = [
          'Command: $_lastCommand',
          'Exit: ${result.exitCode}',
          'Elapsed: ${sw.elapsedMilliseconds} ms',
          if (stdoutText.isNotEmpty) 'stdout:\n$stdoutText',
          if (stderrText.isNotEmpty) 'stderr:\n$stderrText',
        ].join('\n\n');
        _status = result.exitCode == 0
            ? 'release verified'
            : 'release verifier exit ${result.exitCode}';
      });
    } on TimeoutException {
      setState(() {
        _output = 'TIMEOUT after 240s\nCommand: $_lastCommand';
        _status = 'release verifier timeout';
      });
    } catch (error) {
      setState(() {
        _output = 'ERROR: $error\nCommand: $_lastCommand';
        _status = 'release verifier error';
      });
    } finally {
      if (mounted) {
        setState(() => _running = false);
      }
    }
  }

  String _providerEnvVarFor(String providerName) {
    final catalog = engelApiProviderByName(providerName);
    if (catalog != null) return catalog.envVar;
    return switch (providerName) {
      'OpenAI API' => 'ENGEL_OPENAI_API_KEY',
      'NVIDIA NIM' => 'NVIDIA_API_KEY',
      'OpenRouter' => 'ENGEL_OPENROUTER_API_KEY',
      'Anthropic' => 'ENGEL_ANTHROPIC_API_KEY',
      'xAI' => 'ENGEL_XAI_API_KEY',
      'Gemini' => 'ENGEL_GEMINI_API_KEY',
      'DeepSeek' => 'ENGEL_DEEPSEEK_API_KEY',
      'DashScope (Qwen)' => 'ENGEL_DASHSCOPE_API_KEY',
      'GLM / Z.AI' => 'ENGEL_ZAI_API_KEY',
      'Kimi / Moonshot' => 'ENGEL_MOONSHOT_API_KEY',
      'Kimi (China)' => 'ENGEL_KIMI_CHINA_API_KEY',
      'MiniMax' => 'ENGEL_MINIMAX_API_KEY',
      'MiniMax (China)' => 'ENGEL_MINIMAX_CHINA_API_KEY',
      'Mistral' => 'ENGEL_MISTRAL_API_KEY',
      'Cohere' => 'ENGEL_COHERE_API_KEY',
      'Groq' => 'ENGEL_GROQ_API_KEY',
      'Perplexity' => 'ENGEL_PERPLEXITY_API_KEY',
      'Hugging Face' => 'ENGEL_HUGGINGFACE_API_KEY',
      _ =>
        'ENGEL_${providerName.toUpperCase().replaceAll(RegExp(r'[^A-Z0-9]+'), '_')}_API_KEY',
    };
  }

  /// NVIDIA NIM uses the dedicated nvidia.env shelf (also copied to CT246).
  /// Other API-key providers share provider_bridges.env.
  String _providerBridgeEnvFileFor(String providerName) {
    if (providerName == 'NVIDIA NIM') {
      return '$appRoot\\run\\secrets\\nvidia.env';
    }
    return providerBridgeEnvFilePath;
  }

  TextEditingController _providerKeyController(String providerName) {
    return _providerKeyTextControllers.putIfAbsent(
      providerName,
      TextEditingController.new,
    );
  }

  String _providerKeyWidgetId(String providerName) {
    return providerName
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'^_+|_+$'), '');
  }

  Future<({int exitCode, String stdout, String stderr})>
  _persistProviderApiKeySecret(
    String providerName,
    String envName,
    String value,
  ) async {
    final receiptFile = File(providerKeySetupReceiptPath);
    await receiptFile.parent.create(recursive: true);
    const script = r'''
$ErrorActionPreference = 'Stop'
$payload = [Console]::In.ReadToEnd() | ConvertFrom-Json
[Environment]::SetEnvironmentVariable($payload.name, $payload.value, 'User')
$envFile = [string]$payload.env_file
$envDir = Split-Path -Parent $envFile
New-Item -ItemType Directory -Force -Path $envDir | Out-Null
$lines = New-Object 'System.Collections.Generic.List[string]'
if (Test-Path -LiteralPath $envFile) {
  foreach ($line in [System.IO.File]::ReadAllLines($envFile)) {
    if ($line -notmatch ('^' + [regex]::Escape([string]$payload.name) + '\s*=')) {
      [void]$lines.Add($line)
    }
  }
}
[void]$lines.Add(('{0}={1}' -f $payload.name, $payload.value))
$utf8NoBom = [System.Text.UTF8Encoding]::new($false)
[System.IO.File]::WriteAllLines($envFile, [string[]]$lines, $utf8NoBom)
$receipt = [pscustomobject]@{
  ok = $true
  provider = $payload.provider
  env_name = $payload.name
  key_chars = $payload.value.Length
  bridge_env_file = $envFile
  bridge_env_file_present = (Test-Path -LiteralPath $envFile)
  secret_values_printed = $false
  saved_at_utc = (Get-Date).ToUniversalTime().ToString('o')
}
$receipt | ConvertTo-Json -Depth 4
''';
    final process = await Process.start(
      'powershell.exe',
      const ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-Command', script],
      workingDirectory: appRoot,
      environment: {
        'ENGEL_APP_ROOT': appRoot,
        'TEMP': engelTempRoot,
        'TMP': engelTempRoot,
        'TMPDIR': engelTempRoot,
      },
    );
    process.stdin.write(
      jsonEncode({
        'provider': providerName,
        'name': envName,
        'value': value,
        'env_file': _providerBridgeEnvFileFor(providerName),
      }),
    );
    await process.stdin.close();
    final stdoutFuture = process.stdout.transform(utf8.decoder).join();
    final stderrFuture = process.stderr.transform(utf8.decoder).join();
    final exitCode = await process.exitCode.timeout(
      const Duration(seconds: 30),
    );
    return (
      exitCode: exitCode,
      stdout: await stdoutFuture,
      stderr: await stderrFuture,
    );
  }

  Future<void> _saveProviderApiKey(String providerName, String rawValue) async {
    final value = rawValue.trim();
    final envName = _providerEnvVarFor(providerName);
    if (value.isEmpty) {
      setState(() {
        _modelRouterStatus = '$providerName key field is empty';
        _status = 'provider key empty';
      });
      return;
    }
    if (_running) return;
    setState(() {
      _running = true;
      _status = 'saving $providerName key route';
      _lastCommand =
          'powershell.exe SetEnvironmentVariable($envName, <redacted>, User)';
      _output =
          'Saving $providerName key to Windows user environment variable $envName.\nSecret value is passed through stdin and is not printed.';
    });
    try {
      final receiptFile = File(providerKeySetupReceiptPath);
      final persist = await _persistProviderApiKeySecret(
        providerName,
        envName,
        value,
      );
      final stdoutText = persist.stdout;
      final stderrText = persist.stderr;
      final exitCode = persist.exitCode;
      if (exitCode == 0) {
        final receipt = {
          'ok': true,
          'provider': providerName,
          'env_name': envName,
          'key_chars': value.length,
          'bridge_env_file': _providerBridgeEnvFileFor(providerName),
          'bridge_secret_backed': true,
          'receipt_stdout': stdoutText.trim(),
          'saved_at_utc': DateTime.now().toUtc().toIso8601String(),
        };
        await receiptFile.writeAsString(
          '${const JsonEncoder.withIndent('  ').convert(receipt)}\n',
        );
        await _writeProviderConnectorProfile(
          providerName,
          status: 'key saved',
          secretBacked: true,
        );
      }
      if (!mounted) return;
      setState(() {
        _modelRouterStatus = exitCode == 0
            ? '$providerName key route saved to $envName'
            : '$providerName key save failed';
        _status = exitCode == 0 ? 'provider key saved' : 'provider key error';
        _output = [
          'Command: $_lastCommand',
          'Exit: $exitCode',
          'Provider: $providerName',
          'Environment variable: $envName',
          'Key characters: ${value.length}',
          'Bridge env file: $providerBridgeEnvFilePath',
          'Receipt: $providerKeySetupReceiptPath',
          if (stdoutText.trim().isNotEmpty)
            'stdout:\n${_pretty(stdoutText.trim())}',
          if (stderrText.trim().isNotEmpty) 'stderr:\n${stderrText.trim()}',
        ].join('\n\n');
      });
      _showConnectorSnack(
        exitCode == 0
            ? '$providerName key saved — now under Connections > AI Providers. Tap Verify to live-check.'
            : '$providerName key save failed.',
        ok: exitCode == 0,
      );
    } on TimeoutException {
      setState(() {
        _status = 'provider key timeout';
        _output = 'TIMEOUT while saving $providerName key route';
      });
    } catch (error) {
      setState(() {
        _status = 'provider key error';
        _output = 'ERROR saving $providerName key route: $error';
      });
    } finally {
      if (mounted) {
        setState(() => _running = false);
      }
    }
  }

  @override
  Future<void> _revealFileInExplorer(String path) async {
    if (_running) return;
    final file = File(path);
    final directory = Directory(path);
    final isFile = await file.exists();
    final isDirectory = await directory.exists();
    if (!isFile && !isDirectory) {
      setState(() {
        _status = 'file missing';
        _output = 'File not found:\n$path';
      });
      return;
    }
    setState(() {
      _running = true;
      _status = 'opening file location';
      _lastCommand = 'explorer.exe /select,$path';
      _output = 'Opening Windows Explorer to:\n$path';
    });
    try {
      final result = isDirectory
          ? await _processRunner('explorer.exe', [path])
          : await _processRunner('explorer.exe', ['/select,', path]);
      setState(() {
        _output = [
          'Command: $_lastCommand',
          'Exit: ${result.exitCode}',
          if (result.stdout.toString().trim().isNotEmpty)
            'stdout:\n${result.stdout}',
          if (result.stderr.toString().trim().isNotEmpty)
            'stderr:\n${result.stderr}',
        ].join('\n\n');
        _status = result.exitCode == 0 ? 'opened' : 'exit ${result.exitCode}';
      });
    } catch (error) {
      setState(() {
        _status = 'open failed';
        _output = 'ERROR: $error\nPath: $path';
      });
    } finally {
      if (mounted) {
        setState(() {
          _running = false;
        });
      }
    }
  }

