  String? _wikiOneViewForPrompt(String text) {
    final normalized = text.toLowerCase().trim().replaceAll('?', '').trim();
    if (normalized == 'wiki journal' ||
        normalized == 'wiki one journal' ||
        normalized == 'windows body journal') {
      return 'journal';
    }
    if (normalized == 'update wiki one' ||
        normalized == 'wiki one update' ||
        normalized == 'wiki one contract' ||
        normalized == 'update the wiki') {
      return 'contract';
    }
    if (normalized == 'wiki one' ||
        normalized == 'wiki one map' ||
        normalized == 'wiki one status' ||
        normalized == 'windows body map' ||
        normalized == 'engel wiki' ||
        normalized == 'engel wiki one' ||
        normalized == 'second brain' ||
        normalized == 'wiki') {
      return 'map';
    }
    return null;
