  String _formatWikiOrgans(String raw) {
    try {
      final decoded = jsonDecode(raw);
      if (decoded is Map && decoded['organs'] is List) {
        final organs = [
          for (final item in decoded['organs']) item,
        ].whereType<Map>().toList();
        final alive = organs.where((item) {
          final life = '${item['life'] ?? item['universe'] ?? ''}'
              .toLowerCase();
          return life == 'alive' || life == 'live';
        }).length;
        final buffer = StringBuffer()
          ..writeln('Engel AI Main organs — ALIVE')
          ..writeln('Count: ${organs.length}  Alive: $alive')
          ..writeln(
            'Engel AI Main is live. These organs are alive. Wiki One does not write the ALIVE_STATE file.',
          )
          ..writeln();
        for (final item in organs) {
          final life = '${item['life'] ?? item['universe'] ?? 'alive'}'
              .toLowerCase();
          final badge = (life == 'alive' || life == 'live')
              ? 'ALIVE'
              : life.toUpperCase();
          buffer.writeln('$badge  ${item['name']} (${item['id']})');
          buffer.writeln('  ${item['does']}');
          final talks = item['talks_to'];
          if (talks is List) {
            buffer.writeln('  talks to: ${talks.join(', ')}');
          }
          buffer.writeln();
        }
        return buffer.toString();
      }
    } catch (_) {}
    return raw;
  }

  Future<void> _loadWikiBrain() async {
    final path = switch (_wikiBrainView) {
      'journal' => engelWikiJournalPath,
      'organs' => engelWikiOrgansPath,
      'contract' => engelWikiContractPath,
      _ => engelWikiOnePath,
    };
    try {
      final file = File(path);
      var body = await file.exists()
          ? await file.readAsString()
          : 'Wiki One file missing:\n$path';
      if (_wikiBrainView == 'organs') {
        body = _formatWikiOrgans(body);
      }
      if (!mounted) return;
      setState(() {
        _wikiBrainText = body;
        _wikiBrainStatus = 'loaded $path';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _wikiBrainText = 'Wiki One could not load:\n$error';
        _wikiBrainStatus = 'load failed';
      });
    }
  }

  // The EXACT phrase that routes to the worker fleet-dispatch lane (proven live
  // 2026-07-12: "Engel Meeting Room" or any wording break broke the detector's
  // phrase match; only this literal form fans out to phones + Sub-Engel).
  static const String _meetingDispatchPrefix =
      'send an order to the meeting room for all devices: ';

  bool _meetingTextAlreadyRoutes(String text) {
    final low = text.toLowerCase();
    final hasRoom = low.contains('meeting room');
    final hasCollective =
        low.contains('all devices') ||
        low.contains('all workers') ||
        low.contains('every worker') ||
        low.contains('whole room') ||
        low.contains('all phones');
    return hasRoom && hasCollective;
  }

  Future<void> _confirmMeetingOrder() async {
    final task = _meetingDraft.trim();
    if (task.isEmpty || _running) return;
    final deliveryTitle = meetingRoomConfirmationTitle(_meetingRoomServer);
    final deliveryDetail = meetingRoomConfirmationDetail(_meetingRoomServer);
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        key: const Key('meeting-task-confirmation'),
        title: Text(deliveryTitle),
        content: Text(
          '$deliveryDetail Replies will appear in Chat.\n\n'
          'Task:\n$task',
        ),
        actions: [
          TextButton(
            key: const Key('meeting-task-cancel'),
            autofocus: true,
            onPressed: () => Navigator.of(dialogContext).pop(false),
            style: TextButton.styleFrom(minimumSize: const Size(96, 48)),
            child: const Text('Cancel'),
          ),
          FilledButton(
            key: const Key('meeting-task-confirm'),
            onPressed: () => Navigator.of(dialogContext).pop(true),
            style: FilledButton.styleFrom(minimumSize: const Size(0, 48)),
            child: const Text('Send task'),
          ),
        ],
      ),
    );
    if (confirmed == true && mounted) {
      await _submitMeetingOrder();
    }
  }

  Future<void> _submitMeetingOrder() async {
    final text = _meetingDraft.trim();
    if (text.isEmpty || _running) return;
    // (2026-07-12) The Meeting Room panel used to only SUBMIT the order (rust
    // native-submit) — it recorded the order but never fanned out, so no phones
    // or Sub-Engel ever got work (only the chat phrasing dispatched). Route
    // through the SAME worker chat dispatch lane the chat composer uses: the
    // proven fan-out to alpha/beta/gamma + Sub-Engel with real returns. Switch
    // to the chat view first so the returns are visible and the chat thread's
    // scroll controller is mounted. Prepend the exact fleet-dispatch trigger
    // phrase unless the operator already wrote a full meeting-room order.
    final dispatchText = _meetingTextAlreadyRoutes(text)
        ? text
        : '$_meetingDispatchPrefix$text';
    setState(() {
      _lastMeetingOrder = text;
      _meetingDraft = '';
      _selectedIndex = _sectionIndexById('chat_runtime');
      _chatDraft = dispatchText;
    });
    _meetingText.clear();
    await _submitChatDraft();
  }

  void _submitGlobalSearch(String value) {
    final query = value.trim().toLowerCase();
    if (query.isEmpty) return;
    String? targetId;

    // Retired/internal names remain useful search vocabulary. Route them to
    // their current owner instead of making the user guess the new label.
    for (final alias in sectionRouteAliases.entries) {
      final label = (sectionChildLabels[alias.key] ?? '').toLowerCase();
      if (alias.key.toLowerCase() == query || label == query) {
        targetId = alias.key;
        break;
      }
    }

    // Exact destinations win. Without this pass, "accounts" could match the
    // Settings description and "files" could match terminal_files first.
    if (targetId == null) {
      for (final section in _sections) {
        for (final child
            in sectionMergeChildren[section.id] ?? const <String>[]) {
          final label = (sectionChildLabels[child] ?? '').toLowerCase();
          if (child.toLowerCase() == query || label == query) {
            targetId = child;
            break;
          }
        }
        if (targetId != null) break;
      }
    }
    if (targetId == null) {
      for (final section in _sections) {
        if (section.id.toLowerCase() == query ||
            section.label.toLowerCase() == query) {
          targetId = section.id;
          break;
        }
      }
    }

    // Partial matching remains useful, but child tools still outrank their
    // owner's broad operation description.
    if (targetId == null) {
      for (final alias in sectionRouteAliases.entries) {
        final aliasHaystack = [
          alias.key,
          sectionChildLabels[alias.key] ?? '',
        ].join(' ').toLowerCase();
        if (aliasHaystack.contains(query)) {
          targetId = alias.key;
          break;
        }
      }
    }
    if (targetId == null) {
      for (final section in _sections) {
        for (final child
            in sectionMergeChildren[section.id] ?? const <String>[]) {
          final childHaystack = [
            child,
            sectionChildLabels[child] ?? '',
          ].join(' ').toLowerCase();
          if (childHaystack.contains(query)) {
            targetId = child;
            break;
          }
        }
        if (targetId != null) break;
      }
    }
    if (targetId == null) {
      for (final section in _sections) {
        final parentHaystack = [
          section.id,
          section.label,
          section.group,
          section.operationLane,
        ].join(' ').toLowerCase();
        if (parentHaystack.contains(query)) {
          targetId = section.id;
          break;
        }
      }
    }
    if (targetId == null) {
      setState(() {
        _status = 'no route for "$value"';
        _output =
            'No Engel tool or setting matched "$value". Use Chat for a request, or search for Training, Devices, Accounts, Memory, Build, or Proof.';
      });
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('No tool or setting matched “$value”.'),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return;
    }
    _selectSectionById(targetId);
    setState(() => _status = 'opened ${sectionChildLabels[targetId] ?? value}');
  }

  Future<void> _confirmSubEngelWorkOrder() async {
    final text = _dispatchDraft.trim();
    if (text.isEmpty || _running) return;
    final confirmed = await showDialog<bool>(
