        content: Text(
          'This creates a real shared-room work-order file for a Windows '
          'Sub-Engel. Review the task before writing it.\n\nTask:\n$text',
        ),
        actions: [
          TextButton(
            key: const Key('sub-engel-order-cancel'),
            autofocus: true,
            onPressed: () => Navigator.of(dialogContext).pop(false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            key: const Key('sub-engel-order-confirm'),
            onPressed: () => Navigator.of(dialogContext).pop(true),
            child: const Text('Write work order'),
          ),
        ],
      ),
    );
    if (confirmed == true && mounted) {
      await _writeSubEngelWorkOrder();
    }
  }

  Future<void> _writeSubEngelWorkOrder() async {
    final text = _dispatchDraft.trim();
    if (text.isEmpty || _running) {
      setState(() {
        _status = 'needs Sub-Engel work text';
        _output =
            'Type a Sub-Engel work order in Worker Dispatch before writing a shared-room order.';
      });
      return;
    }
    setState(() {
      _running = true;
      _status = 'writing Sub-Engel work order';
    });
    try {
      final dir = Directory(subEngelWorkOrdersDir);
      await dir.create(recursive: true);
      final stamp = DateTime.now()
          .toUtc()
          .toIso8601String()
          .replaceAll(RegExp(r'[-:.]'), '')
          .replaceAll('Z', 'Z');
      final id = 'MAIN-$stamp';
      final path = '${dir.path}\\$id.json';
      final order = <String, Object?>{
        'schema': 'engel_sub_engel_work_order_v1',
        'id': id,
        'created_at_utc': DateTime.now().toUtc().toIso8601String(),
        'created_by': 'Engel AI Main',
        'target': 'windows_sub_engel',
        'lane': 'CT246 local Sub-Engel transport',
        'status': 'ready_for_sub_engel_import',
        'order_text': text,
        'shared_room': sharedRoomRoot,
        'expected_return_folder': subEngelSentWorkDir,
        'proof_required': true,
      };
      final file = File(path);
      final encodedOrder = const JsonEncoder.withIndent('  ').convert(order);
      await file.writeAsString('$encodedOrder\n');
      final stat = await file.stat();

      final bus = File(sharedRoomBusPath);
      if (await bus.parent.exists()) {
        final busMessage = jsonEncode({
          'timestamp_utc': DateTime.now().toUtc().toIso8601String(),
          'sender': 'Engel AI Main',
          'channel': 'SUB_ENGEL_WORK_ORDER',
          'message': 'Main wrote Sub-Engel work order $id',
          'path': path,
          'bytes': stat.size,
        });
        await bus.writeAsString('$busMessage\n', mode: FileMode.append);
      }

      if (!mounted) return;
      setState(() {
        _status = 'Sub-Engel work order written';
        _lastCommand = 'write file $path';
        _output = [
          'Wrote real Sub-Engel work order:',
          path,
          '',
          'Bytes: ${stat.size}',
          'Shared room bus: $sharedRoomBusPath',
          '',
          const JsonEncoder.withIndent('  ').convert(order),
        ].join('\n');
      });
      await _scanSubEngelSharedRoomQueues();
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _status = 'Sub-Engel order write failed';
        _output = 'ERROR: $error';
      });
    } finally {
      if (mounted) {
        setState(() {
          _running = false;
        });
      }
    }
  }

