  Future<void> _connectStandaloneTarget(EngelConnectorTarget target) {
    if (target.kind == 'provider') {
      // Providers connect through their API key, not a standalone request
      // packet — route the action to a real live verification instead.
      return _liveVerifyConnector(target);
    }
    if (target.isChannel) {
      return _stageStandaloneChannelSetup(_channelOptionById(target.id));
    }
    return _stageStandaloneIntegrationSetup(
      _integrationOptionBySlug(target.id),
    );
  }

