  String _connectorCredentialMode(EngelConnectorTarget target) {
    return switch (_connectorAuthMode(target)) {
      _ConnectorAuthMode.apiKey => 'API key / access token',
      _ConnectorAuthMode.botToken => 'bot token',
      _ConnectorAuthMode.browserSession => 'browser sign-in',
    };
  }

  _ConnectorAuthMode _connectorAuthMode(EngelConnectorTarget target) {
    if (target.kind == 'provider') return _ConnectorAuthMode.apiKey;
    if (target.kind == 'channel') {
      return switch (target.id) {
        'discord' || 'telegram' => _ConnectorAuthMode.botToken,
        _ => _ConnectorAuthMode.browserSession,
      };
    }
    const apiKeyIntegrations = {
      'airtable',
      'asana',
      'bitbucket',
      'calendly',
      'clickup',
      'digital_ocean',
      'dropbox',
      'figma',
      'github',
      'gitlab',
      'gumroad',
      'hubspot',
      'intercom',
      'linear',
      'notion',
      'sentry',
      'slack',
      'stripe',
      'supabase',
      'vercel',
    };
    const botTokenIntegrations = {
      'discordbot',
      'slackbot',
      'telegram',
      'whatsapp',
    };
    if (botTokenIntegrations.contains(target.id)) {
      return _ConnectorAuthMode.botToken;
    }
    if (apiKeyIntegrations.contains(target.id)) {
      return _ConnectorAuthMode.apiKey;
    }
    return _ConnectorAuthMode.browserSession;
  }

