  String _connectorEnvVarForTarget(EngelConnectorTarget target) {
    if (target.kind == 'provider') {
      final provider = engelApiProviderBySlug(target.id);
      if (provider != null) return provider.envVar;
    }
    final id = target.id
        .trim()
        .toUpperCase()
        .replaceAll(RegExp(r'[^A-Z0-9]+'), '_')
        .replaceAll(RegExp(r'^_+|_+$'), '');
    final kind = target.kind.toUpperCase();
    return 'ENGEL_CONNECTOR_${kind}_${id.isEmpty ? 'TARGET' : id}_SECRET';
  }

