  String _connectorSetupUrl(EngelConnectorTarget target) {
    if (target.kind == 'provider') {
      final provider = engelApiProviderBySlug(target.id);
      if (provider != null) return provider.setupUrl;
    }
    const urls = <String, String>{
      'channel:telegram': 'https://t.me/BotFather',
      'channel:discord': 'https://discord.com/developers/applications',
      'channel:imessage': 'https://bluebubbles.app/install/',
      'integration:airtable': 'https://airtable.com/create/tokens',
      'integration:asana': 'https://app.asana.com/0/my-apps',
      'integration:bitbucket':
          'https://bitbucket.org/account/settings/app-passwords/',
      'integration:box': 'https://account.box.com/developers/console',
