    };
    final direct = urls['${target.kind}:${target.id}'];
    if (direct != null) return direct;
    final authMode = _connectorAuthMode(target);
    final intent = switch (authMode) {
      _ConnectorAuthMode.browserSession => 'browser sign in setup',
      _ConnectorAuthMode.botToken => 'bot token setup',
      _ConnectorAuthMode.apiKey => 'developer API key OAuth setup',
    };
    final query = Uri.encodeComponent('${target.name} $intent');
    return 'https://www.google.com/search?q=$query';
  }

  Map<String, dynamic>? _readConnectorProfile(EngelConnectorTarget target) {
    final file = File(_connectorProfilePath(target));
    if (!file.existsSync()) return null;
    try {
      final decoded = jsonDecode(file.readAsStringSync());
      if (decoded is Map) return decoded.cast<String, dynamic>();
    } catch (_) {
      return null;
    }
    return null;
  }

  bool _connectorProfileExists(EngelConnectorTarget target) {
    return File(_connectorProfilePath(target)).existsSync();
  }

  String _connectorProfileState(EngelConnectorTarget target) {
    final profile = _readConnectorProfile(target);
    if (profile != null) {
      final status = (profile['status'] ?? 'profile saved').toString();
      final authMode = (profile['auth_mode'] ?? '').toString();
      final browserSignedIn = profile['browser_signed_in'] == true;
      if (authMode == 'browser_session' && browserSignedIn) {
        return 'browser signed in';
      }
      if (authMode == 'browser_session') return status;
      if (_connectorAuthMode(target) == _ConnectorAuthMode.browserSession &&
          status.toLowerCase().contains('credential rejected')) {
        return 'browser sign-in required';
      }
      final chars = profile['secret_chars'];
      if (chars is int && chars > 0) return '$status ($chars chars saved)';
      return status;
    }
    final requestState = _connectorRequestState(target);
    if (requestState.startsWith('request staged')) return requestState;
    return 'not connected yet';
  }

  String _connectorRequestState(EngelConnectorTarget target) {
    final file = File(_connectorRequestPath(target));
    if (file.existsSync()) {
      final size = file.statSync().size;
      return 'request staged ($size bytes)';
    }
    return 'not staged yet';
  }

  Future<void> _stageConnectorAndSelect(EngelConnectorTarget target) async {
    setState(() {
      _selectedConnectorTarget = target;
      _connectorReceiptExpanded = false;
    });
    await _connectStandaloneTarget(target);
  }

  Future<void> _stageAndRevealConnectorRequest(
    EngelConnectorTarget target,
  ) async {
    if (!File(_connectorRequestPath(target)).existsSync()) {
      await _stageConnectorAndSelect(target);
    } else {
      _selectConnectorTarget(target);
    }
    if (!mounted) return;
    await _revealFileInExplorer(_connectorRequestPath(target));
  }

  Future<void> _showConnectorReceipt(EngelConnectorTarget target) async {
    final path = _connectorRequestPath(target);
    if (!File(path).existsSync()) {
      await _stageConnectorAndSelect(target);
    }
    if (!mounted) return;
    try {
      final file = File(path);
      final text = await file.readAsString();
      final size = await file.length();
      setState(() {
        _selectedConnectorTarget = target;
        _connectorReceiptExpanded = true;
        _status = '${target.name} connector receipt shown';
        _lastCommand = 'read file $path';
        _output = [
          'Connector receipt file:',
          path,
          '',
          'Bytes: $size',
          'Connector: ${target.name}',
          'Mode: ${_connectorCredentialMode(target)}',
          '',
          text,
        ].join('\n');
      });
    } catch (error) {
      setState(() {
        _selectedConnectorTarget = target;
        _connectorReceiptExpanded = true;
        _status = 'connector receipt read failed';
        _output = 'ERROR reading $path:\n$error';
      });
    }
  }

  Future<void> _openConnectorBrowserSetup(EngelConnectorTarget target) async {
    if (_running) return;
    final url = _connectorSetupUrl(target);
    final browserPath = _connectorBrowserRequestPath(target);
    final profilePath = _connectorProfilePath(target);
    final authMode = _connectorAuthMode(target);
    final browserRequest = <String, Object?>{
      'schema': 'engel_browser_connector_handoff_v1',
      'created_at_utc': DateTime.now().toUtc().toIso8601String(),
      'created_by': 'Engel AI Main',
      'action': 'open_provider_setup',
      'connector_kind': target.kind,
      'connector_id': target.id,
      'connector_name': target.name,
      'category': target.category,
      'provider_setup_url': url,
      'profile_path': profilePath,
      'env_name': _connectorEnvVarForTarget(target),
      'auth_mode': authMode.name,
      'status': 'ready_for_browser_control',
      'secret_policy': authMode == _ConnectorAuthMode.browserSession
          ? 'Engel opens a persistent browser profile for sign-in; no raw password, OAuth code, or token is stored in the connector profile.'
          : 'Engel opens a persistent browser profile for setup; secrets are saved only to Windows user environment when the operator clicks Save connection.',
    };
    setState(() {
      _running = true;
      _selectedConnectorTarget = target;
      _connectorReceiptExpanded = false;
      _status = 'opening ${target.name} browser setup';
      _lastCommand =
          '$browserVenvPython $engelBrowserControlScriptPath login $url';
      _output = [
        'Opening browser setup for ${target.name}:',
        url,
        '',
        'Writing browser-control handoff:',
        browserPath,
      ].join('\n');
    });
    try {
      final file = File(browserPath);
      await file.parent.create(recursive: true);
      await file.writeAsString(
        '${const JsonEncoder.withIndent('  ').convert(browserRequest)}\n',
      );
      final browserPython = File(browserVenvPython).existsSync()
          ? browserVenvPython
          : 'python.exe';
      final result = await _processRunner(browserPython, [
        engelBrowserControlScriptPath,
        'login',
        url,
        '--timeout',
        '360',
      ], workingDirectory: appRoot).timeout(const Duration(minutes: 7));
      final stdoutText = result.stdout.toString().trim();
      Map<String, dynamic>? browserResult;
      try {
        final decoded = jsonDecode(stdoutText);
        if (decoded is Map) browserResult = decoded.cast<String, dynamic>();
      } catch (_) {}
      final signedIn = browserResult?['logged_in'] == true;
      final browserStatus =
          browserResult?['status']?.toString().trim().isNotEmpty == true
          ? browserResult!['status'].toString().trim()
          : result.exitCode == 0
          ? 'browser setup opened'
          : 'browser setup needs attention';
      final profile = <String, Object?>{
        'schema': 'engel_connector_profile_v1',
        'created_at_utc': DateTime.now().toUtc().toIso8601String(),
        'created_by': 'Engel AI Main',
        'connector_kind': target.kind,
        'connector_id': target.id,
        'connector_name': target.name,
        'category': target.category,
        'auth_mode': 'browser_session',
        'status': signedIn
            ? 'browser signed in'
            : 'browser setup opened; sign-in not complete',
        'browser_signed_in': signedIn,
        'browser_status': browserStatus,
        'provider_setup_url': url,
        'browser_control_handoff': browserPath,
        'browser_profile_root': '$appRoot\\browser_profile\\sites',
        'standalone_request_path': _connectorRequestPath(target),
        'secret_policy':
            'no raw token is stored for this browser-session connector',
        'verify_routes': [
          'connector_test_connection',
          'browser_control_open',
          'connectors_verify',
        ],
      };
      final profileFile = File(profilePath);
      await profileFile.parent.create(recursive: true);
      await profileFile.writeAsString(
        '${const JsonEncoder.withIndent('  ').convert(profile)}\n',
      );
      if (!mounted) return;
      setState(() {
        _status = signedIn
            ? '${target.name} browser signed in'
            : '${target.name} browser setup needs sign-in';
        _output = [
          'Command: $_lastCommand',
          'Exit: ${result.exitCode}',
          'Connector: ${target.name}',
          'URL: $url',
          'Browser-control handoff: $browserPath',
          'Profile target: $profilePath',
          'Browser status: $browserStatus',
          if (stdoutText.isNotEmpty) 'stdout:\n${_pretty(stdoutText)}',
          if (result.stderr.toString().trim().isNotEmpty)
            'stderr:\n${result.stderr}',
        ].join('\n\n');
      });
    } on TimeoutException {
      if (!mounted) return;
      setState(() {
        _status = '${target.name} browser setup timeout';
        _output =
            'Browser setup stayed open for the sign-in window and timed out.\nConnector: ${target.name}\nURL: $url\nUse Open browser setup again when ready.';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _status = 'browser setup failed';
        _output = 'ERROR opening $url for ${target.name}:\n$error';
      });
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  Future<void> _saveConnectorConnection(EngelConnectorTarget target) async {
    final value = _connectorSecretText.text.trim();
    final envName = _connectorEnvVarForTarget(target);
    final profilePath = _connectorProfilePath(target);
    final browserPath = _connectorBrowserRequestPath(target);
    final authMode = _connectorAuthMode(target);
    if (value.isEmpty) {
      if (authMode == _ConnectorAuthMode.browserSession) {
        final profile = _readConnectorProfile(target);
        if (profile?['browser_signed_in'] == true) {
          setState(() {
            _status = '${target.name} browser session already connected';
            _output = [
              'Connector: ${target.name}',
              'Browser session is already saved for Engel use.',
              'Profile: $profilePath',
              'Use Test connection to re-check it.',
            ].join('\n');
          });
          return;
        }
        await _openConnectorBrowserSetup(target);
        return;
      }
      setState(() {
        _status = '${target.name} needs token or API key';
        _output = [
          'No secret was saved.',
          'Connector: ${target.name}',
          'Paste the ${_connectorCredentialMode(target)} into the connector secret field, then click Save connection.',
        ].join('\n');
      });
      return;
    }
    if (_running) return;
    setState(() {
      _running = true;
      _selectedConnectorTarget = target;
      _connectorReceiptExpanded = false;
      _status = 'saving ${target.name} connector';
      _lastCommand =
          'powershell.exe SetEnvironmentVariable($envName, <redacted>, User)';
      _output = [
        'Saving ${target.name} connector secret to Windows user environment variable $envName.',
        'Secret value is passed through stdin and is not printed or written to profile JSON.',
      ].join('\n');
    });
    try {
      const script = r'''
$ErrorActionPreference = 'Stop'
$payload = [Console]::In.ReadToEnd() | ConvertFrom-Json
[Environment]::SetEnvironmentVariable($payload.name, $payload.value, 'User')
$receipt = [pscustomobject]@{
  ok = $true
  env_name = $payload.name
  secret_chars = $payload.value.Length
  saved_at_utc = (Get-Date).ToUniversalTime().ToString('o')
}
$receipt | ConvertTo-Json -Depth 4
''';
      final process = await Process.start(
        'powershell.exe',
        const ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-Command', script],
        workingDirectory: appRoot,
        environment: {
          'ENGEL_APP_ROOT': appRoot,
          'TEMP': engelTempRoot,
          'TMP': engelTempRoot,
          'TMPDIR': engelTempRoot,
        },
      );
      process.stdin.write(jsonEncode({'name': envName, 'value': value}));
      await process.stdin.close();
      final stdoutFuture = process.stdout.transform(utf8.decoder).join();
      final stderrFuture = process.stderr.transform(utf8.decoder).join();
      final exitCode = await process.exitCode.timeout(
        const Duration(seconds: 30),
      );
      final stdoutText = await stdoutFuture;
      final stderrText = await stderrFuture;
      if (exitCode == 0) {
        final profile = <String, Object?>{
          'schema': 'engel_connector_profile_v1',
          'created_at_utc': DateTime.now().toUtc().toIso8601String(),
          'created_by': 'Engel AI Main',
          'connector_kind': target.kind,
          'connector_id': target.id,
          'connector_name': target.name,
          'category': target.category,
          'auth_mode': authMode == _ConnectorAuthMode.botToken
              ? 'bot_token'
              : 'api_key',
          'status': 'connected profile saved',
          'env_name': envName,
          'secret_chars': value.length,
          'secret_policy':
              'raw secret stored only in Windows User environment variable; profile contains metadata only',
          'provider_setup_url': _connectorSetupUrl(target),
          'browser_control_handoff': browserPath,
          'standalone_request_path': _connectorRequestPath(target),
          'source_executable': standaloneConnectionSourceExe,
          'verify_routes': [
            'connector_test_connection',
            'connectors_verify',
            'gateway_status',
          ],
        };
        final profileFile = File(profilePath);
        await profileFile.parent.create(recursive: true);
        await profileFile.writeAsString(
          '${const JsonEncoder.withIndent('  ').convert(profile)}\n',
        );
      }
      if (!mounted) return;
      setState(() {
        _status = exitCode == 0
            ? '${target.name} connector profile saved'
            : '${target.name} connector save failed';
        _output = [
          'Command: $_lastCommand',
          'Exit: $exitCode',
          'Connector: ${target.name}',
          'Environment variable: $envName',
          'Secret characters: ${value.length}',
          'Profile: $profilePath',
          'Browser-control handoff: $browserPath',
          if (stdoutText.trim().isNotEmpty)
            'stdout:\n${_pretty(stdoutText.trim())}',
          if (stderrText.trim().isNotEmpty) 'stderr:\n${stderrText.trim()}',
        ].join('\n\n');
      });
    } on TimeoutException {
      setState(() {
        _status = '${target.name} connector save timeout';
        _output = 'TIMEOUT while saving ${target.name} connector profile.';
      });
    } catch (error) {
      setState(() {
        _status = '${target.name} connector save error';
        _output = 'ERROR saving ${target.name} connector profile:\n$error';
      });
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  Future<void> _testConnectorConnection(EngelConnectorTarget target) async {
    if (_running) return;
    final envName = _connectorEnvVarForTarget(target);
    final profilePath = _connectorProfilePath(target);
    final profile = _readConnectorProfile(target);
    if (profile == null) {
      setState(() {
        _status = '${target.name} not connected';
        _output = [
          'No connector profile exists yet.',
          'Connector: ${target.name}',
          'Expected profile: $profilePath',
          'Open browser setup, paste the connector token/API key, then Save connection.',
        ].join('\n');
      });
      return;
    }
    setState(() {
      _running = true;
      _selectedConnectorTarget = target;
      _connectorReceiptExpanded = false;
      _status = 'testing ${target.name} connector';
      _lastCommand = 'powershell.exe read user env $envName';
      _output = 'Testing saved connector profile for ${target.name}.';
    });
    try {
      final payloadBase64 = base64Encode(
        utf8.encode(
          jsonEncode({
            'env_name': envName,
            'profile_path': profilePath,
            'connector': target.name,
          }),
        ),
      );
      final script =
          '''
\$payloadJson = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('$payloadBase64'))
\$payload = \$payloadJson | ConvertFrom-Json
\$value = [Environment]::GetEnvironmentVariable(\$payload.env_name, 'User')
\$secretChars = if ([string]::IsNullOrWhiteSpace(\$value)) { 0 } else { \$value.Length }
[pscustomobject]@{
  ok = (\$secretChars -gt 0 -and (Test-Path -LiteralPath \$payload.profile_path))
  connector = \$payload.connector
  env_name = \$payload.env_name
  secret_chars = \$secretChars
  profile_path = \$payload.profile_path
  profile_exists = (Test-Path -LiteralPath \$payload.profile_path)
  checked_at_utc = (Get-Date).ToUniversalTime().ToString('o')
} | ConvertTo-Json -Depth 4
''';
      final result = await _processRunner('powershell.exe', [
        '-NoProfile',
        '-ExecutionPolicy',
        'Bypass',
        '-Command',
        script,
      ]);
      if (!mounted) return;
      final stdoutText = result.stdout.toString().trim();
      setState(() {
        final ok =
            stdoutText.contains('"ok": true') ||
            stdoutText.contains('"ok":  true');
        _status = ok
            ? '${target.name} connector profile verified'
            : '${target.name} connector profile needs attention';
        _output = [
          'Command: $_lastCommand',
          'Exit: ${result.exitCode}',
          'Connector: ${target.name}',
          'Profile: $profilePath',
          'Env: $envName',
          if (stdoutText.isNotEmpty) 'stdout:\n${_pretty(stdoutText)}',
          if (result.stderr.toString().trim().isNotEmpty)
            'stderr:\n${result.stderr.toString().trim()}',
        ].join('\n\n');
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _status = '${target.name} connector test failed';
        _output = 'ERROR testing ${target.name} connector:\n$error';
      });
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  /// Reads a saved Windows User-scope environment variable (the connector/key
  /// store). Returns null when unset or unreadable.
  Future<String?> _readUserEnvVar(String name) async {
    try {
      final result = await _processRunner('powershell.exe', [
        '-NoProfile',
        '-ExecutionPolicy',
        'Bypass',
        '-Command',
        "[Environment]::GetEnvironmentVariable('${name.replaceAll("'", "''")}','User')",
      ]).timeout(const Duration(seconds: 20));
      final value = result.stdout.toString().trim();
      return value.isEmpty ? null : value;
    } catch (_) {
      return null;
    }
  }

  /// Performs one real authenticated request against the provider and reports
  /// whether the credential is live. States: verified / invalid / inconclusive
  /// / error.
  Future<({String state, int code, String detail})> _runLiveVerify(
    _LiveVerifySpec spec,
    String key,
  ) async {
    final url = spec.url.replaceAll('{KEY}', key);
    final client = HttpClient()
      ..connectionTimeout = const Duration(seconds: 12);
    try {
      final request = await client.openUrl(spec.method, Uri.parse(url));
      request.headers.set('User-Agent', 'EngelAIMain/1.0');
      spec.headers.forEach(
        (k, v) => request.headers.set(k, v.replaceAll('{KEY}', key)),
      );
      if (spec.body != null) {
        request.headers.contentType = ContentType.json;
        request.add(utf8.encode(spec.body!.replaceAll('{KEY}', key)));
      }
      final response = await request.close().timeout(
        const Duration(seconds: 18),
      );
      final code = response.statusCode;
      final bodyText = await response
          .transform(utf8.decoder)
          .join()
          .timeout(const Duration(seconds: 10), onTimeout: () => '');
      final compact = bodyText.replaceAll(RegExp(r'\s+'), '');
      final firstLine = bodyText.trim().isEmpty
          ? ''
          : bodyText.trim().split('\n').first;
      final snippet = firstLine.length > 200
          ? '${firstLine.substring(0, 200)}…'
          : firstLine;
      if (code >= 200 && code < 300) {
        if (spec.okBodyContains != null &&
            !compact.contains(spec.okBodyContains!.replaceAll(' ', ''))) {
          return (
            state: 'invalid',
            code: code,
            detail: 'HTTP $code but credential rejected: $snippet',
          );
        }
        return (
          state: 'verified',
          code: code,
          detail: 'HTTP $code OK $snippet',
        );
      }
      if (code == 401 || code == 403) {
        return (
          state: 'invalid',
          code: code,
          detail: 'HTTP $code credential rejected: $snippet',
        );
      }
      if (code == 429) {
        final low = compact.toLowerCase();
        // A hard quota/billing block means the key is valid but CANNOT generate,
        // so it must not read as "verified". OpenAI signals insufficient_quota;
        // Google signals RESOURCE_EXHAUSTED / free_tier / "limit:0" / quota
        // exceeded. Only a genuine transient rate-limit (none of these) counts as
        // "reached provider, credential valid".
        final hardQuota =
            low.contains('insufficient_quota') ||
            low.contains('resource_exhausted') ||
            low.contains('free_tier') ||
            low.contains('freetier') ||
            low.contains('limit:0') ||
            low.contains('quotaexceeded') ||
            low.contains('quota exceeded');
        if (hardQuota) {
          return (
            state: 'quota',
            code: code,
            detail: 'HTTP 429 provider quota/billing blocked: $snippet',
          );
        }
        return (
          state: 'verified',
          code: code,
          detail: 'HTTP 429 rate limited (reached provider; credential valid)',
        );
      }
      return (
        state: 'inconclusive',
        code: code,
        detail: 'HTTP $code could not confirm: $snippet',
      );
    } on TimeoutException {
      return (
        state: 'error',
        code: 0,
        detail: 'Timed out contacting provider.',
      );
    } catch (error) {
      return (state: 'error', code: 0, detail: 'Network error: $error');
    } finally {
      client.close(force: true);
    }
  }

  String _liveVerifyHeadline(String state) => switch (state) {
    'verified' => 'connected — live verified',
    'invalid' => 'credential rejected by provider',
    'quota' => 'quota blocked by provider',
    'inconclusive' => 'saved — live check inconclusive',
    _ => 'saved — live check error',
  };

  /// Verify button on the API keys page: real network check for the provider.
  void _showConnectorSnack(String message, {required bool ok}) {
    final messenger = ScaffoldMessenger.maybeOf(context);
    messenger?.hideCurrentSnackBar();
    messenger?.showSnackBar(
      SnackBar(
        content: Text(message),
        backgroundColor: ok ? const Color(0xff15603a) : const Color(0xff5a2330),
        behavior: SnackBarBehavior.floating,
        duration: const Duration(seconds: 4),
      ),
    );
  }

  EngelConnectorTarget? _providerConnectorTarget(String providerName) {
    final provider = engelApiProviderByName(providerName);
    if (provider == null) return null;
    return EngelConnectorTarget(
      kind: 'provider',
      id: provider.slug,
      name: provider.name,
      category: 'AI Providers',
      detail:
          'Frontier model provider key — live-verified against the ${provider.name} API.',
    );
  }

  /// Records a provider's connection state as a connector profile so it shows
  /// up under Connections > AI Providers (single source of truth for the row).
  Future<void> _writeProviderConnectorProfile(
    String providerName, {
    required String status,
    bool? liveVerified,
    String? liveState,
    int? liveCode,
    bool? secretBacked,
  }) async {
    final target = _providerConnectorTarget(providerName);
    if (target == null) return;
    final nowUtc = DateTime.now().toUtc().toIso8601String();
    final profile = <String, Object?>{
      'schema': 'engel_connector_profile_v1',
      'created_at_utc': nowUtc,
      'created_by': 'Engel AI Main',
      'connector_kind': 'provider',
      'connector_id': target.id,
      'connector_name': providerName,
      'category': 'AI Providers',
      'status': status,
      'env_name': _providerEnvVarFor(providerName),
    };
    if (secretBacked != null) {
      profile['secret_backed'] = secretBacked;
      profile['secret_policy'] = secretBacked
          ? 'Secret is stored in Windows User environment and run/secrets/provider_bridges.env; value is not stored in this profile.'
          : 'Profile was verified from a temporary field or old state; bridge secret store was not confirmed.';
    }
    if (liveVerified != null) {
      profile['live_verified'] = liveVerified;
      profile['live_verify_state'] = liveState;
      profile['live_verify_code'] = liveCode;
      profile['live_verified_at_utc'] = nowUtc;
    }
    try {
      final file = File(_connectorProfilePath(target));
      await file.parent.create(recursive: true);
      await file.writeAsString(
        '${const JsonEncoder.withIndent('  ').convert(profile)}\n',
      );
    } catch (_) {}
  }

  /// Persistent connection state for an API-key provider, read from its saved
  /// connector profile (single source of truth for the API keys badge + dot).
  ({Color color, String? label}) _providerKeyStatus(String providerName) {
    final target = _providerConnectorTarget(providerName);
    final profile = target == null ? null : _readConnectorProfile(target);
    if (profile == null) return (color: const Color(0xff333337), label: null);
    final secretBacked = profile['secret_backed'] == true;
    if (profile['live_verified'] == true) {
      if (!secretBacked) {
        return (
          color: const Color(0xffd9a441),
          label: 'Verified - save key for bridge',
        );
      }
      return (
        color: const Color(0xff00e87a),
        label: 'Connected · live verified',
      );
    }
    final state = (profile['live_verify_state'] ?? '').toString();
    if (state == 'invalid') {
      return (
        color: const Color(0xffe2554f),
        label: 'Key rejected by provider',
      );
    }
    if (state == 'quota') {
      return (color: const Color(0xffe2554f), label: 'Quota / billing blocked');
    }
    final status = (profile['status'] ?? 'Key saved').toString();
    return (color: const Color(0xffd9a441), label: status);
  }

  bool _isoUtcIsFresh(Object? rawValue, Duration maxAge) {
    final text = rawValue?.toString().trim() ?? '';
    if (text.isEmpty) return false;
    final parsed = DateTime.tryParse(text);
    if (parsed == null) return false;
    final age = DateTime.now().toUtc().difference(parsed.toUtc());
    return age >= Duration.zero && age <= maxAge;
  }

  String _shortBridgeStatus(Object? rawValue) {
    final text = rawValue?.toString().trim() ?? '';
    if (text.isEmpty) return 'no probe status recorded';
    return text.length <= 120 ? text : '${text.substring(0, 120)}...';
  }

  ({String status, String detail}) _chatGptBrowserBridgeStatus() {
    final stateFile = File(chatGptBrowserWorkerStatePath);
    if (!stateFile.existsSync()) {
      return (
        status: 'Needs check',
        detail:
            'ChatGPT browser bridge has no saved state yet. Tap to run a live probe.',
      );
    }
    try {
      final decoded = jsonDecode(stateFile.readAsStringSync());
      if (decoded is! Map<String, dynamic>) {
        return (
          status: 'Needs check',
          detail:
              'ChatGPT bridge state could not be read. Tap to rebuild the probe state.',
        );
      }
      final probeFresh = _isoUtcIsFresh(
        decoded['last_probe_at_utc'],
        const Duration(minutes: 10),
      );
      final heartbeatFresh = _isoUtcIsFresh(
        decoded['last_heartbeat_utc'],
        const Duration(minutes: 2),
      );
      final hasProbe = decoded.containsKey('last_probe_ok');
      final probeOk = decoded['last_probe_ok'] == true;
      final probeStatus = _shortBridgeStatus(decoded['last_probe_status']);
      if (hasProbe && probeOk && probeFresh) {
        return (
          status: 'Connected',
          detail:
              'ChatGPT browser bridge was live-verified by a fresh response.',
        );
      }
      if (hasProbe && !probeOk && probeFresh) {
        return (
          status: 'Needs attention',
          detail: 'Latest ChatGPT bridge probe failed: $probeStatus',
        );
      }
      if (heartbeatFresh) {
        return (
          status: 'Worker running',
          detail:
              'Worker heartbeat is fresh, but ChatGPT response is not verified. Tap to probe.',
        );
      }
      if (hasProbe && !probeOk) {
        return (
          status: 'Needs attention',
          detail: 'Last ChatGPT bridge probe failed: $probeStatus',
        );
      }
      return (
        status: 'Needs check',
        detail:
            'No fresh ChatGPT bridge response proof is saved. Tap to run one.',
      );
    } catch (_) {
      return (
        status: 'Needs check',
        detail: 'ChatGPT bridge state read failed. Tap to run a new probe.',
      );
    }
  }

  /// Account cards for API-key providers that have a saved/verified profile, so
  /// they appear in the Accounts > Connected list (not only the API keys page).
  List<Widget> _apiProviderAccountCards(StateSetter refreshDialog) {
    final cards = <Widget>[];
    for (final p in engelApiKeyProviders) {
      final target = _providerConnectorTarget(p.name);
      final profile = target == null ? null : _readConnectorProfile(target);
      if (profile == null) continue;
      final verified = profile['live_verified'] == true;
      final secretBacked = profile['secret_backed'] == true;
      final state = (profile['live_verify_state'] ?? '').toString();
      final status = verified && secretBacked
          ? 'Connected'
          : verified
          ? 'Needs Save'
          : (state == 'invalid'
                ? 'Rejected'
                : state == 'quota'
                ? 'Quota'
                : 'Saved');
      final detail = verified && secretBacked
          ? 'API key live-verified against the ${p.name} API. Tap to re-verify.'
          : verified
          ? 'API key verified, but the bridge secret store is not confirmed. Save key again or re-verify from the typed field.'
          : state == 'invalid'
          ? 'Saved key was rejected by ${p.name}. Tap to re-verify.'
          : state == 'quota'
          ? '${p.name} accepted the key but refused generation for quota/billing. Tap to re-check.'
          : 'API key saved. Tap to live-verify against ${p.name}.';
      cards.add(
        _providerConnectCard(
          title: '${p.name} (API key)',
          status: status,
          detail: detail,
          onTap: () => unawaited(
            _liveVerifyProviderKey(p.name).then((_) {
              if (mounted) refreshDialog(() {});
            }),
          ),
        ),
      );
    }
    return cards;
  }

  Future<void> _liveVerifyProviderKey(String providerName) async {
    if (_running) return;
    final spec = _engelLiveVerifySpecForProvider(providerName);
    final envName = _providerEnvVarFor(providerName);
    final typed = _providerKeyController(providerName).text.trim();
    setState(() {
      _running = true;
      _status = 'verifying $providerName';
      _modelRouterStatus = 'verifying $providerName…';
      _output = 'Live-verifying $providerName credential…';
    });
    try {
      final key = typed.isNotEmpty
          ? typed
          : (await _readUserEnvVar(envName) ?? '');
      if (key.isEmpty) {
        setState(() {
          _status = '$providerName: no key';
          _modelRouterStatus = '$providerName has no saved key';
          _output =
              'No $providerName key found.\nPaste a key and Save key first, then Verify.\nEnv: $envName';
        });
        _showConnectorSnack(
          '$providerName: paste a key and Save key first.',
          ok: false,
        );
        return;
      }
      if (spec == null) {
        await _writeProviderConnectorProfile(
          providerName,
          status: 'key saved (no live check)',
        );
        setState(() {
          _status = '$providerName saved (no live check)';
          _modelRouterStatus = '$providerName key saved; no live endpoint';
          _output =
              '$providerName key is saved in $envName.\nNo stateless live-verification endpoint is wired for $providerName, so Engel cannot confirm it over the network without spending tokens.\nIt is now listed under Connections > AI Providers.';
        });
        _showConnectorSnack(
          '$providerName key saved (no live endpoint to verify).',
          ok: true,
        );
        return;
      }
      final result = await _runLiveVerify(spec, key);
      var bridgeSecretBacked = typed.isEmpty;
      var persistExitCode = 0;
      var persistError = '';
      if (result.state == 'verified' || result.state == 'quota') {
        final persist = await _persistProviderApiKeySecret(
          providerName,
          envName,
          key,
        );
        persistExitCode = persist.exitCode;
        bridgeSecretBacked = persist.exitCode == 0;
        persistError = persist.stderr.trim();
      }
      // "Live verified" requires BOTH a genuine verified generate AND the key
      // actually landing in the bridge secret store. If the persist failed, the
      // runtime can't use the key, so a green "connected — live verified" badge
      // would be a lie — report it honestly instead.
      final trulyLive = result.state == 'verified' && bridgeSecretBacked;
      final headline = (result.state == 'verified' && !bridgeSecretBacked)
          ? 'verified — key not saved to bridge (retry Save key)'
          : _liveVerifyHeadline(result.state);
      await _writeProviderConnectorProfile(
        providerName,
        status: headline,
        liveVerified: trulyLive,
        liveState: result.state,
        liveCode: result.code,
        secretBacked: bridgeSecretBacked,
      );
      if (!mounted) return;
      setState(() {
        _status = '$providerName: ${result.state}';
        _modelRouterStatus = '$providerName — $headline';
        _output = [
          'Live verification: ${spec.label}',
          'Endpoint: ${spec.method} ${spec.url.replaceAll('{KEY}', '***')}',
          'Result: ${result.state.toUpperCase()} (HTTP ${result.code})',
          result.detail,
          'Key source: ${typed.isNotEmpty ? 'entered field' : 'saved env $envName'}',
          'Bridge secret store: ${bridgeSecretBacked ? 'updated' : 'not updated'}',
          if (persistExitCode != 0)
            'Bridge secret store exit: $persistExitCode',
          if (persistError.isNotEmpty)
            'Bridge secret store stderr:\n$persistError',
          'Now shown under Connections > AI Providers.',
        ].join('\n');
      });
      _showConnectorSnack(
        '$providerName — $headline (HTTP ${result.code})',
        ok: trulyLive,
      );
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  /// Test connection button on a connector: real network check when an endpoint
  /// is known, otherwise the local saved-profile check.
  Future<void> _liveVerifyConnector(EngelConnectorTarget target) async {
    if (_running) return;
    if (_connectorAuthMode(target) == _ConnectorAuthMode.browserSession) {
      await _testConnectorBrowserSession(target);
      return;
    }
    final spec = _engelLiveVerifySpecForConnector(target.kind, target.id);
    if (spec == null) {
      await _testConnectorConnection(target);
      return;
    }
    final envName = _connectorEnvVarForTarget(target);
    final typed = _connectorSecretText.text.trim();
    setState(() {
      _running = true;
      _selectedConnectorTarget = target;
      _connectorReceiptExpanded = false;
      _status = 'verifying ${target.name}';
      _output = 'Live-verifying ${target.name} credential…';
    });
    try {
      final key = typed.isNotEmpty
          ? typed
          : (await _readUserEnvVar(envName) ?? '');
      if (key.isEmpty) {
        setState(() {
          _status = '${target.name}: no secret';
          _output =
              'No secret found for ${target.name}.\nPaste the token/key and Save connection first, then Test connection.\nEnv: $envName';
        });
        return;
      }
      final result = await _runLiveVerify(spec, key);
      final profile = _readConnectorProfile(target);
      if (profile != null) {
        profile['live_verified'] = result.state == 'verified';
        profile['live_verify_state'] = result.state;
        profile['live_verify_code'] = result.code;
        profile['live_verified_at_utc'] = DateTime.now()
            .toUtc()
            .toIso8601String();
        profile['status'] = _liveVerifyHeadline(result.state);
        try {
          File(_connectorProfilePath(target)).writeAsStringSync(
            '${const JsonEncoder.withIndent('  ').convert(profile)}\n',
          );
        } catch (_) {}
      }
      if (!mounted) return;
      setState(() {
        _status = '${target.name}: ${result.state}';
        _output = [
          'Live verification: ${spec.label}',
          'Endpoint: ${spec.method} ${spec.url.replaceAll('{KEY}', '***')}',
          'Result: ${result.state.toUpperCase()} (HTTP ${result.code})',
          result.detail,
          'Key source: ${typed.isNotEmpty ? 'entered field' : 'saved env $envName'}',
          if (profile == null)
            'No saved profile yet — Save connection to persist this lane.',
        ].join('\n');
      });
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  Future<void> _testConnectorBrowserSession(EngelConnectorTarget target) async {
    if (_running) return;
    final url = _connectorSetupUrl(target);
    final profilePath = _connectorProfilePath(target);
    setState(() {
      _running = true;
      _selectedConnectorTarget = target;
      _connectorReceiptExpanded = false;
      _status = 'checking ${target.name} browser session';
      _lastCommand =
          '$browserVenvPython $engelBrowserControlScriptPath open $url';
      _output = 'Checking Engel browser session for ${target.name}.';
    });
    try {
      final browserPython = File(browserVenvPython).existsSync()
          ? browserVenvPython
          : 'python.exe';
      final result = await _processRunner(browserPython, [
        engelBrowserControlScriptPath,
        'open',
        url,
        '--timeout',
        '90',
      ], workingDirectory: appRoot).timeout(const Duration(minutes: 2));
      final stdoutText = result.stdout.toString().trim();
      Map<String, dynamic>? browserResult;
      try {
        final decoded = jsonDecode(stdoutText);
        if (decoded is Map) browserResult = decoded.cast<String, dynamic>();
      } catch (_) {}
      final ok = browserResult?['ok'] == true;
      final loginRequired = browserResult?['login_required'] == true;
      final signedIn = ok && !loginRequired;
      final browserStatus =
          browserResult?['status']?.toString().trim().isNotEmpty == true
          ? browserResult!['status'].toString().trim()
          : signedIn
          ? 'browser session reachable'
          : 'browser session needs sign-in';
      final current = _readConnectorProfile(target) ?? <String, dynamic>{};
      current
        ..['schema'] = 'engel_connector_profile_v1'
        ..['created_by'] = 'Engel AI Main'
        ..['connector_kind'] = target.kind
        ..['connector_id'] = target.id
        ..['connector_name'] = target.name
        ..['category'] = target.category
        ..['auth_mode'] = 'browser_session'
        ..['browser_signed_in'] = signedIn
        ..['browser_status'] = browserStatus
        ..['provider_setup_url'] = url
        ..['status'] = signedIn
            ? 'browser signed in'
            : 'browser sign-in required'
        ..['checked_at_utc'] = DateTime.now().toUtc().toIso8601String()
        ..['secret_policy'] =
            'no raw token is stored for this browser-session connector';
      current.putIfAbsent(
        'created_at_utc',
        () => DateTime.now().toUtc().toIso8601String(),
      );
      final profileFile = File(profilePath);
      await profileFile.parent.create(recursive: true);
      await profileFile.writeAsString(
        '${const JsonEncoder.withIndent('  ').convert(current)}\n',
      );
      if (!mounted) return;
      setState(() {
        _status = signedIn
            ? '${target.name} browser session connected'
            : '${target.name} needs browser sign-in';
        _output = [
          'Command: $_lastCommand',
          'Exit: ${result.exitCode}',
          'Connector: ${target.name}',
          'Profile: $profilePath',
          'Browser status: $browserStatus',
          signedIn
              ? 'Result: CONNECTED through Engel browser profile.'
              : 'Result: sign in with Open browser setup, then Test connection again.',
          if (stdoutText.isNotEmpty) 'stdout:\n${_pretty(stdoutText)}',
          if (result.stderr.toString().trim().isNotEmpty)
            'stderr:\n${result.stderr.toString().trim()}',
        ].join('\n\n');
      });
    } on TimeoutException {
      if (!mounted) return;
      setState(() {
        _status = '${target.name} browser session check timed out';
        _output =
            'Timed out checking ${target.name}. Use Open browser setup for a visible sign-in, then test again.';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _status = '${target.name} browser session check failed';
        _output = 'ERROR checking ${target.name} browser session:\n$error';
      });
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

