  bool _environmentFlagEnabled(String name) {
    final value = (Platform.environment[name] ?? '').trim().toLowerCase();
    return value == '1' || value == 'true' || value == 'yes' || value == 'on';
  }

  double _environmentDouble(String name, double fallback) {
    final value = double.tryParse((Platform.environment[name] ?? '').trim());
    return value == null || value <= 0 ? fallback : value;
  }

