  List<String> _stringListFromJson(Object? value) {
    if (value is! List) return const [];
    return [
      for (final item in value)
        if (item.toString().trim().isNotEmpty) item.toString().trim(),
    ];
  }

  Future<List<String>> _loadChatUiSoakPromptsFromEnvironment() async {
    final rawPrompts =
        (Platform.environment['ENGEL_UI_CHAT_SOAK_PROMPTS'] ?? '').trim();
    if (rawPrompts.isNotEmpty) {
      final split = rawPrompts
          .split(RegExp(r'\r?\n|\|\|\|'))
          .map((item) => item.trim())
          .where((item) => item.isNotEmpty)
          .toList(growable: false);
      if (split.isNotEmpty) return split;
    }
    final templatePath =
        (Platform.environment['ENGEL_UI_CHAT_SOAK_TEMPLATE'] ?? '').trim();
    if (templatePath.isNotEmpty) {
      try {
        final file = File(templatePath);
        if (await file.exists()) {
          final decoded = jsonDecode(await file.readAsString());
          if (decoded is Map<String, dynamic>) {
            final mode = (Platform.environment['ENGEL_UI_CHAT_SOAK_MODE'] ?? '')
                .trim()
                .toLowerCase();
            final prompts = mode == 'smoke'
                ? _stringListFromJson(decoded['smoke_prompts'])
                : _stringListFromJson(decoded['active_prompts']);
            if (prompts.isNotEmpty) return prompts;
          }
        }
      } catch (error) {
        _writeChatUiSoakEvent('template_read_error', {'error': '$error'});
      }
    }
    return _defaultChatUiSoakPrompts();
  }

  void _writeChatUiSoakEvent(String event, Map<String, Object?> details) {
    final runId = _chatUiSoakRunId.isEmpty
        ? 'engel_chat_ui_soak_unstarted'
        : _chatUiSoakRunId;
    try {
      final dir = Directory('$appRoot\\reports\\codex_bridge');
      dir.createSync(recursive: true);
      final file = File('${dir.path}\\ENGEL_CHAT_UI_SOAK_$runId.jsonl');
      final payload = <String, Object?>{
        'schema': 'engel_chat_ui_soak_event_v1',
        'event': event,
        'run_id': runId,
        'updated_at_utc': DateTime.now().toUtc().toIso8601String(),
        'chat_ui_soak_active': _chatUiSoakActive,
        'prompt_index': _chatUiSoakIndex,
        'prompt_completed': _chatUiSoakCompleted,
        'prompt_count': _chatUiSoakPrompts.length,
        'deadline_utc': _chatUiSoakDeadlineUtc?.toIso8601String() ?? '',
        'next_due_utc': _chatUiSoakNextDueUtc?.toIso8601String() ?? '',
        ...details,
      };
      file.writeAsStringSync('${jsonEncode(payload)}\n', mode: FileMode.append);
    } catch (_) {
      // A receipt write failure must not break normal Chat.
    }
  }

  // ---- UI chat inbox -------------------------------------------------------
  // Outside drivers (the prompt-training runner) used to deliver prompts by
  // moving the real mouse to fixed pixels and injecting keystrokes, which
  // silently typed into whatever window happened to hold focus and left the run
  // waiting out a 760s timeout per prompt. They now drop a request file here and
  // Engel types it into its OWN visible Chat composer and presses send through
  // the same path as the Send button, so the run still proves the real UI.
  Directory get _uiChatInboxRequestDir =>
      Directory('$appRoot\\runtime\\ui_chat_inbox\\requests');

  Directory get _uiChatInboxResultDir =>
      Directory('$appRoot\\runtime\\ui_chat_inbox\\results');

  void _startUiChatInboxWatcher() {
    _uiChatInboxTimer?.cancel();
    _uiChatInboxTimer = Timer.periodic(
      const Duration(seconds: 2),
      (_) => unawaited(_drainUiChatInbox()),
    );
  }

  void _writeUiChatInboxResult(String requestId, Map<String, Object?> payload) {
    try {
      final dir = _uiChatInboxResultDir;
      dir.createSync(recursive: true);
      File('${dir.path}\\$requestId.json').writeAsStringSync(
        jsonEncode(<String, Object?>{
          'schema': 'engel_ui_chat_inbox_result_v1',
          'request_id': requestId,
          'updated_at_utc': DateTime.now().toUtc().toIso8601String(),
          ...payload,
        }),
      );
    } catch (_) {
      // A receipt write failure must not break normal Chat.
    }
  }

  Future<void> _drainUiChatInbox() async {
    if (!mounted || _uiChatInboxBusy || _running) return;
    File? request;
    try {
      final dir = _uiChatInboxRequestDir;
      if (!dir.existsSync()) return;
      final pending =
          dir
              .listSync()
              .whereType<File>()
              .where((f) => f.path.endsWith('.json'))
              .toList()
            ..sort((a, b) => a.path.compareTo(b.path));
      if (pending.isEmpty) return;
      request = pending.first;
    } catch (_) {
      return;
    }
    _uiChatInboxBusy = true;
    final requestId = request.uri.pathSegments.last.replaceAll('.json', '');
    try {
      final decoded = jsonDecode(request.readAsStringSync());
      final prompt = decoded is Map ? '${decoded['prompt'] ?? ''}'.trim() : '';
      // Trainer metadata ("this is a training turn of discipline X") rides the
      // request to the service for routing + memory hygiene. Absent on older
      // trainers; forwarded opaquely — the worker/service clamp it narrow-only.
      final rawMetadata = decoded is Map ? decoded['metadata'] : null;
      final inboxMetadata = rawMetadata is Map
          ? rawMetadata.map((k, v) => MapEntry('$k', v as Object?))
          : null;
      // Consume the request before submitting: a crash mid-turn must not leave a
      // prompt that replays forever.
      try {
        request.deleteSync();
      } catch (_) {}
      if (prompt.isEmpty) {
        _writeUiChatInboxResult(requestId, {
          'accepted': false,
          'status': 'request had no prompt text',
        });
        return;
      }
      // Show it happening: open Chat and put the text in the real composer.
      // Operator retries use this same Send path as the visible UI, not a
      // backend CLI assemble. Training packs still label themselves.
      final inboxKind = '${inboxMetadata?['kind'] ?? ''}'.trim().toLowerCase();
      final inboxSource = decoded is Map
          ? '${decoded['source'] ?? ''}'.trim()
          : '';
      final isOperatorRetry =
          inboxKind == 'operator_retry' || inboxSource == 'operator_retry';
      final isTrainingInbox =
          inboxMetadata != null &&
          (inboxMetadata['interactive'] == false ||
              '${inboxMetadata['curriculum'] ?? ''}'.trim().isNotEmpty);
      setState(() {
        _selectedIndex = _sectionIndexById('chat_runtime');
        _chatDraft = prompt;
        _chatText.text = prompt;
        _chatText.selection = TextSelection.collapsed(offset: prompt.length);
        _status = isOperatorRetry
            ? 'Retry in chat composer'
            : isTrainingInbox
            ? 'Training prompt in chat composer'
            : 'Prompt in chat composer';
      });
      _writeUiChatInboxResult(requestId, {
        'accepted': true,
        'status': 'prompt visible in composer',
        'prompt': prompt,
        'submitted_at_utc': DateTime.now().toUtc().toIso8601String(),
      });
      await Future<void>.delayed(const Duration(milliseconds: 450));
      if (!mounted) return;
      await _submitChatDraft(inboxMetadata: inboxMetadata);
      if (!mounted) return;
      _writeUiChatInboxResult(requestId, {
        'accepted': true,
        'completed': true,
        'status': 'chat turn finished',
        'prompt': prompt,
        'reply': _chatMessages.isNotEmpty ? _chatMessages.last.last : _output,
        'finished_at_utc': DateTime.now().toUtc().toIso8601String(),
      });
    } catch (error) {
      _writeUiChatInboxResult(requestId, {
        'accepted': false,
        'status': 'inbox delivery failed',
        'error': '$error',
      });
    } finally {
      _uiChatInboxBusy = false;
    }
  }

  Future<void> _maybeStartChatUiSoakFromEnvironment() async {
    if (!_environmentFlagEnabled('ENGEL_UI_CHAT_SOAK_ENABLED')) return;
    final startDelaySeconds = _environmentDouble(
      'ENGEL_UI_CHAT_SOAK_START_DELAY_SECONDS',
      12,
    );
    if (startDelaySeconds > 0) {
      await Future<void>.delayed(
        Duration(milliseconds: (startDelaySeconds * 1000).round()),
      );
    }
    final prompts = await _loadChatUiSoakPromptsFromEnvironment();
    if (!mounted || prompts.isEmpty) return;
    final minutes = _environmentDouble('ENGEL_UI_CHAT_SOAK_MINUTES', 60);
    final now = DateTime.now().toUtc();
    final runId =
        'ui_soak_${now.toIso8601String().replaceAll(RegExp(r'[^0-9A-Za-z]'), '')}_${ProcessInfo.currentRss}';
    final intervalMs = math
        .max(
          1000,
          ((minutes * 60 * 1000) / math.max(1, prompts.length)).round(),
        )
        .toInt();
    final interval = Duration(milliseconds: intervalMs);
    setState(() {
      _chatUiSoakActive = true;
      _chatUiSoakRunId = runId;
      _chatUiSoakPrompts = prompts;
      _chatUiSoakIndex = 0;
      _chatUiSoakCompleted = 0;
      _chatUiSoakDeadlineUtc = now.add(
        Duration(milliseconds: (minutes * 60 * 1000).round()),
      );
      _chatUiSoakNextDueUtc = now;
      _selectedIndex = _sectionIndexById('chat_runtime');
      _status = 'Chat UI soak active';
      _output =
          'Engel Chat UI soak active: ${prompts.length} prompt(s), ${minutes.toStringAsFixed(2)} minute(s).';
    });
    _writeChatUiSoakEvent('start', {
      'minutes': minutes,
      'interval_ms': interval.inMilliseconds,
    });
    unawaited(_submitNextChatUiSoakPrompt(interval));
    _chatUiSoakTimer?.cancel();
    _chatUiSoakTimer = Timer.periodic(const Duration(seconds: 1), (timer) {
      if (!mounted || !_chatUiSoakActive) {
        timer.cancel();
        return;
      }
      final deadline = _chatUiSoakDeadlineUtc;
      final current = DateTime.now().toUtc();
      if (deadline != null && current.isAfter(deadline)) {
        timer.cancel();
        setState(() {
          _chatUiSoakActive = false;
          _status = 'Chat UI soak complete';
        });
        _writeChatUiSoakEvent('complete', {'reason': 'deadline_reached'});
        return;
      }
      final nextDue = _chatUiSoakNextDueUtc;
      if (!_running &&
          _chatUiSoakIndex < _chatUiSoakPrompts.length &&
          nextDue != null &&
          !current.isBefore(nextDue)) {
        unawaited(_submitNextChatUiSoakPrompt(interval));
      }
    });
  }

  Future<void> _submitNextChatUiSoakPrompt(Duration interval) async {
    if (!mounted || !_chatUiSoakActive || _running) return;
    if (_chatUiSoakIndex >= _chatUiSoakPrompts.length) return;
    final promptNumber = _chatUiSoakIndex + 1;
    final prompt = _chatUiSoakPrompts[_chatUiSoakIndex];
    setState(() {
      _selectedIndex = _sectionIndexById('chat_runtime');
      _chatDraft = prompt;
      _chatText.text = prompt;
      _chatText.selection = TextSelection.collapsed(offset: prompt.length);
      _status =
          'Chat UI soak prompt $promptNumber/${_chatUiSoakPrompts.length}';
    });
    _writeChatUiSoakEvent('prompt_visible_in_composer', {
      'prompt_number': promptNumber,
      'prompt': prompt,
    });
    await Future<void>.delayed(const Duration(milliseconds: 450));
    if (!mounted || !_chatUiSoakActive || _running) return;
    _chatUiSoakIndex = promptNumber;
    _chatUiSoakNextDueUtc = DateTime.now().toUtc().add(interval);
    _writeChatUiSoakEvent('prompt_submitted', {
      'prompt_number': promptNumber,
      'prompt': prompt,
    });
    await _submitChatDraft();
    if (!mounted) return;
    setState(() {
      if (_chatUiSoakCompleted < promptNumber) {
        _chatUiSoakCompleted = promptNumber;
      }
      if (_chatUiSoakIndex >= _chatUiSoakPrompts.length) {
        _status = 'Chat UI soak prompts submitted';
      }
    });
    _writeChatUiSoakEvent('prompt_reply_finished', {
      'prompt_number': promptNumber,
      'status': _status,
    });
  }

  Future<List<int>> _readLeadingChatAttachmentBytes(
    File file,
    int limit,
  ) async {
    final bytes = <int>[];
    if (limit <= 0) return bytes;
    await for (final chunk in file.openRead(0, limit)) {
      bytes.addAll(chunk);
      if (bytes.length >= limit) break;
    }
    if (bytes.length <= limit) return bytes;
    return bytes.sublist(0, limit);
  }

  Future<EngelChatAttachment> _buildChatAttachment(String path) async {
    final file = File(path);
    final stat = await file.stat();
    if (stat.type != FileSystemEntityType.file) {
      throw StateError('not a file: $path');
    }
    final mimeType = _chatAttachmentMimeType(path);
    final kind = _chatAttachmentKind(mimeType, path);
    final sizeBytes = stat.size;
    var inlineBase64 = '';
    if (sizeBytes <= chatAttachmentInlineLimitBytes) {
      inlineBase64 = base64Encode(await file.readAsBytes());
    }
    var textPreview = '';
    if (_chatAttachmentLooksText(mimeType, path)) {
      final previewBytes = await _readLeadingChatAttachmentBytes(
        file,
        math.min(sizeBytes, chatAttachmentTextPreviewBytes),
      );
      textPreview = utf8
          .decode(previewBytes, allowMalformed: true)
          .replaceAll('\x00', '')
          .trim();
    }
    return EngelChatAttachment(
      id: 'chat-attachment-${DateTime.now().toUtc().microsecondsSinceEpoch}',
      path: path,
      name: _chatAttachmentNameFromPath(path),
      sizeBytes: sizeBytes,
      mimeType: mimeType,
      kind: kind,
      inlineBase64: inlineBase64,
      inlineTruncated: sizeBytes > chatAttachmentInlineLimitBytes,
      textPreview: textPreview,
      textPreviewTruncated:
          textPreview.isNotEmpty && sizeBytes > chatAttachmentTextPreviewBytes,
    );
  }

  Future<void> _pickChatAttachments() async {
    if (_running) return;
    if (!Platform.isWindows) {
      setState(() {
        _status = 'attachments unavailable';
        _output = 'Engel chat attachments currently use the Windows picker.';
      });
      return;
    }
    final remaining = chatAttachmentMaxFiles - _chatAttachments.length;
    if (remaining <= 0) {
      setState(() {
        _status = 'attachment limit reached';
        _output =
            'Engel chat can attach up to $chatAttachmentMaxFiles files per turn.';
      });
      return;
    }
    const pickerScript = r'''
Add-Type -AssemblyName System.Windows.Forms
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$dialog = New-Object System.Windows.Forms.OpenFileDialog
$dialog.Title = 'Attach files to Engel AI Main Chat'
$dialog.Filter = 'All files (*.*)|*.*'
$dialog.Multiselect = $true
if ($dialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
  $dialog.FileNames | ForEach-Object { Write-Output $_ }
}
''';
    setState(() {
      _status = 'choosing attachment';
      _output = 'Opening the Windows file picker for Engel chat attachments.';
    });
    try {
      final result = await _processRunner('powershell.exe', [
        '-NoProfile',
        '-Sta',
        '-ExecutionPolicy',
        'Bypass',
        '-Command',
        pickerScript,
      ], workingDirectory: appRoot).timeout(const Duration(minutes: 5));
      final rawPaths = result.stdout
          .toString()
          .split(RegExp(r'\r?\n'))
          .map((line) => line.trim())
          .where((line) => line.isNotEmpty)
          .toList();
      if (rawPaths.isEmpty) {
        setState(() {
          _status = 'attachment picker closed';
          _output = 'No attachment was selected.';
        });
        return;
      }
      final existing = _chatAttachments
          .map((item) => item.path.toLowerCase())
          .toSet();
      final selected = <String>[];
      for (final path in rawPaths) {
        final key = path.toLowerCase();
        if (existing.contains(key) || selected.contains(path)) continue;
        selected.add(path);
        if (selected.length >= remaining) break;
      }
      final added = <EngelChatAttachment>[];
      final failures = <String>[];
      for (final path in selected) {
        try {
          added.add(await _buildChatAttachment(path));
        } catch (error) {
          failures.add('$path: $error');
        }
      }
      if (!mounted) return;
      setState(() {
        _chatAttachments.addAll(added);
        _status = added.isEmpty
            ? 'attachment failed'
            : 'attached ${added.length} file${added.length == 1 ? '' : 's'}';
        _output = [
          if (added.isNotEmpty)
            'Attached to next Engel chat turn:\n${added.map((item) => '- ${item.name} (${_chatAttachmentSizeLabel(item.sizeBytes)}, ${item.kind})').join('\n')}',
          if (failures.isNotEmpty)
            'Attachment failures:\n${failures.join('\n')}',
        ].where((part) => part.trim().isNotEmpty).join('\n\n');
      });
    } on TimeoutException {
      if (!mounted) return;
      setState(() {
        _status = 'attachment picker timeout';
        _output = 'The Windows file picker did not return before the timeout.';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _status = 'attachment picker error';
        _output = 'ERROR opening Engel chat attachment picker:\n$error';
      });
    }
  }

  Future<void> _pickChatFolder() async {
    if (_running) return;
    if (!Platform.isWindows) {
      setState(() {
        _status = 'folder context unavailable';
        _output = 'Engel folder context currently uses the Windows picker.';
      });
      return;
    }
    if (_chatAttachments.length >= chatAttachmentMaxFiles) {
      setState(() {
        _status = 'attachment limit reached';
        _output =
            'Engel chat can attach up to $chatAttachmentMaxFiles context sources per turn.';
      });
      return;
    }
    final pickerScript =
        r'''
Add-Type -AssemblyName System.Windows.Forms
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$dialog = New-Object System.Windows.Forms.FolderBrowserDialog
$dialog.Description = 'Add a folder manifest to Engel AI Main Chat'
$dialog.ShowNewFolderButton = $false
if ($dialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
  $root = $dialog.SelectedPath
  $items = @(Get-ChildItem -LiteralPath $root -Recurse -File -ErrorAction SilentlyContinue)
  $shown = @($items | Select-Object -First __MAX_ENTRIES__ | ForEach-Object {
    $_.FullName.Substring($root.Length).TrimStart('\')
  })
  $totalBytes = ($items | Measure-Object -Property Length -Sum).Sum
  if ($null -eq $totalBytes) { $totalBytes = 0 }
  [ordered]@{
    ok = $true
    path = $root
    totalCount = $items.Count
    totalBytes = [int64]$totalBytes
    entries = $shown
    truncated = $items.Count -gt __MAX_ENTRIES__
  } | ConvertTo-Json -Compress -Depth 4
}
'''
            .replaceAll('__MAX_ENTRIES__', '$chatFolderManifestMaxEntries');
    setState(() {
      _status = 'choosing folder context';
      _output = 'Opening the Windows folder picker.';
    });
    try {
      final result = await _processRunner('powershell.exe', [
        '-NoProfile',
        '-Sta',
        '-ExecutionPolicy',
        'Bypass',
        '-Command',
        pickerScript,
      ], workingDirectory: appRoot).timeout(const Duration(minutes: 5));
      final raw = result.stdout.toString().trim();
      if (raw.isEmpty) {
        if (!mounted) return;
        setState(() {
          _status = 'folder picker closed';
          _output = 'No folder was selected.';
        });
        return;
      }
      final parsed = jsonDecode(raw);
      if (parsed is! Map || parsed['ok'] != true) {
        throw const FormatException('folder picker returned invalid JSON');
      }
      final path = (parsed['path'] ?? '').toString().trim();
      final entries = parsed['entries'] is List
          ? (parsed['entries'] as List)
                .map((item) => item.toString())
                .where((item) => item.trim().isNotEmpty)
                .toList()
          : <String>[];
      final totalCount = int.tryParse('${parsed['totalCount'] ?? 0}') ?? 0;
      final totalBytes = int.tryParse('${parsed['totalBytes'] ?? 0}') ?? 0;
      final truncated = parsed['truncated'] == true;
      final manifest = <String>[
        'Folder: ${_chatAttachmentNameFromPath(path)}',
        'Files: $totalCount',
        ...entries,
        if (truncated)
          '... manifest limited to the first $chatFolderManifestMaxEntries files',
      ].join('\n');
      final attachment = EngelChatAttachment(
        id: 'chat-folder-${DateTime.now().toUtc().microsecondsSinceEpoch}',
        path: path,
        name: _chatAttachmentNameFromPath(path),
        sizeBytes: totalBytes,
        mimeType: 'application/x-directory',
        kind: 'folder',
        inlineBase64: '',
        inlineTruncated: true,
        textPreview: manifest,
        textPreviewTruncated: truncated,
      );
      if (!mounted) return;
      setState(() {
        _chatAttachments.add(attachment);
        _status = 'folder context attached';
        _output =
            'Added ${attachment.name}: $totalCount files represented by a bounded manifest.';
      });
    } on TimeoutException {
      if (!mounted) return;
      setState(() {
        _status = 'folder picker timeout';
        _output =
            'The Windows folder picker did not return before the timeout.';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _status = 'folder context error';
        _output = 'ERROR adding folder context:\n$error';
      });
    }
  }

  void _insertTextIntoChatComposer(String value) {
    final text = sanitizeEngelChatTextForWorker(value).trimRight();
    if (text.isEmpty) return;
    final current = _chatText.text;
    final selection = _chatText.selection;
    if (selection.isValid) {
      final start = math.max(0, math.min(selection.start, current.length));
      final end = math.max(0, math.min(selection.end, current.length));
      final next = current.replaceRange(start, end, text);
      _chatText.text = next;
      _chatText.selection = TextSelection.collapsed(
        offset: start + text.length,
      );
      _chatDraft = next;
      return;
    }
    final spacer = current.trim().isEmpty || current.endsWith('\n') ? '' : '\n';
    final next = '$current$spacer$text';
    _chatText.text = next;
    _chatText.selection = TextSelection.collapsed(offset: next.length);
    _chatDraft = next;
  }

  Future<void> _pasteChatClipboard() async {
    if (_running) return;
    if (!Platform.isWindows) {
      setState(() {
        _status = 'paste unavailable';
        _output =
            'Engel chat clipboard paste currently uses the Windows clipboard.';
      });
      return;
    }
    final attachmentDir = chatAttachmentRuntimeDir.replaceAll("'", "''");
    final pasteScript =
        r'''
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$result = [ordered]@{
  ok = $true
  text = ''
  files = @()
  imagePath = ''
  status = 'empty'
  error = ''
}
try {
  if ([System.Windows.Forms.Clipboard]::ContainsText()) {
    $result.text = [System.Windows.Forms.Clipboard]::GetText()
    $result.status = 'text'
  }
  if ([System.Windows.Forms.Clipboard]::ContainsFileDropList()) {
    $list = [System.Windows.Forms.Clipboard]::GetFileDropList()
    foreach ($item in $list) {
      $result.files += [string]$item
    }
    $result.status = if ($result.status -eq 'text') { 'text-files' } else { 'files' }
  }
  if ([System.Windows.Forms.Clipboard]::ContainsImage()) {
    $dir = '__ENGEL_CHAT_ATTACHMENT_DIR__'
    New-Item -ItemType Directory -Force -Path $dir | Out-Null
    $stamp = [DateTime]::UtcNow.ToString('yyyyMMddTHHmmssfffffffZ')
    $imagePath = Join-Path $dir ("clipboard_image_$stamp.png")
    $image = [System.Windows.Forms.Clipboard]::GetImage()
    $image.Save($imagePath, [System.Drawing.Imaging.ImageFormat]::Png)
    $image.Dispose()
    $result.imagePath = $imagePath
    $result.status = if ($result.status -eq 'text') { 'text-image' } elseif ($result.status -eq 'files') { 'files-image' } else { 'image' }
  }
} catch {
  $result.ok = $false
  $result.status = 'error'
  $result.error = $_.Exception.Message
}
$result | ConvertTo-Json -Compress -Depth 5
'''
            .replaceAll('__ENGEL_CHAT_ATTACHMENT_DIR__', attachmentDir);
    setState(() {
      _status = 'reading clipboard';
      _output = 'Reading Windows clipboard for Engel chat.';
    });
    try {
      final result = await _processRunner('powershell.exe', [
        '-NoProfile',
        '-Sta',
        '-ExecutionPolicy',
        'Bypass',
        '-Command',
        pasteScript,
      ], workingDirectory: appRoot).timeout(const Duration(seconds: 25));
      final parsed = jsonDecode(result.stdout.toString().trim());
      if (parsed is! Map || parsed['ok'] != true) {
        throw StateError(
          parsed is Map
              ? parsed['error']
              : 'clipboard returned non-object JSON',
        );
      }
      final pastedText = (parsed['text'] ?? '').toString();
      final paths = <String>[];
      final files = parsed['files'];
      if (files is List) {
        paths.addAll(
          files
              .map((item) => item.toString())
              .where((item) => item.trim().isNotEmpty),
        );
      }
      final imagePath = (parsed['imagePath'] ?? '').toString().trim();
      if (imagePath.isNotEmpty) paths.add(imagePath);
      final remaining = chatAttachmentMaxFiles - _chatAttachments.length;
      final selected = <String>[];
      if (remaining > 0) {
        final existing = _chatAttachments
            .map((item) => item.path.toLowerCase())
            .toSet();
        for (final path in paths) {
          final key = path.toLowerCase();
          if (existing.contains(key) || selected.contains(path)) continue;
          selected.add(path);
          if (selected.length >= remaining) break;
        }
      }
      final added = <EngelChatAttachment>[];
      final failures = <String>[];
      for (final path in selected) {
        try {
          added.add(await _buildChatAttachment(path));
        } catch (error) {
          failures.add('$path: $error');
        }
      }
      if (!mounted) return;
      setState(() {
        if (pastedText.trim().isNotEmpty) {
          _insertTextIntoChatComposer(pastedText);
          _chatContextItems.add({
            'schema': 'engel_chat_context_item_v1',
            'id': 'clipboard-${DateTime.now().toUtc().microsecondsSinceEpoch}',
            'kind': 'pasted_text',
            'name': 'Windows clipboard text',
            'mime_type': 'text/plain',
            'text': pastedText,
            'source': 'ROG Engel AI Main Chat UI clipboard',
          });
        }
        _chatAttachments.addAll(added);
        final parts = <String>[
          if (pastedText.trim().isNotEmpty)
            'Pasted text into the Engel chat composer.',
          if (added.isNotEmpty)
            'Staged attachment(s):\n${added.map((item) => '- ${item.name} (${_chatAttachmentSizeLabel(item.sizeBytes)}, ${item.kind})').join('\n')}',
          if (paths.length > selected.length)
            'Some clipboard files were not staged because the per-turn limit is $chatAttachmentMaxFiles.',
          if (failures.isNotEmpty)
            'Paste attachment failures:\n${failures.join('\n')}',
        ];
        _status = parts.isEmpty ? 'clipboard empty' : 'clipboard pasted';
        _output = parts.isEmpty
            ? 'Clipboard did not contain text, files, or an image Engel can use.'
            : parts.join('\n\n');
      });
    } on TimeoutException {
      if (!mounted) return;
      setState(() {
        _status = 'clipboard timeout';
        _output = 'Windows clipboard did not return before the timeout.';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _status = 'clipboard error';
        _output = 'ERROR reading clipboard for Engel chat:\n$error';
      });
    }
  }

  void _removeChatAttachment(String id) {
    if (_running) return;
    setState(() {
      _chatAttachments.removeWhere((item) => item.id == id);
      _status = _chatAttachments.isEmpty
          ? 'attachments cleared'
          : '${_chatAttachments.length} attachment(s) staged';
    });
  }

  List<Map<String, Object?>> _chatAttachmentPayloads(
    List<EngelChatAttachment> attachments,
  ) {
    return attachments.map((item) => item.toPayload()).toList();
  }

  String _chatAttachmentBubbleSummary(List<EngelChatAttachment> attachments) {
    if (attachments.isEmpty) return '';
    final lines = [
      'Attachments:',
      for (final item in attachments)
        '- ${item.name} (${_chatAttachmentSizeLabel(item.sizeBytes)}, ${item.kind}${item.inlineTruncated ? ', metadata-only large file' : ''})',
    ];
    return lines.join('\n');
  }

  String _promptWithAttachmentContext(
    String prompt,
    List<EngelChatAttachment> attachments,
  ) {
    final cleanPrompt = _cleanLocalChatPrompt(prompt);
    if (attachments.isEmpty) return cleanPrompt;
    final lines = <String>[
      cleanPrompt.isEmpty ? 'Please review the attached file(s).' : cleanPrompt,
      '',
      'Engel chat attachments for this user turn:',
    ];
    for (var index = 0; index < attachments.length; index++) {
      final item = attachments[index];
      lines.add(
        '${index + 1}. ${item.name} - ${item.kind}, ${item.mimeType}, ${_chatAttachmentSizeLabel(item.sizeBytes)}',
      );
      if (item.textPreview.isNotEmpty) {
        lines.add(
          'Preview:\n${sanitizeEngelChatTextForWorker(item.textPreview).trim()}',
        );
      } else if (item.kind == 'image') {
        lines.add('Image content was attached for server-side storage.');
      } else if (item.inlineTruncated) {
        lines.add(
          'Large file attached as metadata only in the UI fallback lane.',
        );
      }
    }
    return lines.join('\n');
  }

  void _clearChat() {
    if (_running) return;
    setState(() {
      _chatDraft = '';
      _lastChatDraft = '';
      _agentWorkReviewPending = false;
      _agentTaskState = '';
      _agentTaskGoal = '';
      _agentTaskStatus = '';
      _agentTaskProofPath = '';
      _agentTaskProofDetails = '';
      _chatProviderChoice = 'auto';
      _chatMessages.clear();
      _chatTokenUsage = null;
      _chatAttachments.clear();
      _chatContextItems.clear();
      _chatConversationId =
          'rog-ui-${DateTime.now().toUtc().microsecondsSinceEpoch}';
      _status = 'ready';
      _output = 'New Engel chat ready. Type a message to talk with Engel.';
    });
    _chatText.clear();
  }

  bool get _chatHasContent =>
      _chatDraft.trim().isNotEmpty ||
      _lastChatDraft.trim().isNotEmpty ||
      _chatMessages.isNotEmpty ||
      _chatAttachments.isNotEmpty;

  bool get _otherWorkRunning => _running && !_chatRunning;

  String get _otherWorkMessage =>
      'Engel is finishing another task. Your message is saved here. '
      'Send will be available when it finishes.';

  void _announcePromptBusy() {
    _showConnectorSnack(
      _chatRunning
          ? 'Engel is answering this chat. Use Stop before starting something else.'
          : _otherWorkMessage,
      ok: false,
    );
  }

  Future<void> _startNewChat() async {
    if (_running) {
      _announcePromptBusy();
      return;
    }
    if (_chatHasContent) {
      final confirmed = await showDialog<bool>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          title: const Text('Start a new chat?'),
          content: const Text(
            'This clears the current conversation from this window. Saved Engel memory is not deleted.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(false),
              child: const Text('Keep this chat'),
            ),
            FilledButton(
              key: const Key('confirm-new-chat'),
              onPressed: () => Navigator.of(dialogContext).pop(true),
              child: const Text('Start new chat'),
            ),
          ],
        ),
      );
      if (confirmed != true || !mounted) return;
    }
    _clearChat();
    _selectSectionById('chat_runtime');
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _chatInputFocus.requestFocus();
    });
  }

  void _submitHomePrompt() {
    final prompt = _cleanLocalChatPrompt(_homePromptText.text);
    if (prompt.isEmpty) return;
    if (_running) {
      _announcePromptBusy();
      return;
    }
    final wikiView = _wikiOneViewForPrompt(prompt);
    if (wikiView != null) {
      _homePromptText.clear();
      unawaited(_openWikiBrain(wikiView));
      return;
    }
    _homePromptText.clear();
    _openChatWithDraft(prompt);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) unawaited(_submitChatDraft());
    });
  }

  void _replaceLastAssistantBubble(String role, String text) {
    if (_chatMessages.isNotEmpty) {
      final lastRole = _chatMessages.last.first;
      if (lastRole == 'Engel AI' ||
          lastRole == 'Engel Runtime' ||
          lastRole == 'Engel Thinking' ||
          lastRole == 'Thinking' ||
          lastRole == 'Engel Status' ||
          lastRole == 'Engel Error') {
        _chatMessages.removeLast();
      }
    }
    _chatMessages.add([role, text]);
    _queueChatThreadBottomScroll();
  }

  void _queueChatThreadBottomScroll() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_chatScroll.hasClients) return;
      _chatScroll.animateTo(
        _chatScroll.position.maxScrollExtent,
        duration: const Duration(milliseconds: 240),
        curve: Curves.easeOutCubic,
      );
    });
  }

  Future<void> _submitChatDraft({Map<String, Object?>? inboxMetadata}) async {
    // inboxMetadata is only ever supplied by _drainUiChatInbox for the one
    // training turn it delivers; every operator path calls with none, so a
    // stale training context can never ride on a human turn (consume-once by
    // construction — no field to clear).
    final rawText = _cleanLocalChatPrompt(_chatDraft);
    final providerChoice = _effectiveChatProvider;
    final attachments = List<EngelChatAttachment>.from(_chatAttachments);
    final contextItems = _chatContextItems
        .map((item) => Map<String, Object?>.from(item))
        .toList();
    if (rawText.isEmpty && attachments.isEmpty) return;
    if (_running) {
      _announcePromptBusy();
      return;
    }
    if (_mainServerOnline != true && widget.localChatRunner == null) {
      final checking = _mainServerOnline == null;
      setState(() {
        _status = checking
            ? 'waiting for Engel chat connection'
            : 'Engel chat unavailable';
        _output = checking
            ? 'Engel is checking the chat connection. Your message and attachments are still here. Send again when the header says Chat ready.'
            : 'Engel chat is unavailable. Your message and attachments are still here. Use Try again or Connection help above.';
      });
      _showConnectorSnack(
        checking
            ? 'Still checking Engel chat. Your message is saved here.'
            : 'Engel chat is unavailable. Your message is saved here.',
        ok: false,
      );
      return;
    }
    final plainText = rawText.isEmpty
        ? 'Please review the attached file(s).'
        : rawText;
    // Training inbox turns must stay on CT246 chat. Building-code excerpts
    // contain the word "code"; treating them as operator work prefixes
    // "engel work" and the Agent Kernel steals the turn (Construction 7h
    // 2026-09-13 died at prompt 41 with a 21s Engelscript reject).
    // The voice card says "you are not a Discord guest". Do not open Discord
    // desktop for a training turn; the worker also skips Discord checkout
    // when interactive is false.
    final nonInteractiveInbox =
        inboxMetadata != null && inboxMetadata['interactive'] == false;
    if (!nonInteractiveInbox &&
        _chatPromptLooksLikeDiscordCheckout(plainText)) {
      unawaited(_openDiscordDesktop());
    }
    final isAgentWork =
        !nonInteractiveInbox &&
        !_chatPromptLooksLikeCompanionCreativeChat(plainText) &&
        (_agentWorkReviewPending || _chatPromptLooksLikeOperatorWork(plainText));
    final text = isAgentWork ? 'engel work $plainText' : plainText;
    final visibleText = isAgentWork ? 'Task: $plainText' : plainText;
    final displayText = attachments.isEmpty
        ? visibleText
        : '$visibleText\n\n${_chatAttachmentBubbleSummary(attachments)}';
    setState(() {
      _running = true;
      _chatRunning = true;
      _status = 'Engel chat running';
      _lastChatDraft = visibleText;
      _chatDraft = '';
      _agentWorkReviewPending = false;
      if (isAgentWork) {
        _agentTaskState = 'running';
        _agentTaskGoal = plainText;
        _agentTaskStatus = 'Choosing safe tools and starting the work';
        _agentTaskProofPath = '';
        _agentTaskProofDetails = '';
      }
      _chatProviderChoice = 'auto';
      _chatAttachments.clear();
      _chatContextItems.clear();
      final stillPaths = attachments
          .where((item) => item.isStillImage && item.path.trim().isNotEmpty)
          .map((item) => item.path)
          .join('|');
      _chatMessages.add(
        stillPaths.isEmpty
            ? ['Operator', displayText]
            : ['Operator', displayText, stillPaths],
      );
      _chatMessages.add([
        'Engel Runtime',
        'Engel is working on your message.\n\nI will say when this is done or if it failed.',
      ]);
      _output = 'Queued Engel standalone chat LLM request.';
    });
    _queueChatThreadBottomScroll();
    _chatText.clear();
    // A non-interactive turn (prompt training / automation) must never take the browse
    // lane. Two things go wrong if it does, and both are silent: _runEngelBrowse is the
    // one branch that does NOT forward inboxMetadata, so the turn loses interactive:false
    // and every gate keyed on it; and the turn never reaches the worker at all, so no
    // wrapper receipt is written and a local-only training run makes an outward web
    // request. No delivered prompt classifies as browse today (0 of 1600 swept across all
    // 5 curricula x 4 levels), so this costs nothing now and closes the hole before some
    // future card mentions a domain or asks Engel to "render an image of" something.
    final nonInteractiveTurn = nonInteractiveInbox;
    // A work task that quotes a link has to finish on the agent lane. Sending
    // it to the browser instead opened the first URL, waited out the hold, and
    // left "Engel is working on your task" spinning after Chat was ready.
    final browseIntent = nonInteractiveTurn || isAgentWork
        ? null
        : _detectChatBrowserIntent(text);
    _writeLocalChatDiagnostic('route_selected', {
      'browse_kind': browseIntent?.kind ?? '',
      'browse_suppressed_non_interactive': nonInteractiveTurn,
      'prompt_length': text.length,
    });
    if (browseIntent != null) {
      await _runEngelBrowse(
        _promptWithAttachmentContext(text, attachments),
        browseIntent,
      );
    } else {
      await _runLocalChatReply(
        text,
        displayPrompt: visibleText,
        agentGoal: isAgentWork ? plainText : null,
        attachments: attachments,
        contextItems: contextItems,
        providerChoice: providerChoice,
        inboxMetadata: inboxMetadata,
      );
    }
  }

  String _cleanLocalChatPrompt(String value) {
    return cleanEngelChatTextForWorker(value);
  }

  void _persistVisibleChatTurn(
    String prompt,
    String reply,
    Map<String, dynamic>? parsed,
    bool workNotFinished,
    TokenUsageSnapshot? tokenUsage,
  ) {
    try {
      final dir = Directory('$appRoot\\memory\\persistent_chat');
      dir.createSync(recursive: true);
      final payload = <String, Object?>{
        'schema': 'engel_ai_main_persistent_chat_history_v1',
        'memory_source': 'engel-flutter-main visible chat',
        'created_at_utc': DateTime.now().toUtc().toIso8601String(),
        'prompt': prompt,
        'assistant_reply': reply,
        'ok': parsed?['ok'],
        'status': parsed?['status']?.toString() ?? _status,
        'build_verified': parsed?['build_verified'],
        'work_not_finished': workNotFinished,
        if (tokenUsage != null) 'token_usage': tokenUsage.toJson(),
        'workspace_receipt_path':
            parsed?['workspace_receipt_path']?.toString() ?? '',
        'persistent_chat_memory_path':
            '${dir.path}\\ENGEL_AI_MAIN_LLM_CHAT_MEMORY.jsonl',
        'model_output_trusted': false,
        'trusted_memory_write_enabled': false,
        'trust_scope':
            'context-only chat continuity; not approved trusted memory',
      };
      File(
        '${dir.path}\\ENGEL_AI_MAIN_LLM_CHAT_MEMORY.jsonl',
      ).writeAsStringSync(
        '${jsonEncode(payload)}\n',
        mode: FileMode.append,
        flush: true,
      );
    } catch (_) {
      // Recall persistence must never block Chat.
    }
  }

  void _writeLocalChatDiagnostic(
    String event, [
    Map<String, Object?> details = const {},
  ]) {
    try {
      final dir = Directory('${_engelTempRootForRuntime()}\\chat_diagnostics');
      dir.createSync(recursive: true);
      final payload = <String, Object?>{
        'schema': 'engel_ui_chat_diagnostic_v1',
        'event': event,
        'updated_at_utc': DateTime.now().toUtc().toIso8601String(),
        ...details,
      };
      File('${dir.path}\\engel_ui_chat_diagnostics.jsonl').writeAsStringSync(
        '${jsonEncode(payload)}\n',
        mode: FileMode.append,
        flush: true,
      );
    } catch (_) {
      // Diagnostics must never block Chat.
    }
  }

  Future<File?> _writeLocalChatPromptFile(String prompt) async {
    try {
      final dir = Directory('${_engelTempRootForRuntime()}\\chat_prompts');
      dir.createSync(recursive: true);
      final stamp = DateTime.now().toUtc().microsecondsSinceEpoch;
      final file = File('${dir.path}\\engel_ui_chat_prompt_$stamp.txt');
      file.writeAsStringSync(
        _cleanLocalChatPrompt(prompt),
        encoding: utf8,
        flush: true,
      );
      return file;
    } catch (_) {
      return null;
    }
  }

  bool _promptExplicitlyRequestsLanguageCatalog(String prompt) {
    final lowered = prompt.toLowerCase();
    return lowered.contains('all known code languages') ||
        lowered.contains('all code languages') ||
        lowered.contains('all types of code language') ||
        lowered.contains('language catalog') ||
        lowered.contains('polyglot catalog');
  }

  bool _promptContainsTokenOrPhrase(String lowered, String term) {
    final needle = term.toLowerCase();
    if (needle.trim().isEmpty) return false;
    if (RegExp(r'^[a-z0-9_]+$').hasMatch(needle)) {
      return RegExp(
        '(^|[^a-z0-9_])${RegExp.escape(needle)}([^a-z0-9_]|\$)',
      ).hasMatch(lowered);
    }
    return lowered.contains(needle);
  }

  String _normalizeDiscordPrompt(String prompt) {
    var text = prompt.toLowerCase().trim();
    const typos = <String, String>{
      'dicord': 'discord',
      'discrod': 'discord',
      'discort': 'discord',
      'disord': 'discord',
      'discrd': 'discord',
      'discordd': 'discord',
    };
    for (final entry in typos.entries) {
      text = text.replaceAll(entry.key, entry.value);
    }
    if (text.startsWith('engel work ')) {
      text = text.substring('engel work '.length);
    }
    return text;
  }

  bool _chatPromptLooksLikeDiscordCheckout(String prompt) {
    final lowered = _normalizeDiscordPrompt(prompt);
    if (lowered.startsWith('what is') ||
        lowered.startsWith("what's") ||
        lowered.startsWith('tell me about') ||
        lowered.startsWith('explain ')) {
      return false;
    }
    // Curriculum cards talk about Discord desks. They stay on Chat.
    if (lowered.contains('training depth:') ||
        lowered.contains('training task:')) {
      return false;
    }
    if (RegExp(
      r'\b(?:fix|wire|repair|rebuild|install|update|patch)\b',
    ).hasMatch(lowered)) {
      return false;
    }
    if (lowered == 'discord' ||
        lowered == 'discord chat' ||
        lowered == 'check out discord chat') {
      return true;
    }
    // The chat voice card says "you are not a Discord guest". That identity
    // line is not a request to open the room. Training prompts carry it on
    // every turn, and the old check treated them as Discord checkout.
    final stripped = lowered
        .replaceAll('not a discord guest', ' ')
        .replaceAll('not discord', ' ');
    if (!stripped.contains('discord') && !stripped.contains('#general')) {
      return false;
    }
    const markers = [
      'check',
      'open',
      'look',
      'read',
      'show',
      'status',
      'chat',
      'thread',
      'repeat',
      'replies',
    ];
    return markers.any(stripped.contains);
  }

  Future<void> _openDiscordDesktop() async {
    try {
      await Process.start('cmd.exe', [
        '/c',
        'start',
        '',
        'discord://',
      ], mode: ProcessStartMode.detached);
    } catch (_) {}
  }

  bool _chatPromptLooksLikeCompanionCreativeChat(String prompt) {
    final lowered = prompt.toLowerCase();
    const keepKernel = [
      'python',
      'flutter app',
      'engel work',
      'fix the',
      'wire the',
    ];
    if (keepKernel.any((term) => lowered.contains(term))) return false;
    const create = ['create', 'make', 'build', 'write', 'draw', 'design'];
    const artifact = [
      'html',
      'game',
      'webpage',
      'web page',
      'landing page',
      'mini game',
      'pong',
      'snake',
      'canvas',
    ];
    return create.any((term) => lowered.contains(term)) &&
        artifact.any((term) => lowered.contains(term));
  }

  bool _chatPromptLooksLikeOperatorWork(String prompt) {
    if (_chatPromptLooksLikeCreationOrCode(prompt)) return true;
    if (_chatPromptLooksLikeDiscordCheckout(prompt)) return true;
    final lowered = prompt.toLowerCase();
    const verbs = [
      'fix',
      'wire',
      'pair',
      'connect',
      'repair',
      'respond',
      'reply to',
      'collab',
      'dispatch',
      'install',
      'launch',
      'stop looping',
      'name the gap',
      'engel work',
    ];
    if (lowered.startsWith('what is') ||
        lowered.startsWith("what's") ||
        lowered.startsWith('tell me about') ||
        lowered.startsWith('explain ')) {
      return false;
    }
    return verbs.any((verb) => lowered.contains(verb));
  }

  bool _chatPromptLooksLikeCreationOrCode(String prompt) {
    final lowered = prompt.toLowerCase();
    if (lowered.contains('```') ||
        _promptExplicitlyRequestsLanguageCatalog(prompt)) {
      return true;
    }
    // "App" is also how the operator refers to the running Engel UI. Only
    // classify it as software work when a direct change/create verb targets
    // the app; identity and proof questions must remain normal conversation.
    final appChangeRequest = RegExp(
      r'\b(?:build|create|make|develop|write|fix|debug|refactor|implement|code|update|upgrade)\b.{0,40}\b(?:app|application)\b',
    ).hasMatch(lowered);
    if (appChangeRequest) return true;
    // A creation verb by itself is not code. In particular, normal requests
    // such as "write a client update" and device work such as "ask Gamma"
    // must reach chat/device routing without the code-language catalog prefix.
    const codeTerms = [
      'code',
      'script',
      'function',
      'program',
      'tool',
      'cli',
      'api',
      'endpoint',
      'website',
      'webpage',
      'web page',
      'python',
      'rust',
      'dart',
      'flutter',
      'javascript',
      'typescript',
      'powershell',
      'bash',
      'sql',
      'html',
      'css',
      'c++',
      'cpp',
      'kernel',
      'driver',
      'firmware',
      'compile',
      'refactor',
      'algorithm',
      // Mission Control job creation is creation-class work: it drives a real
      // build/verify pipeline and needs the big token budget (Codex 20260711).
      'mission control',
      'this room',
      'meeting room',
      'more comments',
      'more posts',
    ];
    return codeTerms.any((term) => _promptContainsTokenOrPhrase(lowered, term));
  }

  String _chatBuildSize(String prompt) {
    final lowered = _cleanLocalChatPrompt(prompt).toLowerCase();
    if (_promptContainsTokenOrPhrase(lowered, 'expert')) return 'expert';
    if (_promptContainsTokenOrPhrase(lowered, 'medium') &&
        !_promptContainsTokenOrPhrase(lowered, 'large')) {
      return 'medium';
    }
    if (_promptContainsTokenOrPhrase(lowered, 'large')) return 'large';
    const largeTerms = [
      'large',
      'full app',
      'production',
      'multi-page',
      'multipage',
      'dashboard',
      'authentication',
      'database',
      'admin panel',
      'complete system',
      'end to end',
      'end-to-end',
      'desktop app',
      'mobile app',
    ];
    return lowered.length >= 700 || largeTerms.any(lowered.contains)
        ? 'large'
        : 'medium';
  }

  int _localChatMaxTokensForPrompt(String prompt) {
    if (_chatPromptLooksLikeCreationOrCode(prompt)) {
      return switch (_chatBuildSize(prompt)) {
        'expert' => 16384,
        'large' => 12288,
        _ => 6000,
      };
    }
    final length = _cleanLocalChatPrompt(prompt).length;
    if (length <= 280) return 640;
    if (length <= 1200) return 1024;
    return 1536;
  }

  Future<void> _runLocalChatReply(
    String prompt, {
    String? displayPrompt,
    String? agentGoal,
    List<EngelChatAttachment> attachments = const [],
    List<Map<String, Object?>> contextItems = const [],
    String providerChoice = 'auto',
    Map<String, Object?>? inboxMetadata,
  }) async {
    final runner = widget.localChatRunner ?? defaultLocalChatRunner;
    final exe = widget.localChatRunner == null
        ? await _findStandaloneChatPython()
        : File('engel-standalone-chat-test.exe');
    final script = File(standaloneChatLlmScriptPath);
    final workerScript = File(longLivedLocalModelWorkerScriptPath);
    _writeLocalChatDiagnostic('runtime_discovery', {
      'python_found': exe != null,
      'python_path': exe?.path ?? '',
      'runner_script_exists': script.existsSync(),
      'worker_script_exists': workerScript.existsSync(),
    });
    if (exe == null ||
        (widget.localChatRunner == null &&
            (!await script.exists() || !await workerScript.exists()))) {
      setState(() {
        _replaceLastAssistantBubble(
          'Engel Error',
          'Engel standalone chat LLM runner was not found. Chat could not run.',
        );
        _running = false;
        _chatRunning = false;
        _output =
            'Engel standalone chat LLM runner was not found. Expected $standaloneChatLlmScriptPath and $longLivedLocalModelWorkerScriptPath';
        _status = 'chat runner missing';
      });
      return;
    }
    String effectivePrompt = widget.localChatRunner == null
        ? prompt
        : _promptWithAttachmentContext(prompt, attachments);
    final languagesContextApplied =
        _languagesContextEnabled &&
        (_promptExplicitlyRequestsLanguageCatalog(effectivePrompt) ||
            _chatPromptLooksLikeCreationOrCode(effectivePrompt));
    if (languagesContextApplied) {
      final prefix = _buildLanguagesPromptPrefix();
      effectivePrompt =
          '$prefix\n\nOperator request follows:\n$effectivePrompt';
    }
    final promptFile = await _writeLocalChatPromptFile(effectivePrompt);
    final maxTokens = _localChatMaxTokensForPrompt(prompt);
    final creationRoute = _chatPromptLooksLikeCreationOrCode(prompt);
    final chatTimeoutSeconds = creationRoute
        ? switch (_chatBuildSize(prompt)) {
            'expert' => 1800,
            'large' => 1800,
            _ => 480,
          }
        : (attachments.any((item) => item.isStillImage)
              ? engelLocalVisionChatTimeoutSeconds
              : engelLocalChatTimeoutSeconds);
    _writeLocalChatDiagnostic('worker_request_ready', {
      'prompt_file': promptFile?.path ?? '',
      'prompt_file_written': promptFile != null,
      'timeout_seconds': chatTimeoutSeconds,
      'max_tokens': maxTokens,
    });
    final args = [
      standaloneChatLlmScriptPath,
      if (promptFile != null)
        '--prompt-file=${promptFile.path}'
      else
        '--prompt=${_cleanLocalChatPrompt(effectivePrompt)}',
      '--timeout=$chatTimeoutSeconds',
      '--max-tokens=$maxTokens',
    ];
    _writeLocalChatDiagnostic('runtime_trace', {
      'stage': widget.localChatRunner == null
          ? 'Using long-lived local model service'
          : 'Launching chat backend',
      'prompt_file': promptFile?.path ?? '',
    });
    final runtimeTrace = _chatRuntimeTrace(
      prompt: prompt,
      stage: 'request started',
      promptFile: promptFile,
      executablePath: exe.path,
      arguments: args,
      languagesContextApplied: languagesContextApplied,
      providerOverride: providerChoice,
      timeoutSeconds: chatTimeoutSeconds,
      maxTokens: maxTokens,
      attachmentCount: attachments.length,
    );
    // Keep the live bubble friendly and safe: provenance paths remain available
    // through the diagnostics/tools surface, while the in-progress chat only
    // exposes the route and bounded command budget.
    final runtimeRoute = runtimeTrace
        .split('\n')
        .firstWhere(
          (line) => line.startsWith('Route:'),
          orElse: () => 'Route: normal chat lane first',
        );
    String liveTrace(int seconds) {
      final progress = _chatProgressText.trim();
      final working = progress.isEmpty
          ? 'Engel is working on your message.'
          : progress;
      return '$working\n\n$runtimeRoute\nCommand budget: --max-tokens=$maxTokens\n\n'
          'Still going — ${seconds}s elapsed. I will say when this is done or if it failed.';
    }

    final turnId = ++_chatTurnSerial;
    _activeChatTurn = turnId;
    final sw = Stopwatch()..start();
    _chatActivity.clear();
    _chatStreamText = '';
    _chatProgressText = '';
    _localModelService.onActivity = (line) {
      if (!mounted || !_chatRunning) return;
      // Skip the JSONL request/response protocol echoes; keep readable logs.
      if (line.startsWith('{') && line.contains('"id"')) return;
      _chatActivity.add(line);
      if (_chatActivity.length > 14) {
        _chatActivity.removeRange(0, _chatActivity.length - 14);
      }
    };
    // SSE tokens streamed end-to-end (GPU -> CT246 -> worker -> here): append
    // each token and render the reply live, with a cursor while it generates.
    _localModelService.onDelta = (id, delta) {
      if (!mounted || !_chatRunning) return;
      if (delta.isEmpty) return;
      _chatStreamText += delta;
      setState(() {
        _replaceLastAssistantBubble('Engel AI', '$_chatStreamText▍');
      });
    };
    _localModelService.onProgress = (id, statusText) {
      if (!mounted || !_chatRunning) return;
      if (statusText.trim().isEmpty) return;
      _chatProgressText = statusText.trim();
      if (_chatStreamText.isNotEmpty) return;
      setState(() {
        _replaceLastAssistantBubble(
          'Engel Runtime',
          liveTrace(sw.elapsed.inSeconds),
        );
      });
    };
    setState(() {
      _status = agentGoal == null
          ? 'Engel AI is replying'
          : 'Engel is working on your task';
      if (agentGoal != null) {
        _agentTaskState = 'running';
        _agentTaskGoal = agentGoal;
        _agentTaskStatus = 'Working through the safest available path';
      }
      _replaceLastAssistantBubble('Engel Runtime', liveTrace(0));
      _lastCommand = widget.localChatRunner == null
          ? 'Engel long-lived local model worker via tools\\engel_main_local_model_worker.py'
          : 'Engel standalone local LLM via tools\\run_engel_ui_chat_meeting_room_llm.py';
      _output = liveTrace(0);
    });
    _chatHeartbeatTimer?.cancel();
    _chatHeartbeatTimer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (!mounted || !_chatRunning) {
        _chatHeartbeatTimer?.cancel();
        return;
      }
      // Once tokens start streaming, the live reply text owns the bubble — don't
      // overwrite it with the activity trace.
      if (_chatStreamText.isNotEmpty) return;
      setState(
        () => _replaceLastAssistantBubble(
          'Engel Runtime',
          liveTrace(sw.elapsed.inSeconds),
        ),
      );
    });
    try {
      final vaultRoot = _engelVaultMemoryRootFromEnv();
      final chatTempRoot = _engelTempRootForRuntime();
      final chatEnvironment = {
        'ENGEL_APP_ROOT': appRoot,
        'ENGEL_HOME': _engelHomeRootForRuntime(),
        'ENGEL_UI_PROVIDER_CHOICE': providerChoice,
        'TEMP': chatTempRoot,
        'TMP': chatTempRoot,
        'TMPDIR': chatTempRoot,
        'CARGO_HOME': _engelCargoHomeForRuntime(),
        ..._engelMainServerRuntimeEnvironment(),
        if (vaultRoot.isNotEmpty) 'ENGEL_VAULT_MEMORY_ROOT': vaultRoot,
        if ((Platform.environment['ENGEL_STANDALONE_CHAT_PROVIDER'] ?? '')
            .trim()
            .isNotEmpty)
          'ENGEL_STANDALONE_CHAT_PROVIDER': Platform
              .environment['ENGEL_STANDALONE_CHAT_PROVIDER']!
              .trim(),
      };
      // (2026-07-07 audit Res-1) The long-lived worker path governs its own idle
      // deadline inside runChat (reset by every streamed token), so it must NOT be
      // wrapped in a fixed whole-turn .timeout that would cut long/active streams.
      // The injected test runner keeps the fixed wall-clock timeout.
      final result = await (widget.localChatRunner == null
          ? _localModelService.runChat(
              executable: exe.path,
              prompt: effectivePrompt,
              conversationId: _chatConversationId,
              timeoutSeconds: chatTimeoutSeconds,
              maxTokens: maxTokens,
              environment: chatEnvironment,
              attachments: _chatAttachmentPayloads(attachments),
              contextItems: contextItems,
              provider: providerChoice,
              model: _effectiveChatModel,
              selectedModelId: _activeModelId,
              selectedModelName: _activeModelName,
              selectedCreationModelId: _creationModelId,
              thinkingEnabled: _thinkingEnabled,
              reasoningEffort: _reasoningEffort,
              inboxMetadata: inboxMetadata,
            )
          : runner(
              exe.path,
              args,
              workingDirectory: appRoot,
              environment: chatEnvironment,
            ).timeout(Duration(seconds: chatTimeoutSeconds)));
      if (_activeChatTurn != turnId) return;
      _writeLocalChatDiagnostic('worker_result_received', {
        'exit_code': result.exitCode,
        'elapsed_ms': sw.elapsedMilliseconds,
      });
      _chatHeartbeatTimer?.cancel();
      sw.stop();
      final stdoutRaw = result.stdout.toString();
      final parsed = _tryJson(stdoutRaw);
      final reply = await _replyFromLocalChatResult(parsed, stdoutRaw);
      // A warning is shown only for a receipt carrying explicit, trusted
      // usage and limit fields.  A response without that evidence clears the
      // prior indicator instead of leaving a stale quota claim on screen.
      final tokenUsage = TokenUsageSnapshot.fromResponse(parsed);
      unawaited(_loadBuildPreviewFromReceipt(parsed));
      final backendOk = _localChatSucceeded(result.exitCode, parsed);
      final readableReply = _localChatHasReadableReply(parsed, reply);
      final proofSummary = _standaloneChatProofSummary(parsed);
      final taskOutcome = agentGoal == null
          ? null
          : _agentTaskOutcome(
              parsed,
              reply,
              backendOk,
              proofSummary,
              goal: agentGoal,
            );
      final buildVerified = parsed?['build_verified'];
      final receiptBuildVerified = parsed?['receipt'] is Map
          ? parsed!['receipt']['build_verified']
          : null;
      final workNotFinished =
          buildVerified == false || receiptBuildVerified == false;
      final role = taskOutcome != null && !taskOutcome.ok
          ? 'Engel Error'
          : workNotFinished
          ? 'Engel Status'
          : backendOk
          ? (readableReply ? 'Engel AI' : 'Engel Status')
          : 'Engel Error';
      final finalStatus = taskOutcome != null
          ? (taskOutcome.ok ? 'task completed' : 'task needs attention')
          : workNotFinished
          ? 'work not finished'
          : backendOk
          ? (readableReply ? 'chat replied' : 'chat no readable answer')
          : _localChatFailureStatus(result.exitCode, parsed);
      if (!mounted) return;
      // (2026-07-07 audit fix ④) If we streamed tokens and the authoritative
      // receipt reply only differs by surrounding whitespace, keep the text the
      // user already watched stream in — otherwise the bubble visibly mutates at
      // turn end (e.g. a trimmed leading space " PONG" -> "PONG").
      final streamedTrimmed = _chatStreamText.trim();
      final finalReply =
          (role == 'Engel AI' &&
              streamedTrimmed.isNotEmpty &&
              streamedTrimmed == reply.trim())
          ? streamedTrimmed
          : reply;
      setState(() {
        _replaceLastAssistantBubble(role, finalReply);
        _chatTokenUsage = tokenUsage;
        _output = [
          finalReply,
          if (workNotFinished) 'This work is not finished.',
          'Elapsed: ${sw.elapsedMilliseconds} ms',
          if (proofSummary.isNotEmpty) proofSummary,
        ].join('\n\n');
        _status = finalStatus;
        if (taskOutcome != null) {
          _agentTaskState = taskOutcome.ok ? 'success' : 'failure';
          _agentTaskStatus = taskOutcome.status;
          _agentTaskProofPath = taskOutcome.proofPath;
          _agentTaskProofDetails = taskOutcome.details;
        }
      });
      _persistVisibleChatTurn(
        prompt,
        finalReply,
        parsed,
        workNotFinished,
        tokenUsage,
      );
      // Voice-out: speak the answer aloud when the operator has enabled it and
      // this turn produced a real reply (not a status/error bubble).
      if (_voiceReplies && role == 'Engel AI') {
        unawaited(_speakEngelReply(reply));
      }
    } on EngelChatCancelled {
      if (_activeChatTurn != turnId) return;
      _chatHeartbeatTimer?.cancel();
      sw.stop();
      if (!mounted) return;
      setState(() {
        _replaceLastAssistantBubble(
          'Engel Status',
          '⏹ Stopped by operator after ${sw.elapsed.inSeconds}s. The Engel worker was reset — your next message starts a fresh turn.',
        );
        _output =
            'Chat stopped by operator after ${sw.elapsedMilliseconds} ms.';
        _status = 'chat stopped';
        if (agentGoal != null) {
          _agentTaskState = 'stopped';
          _agentTaskGoal = agentGoal;
          _agentTaskStatus = 'Stopped before completion';
          _agentTaskProofPath = '';
          _agentTaskProofDetails =
              'The task was stopped before a final completion receipt was returned.';
        }
      });
    } on TimeoutException {
      if (_activeChatTurn != turnId) return;
      _writeLocalChatDiagnostic('worker_timeout', {
        'timeout_seconds': chatTimeoutSeconds,
        'elapsed_ms': sw.elapsedMilliseconds,
      });
      _chatHeartbeatTimer?.cancel();
      if (!mounted) return;
      // (2026-07-07 audit Res-1) The watchdog only fires after a full idle window
      // with no tokens. If any reply already streamed in, keep it instead of
      // replacing the bubble with a bare error.
      final streamed = _chatStreamText.trim();
      setState(() {
        if (streamed.isNotEmpty) {
          _replaceLastAssistantBubble(
            'Engel AI',
            '$streamed\n\n_(Engel went quiet for ${chatTimeoutSeconds}s — reply may be cut off.)_',
          );
          _status = 'chat idle timeout (partial reply kept)';
        } else {
          _replaceLastAssistantBubble(
            'Engel Error',
            'Engel chat went silent for $chatTimeoutSeconds seconds with no response. Try again, or switch the chat route in Settings.',
          );
          _status = 'chat timeout';
        }
        _output = 'IDLE TIMEOUT after ${chatTimeoutSeconds}s\n$_lastCommand';
        if (agentGoal != null) {
          _agentTaskState = 'failure';
          _agentTaskGoal = agentGoal;
          _agentTaskStatus = 'Engel stopped receiving progress';
          _agentTaskProofPath = '';
          _agentTaskProofDetails = streamed.isNotEmpty
              ? 'A partial answer was kept, but the task did not return a final completion receipt.'
              : 'No progress was returned before the idle timeout.';
        }
      });
    } catch (error) {
      if (_activeChatTurn != turnId) return;
      _writeLocalChatDiagnostic('worker_error', {
        'error': '$error',
        'elapsed_ms': sw.elapsedMilliseconds,
      });
      _chatHeartbeatTimer?.cancel();
      if (!mounted) return;
      setState(() {
        _replaceLastAssistantBubble('Engel Error', 'ERROR: $error');
        _output = 'ERROR: $error\n$_lastCommand';
        _status = 'chat error';
        if (agentGoal != null) {
          _agentTaskState = 'failure';
          _agentTaskGoal = agentGoal;
          _agentTaskStatus = 'Engel could not finish the task';
          _agentTaskProofPath = '';
          _agentTaskProofDetails = 'Task error: $error';
        }
      });
    } finally {
      if (_activeChatTurn == turnId) {
        _chatHeartbeatTimer?.cancel();
        _localModelService.onActivity = null;
        _localModelService.onDelta = null;
        _localModelService.onProgress = null;
      }
      if (mounted && _activeChatTurn == turnId) {
        setState(() {
          _running = false;
          _chatRunning = false;
          _activeChatTurn = null;
        });
      }
    }
  }

  /// Stop button: cancels the in-flight chat turn. When the long-lived worker is
  /// running this resets it (the awaiting turn throws [EngelChatCancelled] and
  /// _runLocalChatReply renders the "stopped" bubble). For the injected test
  /// runner there is nothing to interrupt, so the UI wait is simply released.
  void _stopChat() {
    if (!_chatRunning) return;
    setState(() => _status = 'stopping Engel chat…');
    final cancelled = _localModelService.cancelActive();
    if (!cancelled) {
      _activeChatTurn = null;
      _chatHeartbeatTimer?.cancel();
      _localModelService.onActivity = null;
      _localModelService.onDelta = null;
      _localModelService.onProgress = null;
      if (!mounted) return;
      setState(() {
        _replaceLastAssistantBubble(
          'Engel Status',
          '⏹ Stop requested. The current lane could not be interrupted; its reply will be ignored.',
        );
        _running = false;
        _chatRunning = false;
        _status = 'chat stopped';
        if (_agentTaskState == 'running') {
          _agentTaskState = 'stopped';
          _agentTaskStatus = 'Stopped before completion';
          _agentTaskProofPath = '';
          _agentTaskProofDetails =
              'The task was stopped before a final completion receipt was returned.';
        }
      });
    }
  }

  String _chatRuntimeTrace({
    required String prompt,
    required String stage,
    File? promptFile,
    String? executablePath,
    List<String>? arguments,
    bool languagesContextApplied = false,
    String providerOverride = '',
    int timeoutSeconds = engelLocalChatTimeoutSeconds,
    int? maxTokens,
    int attachmentCount = 0,
  }) {
    final creationRoute = _chatPromptLooksLikeCreationOrCode(prompt);
    final route = creationRoute
        ? 'creation/device classifier active; Meeting Room may be used'
        : 'normal chat lane first; workers stay out unless backend classifies otherwise';
    final command = arguments == null || arguments.isEmpty
        ? 'pending'
        : 'python ${arguments.map(_quoteForDisplay).join(' ')}';
    final budget = maxTokens == null
        ? 'pending'
        : '${timeoutSeconds}s / max tokens: $maxTokens';
    return [
      'Engel runtime',
      'Stage: $stage',
      'Prompt chars: ${prompt.length}',
      'Prompt file: ${promptFile?.path ?? 'not written yet'}',
      'Executable: ${executablePath ?? 'not selected yet'}',
      'Backend script: $standaloneChatLlmScriptPath',
      'Long-lived worker: $longLivedLocalModelWorkerScriptPath',
      'Server chat tunnel: $engelMainServerChatHealthUrl',
      'Connection Doctor: $connectionLoopDoctorScriptPath',
      'Working directory: $appRoot',
      'Command: $command',
      'Timeout: $budget',
      'Route: $route',
      'Attachments: $attachmentCount',
      'Provider override: ${providerOverride.isEmpty ? 'none' : providerOverride}',
      'Language catalog injected: ${languagesContextApplied ? 'yes' : 'no'}',
      'Receipt target: D:\\b.WorkSpace\\Engel App\\reports\\engel_standalone_chat_llm\\chat_receipts',
      'Memory target: D:\\b.WorkSpace\\Engel App\\memory\\persistent_chat',
    ].join('\n');
  }

  String _quoteForDisplay(String value) {
    if (!value.contains(' ') && !value.contains('"')) return value;
    return '"${value.replaceAll('"', r'\"')}"';
  }

  String _standaloneChatProofSummary(Map<String, dynamic>? parsed) {
    if (parsed == null) return '';
    final lines = <String>[];
    final engine = parsed['chat_engine']?.toString();
    final model = parsed['model']?.toString();
    final latency = parsed['latency_ms']?.toString();
    final workspaceReceipt = parsed['workspace_receipt_path']?.toString();
    final externalReceipt = parsed['external_receipt_path']?.toString();
    final meetingOrder = parsed['meeting_room_order_id']?.toString();
    final meetingReceipt = parsed['ui_meeting_room_receipt_path']?.toString();
    final meetingReply = parsed['meeting_room_reply']?.toString();
    if (engine != null && engine.trim().isNotEmpty) {
      lines.add('Engine: $engine');
    }
    if (model != null && model.trim().isNotEmpty) {
      lines.add('Model: $model');
    }
    if (latency != null && latency.trim().isNotEmpty) {
      lines.add('Local LLM latency: $latency ms');
    }
    if (workspaceReceipt != null && workspaceReceipt.trim().isNotEmpty) {
      lines.add('Receipt: $workspaceReceipt');
    }
    if (externalReceipt != null && externalReceipt.trim().isNotEmpty) {
      lines.add('External receipt: $externalReceipt');
    }
    if (meetingOrder != null && meetingOrder.trim().isNotEmpty) {
      lines.add('Meeting Room order: $meetingOrder');
    }
    if (meetingReceipt != null && meetingReceipt.trim().isNotEmpty) {
      lines.add('Meeting Room receipt: $meetingReceipt');
    }
    if (meetingReply != null && meetingReply.trim().isNotEmpty) {
      lines.add('Meeting Room proof: ${_oneLine(meetingReply, 700)}');
    }
    final stationResults = parsed['meeting_room_station_results'];
    if (stationResults is List && stationResults.isNotEmpty) {
      lines.add(
        'Meeting Room stations: ${stationResults.take(8).map((item) => item.toString()).join(', ')}',
      );
    }
    return lines.join('\n');
  }

  List<Map<String, dynamic>> _nestedLocalChatMaps(
    Map<String, dynamic>? parsed,
  ) {
    if (parsed == null) return const [];
    final maps = <Map<String, dynamic>>[];
    final queue = <(Object, int)>[(parsed, 0)];
    var visited = 0;
    while (queue.isNotEmpty && visited < 120) {
      final (value, depth) = queue.removeAt(0);
      visited += 1;
      if (depth > 6) continue;
      if (value is Map) {
        final map = Map<String, dynamic>.from(value);
        maps.add(map);
        for (final child in map.values) {
          if (child is Map || child is List) {
            queue.add((child as Object, depth + 1));
          }
        }
      } else if (value is List) {
        for (final child in value.take(40)) {
          if (child is Map || child is List) {
            queue.add((child as Object, depth + 1));
          }
        }
      }
    }
    return maps;
  }

  ({bool ok, String status, String proofPath, String details})
  _agentTaskOutcome(
    Map<String, dynamic>? parsed,
    String reply,
    bool backendOk,
    String proofSummary, {
    String? goal,
  }) {
    final maps = _nestedLocalChatMaps(parsed);
    Map<String, dynamic>? kernel;
    for (final map in maps) {
      final schema = map['schema']?.toString() ?? '';
      if (schema == 'engel_agent_kernel_run_v1' ||
          schema == 'engel_ui_agent_task_result_v1' ||
          map['engel_agent_kernel_used'] == true) {
        kernel = map;
        if (schema == 'engel_agent_kernel_run_v1') break;
      }
    }
    final renderedStatus = RegExp(
      r'^Status:\s*(.+?)\s*$',
      multiLine: true,
      caseSensitive: false,
    ).firstMatch(reply)?.group(1)?.trim();
    var status = renderedStatus ?? kernel?['status']?.toString().trim() ?? '';
    final negative = RegExp(
      r'needs attention|fail|error|refus|denied|blocked|crash|empty goal|too many|no code model',
      caseSensitive: false,
    ).hasMatch(status);
    final kernelOk = kernel?['ok'];
    var ok = negative
        ? false
        : kernelOk is bool
        ? kernelOk
        : backendOk;
    final wantsDiscordReply = _chatPromptLooksLikeSubEngelReply(goal ?? '');
    final discordPosted =
        parsed?['discord_posted'] == true ||
        kernel?['discord_posted'] == true ||
        (parsed?['receipt'] is Map &&
            parsed!['receipt']['discord_posted'] == true);
    if (wantsDiscordReply && discordPosted != true) {
      ok = false;
      if (status.isEmpty || status == 'done' || status == 'Completed') {
        status = 'Did not post to Discord';
      }
    }
    if (_looksLikeInternalJsonDump(reply)) {
      ok = false;
      if (!wantsDiscordReply || discordPosted != true) {
        status = status.isEmpty
            ? 'Internal receipt is not a user reply'
            : status;
      }
    }
    if (status.isEmpty || status.startsWith('engel agent kernel')) {
      status = ok ? 'Completed' : 'Needs attention';
    }

    var proofPath = kernel?['receipt_path']?.toString().trim() ?? '';
    if (proofPath.isEmpty) {
      proofPath =
          RegExp(
            r'^Receipt:\s*(.+?)\s*$',
            multiLine: true,
            caseSensitive: false,
          ).firstMatch(reply)?.group(1)?.trim() ??
          '';
    }
    if (proofPath.toLowerCase() == 'not written') proofPath = '';

    final detailLines = <String>['Result: $status'];
    final selection = kernel?['selection'];
    final engine = selection is Map
        ? selection['engine']?.toString().trim() ?? ''
        : '';
    if (engine.isNotEmpty) detailLines.add('Work path: $engine');
    final executedRoutes = kernel?['executed_routes'];
    if (executedRoutes is num && executedRoutes > 0) {
      detailLines.add('Verified checks completed: ${executedRoutes.toInt()}');
    }
    final problems = kernel?['problems'];
    if (problems is List && problems.isNotEmpty) {
      detailLines.add(
        'Needs attention: ${problems.take(6).map((item) => item.toString()).join('; ')}',
      );
    }
    if (proofPath.isNotEmpty) detailLines.add('Agent receipt: $proofPath');
    if (proofSummary.trim().isNotEmpty) {
      detailLines.add(proofSummary.trim());
    }
    return (
      ok: ok,
      status: status,
      proofPath: proofPath,
      details: detailLines.join('\n'),
    );
  }

  Map<String, dynamic>? _buildReceiptFromParsed(Map<String, dynamic>? parsed) {
    Map<String, dynamic>? current = parsed;
    for (var depth = 0; depth < 5 && current != null; depth++) {
      final action = current['action'];
      final hasBuildAction =
          action is Map && action['kind']?.toString() == 'app_build';
      if (current['build_preview'] is Map || hasBuildAction) return current;
      final nested = current['receipt'];
      current = nested is Map ? Map<String, dynamic>.from(nested) : null;
    }
    return null;
  }

  String _serverArtifactUrl(Object? value) {
    final raw = value?.toString().trim() ?? '';
    if (raw.isEmpty) return '';
    final parsed = Uri.tryParse(raw);
    if (parsed != null && parsed.hasScheme) return parsed.toString();
    return Uri.parse(engelMainServerChatHealthUrl).resolve(raw).toString();
  }

  Future<String> _readBuildPreviewText(String url) async {
    if (url.isEmpty) return '';
    final client = HttpClient()..connectionTimeout = const Duration(seconds: 8);
    try {
      final request = await client.getUrl(Uri.parse(url));
      final response = await request.close().timeout(
        const Duration(seconds: 12),
      );
      if (response.statusCode != 200) return '';
      final bytes = await response.fold<List<int>>(
        <int>[],
        (buffer, chunk) => buffer..addAll(chunk),
      );
      final text = utf8.decode(bytes, allowMalformed: true);
      return text.length > 12000 ? '${text.substring(0, 12000)}\n...' : text;
    } catch (_) {
      return '';
    } finally {
      client.close(force: true);
    }
  }

  Future<File?> _captureWebBuildPreview(String url, String title) async {
    if (url.isEmpty || widget.localChatRunner != null) return null;
    final edgeCandidates = [
      File(r'C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe'),
      File(r'C:\Program Files\Microsoft\Edge\Application\msedge.exe'),
    ];
    final edge = edgeCandidates.where((file) => file.existsSync()).firstOrNull;
    if (edge == null) return null;
    final dir = Directory('$appRoot\\runtime\\build_previews');
    dir.createSync(recursive: true);
    final profile = Directory('${dir.path}\\edge-profile')
      ..createSync(recursive: true);
    final slug = title
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'^_+|_+$'), '');
    final screenshot = File(
      '${dir.path}\\${slug.isEmpty ? 'build' : slug}_${DateTime.now().toUtc().microsecondsSinceEpoch}.png',
    );
    try {
      final result = await Process.run(edge.path, [
        '--headless=new',
        '--disable-gpu',
        '--disable-extensions',
        '--hide-scrollbars',
        '--no-first-run',
        '--window-size=1100,760',
        '--user-data-dir=${profile.path}',
        '--screenshot=${screenshot.path}',
        url,
      ]).timeout(const Duration(seconds: 45));
      if (result.exitCode == 0 && screenshot.existsSync()) return screenshot;
    } catch (_) {
      return null;
    }
    return null;
  }

  Future<void> _loadBuildPreviewFromReceipt(
    Map<String, dynamic>? parsed,
  ) async {
    final receipt = _buildReceiptFromParsed(parsed);
    if (receipt == null) return;
    final preview = receipt['build_preview'] is Map
        ? Map<String, dynamic>.from(receipt['build_preview'] as Map)
        : <String, dynamic>{};
    final package = receipt['build_package'] is Map
        ? Map<String, dynamic>.from(receipt['build_package'] as Map)
        : <String, dynamic>{};
    final action = receipt['action'] is Map
        ? Map<String, dynamic>.from(receipt['action'] as Map)
        : <String, dynamic>{};
    final review = receipt['build_review'] is Map
        ? Map<String, dynamic>.from(receipt['build_review'] as Map)
        : <String, dynamic>{};
    final providerReview = review['provider'] is Map
        ? Map<String, dynamic>.from(review['provider'] as Map)
        : <String, dynamic>{};
    final lifecycle = <Map<String, dynamic>>[
      for (final row
          in (receipt['build_lifecycle'] is List
              ? receipt['build_lifecycle'] as List
              : const []))
        if (row is Map) Map<String, dynamic>.from(row),
    ];
    final files = <String>[
      for (final item
          in (preview['files'] is List ? preview['files'] as List : const []))
        item.toString(),
    ];
    final info = EngelBuildPreview(
      title: preview['title']?.toString().trim().isNotEmpty == true
          ? preview['title'].toString()
          : 'Engel Build',
      kind: preview['kind']?.toString() ?? 'app',
      language: action['language']?.toString() ?? '',
      buildSize: receipt['build_size']?.toString() ?? 'medium',
      verified: receipt['build_verified'] == true,
      workspacePath: preview['workspace_path']?.toString() ?? '',
      entryFile: preview['entry_file']?.toString() ?? '',
      previewUrl: _serverArtifactUrl(preview['url']),
      sourceUrl: _serverArtifactUrl(preview['source_url']),
      packagePath: package['path']?.toString() ?? '',
      packageUrl: _serverArtifactUrl(package['download_url']),
      packageSha256: package['sha256']?.toString() ?? '',
      files: files,
      lifecycle: lifecycle,
      reviewSummary: providerReview['summary']?.toString() ?? '',
      runOutput: preview['run_output']?.toString() ?? '',
      screenshotPath: '',
      sourcePreview: '',
      error: '',
    );
    if (!mounted) return;
    setState(() {
      _buildPreview = info;
      _buildPreviewVisible = true;
      _buildPreviewBusy = true;
    });
    final source = widget.localChatRunner != null
        ? ''
        : await _readBuildPreviewText(info.sourceUrl);
    final screenshot = info.kind == 'web'
        ? await _captureWebBuildPreview(info.previewUrl, info.title)
        : null;
    if (!mounted || _buildPreview?.workspacePath != info.workspacePath) return;
    setState(() {
      _buildPreview = info.copyWith(
        screenshotPath: screenshot?.path ?? '',
        sourcePreview: source,
        error: info.kind == 'web' && screenshot == null
            ? 'Web proof is available at the preview URL, but the embedded screenshot could not be rendered.'
            : '',
      );
      _buildPreviewBusy = false;
    });
  }

  Future<void> _openBuildPreviewUrl() async {
    final url = _buildPreview?.previewUrl ?? '';
    if (url.isEmpty) return;
    await Process.start('cmd.exe', [
      '/c',
      'start',
      '',
      url,
    ], mode: ProcessStartMode.detached);
  }

  Future<void> _downloadBuildPackage() async {
    final preview = _buildPreview;
    if (preview == null || preview.packageUrl.isEmpty) return;
    setState(() => _buildPreviewBusy = true);
    final client = HttpClient()
      ..connectionTimeout = const Duration(seconds: 10);
    try {
      final request = await client.getUrl(Uri.parse(preview.packageUrl));
      final response = await request.close().timeout(
        const Duration(seconds: 30),
      );
      if (response.statusCode != 200) {
        throw HttpException('package HTTP ${response.statusCode}');
      }
      final dir = Directory('$appRoot\\runtime\\build_previews\\packages')
        ..createSync(recursive: true);
      final name = preview.packagePath.replaceAll('\\', '/').split('/').last;
      final file = File(
        '${dir.path}\\${name.isEmpty ? 'engel-build.zip' : name}',
      );
      final sink = file.openWrite();
      await response.pipe(sink);
      await Process.start('explorer.exe', [
        '/select,',
        file.path,
      ], mode: ProcessStartMode.detached);
      if (mounted) setState(() => _status = 'build package downloaded');
    } catch (error) {
      if (mounted) {
        setState(() {
          _status = 'build package download failed';
          _buildPreview = preview.copyWith(
            error: 'Package download failed: $error',
          );
        });
      }
    } finally {
      client.close(force: true);
      if (mounted) setState(() => _buildPreviewBusy = false);
    }
  }

  String _oneLine(String text, int limit) {
    final clean = text.replaceAll('\r', ' ').replaceAll('\n', ' ').trim();
    if (clean.length <= limit) return clean;
    return '${clean.substring(0, limit - 3).trimRight()}...';
  }

  Map<String, dynamic>? _tryJson(String text) {
    final trimmed = text.trim();
    if (trimmed.isEmpty) return null;
    try {
      final parsed = jsonDecode(trimmed);
      return parsed is Map<String, dynamic> ? parsed : null;
    } catch (_) {
      // Continue below. The upgraded bridge can write progress text around the
      // final JSON receipt.
    }
    final candidates = <Map<String, dynamic>>[];
    for (
      var start = trimmed.indexOf('{');
      start >= 0;
      start = trimmed.indexOf('{', start + 1)
    ) {
      var depth = 0;
      var inString = false;
      var escaped = false;
      for (var index = start; index < trimmed.length; index++) {
        final code = trimmed.codeUnitAt(index);
        if (inString) {
          if (escaped) {
            escaped = false;
          } else if (code == 92) {
            escaped = true;
          } else if (code == 34) {
            inString = false;
          }
          continue;
        }
        if (code == 34) {
          inString = true;
        } else if (code == 123) {
          depth++;
        } else if (code == 125) {
          depth--;
          if (depth == 0) {
            try {
              final parsed = jsonDecode(trimmed.substring(start, index + 1));
              if (parsed is Map<String, dynamic>) candidates.add(parsed);
            } catch (_) {
              // Keep scanning for the final valid receipt.
            }
            break;
          }
        }
      }
    }
    if (candidates.isEmpty) return null;
    for (final candidate in candidates.reversed) {
      if (_localChatAssistantReply(candidate) != null ||
          candidate.containsKey('ok') ||
          candidate.containsKey('schema') ||
          candidate.containsKey('receipt')) {
        return candidate;
      }
    }
    return candidates.last;
  }

  File _pathFromAppRoot(String pathText) {
    final path = pathText.replaceAll('/', '\\');
    if (RegExp(r'^[A-Za-z]:\\').hasMatch(path) || path.startsWith(r'\\')) {
      return File(path);
    }
    return File('$appRoot\\$path');
  }

  bool _localChatSucceeded(int exitCode, Map<String, dynamic>? parsed) {
    final assistantReply = parsed == null
        ? null
        : _localChatAssistantReply(parsed);
    if (assistantReply != null &&
        _localChatHasReadableReply(parsed, assistantReply)) {
      return true;
    }
    if (exitCode != 0) return false;
    if (parsed?['ok'] == false &&
        parsed?['readable_output_captured'] == true &&
        _localChatAssistantReply(parsed!) != null) {
      return true;
    }
    return parsed?['ok'] != false;
  }

  bool _looksLikeInternalJsonDump(String reply) {
    final clean = reply.trim();
    return clean.startsWith('{') &&
        (clean.contains('"schema"') ||
            clean.contains('"lifted_intent"') ||
            clean.contains('"engel_agent_kernel_run_v1"'));
  }

  bool _chatPromptLooksLikeSubEngelReply(String prompt) {
    final lowered = prompt.toLowerCase();
    if (!lowered.contains('sub-engel') &&
        !lowered.contains('sub engel') &&
        !lowered.contains('subengel')) {
      return false;
    }
    return lowered.contains('reply') ||
        lowered.contains('respond') ||
        lowered.contains('responed') ||
        lowered.contains('collab') ||
        lowered.contains('answer sub');
  }

  bool _localChatHasReadableReply(Map<String, dynamic>? parsed, String reply) {
    final cleanReply = reply.trim();
    final hasReply =
        cleanReply.isNotEmpty &&
        !cleanReply.contains('no readable assistant answer was captured') &&
        !_looksLikeInternalJsonDump(cleanReply);
    if (!hasReply) return false;
    final readable = parsed?['readable_output_captured'];
    if (readable is bool) {
      return readable || _localChatAssistantReply(parsed!) != null;
    }
    final receipt = parsed?['receipt'];
    if (receipt is Map) {
      final receiptReadable = receipt['readable_output_captured'];
      if (receiptReadable is bool) return receiptReadable || hasReply;
    }
    return hasReply;
  }

  String _localChatFailureStatus(int exitCode, Map<String, dynamic>? parsed) {
    if (exitCode != 0) return 'chat exit $exitCode';
    final status = parsed?['status']?.toString();
    if (status != null && status.trim().isNotEmpty) return 'chat $status';
    return 'chat blocked';
  }

  /// Surface Conductor/kernel status + problems when the wrapper reply was
  /// lost or empty, so Tasks shows the real failure instead of a generic.
  String? _kernelOrConductorExplain(Map<String, dynamic> parsed) {
    Map<String, dynamic>? kernel;
    final maps = _nestedLocalChatMaps(parsed);
    for (final map in maps) {
      final schema = map['schema']?.toString() ?? '';
      if (schema == 'engel_agent_kernel_run_v1' ||
          schema == 'engel_ui_agent_task_result_v1' ||
          map['engel_agent_kernel_used'] == true) {
        kernel = map;
        if (schema == 'engel_agent_kernel_run_v1') break;
      }
    }
    kernel ??=
        (parsed['schema']?.toString() == 'engel_agent_kernel_run_v1')
        ? parsed
        : null;
    if (kernel == null) return null;
    final parts = <String>[];
    final status = kernel['status']?.toString().trim() ?? '';
    if (status.isNotEmpty) parts.add(status);
    final problems = kernel['problems'];
    if (problems is List && problems.isNotEmpty) {
      parts.add(
        problems.take(6).map((item) => item.toString()).join('; '),
      );
    }
    if (parts.isEmpty) return null;
    return parts.join('\n');
  }

  String? _localChatJsonMessage(Map<String, dynamic> parsed) {
    for (final key in ['reason', 'error', 'message', 'final_decision']) {
      final value = parsed[key]?.toString();
      if (value != null && value.trim().isNotEmpty) return value.trim();
    }
    final receipt = parsed['receipt'];
    if (receipt is Map) {
      for (final key in ['reason', 'error', 'message', 'final_decision']) {
        final value = receipt[key]?.toString();
        if (value != null && value.trim().isNotEmpty) return value.trim();
      }
    }
    return null;
  }

  String? _localChatTextValue(Object? value) {
    if (value == null) return null;
    if (value is String) {
      final trimmed = value.trim();
      return trimmed.isEmpty ? null : trimmed;
    }
    if (value is num || value is bool) return null;
    if (value is Map) {
      for (final key in [
        'assistant_output_text',
        'visible_reply',
        'assistant_reply',
        'local_llm_reply',
        'assistant_message',
        'reply',
        'response',
        'answer',
        'content',
        'text',
        'message',
        'delta',
        'output_text',
      ]) {
        final nested = _localChatTextValue(value[key]);
        if (nested != null) return nested;
      }
    }
    if (value is List) {
      final pieces = <String>[];
      for (final item in value) {
        final nested = _localChatTextValue(item);
        if (nested != null) pieces.add(nested);
      }
      if (pieces.isNotEmpty) return pieces.join('\n').trim();
    }
    return null;
  }

  String? _firstLocalChatText(Map<dynamic, dynamic> source, List<String> keys) {
    for (final key in keys) {
      final value = _localChatTextValue(source[key]);
      if (value != null && value.trim().isNotEmpty) return value.trim();
    }
    return null;
  }

  bool _looksLikeMeetingRoomProofReply(String value) {
    final lower = value.trim().toLowerCase();
    return lower.startsWith(
          'done. i routed this through the agent meeting room',
        ) ||
        lower.startsWith('i routed this through the agent meeting room') ||
        (lower.contains('real station output back') &&
            lower.contains('meeting room'));
  }

  String? _localChatAssistantReply(Map<String, dynamic> parsed) {
    final containers = <Map<dynamic, dynamic>>[parsed];
    final receipt = parsed['receipt'];
    if (receipt is Map) {
      containers.add(receipt);
    }
    const naturalKeys = [
      'assistant_output_text',
      'visible_reply',
      'visible_answer',
      'final_reply',
      'local_llm_reply',
      'assistant_message',
      'raw_first_reply',
      'reply',
      'response',
      'answer',
      'content',
      'text',
      'output_text',
      'choices',
      'outputs',
    ];
    for (final container in containers) {
      final value = _firstLocalChatText(container, naturalKeys);
      if (value != null && !_looksLikeMeetingRoomProofReply(value)) {
        return value;
      }
    }
    for (final container in containers) {
      final value = _firstLocalChatText(container, const ['assistant_reply']);
      if (value != null && !_looksLikeMeetingRoomProofReply(value)) {
        return value;
      }
    }
    for (final container in containers) {
      final value = _firstLocalChatText(container, const ['assistant_reply']);
      if (value != null) return value;
    }
    return null;
  }

  Future<String> _replyFromLocalChatResult(
    Map<String, dynamic>? parsed,
    String fallback,
  ) async {
    if (parsed == null) {
      final reply = _extractAssistantReply(fallback);
      return reply.trim().isEmpty
          ? 'Engel chat ran, but no readable assistant answer was captured.'
          : reply;
    }
    final status = parsed['status']?.toString() ?? 'unknown';
    final directReply = _localChatAssistantReply(parsed);
    if (directReply != null &&
        _localChatHasReadableReply(parsed, directReply)) {
      return directReply;
    }
    if (parsed['ok'] == false) {
      final message =
          _localChatJsonMessage(parsed) ??
          _kernelOrConductorExplain(parsed) ??
          'Engel chat request did not return a usable reply.';
      return '$status\n$message';
    }
    if (directReply != null) return directReply;
    final receipt = parsed['receipt'];
    final stdoutPath = receipt is Map
        ? receipt['stdout_log_path']?.toString()
        : null;
    if (stdoutPath != null && stdoutPath.trim().isNotEmpty) {
      final logPath = _pathFromAppRoot(stdoutPath);
      if (await logPath.exists()) {
        final reply = _extractAssistantReply(await logPath.readAsString());
        if (reply.trim().isNotEmpty) return reply;
      }
    }
    final decision =
        parsed['final_decision']?.toString() ??
        (receipt is Map ? receipt['final_decision']?.toString() : null);
    if (decision != null && decision.trim().isNotEmpty) {
      return '$status\n$decision';
    }
    final reply = _extractAssistantReply(fallback);
    if (reply.trim().isNotEmpty) return reply;
    return '$status\nEngel ran local chat, but no readable assistant answer was captured.';
  }

  String _extractAssistantReply(String text) {
    var clean = text.replaceAll('\r\n', '\n').replaceAll('\r', '\n').trim();
    if (clean.isEmpty) return '';
    final statsIndex = clean.indexOf('[ Prompt:');
    if (statsIndex >= 0) clean = clean.substring(0, statsIndex).trim();
    clean = clean.replaceAll('Exiting...', '').trim();
    final filtered = clean
        .split('\n')
        .where((line) {
          final trimmed = line.trim();
          if (trimmed.isEmpty) return true;
          final lower = trimmed.toLowerCase();
          if (lower.startsWith('loading model')) return false;
          if (lower.startsWith('build')) return false;
          if (lower.startsWith('model')) return false;
          if (lower.startsWith('modalities')) return false;
          if (lower.startsWith('available commands')) return false;
          if (trimmed.startsWith('>')) return false;
          if (trimmed.contains('APPROVED LOCAL CHAT MEMORY CONTEXT')) {
            return false;
          }
          if (trimmed.contains('UNTRUSTED LOCAL SESSION TRANSCRIPT')) {
            return false;
          }
          return true;
        })
        .join('\n')
        .trim();
    if (filtered.isEmpty) return '';
    final paragraphs = filtered
        .split(RegExp(r'\n\s*\n'))
        .map((part) => part.trim())
        .where((part) => part.isNotEmpty)
        .toList();
    for (final paragraph in paragraphs.reversed) {
      if (paragraph.length > 1800) continue;
      return paragraph;
    }
    return filtered.length > 1800
        ? '${filtered.substring(0, 1800)}...'
        : filtered;
  }

  Future<void> _refreshEngelBridgeStatus({bool quiet = false}) async {
    // quiet: refresh the pill's liveness fields WITHOUT writing the Results
    // panel — page-open refreshes must not overwrite whatever the operator was
    // reading there (the idle placeholder is itself asserted by tests).
    try {
      final requestRoot = Directory(standaloneConnectionRequestRoot);
      final profileRoot = Directory(connectorProfileRoot);
      final browserControlRoot = Directory(connectorBrowserControlRoot);
      final sourceExe = File(standaloneConnectionSourceExe);
      final chatConfig = File(widget.modelRouterConfigPath);
      final requestFiles = <FileSystemEntity>[];
      for (final root in [requestRoot, profileRoot, browserControlRoot]) {
        if (!root.existsSync()) continue;
        try {
          requestFiles.addAll(
            root
                .listSync(recursive: true, followLinks: false)
                .where(
                  (entry) => entry is File && entry.path.endsWith('.json'),
                ),
          );
        } on FileSystemException {
          // The browser worker rewrites its status files continuously; a file
          // vanishing mid-listing must not flip the whole pill to "offline" —
          // liveness is decided by the two file checks below, and this count
          // is best-effort decoration.
          continue;
        }
      }
      final sourceOk = sourceExe.existsSync();
      final chatConfigOk = chatConfig.existsSync();
      if (!mounted) return;
      setState(() {
        _engelBridgeLive = sourceOk && chatConfigOk;
        _engelBridgeProcessCount = requestFiles.length;
        _engelBridgeProcessIds = '${requestFiles.length} json status files';
        _engelBridgeWindowTitle = sourceOk
            ? 'Engel standalone source ready'
            : 'Engel standalone source missing';
        _engelBridgeStatus =
            '${sourceOk ? 'source ready' : 'source missing'} / '
            '${chatConfigOk ? 'chat config ready' : 'chat config missing'} / '
            '${requestFiles.length} connector files';
        if (!quiet) {
          _output =
              'Engel bridge refresh finished.\n'
              'Status: $_engelBridgeStatus\n'
              'Standalone source: $standaloneConnectionSourceExe\n'
              'Connector requests: $standaloneConnectionRequestRoot\n'
              'Connector profiles: $connectorProfileRoot\n'
              'Browser control: $connectorBrowserControlRoot\n'
              'Chat model config: ${widget.modelRouterConfigPath}\n'
              'Engel did not launch any external desktop app.';
          _status = _engelBridgeLive
              ? 'Engel bridge ready'
              : 'Engel bridge scan complete';
        }
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _engelBridgeLive = false;
        _engelBridgeProcessCount = 0;
        _engelBridgeProcessIds = 'error';
        _engelBridgeWindowTitle = 'Engel bridge scan failed';
        _engelBridgeStatus = 'Engel bridge status unavailable';
        if (!quiet) {
          _output =
              'Engel bridge refresh failed.\n'
              'Error: $error\n'
              'Engel did not launch any external desktop app.';
          _status = 'Engel bridge error';
        }
      });
    }
  }

  Future<File?> _findRustExe() async {
    final override = widget.rustExeOverride?.trim();
    if (override != null && override.isNotEmpty) return File(override);
    final candidates = [
      File(Platform.environment['ENGEL_AI_RS_EXE'] ?? ''),
      File(
        '$appRoot\\runtime\\temp\\engel-rust-rewrite\\cargo-target\\debug\\engel-ai-rs.exe',
      ),
      File(
        '$appRoot\\runtime\\temp\\engel-rust-rewrite\\cargo-target\\release\\engel-ai-rs.exe',
      ),
      File('$appRoot\\rust\\engel-core-rs\\target\\debug\\engel-ai-rs.exe'),
      File('$appRoot\\rust\\engel-core-rs\\target\\release\\engel-ai-rs.exe'),
    ];
    for (final file in candidates) {
      if (file.path.isNotEmpty && await file.exists()) return file;
    }
    return null;
  }

  // A flash-drive copy is deliberately small: it carries the Flutter shell
  // and writable workspace, not the development Rust toolchain or a binary
  // compiled with this computer's absolute paths.  Keep the two everyday
  // Terminal & Files actions useful in that copy with a bounded, read-only
  // Dart fallback.  The normal checkout still uses the real Rust command
  // unchanged; this branch is only selected when ENGEL_APP_ROOT is relative
  // (the portable build's `workspace` value).
  bool get _isPortableWorkspaceBuild {
    final value = appRoot.trim();
    if (value.isEmpty) return false;
    return !RegExp(r'^(?:[A-Za-z]:[\\/]|\\\\|/)').hasMatch(value);
  }

  Directory _portableWorkspaceRoot() {
    final configured = Directory(appRoot);
    if (configured.existsSync()) return configured;
    // Support opening app\\EngelAIMain.exe directly, not only through the
    // supplied launcher (which sets the stage as the current directory).
    // The portable layout always keeps workspace beside app/.
    try {
      final executableDirectory = File(Platform.resolvedExecutable).parent;
      final sibling = Directory(
        '${executableDirectory.parent.path}${Platform.pathSeparator}workspace',
      );
      if (sibling.existsSync()) return sibling;
    } catch (_) {
      // Fall back to the configured relative path and report its state below.
    }
    return configured;
  }

  static const _portableTerminalFallbackKeys = <String>{
    'feature_search_terminal',
    'feature_search_files',
    'feature_search_preview',
    'feature_search_logs',
    'workspace_inventory_short',
    'workspace_inventory_report',
    'runtime_wsl_status',
    'runtime_sandbox_status',
    'patch_plan_preview',
  };

  static const _portableScanSkipDirectories = <String>{
    '.git',
    '.dart_tool',
    'build',
    'dist',
    'target',
    'node_modules',
    'ms-playwright',
    'browser_ai_venv',
    'browser_python',
  };

  Future<List<FileSystemEntity>> _portableWorkspaceEntries(
    Directory root, {
    int limit = 80,
    int maxDepth = 0,
  }) async {
    if (!await root.exists()) return const <FileSystemEntity>[];
    final entries = <FileSystemEntity>[];
    Future<void> visit(Directory directory, int depth) async {
      if (entries.length >= limit) return;
      List<FileSystemEntity> children;
      try {
        children = await directory.list(followLinks: false).toList();
      } catch (_) {
        return;
      }
      children.sort(
        (a, b) => a.path.toLowerCase().compareTo(b.path.toLowerCase()),
      );
      for (final entity in children) {
        if (entries.length >= limit) return;
        entries.add(entity);
        if (entity is Directory && depth < maxDepth) {
          final segments = entity.uri.pathSegments
              .where((segment) => segment.isNotEmpty)
              .toList();
          final name = segments.isEmpty ? '' : segments.last;
          if (!_portableScanSkipDirectories.contains(name.toLowerCase())) {
            await visit(entity, depth + 1);
          }
        }
      }
    }

    await visit(root, 0);
    entries.sort(
      (a, b) => a.path.toLowerCase().compareTo(b.path.toLowerCase()),
    );
    return entries;
  }

  String _portableEntityLabel(FileSystemEntity entity) {
    final segments = entity.uri.pathSegments
        .where((segment) => segment.isNotEmpty)
        .toList();
    final name = segments.isEmpty ? entity.path : segments.last;
    if (entity is Directory) return '[dir] $name';
    if (entity is File) {
      try {
        return '[file] $name (${_formatBytes(entity.statSync().size)})';
      } catch (_) {
        return '[file] $name';
      }
    }
    return '[entry] $name';
  }

  Future<bool> _runPortableTerminalFilesFallback(
    RustCommand command, [
    String text = '',
  ]) async {
    if (!_isPortableWorkspaceBuild ||
        !_portableTerminalFallbackKeys.contains(command.key)) {
      return false;
    }
    final root = _portableWorkspaceRoot();
    setState(() {
      _running = true;
      _status = 'reading portable ${command.label.toLowerCase()}';
      _lastCommand = 'portable-readonly ${command.key}';
      _output =
          'Reading the portable workspace without Rust or shell execution...';
    });
    try {
      final query = text.trim().toLowerCase();
      final recursiveScan = command.key.startsWith('feature_search_');
      final entries = await _portableWorkspaceEntries(
        root,
        limit: recursiveScan ? 240 : 80,
        maxDepth: recursiveScan ? 3 : 0,
      );
      String output;
      if (command.key == 'feature_search_files') {
        final fileEntries = entries
            .where(
              (entity) =>
                  entity is File ||
                  entity.path.toLowerCase().contains('file') ||
                  entity.path.toLowerCase().contains('browser'),
            )
            .where(
              (entity) =>
                  query.isEmpty || entity.path.toLowerCase().contains(query),
            )
            .map(_portableEntityLabel)
            .toList();
        final routeMatches = rustCommands
            .where((candidate) {
              final haystack = '${candidate.key} ${candidate.label}'
                  .toLowerCase();
              return query.isEmpty
                  ? haystack.contains('file') || haystack.contains('browser')
                  : haystack.contains(query);
            })
            .take(16)
            .map(
              (candidate) => '- route: ${candidate.label} (${candidate.key})',
            );
        output = [
          'Portable Files search',
          'Workspace: ${root.path}',
          'Read-only bounded scan (up to ${entries.length} entries, depth 3); no shell command was executed.',
          if (fileEntries.isEmpty)
            'No matching files were found in the bounded scan.'
          else
            ...fileEntries,
          ...routeMatches,
        ].join('\n');
      } else if (command.key == 'feature_search_logs') {
        final logEntries = entries
            .where(
              (entity) =>
                  entity.path.toLowerCase().contains('report') ||
                  entity.path.toLowerCase().contains('log'),
            )
            .map(_portableEntityLabel)
            .toList();
        output = [
          'Portable receipts & logs search',
          'Workspace: ${root.path}',
          'Read-only bounded scan (up to ${entries.length} entries, depth 3); no shell command was executed.',
          if (logEntries.isEmpty)
            'No report/log entries were found in the bounded scan.'
          else
            ...logEntries,
        ].join('\n');
      } else if (command.key.startsWith('feature_search_')) {
        final needle = query.isEmpty
            ? command.label.toLowerCase().replaceFirst(' search', '')
            : query;
        final aliases = switch (command.key) {
          'feature_search_terminal' => const ['terminal', 'console', 'shell'],
          'feature_search_preview' => const ['preview', 'artifact', 'review'],
          _ => const <String>[],
        };
        final pathMatches = entries
            .where((entity) {
              final path = entity.path.toLowerCase();
              return path.contains(needle) ||
                  aliases.any((alias) => path.contains(alias));
            })
            .take(48)
            .map(_portableEntityLabel)
            .toList();
        final routeMatches = rustCommands
            .where((candidate) {
              final haystack = '${candidate.key} ${candidate.label}'
                  .toLowerCase();
              return haystack.contains(needle);
            })
            .take(24)
            .map((candidate) => '- ${candidate.label} (${candidate.key})')
            .toList();
        output = [
          'Portable ${command.label}',
          'Workspace: ${root.path}',
          'Read-only bounded path and route scan; no shell command was executed.',
          if (pathMatches.isEmpty && routeMatches.isEmpty)
            'No matching paths or route names were found.'
          else
            ...pathMatches,
          ...routeMatches,
        ].join('\n');
      } else if (command.key == 'workspace_inventory_short' ||
          command.key == 'workspace_inventory_report') {
        final directories = entries.whereType<Directory>().length;
        final files = entries.whereType<File>().length;
        final lines = <String>[
          'Portable workspace inventory',
          'Root: ${root.path}',
          'Top-level directories: $directories',
          'Top-level files: $files',
          'Entries are bounded to ${entries.length}; no recursive scan or mutation was performed.',
          ...entries.map(_portableEntityLabel),
        ];
        output = lines.join('\n');
        if (command.key == 'workspace_inventory_report') {
          try {
            final reportDir = Directory('${root.path}\\reports\\codex_bridge');
            await reportDir.create(recursive: true);
            final report = File(
              '${reportDir.path}\\ENGEL_PORTABLE_WORKSPACE_INVENTORY.json',
            );
            await report.writeAsString(
              JsonEncoder.withIndent('  ').convert({
                'schema': 'engel_portable_workspace_inventory_v1',
                'read_only': true,
                'root': root.path,
                'bounded_entry_count': entries.length,
                'entries': entries.map((entity) => entity.path).toList(),
              }),
            );
            output = '$output\nReceipt: ${report.path}';
          } catch (error) {
            output =
                '$output\nReceipt could not be written (read-only media): $error';
          }
        }
      } else {
        final detail = switch (command.key) {
          'runtime_wsl_status' =>
            'WSL status is not bundled. Install/configure WSL on this desktop, then use the Runtime Workspace page.',
          'runtime_sandbox_status' =>
            'Sandbox status is not bundled. Use the host Engel runtime when it is available.',
          'patch_plan_preview' =>
            'No patch was applied. Portable mode exposes a read-only preview only.',
          _ =>
            'This portable action is read-only and has no local runtime yet.',
        };
        output = '$detail\nRoot: ${root.path}';
      }
      if (mounted) {
        setState(() {
          _output = output;
          _status = 'done';
        });
      }
    } catch (error) {
      if (mounted) {
        setState(() {
          _status = 'portable read error';
          _output = 'Portable Terminal & Files read failed: $error';
        });
      }
    } finally {
      if (mounted) setState(() => _running = false);
    }
    return true;
  }

  @override
  Future<File?> _findStandaloneChatPython() async {
    final candidates = [
      File(Platform.environment['ENGEL_PYTHON_EXE'] ?? ''),
      File(runtimePythonExe),
      File(Platform.environment['PYTHON'] ?? ''),
      File('python.exe'),
      File('python'),
    ];
    for (final file in candidates) {
      if (file.path.isEmpty) continue;
      if (file.path == 'python.exe' || file.path == 'python') return file;
      if (await file.exists()) return file;
    }
    return null;
  }

  @override
  String _pretty(String text) {
    final trimmed = text.trim();
    if (trimmed.isEmpty) return '';
    try {
      return const JsonEncoder.withIndent('  ').convert(jsonDecode(trimmed));
    } catch (_) {
      return trimmed;
    }
  }

  @override
  Widget build(BuildContext context) {
    final sections = _sections;
    final selected = sections[_selectedIndex.clamp(0, sections.length - 1)];
    final media = MediaQuery.of(context);
    final effectiveTextScaler = _EngelTextScaler(
      base: media.textScaler,
      multiplier: _interfaceTextScale,
      minScaleFactor: _interfaceTextScale,
      maxScaleFactor: 3,
    );
    return MediaQuery(
      data: media.copyWith(textScaler: effectiveTextScaler),
      child: Scaffold(
        body: Stack(
          fit: StackFit.expand,
          children: [
            Image.file(
              File(engelDesktopBackgroundPath),
              fit: BoxFit.cover,
              alignment: Alignment.center,
              errorBuilder: (context, error, stackTrace) => const DecoratedBox(
                decoration: BoxDecoration(
                  gradient: EngelLiquidGlass.quietBackdrop,
                ),
              ),
            ),
            DecoratedBox(
              decoration: BoxDecoration(
                color: EngelLiquidGlass.backdrop.withValues(
                  alpha: _backgroundWashOpacity.clamp(0.12, 0.52),
                ),
              ),
            ),
            Padding(
              padding: const EdgeInsets.all(14),
              child: ClipRRect(
                borderRadius: BorderRadius.circular(EngelLiquidGlass.radius),
                child: DecoratedBox(
                  decoration: EngelLiquidGlass.shellDecoration(
                    opacity: _mainShellOpacity.clamp(0.28, 0.58),
                  ),
                  child: LayoutBuilder(
                    builder: (context, constraints) {
                      final textScale = _effectiveInterfaceTextScale;
                      final compactNavigation =
                          constraints.maxWidth < 920 || textScale > 1.45;
                      final compactNavigationWidth = math.min(
                        420.0,
                        constraints.maxWidth * 0.9,
                      );
                      return Stack(
                        children: [
                          Row(
                            children: [
                              if (!compactNavigation)
                                _SideConsole(
                                  key: const Key('persistent-navigation-panel'),
                                  sections: sections,
                                  selectedIndex: _selectedIndex,
                                  sideConsoleOpacity: _sideConsoleOpacity,
                                  onSelected: _selectSectionById,
                                ),
                              Expanded(
                                child: Column(
                                  children: [
                                    _topBar(
                                      selected,
                                      showNavigationButton: compactNavigation,
                                    ),
                                    if (_mainServerOnline != true &&
                                        (selected.id == 'chat_runtime' ||
                                            selected.id == 'status_console' ||
                                            selected.id == 'main' ||
                                            selected.id ==
                                                advancedVaultSectionId))
                                      _chatConnectionRecovery(),
                                    Expanded(child: _sectionBody(selected.id)),
                                  ],
                                ),
                              ),
                            ],
                          ),
                          if (compactNavigation && _compactNavigationOpen) ...[
                            Positioned.fill(
                              child: ModalBarrier(
                                key: const Key(
                                  'compact-navigation-dismiss-area',
                                ),
                                color: const Color(0x99000000),
                                dismissible: true,
                                onDismiss: _closeCompactNavigation,
                              ),
                            ),
                            Align(
                              alignment: Alignment.centerLeft,
                              child: SizedBox(
                                width: compactNavigationWidth,
                                child: _SideConsole(
                                  key: const Key('compact-navigation-panel'),
                                  width: compactNavigationWidth,
                                  sections: sections,
                                  selectedIndex: _selectedIndex,
                                  sideConsoleOpacity: 0.22,
                                  onSelected: _selectFromCompactNavigation,
                                  onRequestClose: _closeCompactNavigation,
