  int _sectionIndexById(String id) {
    final index = _sections.indexWhere((section) => section.id == id);
    return index < 0 ? 0 : index;
  }

  String get _visibleRouteId {
    final sections = _sections;
    final owner = sections[_selectedIndex.clamp(0, sections.length - 1)].id;
    return _sectionTabs[owner] ?? owner;
  }

  String _routeLabel(String routeId) {
    final childLabel = sectionChildLabels[routeId];
    if (childLabel != null) return childLabel;
    return _sections
            .where((section) => section.id == routeId)
            .map((section) => section.label)
            .firstOrNull ??
        routeId.replaceAll('_', ' ');
  }

  void _clearVisibleOutput() {
    final routeId = _visibleRouteId;
    setState(() {
      _outputByRoute.remove(routeId);
      _outputUpdatedAtByRoute.remove(routeId);
      if (_outputValueRouteId == routeId) {
        _outputValue = _idleOutputMessage;
        _outputValueRouteId = null;
      }
    });
  }

  String? _latestOtherResultsRoute(String routeId) {
    final candidates = _outputUpdatedAtByRoute.entries
        .where(
          (entry) =>
              entry.key != routeId &&
              _routesWithResultsPanel.contains(entry.key) &&
              _outputByRoute.containsKey(entry.key),
        )
        .toList(growable: false);
    if (candidates.isEmpty) return null;
    return candidates.reduce((left, right) {
      return left.value.isAfter(right.value) ? left : right;
    }).key;
  }

  /// Which tab each consolidated window is showing (page id).
  final _sectionTabs = <String, String>{};

  void _selectSectionById(String id) {
    // A merged page id still navigates: open its owning window with that tab
    // active, so every pre-consolidation entry point keeps working.
    final resolvedId = sectionRouteAliases[id] ?? id;
    if (referenceOnlySectionIds.contains(resolvedId)) {
      setState(() {
        _selectedIndex = _sectionIndexById(advancedVaultSectionId);
        _sectionTabs[advancedVaultSectionId] = resolvedId;
      });
      return;
    }
    final owner = sectionMergeOwner[resolvedId] ?? resolvedId;
    setState(() {
      _selectedIndex = _sectionIndexById(owner);
      if (id == 'model_runtime' || id == 'free_models' || id == 'cosmos') {
        _showAdvancedModelTools = true;
      }
      if (owner == advancedVaultSectionId) {
        _sectionTabs[advancedVaultSectionId] = advancedVaultSectionId;
      } else if (sectionMergeChildren.containsKey(owner)) {
        _sectionTabs[owner] = resolvedId;
      }
    });
    if (resolvedId == 'local_llm') {
      unawaited(_refreshServerModelInventory());
    }
    if (resolvedId == 'command_center' ||
        resolvedId == 'control' ||
        resolvedId == 'mesh') {
      // The bridge pill was scanned once at startup and never again: one
      // transient listSync error during a stack bounce latched "offline" for a
      // full day while every port was actually up. Re-scan on open.
      unawaited(_refreshEngelBridgeStatus(quiet: true));
    }
    if (resolvedId == 'tasks' || resolvedId == 'meeting') {
      unawaited(_refreshMeetingRoomServer());
    }
    if (resolvedId == 'intent_bridge') {
      unawaited(_refreshLiftedIntentReceipt());
    }
    if (resolvedId == 'goals') {
      unawaited(_refreshGoalPlan());
    }
  }

  void _openChatWithDraft(String draft) {
    _agentWorkReviewPending = false;
    _agentTaskState = '';
    _agentTaskGoal = '';
    _agentTaskStatus = '';
    _agentTaskProofPath = '';
    _agentTaskProofDetails = '';
    _chatDraft = draft;
    _chatText.value = TextEditingValue(
      text: draft,
      selection: TextSelection.collapsed(offset: draft.length),
    );
    _selectSectionById('chat_runtime');
  }

  void _openChatWithAgentGoal(String goal) {
    final cleanGoal = _cleanLocalChatPrompt(goal);
    _agentWorkReviewPending = true;
    _agentTaskState = 'review';
    _agentTaskGoal = cleanGoal;
    _agentTaskStatus = 'Ready for your review';
    _agentTaskProofPath = '';
    _agentTaskProofDetails = '';
    _chatDraft = cleanGoal;
    _chatText.value = TextEditingValue(
      text: cleanGoal,
      selection: TextSelection.collapsed(offset: cleanGoal.length),
    );
    _selectSectionById('chat_runtime');
  }

  String _agentGoalFromDraft(String draft) {
    final value = draft.trim();
    final match = RegExp(
      r'^engel\s+(?:work|solve)\s+',
      caseSensitive: false,
    ).firstMatch(value);
    return match == null ? value : value.substring(match.end).trim();
  }

  Future<void> _showAgentWorkDialog() async {
    if (_running) {
      _announcePromptBusy();
      return;
    }
    final homeDraft = _cleanLocalChatPrompt(_homePromptText.text);
    final existingChatDraft = _cleanLocalChatPrompt(_chatDraft);
    final initialGoal = _agentGoalFromDraft(
      homeDraft.isNotEmpty ? homeDraft : existingChatDraft,
    );
    var goalDraft = initialGoal;
    final goal = await showDialog<String>(
      context: context,
      builder: (dialogContext) {
        return StatefulBuilder(
          builder: (context, setDialogState) {
            void reviewGoal() {
              final value = _cleanLocalChatPrompt(goalDraft);
              if (value.isNotEmpty) Navigator.of(dialogContext).pop(value);
            }

            return AlertDialog(
              title: const Text('Give Engel a goal'),
              content: SizedBox(
                width: 520,
                child: SingleChildScrollView(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text(
                        'Describe the result you want in plain language. Engel will choose the fastest safe tools and keep proof of each step.',
                      ),
                      const SizedBox(height: 14),
                      TextFormField(
                        key: const Key('agent-work-goal-input'),
                        initialValue: initialGoal,
                        autofocus: true,
                        minLines: 2,
                        maxLines: 5,
                        textInputAction: TextInputAction.done,
                        onChanged: (value) =>
                            setDialogState(() => goalDraft = value),
                        onFieldSubmitted: (_) => reviewGoal(),
                        decoration: const InputDecoration(
                          labelText: 'Goal',
                          hintText:
                              'For example: check models and storage, then summarize anything that needs attention',
                        ),
                      ),
                      const SizedBox(height: 10),
                      const Text(
                        'Nothing runs yet. You will review the request in Chat before sending it.',
                        style: TextStyle(
                          color: Color(0xffaebbd0),
                          fontSize: 12,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.of(dialogContext).pop(),
                  child: const Text('Cancel'),
                ),
                FilledButton.icon(
                  key: const Key('agent-work-review'),
                  onPressed: goalDraft.trim().isEmpty ? null : reviewGoal,
                  icon: const Icon(Icons.rate_review_outlined, size: 18),
                  label: const Text('Review in Chat'),
                ),
              ],
            );
          },
        );
      },
    );
    if (!mounted || goal == null) return;
    _homePromptText.clear();
    _openChatWithAgentGoal(goal);
    setState(() => _status = 'Agent goal ready to review');
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _chatInputFocus.requestFocus();
    });
  }

  Future<void> _runMiplAgentCommand(
    List<String> commandArgs, {
    required String runningLabel,
    required String successLabel,
  }) async {
    if (_running) {
      _announcePromptBusy();
      return;
    }
    final python = File(runtimePythonExe);
    final script = File(miplAgentWorkScriptPath);
    if (!python.existsSync() || !script.existsSync()) {
      setState(() {
        _status = 'MIPL agent tools unavailable';
        _output = [
          if (!python.existsSync()) 'Python missing: $runtimePythonExe',
          if (!script.existsSync())
            'MIPL agent work module missing: $miplAgentWorkScriptPath',
        ].join('\n');
      });
      return;
    }
    final args = [miplAgentWorkScriptPath, ...commandArgs];
    setState(() {
      _running = true;
      _status = runningLabel;
      _lastCommand = '$runtimePythonExe ${args.join(' ')}';
      _output = 'Preparing a bounded MIPL work packet...';
    });
    try {
      final sw = Stopwatch()..start();
      final result = await _processRunner(
        runtimePythonExe,
        args,
        workingDirectory: appRoot,
        environment: {
          'ENGEL_APP_ROOT': appRoot,
          'TEMP': engelTempRoot,
          'TMP': engelTempRoot,
          'TMPDIR': engelTempRoot,
        },
      ).timeout(const Duration(seconds: 60));
      sw.stop();
      if (!mounted) return;
      final stdoutText = _pretty(result.stdout.toString());
      final stderrText = result.stderr.toString().trim();
      setState(() {
        _output = [
          if (stdoutText.isNotEmpty) stdoutText,
          if (stderrText.isNotEmpty) 'Details:\n$stderrText',
          'Exit: ${result.exitCode} · ${sw.elapsedMilliseconds} ms',
        ].join('\n\n');
        _status = result.exitCode == 0
            ? successLabel
            : 'MIPL agent command needs attention';
      });
    } on TimeoutException {
      if (!mounted) return;
      setState(() {
        _status = 'MIPL agent command timed out';
        _output = 'The local command did not return within 60 seconds.';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _status = 'MIPL agent command failed';
        _output = 'Engel could not prepare the agent work packet.\n$error';
      });
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  Future<void> _showMiplAgentCreateDialog() async {
    if (_running) {
      _announcePromptBusy();
      return;
    }
    const skillChoices = <String, String>{
      'repository_research': 'Research',
      'reporting': 'Reporting',
      'summarization': 'Summarize',
      'implementation_planning': 'Plan code',
      'coordination': 'Coordinate',
      'conversation': 'Conversation',
      'verification': 'Verification',
      'capability_evaluation': 'Capability eval',
      'curriculum_design': 'Curriculum',
    };
    var nameDraft = '';
    var taskDraft = _agentGoalFromDraft(_cleanLocalChatPrompt(_chatDraft));
    final selectedSkills = <String>{'repository_research', 'reporting'};
    var validationMessage = '';
    final request = await showDialog<Map<String, Object>>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) {
          void createDraft() {
            final name = nameDraft.trim();
            final task = _cleanLocalChatPrompt(taskDraft);
            if (name.isEmpty || task.length < 12 || selectedSkills.isEmpty) {
              setDialogState(() {
                validationMessage =
                    'Add an agent name, a clear task, and at least one skill.';
              });
              return;
            }
            Navigator.of(dialogContext).pop({
              'name': name,
              'task': task,
              'skills': selectedSkills.toList(growable: false),
            });
          }

          return AlertDialog(
            title: const Text('Create a task agent'),
            content: SizedBox(
              width: 620,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text(
                      'Name the agent, describe one result, and choose its skills. Engel creates a draft work packet first; nothing runs.',
                    ),
                    const SizedBox(height: 14),
                    TextFormField(
                      key: const Key('mipl-agent-name-input'),
                      autofocus: true,
                      onChanged: (value) => nameDraft = value,
                      decoration: const InputDecoration(
                        labelText: 'Agent name',
                        hintText: 'Training Receipt Reviewer',
                      ),
                    ),
                    const SizedBox(height: 12),
                    TextFormField(
                      key: const Key('mipl-agent-task-input'),
                      initialValue: taskDraft,
                      minLines: 3,
                      maxLines: 6,
                      onChanged: (value) => taskDraft = value,
                      decoration: const InputDecoration(
                        labelText: 'Assigned task',
                        hintText:
                            'Review the latest training receipts and report anything that needs attention.',
                      ),
                    ),
                    const SizedBox(height: 14),
                    const Text(
                      'Skills',
                      style: TextStyle(fontWeight: FontWeight.w800),
                    ),
                    const SizedBox(height: 7),
                    Wrap(
                      spacing: 7,
                      runSpacing: 7,
                      children: [
                        for (final entry in skillChoices.entries)
                          FilterChip(
                            key: Key('mipl-agent-skill-${entry.key}'),
                            label: Text(entry.value),
                            selected: selectedSkills.contains(entry.key),
                            onSelected: (selected) => setDialogState(() {
                              if (selected) {
                                selectedSkills.add(entry.key);
                              } else {
                                selectedSkills.remove(entry.key);
                              }
                              validationMessage = '';
                            }),
                          ),
                      ],
                    ),
                    const SizedBox(height: 10),
                    const Text(
                      'Verification, capability evaluation, and curriculum changes keep their action tools locked until a named operator grants them.',
                      style: TextStyle(
                        color: Color(0xffaebbd0),
                        fontSize: 12,
                        height: 1.35,
                      ),
                    ),
                    if (validationMessage.isNotEmpty) ...[
                      const SizedBox(height: 10),
                      Text(
                        validationMessage,
                        key: const Key('mipl-agent-create-error'),
                        style: const TextStyle(color: Color(0xffffc857)),
                      ),
                    ],
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(dialogContext).pop(),
                child: const Text('Cancel'),
              ),
              FilledButton.icon(
                key: const Key('mipl-agent-create-draft'),
                onPressed: createDraft,
                icon: const Icon(Icons.person_add_alt_1, size: 18),
                label: const Text('Create draft'),
              ),
            ],
          );
        },
      ),
    );
    if (!mounted || request == null) return;
    final skills = List<String>.from(request['skills']! as List);
    await _runMiplAgentCommand(
      [
        'create',
        '--name',
        request['name']! as String,
        '--task',
        request['task']! as String,
        for (final skill in skills) ...['--skill', skill],
        '--authored-by',
        'Engel UI operator',
        '--summary',
      ],
      runningLabel: 'creating MIPL agent draft',
      successLabel: 'MIPL agent draft created',
    );
  }

  Widget _compactActionGrid(List<Widget> actions) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final textScale = _effectiveInterfaceTextScale;
        final columns = constraints.maxWidth < 520 || textScale > 1.45 ? 1 : 2;
        final cardHeight = textScale > 1.7
            ? 132.0
            : textScale > 1.3
            ? 108.0
            : 86.0;
        return GridView.builder(
          shrinkWrap: true,
          physics: const NeverScrollableScrollPhysics(),
          itemCount: actions.length,
          gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
            crossAxisCount: columns,
            mainAxisSpacing: 10,
            crossAxisSpacing: 10,
            mainAxisExtent: cardHeight,
          ),
          itemBuilder: (context, index) => actions[index],
        );
      },
    );
  }

  Widget _adaptiveWorkbench({
    required Widget primary,
    required Widget secondary,
    required double compactPrimaryHeight,
    double compactSecondaryHeight = 380,
    bool showSecondary = true,
  }) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final textScale = _effectiveInterfaceTextScale;
        final compact = constraints.maxWidth < 980 || textScale > 1.35;
        final heightFactor = textScale > 1.7
            ? 1.25
            : textScale > 1.35
            ? 1.1
            : 1.0;
        if (!showSecondary) {
          if (!compact) return primary;
          return SingleChildScrollView(
            key: const Key('adaptive-workbench-scroll'),
            child: SizedBox(
              height: compactPrimaryHeight * heightFactor,
              child: primary,
            ),
          );
        }
        if (!compact) {
          return Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Expanded(flex: 5, child: primary),
              const SizedBox(width: 12),
              Expanded(flex: 4, child: secondary),
            ],
          );
        }
        return SingleChildScrollView(
          key: const Key('adaptive-workbench-scroll'),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              SizedBox(
                height: compactPrimaryHeight * heightFactor,
                child: primary,
              ),
              const SizedBox(height: 12),
              SizedBox(height: compactSecondaryHeight, child: secondary),
            ],
          ),
        );
      },
    );
  }

  Widget _advancedCommandSearch() {
    return Autocomplete<RustCommand>(
      displayStringForOption: (command) => command.label,
      optionsBuilder: (value) {
        final query = value.text.trim().toLowerCase();
        if (query.length < 2) return const Iterable<RustCommand>.empty();
        return rustCommands
            .where((command) {
              final haystack = [
                command.label,
                command.key,
                ...command.args,
              ].join(' ').toLowerCase();
              return haystack.contains(query);
            })
            .take(12);
      },
      onSelected: (command) => unawaited(_runRust(command)),
      fieldViewBuilder: (context, controller, focusNode, onFieldSubmitted) =>
          TextField(
            key: const Key('advanced-command-search'),
            controller: controller,
            focusNode: focusNode,
            enabled: !_running,
            onSubmitted: (_) => onFieldSubmitted(),
            decoration: const InputDecoration(
              prefixIcon: Icon(Icons.search),
              hintText: 'Find an advanced diagnostic',
              border: OutlineInputBorder(),
            ),
          ),
      optionsViewBuilder: (context, onSelected, options) => Align(
        alignment: Alignment.topLeft,
        child: Material(
          elevation: 10,
          color: const Color(0xff121923),
          borderRadius: BorderRadius.circular(6),
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 520, maxHeight: 300),
            child: ListView.builder(
              padding: const EdgeInsets.symmetric(vertical: 6),
              shrinkWrap: true,
              itemCount: options.length,
              itemBuilder: (context, index) {
                final command = options.elementAt(index);
                return ListTile(
                  dense: true,
                  leading: const Icon(Icons.terminal, size: 18),
                  title: Text(command.label),
                  onTap: () => onSelected(command),
                );
              },
            ),
          ),
        ),
      ),
    );
  }

  RustCommand _commandByKey(String key) {
