  Future<void> _runChatGptBrowserBridgeProbe() async {
    if (_running) return;
    setState(() {
      _running = true;
      _status = 'checking ChatGPT browser bridge';
      _lastCommand =
          '$browserVenvPython $chatGptBrowserWorkerScriptPath send --timeout 45 --max-tokens 80 <probe>';
      _output =
          'Running a real ChatGPT browser bridge probe. Secret values are not read or printed.';
    });
    try {
      final result = await _processRunner(
        browserVenvPython,
        [
          chatGptBrowserWorkerScriptPath,
          'send',
          '--timeout',
          '45',
          '--max-tokens',
          '80',
          'Engel ChatGPT bridge account check: reply in one short sentence.',
        ],
        workingDirectory: appRoot,
        environment: {'ENGEL_APP_ROOT': appRoot},
      ).timeout(const Duration(seconds: 60));
      final stdout = result.stdout.toString().trim();
      final stderr = result.stderr.toString().trim();
      Map<String, dynamic>? decoded;
      try {
        final parsed = jsonDecode(stdout);
        if (parsed is Map<String, dynamic>) decoded = parsed;
      } catch (_) {}
      final ok = decoded?['ok'] == true;
      final status = (decoded?['status'] ?? 'probe finished').toString();
      final reply = (decoded?['assistant_reply'] ?? '').toString().trim();
      setState(() {
        _status = ok
            ? 'ChatGPT bridge connected'
            : 'ChatGPT bridge needs attention';
        _output = [
          'ChatGPT browser bridge probe: ${ok ? 'CONNECTED' : 'NEEDS ATTENTION'}',
          'Exit code: ${result.exitCode}',
          'Status: $status',
          if (reply.isNotEmpty) 'Reply: $reply',
          if (decoded == null && stdout.isNotEmpty)
            stdout.length > 2000 ? stdout.substring(0, 2000) : stdout,
          if (stderr.isNotEmpty)
            'stderr: ${stderr.length > 2000 ? stderr.substring(0, 2000) : stderr}',
        ].join('\n');
      });
      _showConnectorSnack(
        ok
            ? 'ChatGPT browser bridge verified.'
            : 'ChatGPT browser bridge probe failed.',
        ok: ok,
      );
    } on TimeoutException {
      setState(() {
        _status = 'ChatGPT bridge timeout';
        _output =
            'ChatGPT browser bridge probe timed out. The account card will show Needs attention after state refresh.';
      });
      _showConnectorSnack('ChatGPT browser bridge timed out.', ok: false);
    } catch (error) {
      setState(() {
        _status = 'ChatGPT bridge error';
        _output = 'ChatGPT browser bridge probe failed: $error';
      });
      _showConnectorSnack('ChatGPT browser bridge probe failed.', ok: false);
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

