  // --- Goals window: progress meters + month planner ------------------------
  // Reads ONLY memory\engel_goals\ENGEL_GOAL_PLAN.json (written by
  // tools\engel_goal_planner.py). Progress percentages arrive WITH their basis and
  // completion comes only from a goal's own terminal status — the meter renders what
  // the planner could honestly derive, never a guess of its own.
  Map<String, dynamic>? _goalPlan;
  var _goalPlanError = '';
  var _goalPlanNotice = '';
  var _goalPlanRefreshing = false;
  DateTime _goalsMonth = DateTime(DateTime.now().year, DateTime.now().month);
  int? _goalsFocusDay;
  final _goalAddTitle = TextEditingController();
  final _goalAddStart = TextEditingController();
  final _goalAddDue = TextEditingController();
  var _goalAddWeekly = false;
  var _goalAddBusy = false;
  var _goalAddNote = '';
  String? _goalFocusSlug;
  final _goalTalk = TextEditingController();
  var _goalTalkBusy = false;
  var _goalTalkNote = '';

  Future<void> _placeGoalOnPlanner() async {
    final title = _goalAddTitle.text.trim();
    if (title.isEmpty) {
      setState(() => _goalAddNote = 'Give the goal or task a name first.');
      return;
    }
    setState(() {
      _goalAddBusy = true;
      _goalAddNote = '';
    });
    try {
      final args = [
        engelGoalPlannerScriptPath,
        '--add',
        title,
        if (_goalAddStart.text.trim().isNotEmpty) ...[
          '--start',
          _goalAddStart.text.trim(),
        ],
        if (_goalAddDue.text.trim().isNotEmpty) ...[
          '--due',
          _goalAddDue.text.trim(),
        ],
        if (_goalAddWeekly) '--weekly',
      ];
      final result = await Process.run(runtimePythonExe, args);
      if (!mounted) return;
      if (result.exitCode == 0) {
        _goalAddTitle.clear();
        _goalAddStart.clear();
        _goalAddDue.clear();
        setState(() {
          _goalAddWeekly = false;
          _goalAddNote = 'Placed on the plan.';
        });
        await _refreshGoalPlan();
      } else {
        final err = '${result.stderr}'.trim();
        setState(
          () => _goalAddNote =
              'The planner refused it: ${err.isEmpty ? result.stdout : err}',
        );
      }
    } catch (error) {
      if (mounted) {
        setState(() => _goalAddNote = 'Could not run the planner: $error');
      }
    } finally {
      if (mounted) {
        setState(() => _goalAddBusy = false);
      }
    }
  }

  static const _goalMonthNames = [
    'January',
    'February',
    'March',
    'April',
    'May',
    'June',
    'July',
    'August',
    'September',
    'October',
