  ];

  Future<void> _refreshGoalPlan({bool recompute = false}) async {
    if (_goalPlanRefreshing) return;
    setState(() {
      _goalPlanRefreshing = true;
      _goalPlanError = '';
      if (recompute) _goalPlanNotice = '';
    });
    try {
      var notice = '';
      if (recompute && widget.goalPlanPath == engelGoalPlanPath) {
        final result = await Process.run(runtimePythonExe, [
          engelGoalPlannerScriptPath,
          '--plan',
        ]);
        if (result.exitCode != 0) {
          final err = '${result.stderr}'.trim();
          notice =
              'Recompute failed: ${err.isEmpty ? 'planner exit ${result.exitCode}' : err}';
        }
      }
      final file = File(widget.goalPlanPath);
      Map<String, dynamic>? plan;
      if (await file.exists()) {
        final decoded = jsonDecode(await file.readAsString());
        if (decoded is Map && decoded['schema'] == 'engel_goal_plan_v1') {
          plan = Map<String, dynamic>.from(decoded);
        } else {
          throw const FormatException('goal plan carries an unknown schema');
        }
      }
      if (!mounted) return;
      setState(() {
        _goalPlan = plan;
        _goalPlanNotice = notice;
      });
    } catch (error) {
      if (!mounted) return;
      setState(() => _goalPlanError = 'Could not read the goal plan: $error');
    } finally {
      if (mounted) setState(() => _goalPlanRefreshing = false);
    }
  }

  List<Map<String, dynamic>> get _goalPlanEntries {
    final goals = _goalPlan?['goals'];
    if (goals is! Map) return const [];
    const stateOrder = {
      'in_progress': 0,
      'not_started': 1,
      'Rejected': 2,
      'Invalid plan': 2,
      'No planner': 2,
      'Stopped': 2,
      'stalled': 2,
      'done': 3,
    };
    final entries = goals.values
        .whereType<Map>()
        .map((entry) => Map<String, dynamic>.from(entry))
        .toList();
    entries.sort((a, b) {
      final byState = (stateOrder[a['progress_state']] ?? 4).compareTo(
        stateOrder[b['progress_state']] ?? 4,
      );
      if (byState != 0) return byState;
      return '${a['goal']}'.compareTo('${b['goal']}');
    });
    return entries;
  }

