  static const Map<int, int> _goalCp1252FromRune = {
    0x20AC: 0x80,
    0x201A: 0x82,
    0x0192: 0x83,
    0x201E: 0x84,
    0x2026: 0x85,
    0x2020: 0x86,
    0x2021: 0x87,
    0x02C6: 0x88,
    0x2030: 0x89,
    0x0160: 0x8A,
    0x2039: 0x8B,
    0x0152: 0x8C,
    0x017D: 0x8E,
    0x2018: 0x91,
    0x2019: 0x92,
    0x201C: 0x93,
    0x201D: 0x94,
    0x2022: 0x95,
    0x2013: 0x96,
    0x2014: 0x97,
    0x02DC: 0x98,
    0x2122: 0x99,
    0x0161: 0x9A,
    0x203A: 0x9B,
    0x0153: 0x9C,
    0x017E: 0x9E,
    0x0178: 0x9F,
  };

  /// Undo a title that was UTF-8 decoded as Windows-1252. The NVIDIA goal stored
  /// the multiplication sign that way, twice. Titles without those markers stay put.
  String _repairGoalText(String text) {
    var current = text;
    for (var pass = 0; pass < 3; pass++) {
      final suspicious =
          current.contains('\u00C3') ||
          current.contains('\u00C2') ||
          current.contains('\u00E2\u20AC');
      if (!suspicious) break;
      final bytes = <int>[];
      var encodable = true;
      for (final rune in current.runes) {
        if (rune <= 0x7F || (rune >= 0xA0 && rune <= 0xFF)) {
          bytes.add(rune);
          continue;
        }
        final mapped = _goalCp1252FromRune[rune];
        if (mapped == null) {
          encodable = false;
          break;
        }
        bytes.add(mapped);
      }
      if (!encodable) break;
      try {
        final next = utf8.decode(bytes);
        if (next.isEmpty || next == current) break;
        current = next;
      } on FormatException {
        break;
      }
    }
    return current.replaceAll(RegExp(r'\s+'), ' ').trim();
  }

  String _goalCalendarLabel(String goal) {
    final text = _repairGoalText(goal);
    if (text.length <= 36) return text;
    return '${text.substring(0, 33).trimRight()}...';
  }

  bool _goalIsTrainingCard(Map<String, dynamic> entry) {
    return _repairGoalText(
      '${entry['goal'] ?? ''}',
    ).startsWith('Training depth:');
  }

  String _goalClusterKey(String title) {
    return _repairGoalText(title)
        .toLowerCase()
        .split(RegExp(r'[^a-z0-9]+'))
        .where((word) => word.isNotEmpty)
        .take(4)
        .join(' ');
  }

