  };

  int? get _goalDetailDay {
    final today = DateTime.now();
    final inMonth =
        today.year == _goalsMonth.year && today.month == _goalsMonth.month;
    final last = DateTime(_goalsMonth.year, _goalsMonth.month + 1, 0).day;
    final focused = _goalsFocusDay;
    if (focused != null && focused >= 1 && focused <= last) return focused;
    if (inMonth) return today.day;
    return null;
  }

  String _goalWeeklyWeekdayNote() {
    const names = [
      'Monday',
      'Tuesday',
      'Wednesday',
      'Thursday',
      'Friday',
      'Saturday',
      'Sunday',
    ];
    final weekdays = <int>{};
    for (final entry in _goalPlanEntries) {
      if (entry['repeat_weekly'] != true) continue;
      final start = DateTime.tryParse('${entry['operator_start_date'] ?? ''}');
      if (start != null) weekdays.add(start.weekday);
    }
    if (weekdays.isEmpty) return '';
    final labels = weekdays.map((day) => names[day - 1]).join(' and ');
    return ' Weekly tasks in this plan repeat on $labels.';
  }

  /// date (YYYY-MM-DD) -> events for the visible month, derived client-side from
  /// the plan. Every event sits on a real recorded date; nothing is invented.
  /// A projected finish that is already past is also pinned on today as overdue,
  /// so a late goal does not disappear off the current day.
  Map<int, List<Map<String, String>>> _goalMonthEvents() {
    final events = <int, List<Map<String, String>>>{};
    void add(String date, String goal, String kind) {
      if (date.length < 10) return;
      final year = int.tryParse(date.substring(0, 4));
      final month = int.tryParse(date.substring(5, 7));
      final day = int.tryParse(date.substring(8, 10));
      if (year != _goalsMonth.year ||
          month != _goalsMonth.month ||
          day == null) {
        return;
      }
      (events[day] ??= []).add({
        'goal': _goalCalendarLabel(goal),
        'full': _repairGoalText(goal),
        'kind': kind,
      });
    }

    final today = DateTime.now();
    final viewingThisMonth =
        today.year == _goalsMonth.year && today.month == _goalsMonth.month;
    final todayDate = DateTime(today.year, today.month, today.day);

    for (final entry in _goalPlanEntries) {
      final goal = '${entry['goal'] ?? entry['slug'] ?? ''}';
      final start = '${entry['operator_start_date'] ?? ''}';
      if (entry['repeat_weekly'] == true && start.length >= 10) {
        final anchor = DateTime.tryParse(start);
        if (anchor != null) {
          final days = DateTime(_goalsMonth.year, _goalsMonth.month + 1, 0).day;
          for (var day = 1; day <= days; day++) {
            final candidate = DateTime(
              _goalsMonth.year,
              _goalsMonth.month,
              day,
            );
            if (candidate.weekday == anchor.weekday &&
                !candidate.isBefore(anchor)) {
              (events[day] ??= []).add({
                'goal': _goalCalendarLabel(goal),
                'full': _repairGoalText(goal),
                'kind': 'weekly',
              });
            }
          }
        }
      } else {
        add(start, goal, 'start');
      }
      add('${entry['operator_due_date'] ?? ''}', goal, 'due');
      final projected = '${entry['projected_finish_date'] ?? ''}';
      if ('${entry['progress_state']}' == 'done') {
        add(projected, goal, 'done');
      } else if (entry['projected_finish_projectable'] == true) {
        add(projected, goal, 'projected');
        if (viewingThisMonth &&
            '${entry['progress_state']}' == 'in_progress' &&
            projected.length >= 10) {
          final projectedDay = DateTime.tryParse(projected.substring(0, 10));
          if (projectedDay != null && projectedDay.isBefore(todayDate)) {
            (events[today.day] ??= []).add({
              'goal': _goalCalendarLabel(goal),
              'full': _repairGoalText(goal),
              'kind': 'overdue',
            });
          }
        }
      }
    }
    return events;
  }

  Color _goalEventColor(String kind) => switch (kind) {
    'start' => const Color(0xff58a6ff),
    'due' => const Color(0xffffc857),
    'projected' => const Color(0xffb98aff),
    'done' => const Color(0xff35d07f),
    'weekly' => const Color(0xff58e6c8),
    'overdue' => const Color(0xffff9f43),
    _ => const Color(0xff8b98a5),
  };

