  Widget _goalMeterTile(Map<String, dynamic> entry, {bool duplicate = false}) {
    final slug = '${entry['slug'] ?? ''}';
    final state = '${entry['progress_state'] ?? ''}';
    final percent = (entry['progress_percent'] is num)
        ? (entry['progress_percent'] as num).clamp(0, 100).toInt()
        : 0;
    final color = _goalStateColor(state);
    final projected = '${entry['projected_finish_date'] ?? ''}';
    final projectedBasis = _repairGoalText(
      '${entry['projected_finish_basis'] ?? ''}',
    );
    final status = '${entry['status'] ?? ''}'.trim();
    final start = '${entry['operator_start_date'] ?? ''}';
    final due = '${entry['operator_due_date'] ?? ''}';
    final dates = <String>[
      if (start.isNotEmpty) 'starts $start',
      if (due.isNotEmpty) 'due $due',
      if (projected.isNotEmpty && state != 'done' && state != 'stalled')
        'Engel projects $projected',
      if (projected.isNotEmpty && state == 'done') 'finished $projected',
    ];
    final selected = slug.isNotEmpty && slug == _goalFocusSlug;
    return GestureDetector(
      key: Key('goal-meter-$slug'),
      onTap: () => setState(() {
        _goalFocusSlug = selected ? null : slug;
        _goalTalkNote = '';
      }),
      child: Padding(
      padding: const EdgeInsets.only(bottom: 14),
      child: DecoratedBox(
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(10),
          border: Border.all(
            color: selected
                ? const Color(0xff58a6ff)
                : const Color(0x00000000),
          ),
        ),
        child: Padding(
          padding: const EdgeInsets.all(6),
          child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              Expanded(
                child: Text(
                  _repairGoalText('${entry['goal'] ?? slug}'),
                  maxLines: 3,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: Color(0xfff7f7fb),
                    fontSize: 15,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                decoration: BoxDecoration(
                  color: color.withValues(alpha: 0.16),
                  borderRadius: BorderRadius.circular(999),
                ),
                child: Text(
                  '${_goalStateLabel(state)} · $percent%',
                  style: TextStyle(
                    color: color,
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 6),
          ClipRRect(
            borderRadius: BorderRadius.circular(999),
            child: LinearProgressIndicator(
              value: percent / 100,
              minHeight: 8,
              backgroundColor: const Color(0xff1d2430),
              valueColor: AlwaysStoppedAnimation<Color>(color),
            ),
          ),
          const SizedBox(height: 5),
          Text(
            _repairGoalText('${entry['progress_basis'] ?? ''}'),
            style: const TextStyle(color: Color(0xff8b98a5), fontSize: 12),
          ),
          if (status.isNotEmpty && state != 'done')
            Text(
              'Record: $status',
              style: const TextStyle(color: Color(0xffb8c6dd), fontSize: 12),
            ),
          if (duplicate)
            const Text(
              'Another goal record starts with the same words. Both are listed.',
              style: TextStyle(color: Color(0xffffc857), fontSize: 12),
            ),
          if (dates.isNotEmpty)
            Text(
              dates.join('  ·  '),
              style: const TextStyle(color: Color(0xffb8c6dd), fontSize: 12),
            ),
          if (projectedBasis.isNotEmpty && state != 'done' && state != 'stalled')
            Text(
              'Pace: $projectedBasis',
              style: const TextStyle(color: Color(0xff8b98a5), fontSize: 11),
            ),
            ],
          ),
        ),
      ),
      ),
    );
  }

  Future<void> _goalRunPlanner(List<String> args) async {
    final result = await Process.run(runtimePythonExe, [
      engelGoalPlannerScriptPath,
      ...args,
    ]);
    if (result.exitCode != 0) {
      final err = '${result.stderr}'.trim();
      throw Exception(err.isEmpty ? 'planner exit ${result.exitCode}' : err);
    }
  }

  Future<void> _workFocusedGoalInChat(Map<String, dynamic> entry) async {
    final slug = '${entry['slug'] ?? ''}';
    final title = _repairGoalText('${entry['goal'] ?? slug}');
    final say = _goalTalk.text.trim();
    setState(() {
      _goalTalkBusy = true;
      _goalTalkNote = '';
    });
    try {
      if (say.isNotEmpty) {
        await _goalRunPlanner(['--turn', slug, '--say', say]);
      }
      if (!mounted) return;
      _goalTalk.clear();
      _openChatWithAgentGoal(say.isEmpty ? title : '$title\n\n$say');
      await _refreshGoalPlan();
    } catch (error) {
      if (mounted) {
        setState(() => _goalTalkNote = 'Could not open this goal: $error');
      }
    } finally {
      if (mounted) setState(() => _goalTalkBusy = false);
    }
  }

  Future<void> _finishFocusedGoal(Map<String, dynamic> entry) async {
    final slug = '${entry['slug'] ?? ''}';
    final note = _goalTalk.text.trim();
    if (note.length < 3) {
      setState(
        () => _goalTalkNote = 'Write what finished it, then mark it finished.',
      );
      return;
    }
    setState(() {
      _goalTalkBusy = true;
      _goalTalkNote = '';
    });
    try {
      await _goalRunPlanner(['--finish', slug, '--note', note]);
      if (!mounted) return;
      _goalTalk.clear();
      setState(() => _goalTalkNote = 'Marked finished.');
      await _refreshGoalPlan();
    } catch (error) {
      if (mounted) {
        setState(() => _goalTalkNote = 'Could not finish this goal: $error');
      }
    } finally {
      if (mounted) setState(() => _goalTalkBusy = false);
    }
  }

