  Widget _goalMonthGrid() {
    final events = _goalMonthEvents();
    final first = DateTime(_goalsMonth.year, _goalsMonth.month, 1);
    final daysInMonth = DateTime(
      _goalsMonth.year,
      _goalsMonth.month + 1,
      0,
    ).day;
    final leadingBlanks = first.weekday % 7; // Sunday-first grid
    final today = DateTime.now();
    final cells = <Widget>[];
    for (final label in const ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa']) {
      cells.add(
        Center(
          child: Text(
            label,
            style: const TextStyle(
              color: Color(0xff8b98a5),
              fontSize: 11,
              fontWeight: FontWeight.w700,
            ),
          ),
        ),
      );
    }
    for (var i = 0; i < leadingBlanks; i++) {
      cells.add(const SizedBox.shrink());
    }
    for (var day = 1; day <= daysInMonth; day++) {
      final dayEvents = events[day] ?? const [];
      final isToday =
          today.year == _goalsMonth.year &&
          today.month == _goalsMonth.month &&
          today.day == day;
      final selected = day == _goalDetailDay;
      cells.add(
        GestureDetector(
          key: Key('goals-day-$day'),
          onTap: () => setState(() => _goalsFocusDay = day),
          child: Container(
          margin: const EdgeInsets.all(2),
          padding: const EdgeInsets.all(4),
          decoration: BoxDecoration(
            color: dayEvents.isEmpty
                ? const Color(0xff141a24)
                : const Color(0xff1a2333),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(
              color: isToday
                  ? const Color(0xff58a6ff)
                  : selected
                  ? const Color(0xff8b98a5)
                  : const Color(0xff222b3a),
              width: isToday || selected ? 1.4 : 1,
            ),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                '$day',
                style: TextStyle(
                  color: isToday
                      ? const Color(0xff58a6ff)
                      : const Color(0xffb8c6dd),
                  fontSize: 11,
                  fontWeight: FontWeight.w700,
                ),
              ),
              for (final event in dayEvents.take(3))
                Padding(
                  padding: const EdgeInsets.only(top: 2),
                  child: Row(
                    children: [
                      Container(
                        width: 6,
                        height: 6,
                        decoration: BoxDecoration(
                          color: _goalEventColor(event['kind'] ?? ''),
                          shape: BoxShape.circle,
                        ),
                      ),
                      const SizedBox(width: 3),
                      Expanded(
                        child: Text(
                          event['goal'] ?? '',
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            color: Color(0xffb8c6dd),
                            fontSize: 9.5,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              if (dayEvents.length > 3)
                Text(
                  '+${dayEvents.length - 3} more',
                  style: const TextStyle(color: Color(0xff8b98a5), fontSize: 9),
                ),
            ],
          ),
        ),
        ),
      );
    }
    return GridView.count(
      key: const Key('goals-month-grid'),
      crossAxisCount: 7,
      shrinkWrap: true,
      physics: const NeverScrollableScrollPhysics(),
      childAspectRatio: 1.15,
      children: cells,
    );
  }

  Widget _goalDayDetail() {
