    final events = _goalMonthEvents()[day] ?? const <Map<String, String>>[];
    final label =
        '${_goalMonthNames[_goalsMonth.month - 1]} $day, ${_goalsMonth.year}';
    final today = DateTime.now();
    final isToday =
        today.year == _goalsMonth.year &&
        today.month == _goalsMonth.month &&
        today.day == day;
    return Column(
      key: const Key('goals-day-detail'),
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Text(
          isToday ? 'Today, $label' : label,
          style: const TextStyle(
