                  ),
                  const SizedBox(width: 6),
                  Expanded(
                    child: Text(
                      '${_goalEventKindLabel(event['kind'] ?? '')}: ${event['full'] ?? event['goal'] ?? ''}',
                      style: const TextStyle(
                        color: Color(0xffb8c6dd),
                        fontSize: 12,
                        height: 1.3,
                      ),
                    ),
                  ),
                ],
              ),
            ),
      ],
    );
  }

  Widget _goalsPage() {
    final plan = _goalPlan;
    final entries = _goalPlanEntries;
    final trainingEntries = entries.where(_goalIsTrainingCard).toList();
    final operatorEntries = entries
        .where((entry) => !_goalIsTrainingCard(entry))
        .toList();
    bool refused(Map<String, dynamic> entry) {
      return const {
        'Rejected',
        'Invalid plan',
        'No planner',
        'Stopped',
        'stalled',
      }.contains('${entry['progress_state'] ?? ''}');
    }

    final openEntries = operatorEntries.where((entry) {
      final state = '${entry['progress_state'] ?? ''}';
      return state == 'in_progress' ||
          state == 'not_started' ||
          state == 'scheduled' ||
          state == 'with Josh';
    }).toList();
    final stoppedEntries = operatorEntries.where(refused).toList();
    final finishedEntries = operatorEntries
        .where((entry) => '${entry['progress_state']}' == 'done')
        .toList();
    final clusterCounts = <String, int>{};
    for (final entry in operatorEntries) {
      final key = _goalClusterKey('${entry['goal'] ?? ''}');
      if (key.isEmpty) continue;
      clusterCounts[key] = (clusterCounts[key] ?? 0) + 1;
    }
    Widget meterTile(Map<String, dynamic> entry) {
      final key = _goalClusterKey('${entry['goal'] ?? ''}');
      return _goalMeterTile(entry, duplicate: (clusterCounts[key] ?? 0) > 1);
    }

    Map<String, dynamic>? focusedGoal;
    for (final entry in entries) {
      if ('${entry['slug'] ?? ''}' == _goalFocusSlug) focusedGoal = entry;
    }

    final generated = '${plan?['generated_at_utc'] ?? ''}';
    final generatedAt = DateTime.tryParse(generated);
    final planAge = generatedAt == null
        ? null
        : DateTime.now().toUtc().difference(generatedAt.toUtc());
    final staleNote = planAge != null && planAge.inHours >= 36
        ? 'This reading is ${planAge.inDays} day${planAge.inDays == 1 ? '' : 's'} old. '
        : '';
    return _PageFrame(
      child: Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 820),
          child: SingleChildScrollView(
            child: Padding(
              padding: const EdgeInsets.fromLTRB(20, 34, 20, 20),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Row(
                    children: [
                      const Expanded(
                        child: Text(
                          'Goals',
                          style: TextStyle(
                            color: Color(0xfff7f7fb),
                            fontSize: 34,
                            fontWeight: FontWeight.w800,
                            letterSpacing: 0,
                          ),
                        ),
                      ),
                      IconButton(
                        key: const Key('goals-refresh'),
                        tooltip: 'Recompute the goal plan',
                        onPressed: _goalPlanRefreshing
                            ? null
                            : () => _refreshGoalPlan(recompute: true),
                        icon: const Icon(
                          Icons.refresh_rounded,
                          color: Color(0xffb8c6dd),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 18),
                  _macToolPanel(
                    title: 'Place a goal or weekly task',
                    icon: Icons.add_task_rounded,
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        TextField(
                          key: const Key('goal-add-title'),
                          controller: _goalAddTitle,
                          decoration: const InputDecoration(
                            labelText: 'What should happen?',
                            hintText: 'e.g. weekly backup audit',
                          ),
                        ),
                        const SizedBox(height: 8),
                        Row(
                          children: [
                            Expanded(
                              child: TextField(
                                key: const Key('goal-add-start'),
                                controller: _goalAddStart,
                                decoration: const InputDecoration(
                                  labelText: 'Start (YYYY-MM-DD)',
                                ),
                              ),
                            ),
                            const SizedBox(width: 8),
                            Expanded(
                              child: TextField(
                                key: const Key('goal-add-due'),
                                controller: _goalAddDue,
                                decoration: const InputDecoration(
                                  labelText: 'Due (YYYY-MM-DD)',
                                ),
                              ),
                            ),
                          ],
                        ),
                        const SizedBox(height: 6),
                        Row(
                          children: [
                            Checkbox(
                              key: const Key('goal-add-weekly'),
                              value: _goalAddWeekly,
                              onChanged: (value) => setState(
                                () => _goalAddWeekly = value ?? false,
                              ),
