                        else if (plan == null)
                          const Text(
                            'No goal plan yet. Give Engel a goal (Agents window) or run '
                            'tools\\engel_goal_planner.py --plan, and progress meters appear '
                            'here with the basis behind every reading.',
                            style: TextStyle(
                              color: Color(0xffb8c6dd),
                              fontSize: 13,
                              height: 1.4,
                            ),
                          )
                        else if (entries.isEmpty)
                          const Text(
                            'The plan is current but holds no goals yet.',
                            style: TextStyle(
                              color: Color(0xffb8c6dd),
                              fontSize: 13,
                            ),
                          )
                        else ...[
                          if (_goalPlanNotice.isNotEmpty)
                            Padding(
                              padding: const EdgeInsets.only(bottom: 8),
                              child: Text(
                                _goalPlanNotice,
                                style: const TextStyle(
                                  color: Color(0xffffc857),
                                  fontSize: 13,
                                ),
                              ),
                            ),
                          if (openEntries.isEmpty)
                            const Padding(
                              padding: EdgeInsets.only(bottom: 10),
                              child: Text(
                                'No goal is running. A refused ask keeps the rounds it spent, and the chip names why it stopped.',
                                style: TextStyle(
                                  color: Color(0xffb8c6dd),
                                  fontSize: 13,
                                  height: 1.4,
                                ),
                              ),
                            )
                          else ...[
                            _goalMeterHeading('Open'),
                            ...openEntries.map(meterTile),
                          ],
                          if (stoppedEntries.isNotEmpty) ...[
                            _goalMeterHeading('Could not finish'),
                            ...stoppedEntries.map(meterTile),
                          ],
                          if (finishedEntries.isNotEmpty) ...[
                            _goalMeterHeading('Finished'),
                            ...finishedEntries.map(meterTile),
                          ],
                          if (trainingEntries.isNotEmpty)
                            Theme(
                              data: Theme.of(context).copyWith(
                                dividerColor: Colors.transparent,
                              ),
                              child: ExpansionTile(
                                key: const Key('goals-training-cards'),
                                tilePadding: EdgeInsets.zero,
                                iconColor: const Color(0xffb8c6dd),
                                collapsedIconColor: const Color(0xff8b98a5),
                                title: Text(
                                  'Training cards recorded as goals (${trainingEntries.length})',
                                  style: const TextStyle(
                                    color: Color(0xffb8c6dd),
                                    fontSize: 13,
                                    fontWeight: FontWeight.w700,
                                  ),
                                ),
                                children: trainingEntries.map(meterTile).toList(),
                              ),
                            ),
                          if (focusedGoal != null) _goalInteraction(focusedGoal),
                        ],
                      ],
                    ),
                  ),
                  const SizedBox(height: 12),
                  _macToolPanel(
                    title: 'Month planner',
                    icon: Icons.calendar_month_outlined,
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        Row(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            IconButton(
                              key: const Key('goals-month-prev'),
                              onPressed: () => setState(() {
                                _goalsMonth = DateTime(
                                  _goalsMonth.year,
