                        Wrap(
                          spacing: 14,
                          runSpacing: 6,
                          children: [
                            _goalCalendarLegendDot(
                              'Start (operator)',
                              const Color(0xff58a6ff),
                            ),
                            _goalCalendarLegendDot(
                              'Due (operator)',
                              const Color(0xffffc857),
                            ),
                            _goalCalendarLegendDot(
                              'Projected finish (Engel)',
                              const Color(0xffb98aff),
                            ),
                            _goalCalendarLegendDot(
                              'Finished',
                              const Color(0xff35d07f),
                            ),
                            _goalCalendarLegendDot(
                              'Weekly task',
                              const Color(0xff58e6c8),
                            ),
                            _goalCalendarLegendDot(
                              'Overdue',
                              const Color(0xffff9f43),
                            ),
