  Widget _chatConnectionRecovery() {
    final checking = _mainServerOnline == null;
    final accent = checking ? const Color(0xffffc857) : const Color(0xffff7777);
    final background = checking
        ? const Color(0xff282312)
        : const Color(0xff2a151b);
    final title = checking ? 'Checking chat connection' : 'Chat unavailable';
    final detail = checking
        ? 'Checking Engel chat and Meeting Room. Local files and tools stay available.'
        : 'Engel chat is not responding. Files, notes, settings, and local tools still work.';
    final semanticLabel = checking
        ? 'Checking Engel chat connection. Local files and tools remain available.'
        : 'Engel chat is unavailable. Files, notes, settings, and local tools still work.';

    Widget message() {
      return Semantics(
        key: const Key('chat-connection-recovery-announcement'),
        container: true,
        excludeSemantics: true,
        liveRegion: true,
        label: semanticLabel,
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            SizedBox(
              width: 26,
              height: 26,
              child: checking
                  ? CircularProgressIndicator(strokeWidth: 2.4, color: accent)
                  : Icon(Icons.cloud_off_outlined, color: accent, size: 24),
            ),
            const SizedBox(width: 11),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    title,
                    key: const Key('chat-connection-recovery-title'),
                    style: const TextStyle(
                      color: Color(0xfff4f6fb),
                      fontSize: 16,
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                  const SizedBox(height: 3),
                  Text(
                    detail,
                    style: const TextStyle(
                      color: Color(0xffd1d6e1),
                      fontSize: 14,
                      height: 1.35,
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      );
    }

    final actions = Wrap(
      spacing: 8,
      runSpacing: 8,
      children: [
        OutlinedButton.icon(
          key: const Key('chat-connection-retry'),
          onPressed: checking ? null : _retryMainServerHealth,
          style: OutlinedButton.styleFrom(
            minimumSize: const Size(0, 48),
            foregroundColor: const Color(0xfff0f4ff),
            side: BorderSide(color: accent.withValues(alpha: 0.8)),
          ),
          icon: const Icon(Icons.refresh_rounded, size: 18),
          label: Text(checking ? 'Checking…' : 'Try again'),
        ),
        FilledButton.tonalIcon(
          key: const Key('chat-connection-doctor'),
          onPressed: () => _selectSectionById('connection_doctor'),
          style: FilledButton.styleFrom(
            minimumSize: const Size(0, 48),
            backgroundColor: accent.withValues(alpha: 0.16),
            foregroundColor: const Color(0xfff4f6fb),
          ),
          icon: const Icon(Icons.health_and_safety_outlined, size: 18),
          label: const Text('Connection help'),
        ),
      ],
    );

    return Container(
      key: const Key('chat-connection-recovery'),
      width: double.infinity,
      padding: const EdgeInsets.fromLTRB(16, 11, 16, 12),
      decoration: BoxDecoration(
        color: background,
        border: Border(
          bottom: BorderSide(color: accent.withValues(alpha: 0.65)),
        ),
      ),
      child: LayoutBuilder(
        builder: (context, constraints) {
          final stacked =
              constraints.maxWidth < 900 || _effectiveInterfaceTextScale > 1.3;
          if (stacked) {
            return Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                message(),
                const SizedBox(height: 10),
                Align(alignment: Alignment.centerLeft, child: actions),
              ],
            );
          }
          return Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              Expanded(child: message()),
              const SizedBox(width: 18),
              actions,
            ],
          );
        },
      ),
    );
  }

  Widget _topBar(SectionSpec _, {required bool showNavigationButton}) {
    final serverOnline = _mainServerOnline == true;
    final serverChecking = _mainServerOnline == null;
    final serverColor = serverChecking
        ? const Color(0xffffc857)
        : serverOnline
        ? const Color(0xff00e87a)
        : const Color(0xffff6b6b);
    final serverLabel = serverChecking
        ? 'Checking chat'
        : serverOnline
        ? 'Chat ready'
        : 'Chat unavailable';
    final compactStatusLabel = _effectiveInterfaceTextScale > 1.3;
    final textScale = _effectiveInterfaceTextScale;
    final topBarHeight = textScale > 1.7
        ? 88.0
        : textScale > 1.3
        ? 74.0
        : 62.0;
    final serverDisplayLabel = compactStatusLabel
        ? serverChecking
              ? 'Checking'
              : serverOnline
              ? 'Ready'
              : 'Unavailable'
        : serverLabel;
    final serverTooltip = serverChecking
        ? 'Checking the Engel chat connection. Open status and actions.'
        : serverOnline
        ? 'Engel chat is connected. Open status and actions.'
        : 'Engel chat is not responding. Open status and recovery actions.';
    const serverHint = 'Activate for connection status and actions.';
    return Container(
      height: topBarHeight,
      padding: EdgeInsets.symmetric(horizontal: showNavigationButton ? 10 : 18),
      decoration: BoxDecoration(
        color: EngelLiquidGlass.surfaceElevated,
        border: Border(
          bottom: BorderSide(
            color: EngelLiquidGlass.rimStrong.withValues(alpha: 0.55),
            width: 1,
          ),
        ),
      ),
      child: Row(
        children: [
          if (showNavigationButton) ...[
            IconButton(
              key: const Key('open-navigation-menu'),
              onPressed: _toggleCompactNavigation,
              icon: Icon(
                _compactNavigationOpen
                    ? Icons.close_rounded
                    : Icons.menu_rounded,
              ),
              tooltip: _compactNavigationOpen
                  ? 'Close navigation menu'
                  : 'Open navigation menu',
            ),
            const SizedBox(width: 4),
          ],
          const Icon(
            Icons.auto_awesome,
            color: EngelLiquidGlass.accent,
            size: 22,
          ),
          const SizedBox(width: 10),
          const Text(
            'Engel',
            style: TextStyle(
              color: EngelLiquidGlass.textPrimary,
              fontSize: 18,
              fontWeight: FontWeight.w800,
              letterSpacing: -0.2,
            ),
          ),
          const SizedBox(width: 10),
          Flexible(
            child: Semantics(
              key: const Key('main-server-status-semantics'),
              container: true,
              excludeSemantics: true,
              liveRegion: true,
              button: true,
              enabled: true,
              label: 'Engel chat status: $serverLabel',
              hint: serverHint,
              onTap: _showChatConnectionStatus,
              child: Tooltip(
                message: serverTooltip,
                child: InkWell(
                  key: const Key('main-server-status'),
                  onTap: () => unawaited(_showChatConnectionStatus()),
                  borderRadius: BorderRadius.circular(5),
                  child: ConstrainedBox(
                    constraints: const BoxConstraints(minHeight: 44),
                    child: DecoratedBox(
                      decoration: BoxDecoration(
                        color: serverColor.withValues(alpha: 0.1),
                        borderRadius: BorderRadius.circular(5),
                        border: Border.all(color: serverColor, width: 0.9),
                      ),
                      child: Padding(
                        padding: const EdgeInsets.symmetric(horizontal: 9),
                        child: Center(
                          widthFactor: 1,
                          child: Text(
                            serverDisplayLabel,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                              color: serverChecking
                                  ? const Color(0xffffd978)
                                  : serverOnline
                                  ? const Color(0xff79f0ad)
                                  : const Color(0xffff9a9a),
                              fontSize: 11,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ),
          const Spacer(),
          if (!showNavigationButton &&
              MediaQuery.sizeOf(context).width >= 1100) ...[
            _modelPickerButton(),
            const SizedBox(width: 6),
          ],
          IconButton(
            onPressed: () => unawaited(_startNewChat()),
            icon: const Icon(Icons.chat_bubble_outline_rounded, size: 19),
            tooltip: 'New chat',
          ),
          const SizedBox(width: 4),
          IconButton(
            onPressed: _running ? null : () => _runRust(rustCommands[0]),
            icon: const Icon(Icons.verified_outlined, size: 19),
            tooltip: 'System Proof',
          ),
        ],
      ),
    );
  }

