                          },
                        ),
                      ),
                      const SizedBox(height: 18),
                      LayoutBuilder(
                        builder: (context, tileConstraints) {
                          final compact = tileConstraints.maxWidth < 660;
                          final tiles = [
                            _quickActionCard(
                              key: const Key('home-do-task'),
                              label: 'Do a task',
                              description:
                                  'Engel chooses safe tools and shows proof',
                              icon: Icons.auto_awesome_motion_rounded,
                              color: const Color(0xffa78bfa),
                              onTap: () => unawaited(_showAgentWorkDialog()),
                            ),
                            _quickActionCard(
                              key: const Key('home-new-note'),
                              label: 'New note',
                              description: 'Capture an idea or reminder',
                              icon: Icons.note_add,
                              color: const Color(0xff00e87a),
                              onTap: () {
                                _newNoteDraft();
                                _selectSectionById('notes');
                              },
                            ),
                            _quickActionCard(
                              key: const Key('home-worker-task'),
                              label: 'Worker task',
                              description: 'Send work to the Meeting Room team',
                              icon: Icons.assignment,
                              color: const Color(0xffffc857),
                              onTap: () {
                                _meetingText.clear();
                                setState(() {
                                  _meetingDraft = '';
                                  _dispatchDraft = '';
                                  _status = 'new task draft';
                                });
                                _selectSectionById('tasks');
                              },
                            ),
                          ];
                          if (compact) {
                            return Column(
                              crossAxisAlignment: CrossAxisAlignment.stretch,
                              children: [
                                for (final tile in tiles) ...[
                                  tile,
                                  if (tile != tiles.last)
                                    const SizedBox(height: 10),
                                ],
                              ],
                            );
                          }
                          return Row(
                            children: [
                              for (final tile in tiles) ...[
                                Expanded(child: tile),
                                if (tile != tiles.last)
                                  const SizedBox(width: 10),
                              ],
                            ],
                          );
                        },
                      ),
                      const SizedBox(height: 20),
                      Container(height: 1, color: const Color(0xff383943)),
                      const SizedBox(height: 20),
                      const Text(
                        'Quick access',
                        style: TextStyle(
                          color: Color(0xfff7f7fb),
                          fontSize: 19,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      const SizedBox(height: 12),
                      LayoutBuilder(
                        builder: (context, shortcutConstraints) {
                          final shortcuts = [
                            _macRouteRow(
                              key: const Key('home-chat-readiness'),
                              stackValue: true,
                              dense: true,
                              icon: Icons.chat_bubble_outline,
                              title: 'Chat with Engel',
                              value: _chatRunning
                                  ? 'answering'
                                  : _mainServerOnline == true
                                  ? 'ready'
                                  : _mainServerOnline == null
                                  ? 'checking'
                                  : 'unavailable',
                              onTap: () => _selectSectionById('chat_runtime'),
                            ),
                            _macRouteRow(
                              key: const Key('home-meeting-room-shortcut'),
                              stackValue: true,
                              dense: true,
                              icon: Icons.groups_2_outlined,
                              title: 'Meeting Room',
                              value: meetingRoomReadinessLabel(
                                _meetingRoomServer,
                              ),
                              onTap: () {
                                _selectSectionById('meeting');
                                unawaited(_refreshMeetingRoomServer());
                              },
                            ),
                            _macRouteRow(
                              key: const Key('home-devices-shortcut'),
                              stackValue: true,
                              dense: true,
                              icon: Icons.devices_other,
                              title: 'Devices',
                              value: _deviceReadySummary(),
                              onTap: () =>
                                  _selectSectionById('device_visibility'),
                            ),
                            _macRouteRow(
                              key: const Key('home-worker-results-shortcut'),
                              stackValue: true,
                              dense: true,
                              icon: Icons.phonelink,
                              title: 'Sub-Engel work',
                              value:
                                  _deviceVisibility.subEngelWorker.status.label,
                              onTap: () => _selectSectionById('tasks'),
                            ),
                            _macRouteRow(
                              key: const Key('home-wiki-one-shortcut'),
                              stackValue: true,
                              dense: true,
                              icon: Icons.hub_outlined,
                              title: 'Wiki One',
                              value: 'second brain',
                              onTap: () => unawaited(_openWikiBrain()),
                            ),
                            _macRouteRow(
                              key: const Key('home-models-shortcut'),
                              stackValue: true,
                              dense: true,
                              icon: Icons.memory,
                              title: 'Models',
                              value: _creationModelName,
                              onTap: () => _selectSectionById('local_llm'),
                            ),
                          ];
                          final oneColumn =
                              shortcutConstraints.maxWidth < 680 ||
                              _effectiveInterfaceTextScale > 1.3;
                          final shortcutWidth = oneColumn
                              ? shortcutConstraints.maxWidth
                              : (shortcutConstraints.maxWidth - 10) / 2;
                          return Wrap(
                            spacing: 10,
                            runSpacing: 0,
                            children: [
                              for (final shortcut in shortcuts)
                                SizedBox(width: shortcutWidth, child: shortcut),
                            ],
                          );
                        },
                      ),
                    ],
                  ),
                ),
              ),
            ),
          );
        },
      ),
    );
