  Widget _meetingRoomTaskReadiness() {
    final info = _meetingRoomServer;
    final title = meetingRoomReadinessLabel(info);
    final detail = meetingRoomReadinessDetail(info);
    final status = info.status.trim().toLowerCase();
    final starting = !info.ok && status == 'starting';
    final notChecked = !info.ok && status == 'not checked';
    final accent = info.ok ? const Color(0xff47df91) : const Color(0xffffc857);
    final icon = starting
        ? Icons.sync_rounded
        : info.ok
        ? Icons.groups_2_outlined
        : Icons.link_off_rounded;
    final statusContent = Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Icon(icon, color: accent, size: 22),
        const SizedBox(width: 10),
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                title,
                style: const TextStyle(
                  color: Color(0xfff4f7fb),
                  fontWeight: FontWeight.w800,
                ),
              ),
              const SizedBox(height: 3),
              Text(
                detail,
                style: const TextStyle(color: Color(0xffaebbd0), height: 1.35),
              ),
              const SizedBox(height: 3),
              Text(
                'Devices: ${_deviceReadySummary()}',
                key: const Key('tasks-device-ready-summary'),
                style: const TextStyle(color: Color(0xffaebbd0), height: 1.35),
              ),
            ],
          ),
        ),
      ],
    );
    final action = OutlinedButton.icon(
      key: const Key('tasks-meeting-room-check'),
      onPressed: _running || starting
          ? null
          : () => info.ok
                ? unawaited(_refreshMeetingRoomServer())
                : unawaited(_ensureMeetingRoomServer()),
      icon: Icon(
        info.ok ? Icons.refresh_rounded : Icons.link_rounded,
        size: 17,
      ),
      label: Text(
        starting
            ? 'Connecting...'
            : info.ok || notChecked
            ? 'Check Meeting Room'
            : 'Connect Meeting Room',
      ),
    );
    return Semantics(
      key: const Key('tasks-meeting-room-readiness'),
      container: true,
      liveRegion: true,
      label: '$title. $detail. Devices: ${_deviceReadySummary()}',
      child: Container(
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: const Color(0xff151d2f),
          borderRadius: BorderRadius.circular(8),
          border: Border.all(color: accent.withValues(alpha: 0.65)),
        ),
        child: LayoutBuilder(
          builder: (context, constraints) {
            final stack =
                constraints.maxWidth < 600 ||
                _effectiveInterfaceTextScale > 1.3;
            if (stack) {
              return Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  statusContent,
                  const SizedBox(height: 10),
                  Align(alignment: Alignment.centerLeft, child: action),
                ],
              );
            }
            return Row(
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                Expanded(child: statusContent),
                const SizedBox(width: 16),
                action,
              ],
            );
          },
        ),
