  String _buildLanguagesPromptPrefix() {
    final hasKernel = _selectedCodeLanguages.any(
      (l) =>
          l.toLowerCase().contains('kernel') ||
          l.toLowerCase().contains('ebpf') ||
          l.toLowerCase().contains('bpf') ||
          l.toLowerCase().contains('driver') ||
          l.toLowerCase().contains('assembly') ||
          l.toLowerCase().contains('systems'),
    );
    final selected = _selectedCodeLanguages.toList()..sort();
    final langList = selected.isEmpty
        ? 'Auto-select the right language for the request.'
        : 'Preferred language lanes: ${selected.take(18).join(', ')}${selected.length > 18 ? ', and ${selected.length - 18} more selected lanes' : ''}.';
    final kernelHint = hasKernel
        ? 'If the request is kernel, driver, firmware, eBPF, or low-level systems work, provide a safe minimal skeleton or bounded example.'
        : 'Use kernel/driver knowledge only when the operator asks for it.';
    return 'Engel code capability context: $langList Use only the language(s) relevant to the operator request. $kernelHint Answer naturally as Engel AI Main; do not explain this context.';
  }

