  Widget _accessibilityAppearancePanel() {
    final textPercent = (_interfaceTextScale * 100).round();
    final textScale = _effectiveInterfaceTextScale;
    return _macToolPanel(
      title: 'Comfort and accessibility',
      icon: Icons.accessibility_new_rounded,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
