                ],
              );
              if (constraints.maxWidth < 560 || textScale > 1.35) {
                return Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    details,
                    const SizedBox(height: 10),
                    Align(
                      alignment: Alignment.centerRight,
                      child: _Tag('$textPercent%'),
                    ),
                  ],
                );
              }
              return Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Expanded(child: details),
                  _Tag('$textPercent%'),
                ],
              );
            },
          ),
          Slider(
            key: const Key('interface-text-scale'),
            value: _interfaceTextScale,
            min: 1,
            max: 2,
            divisions: 4,
            label: '$textPercent%',
