  Widget _modelPickerButton({bool compact = true, bool creation = false}) {
    final label = creation ? _creationModelName : _activeModelName;
    final shortLabel = _shortModelChipLabel(label);
    final chip = creation ? 'Creation: $shortLabel' : 'Chat: $shortLabel';
    return ConstrainedBox(
      constraints: BoxConstraints(maxWidth: compact ? 240 : 320),
      child: Tooltip(
        message: creation ? 'Creation model: $label' : 'Chat model: $label',
        child: OutlinedButton.icon(
          key: Key(
            creation
                ? 'creation-model-picker-button'
                : 'chat-model-picker-button',
          ),
          onPressed: () => _showModelPicker(creation: creation),
          icon: Icon(
            creation ? Icons.construction : Icons.auto_awesome,
            size: 17,
          ),
          label: Text(chip, overflow: TextOverflow.ellipsis),
          style: OutlinedButton.styleFrom(
            foregroundColor: EngelLiquidGlass.textPrimary,
            side: const BorderSide(color: EngelLiquidGlass.rimStrong),
            backgroundColor: EngelLiquidGlass.surfaceElevated,
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(EngelLiquidGlass.radiusSm),
            ),
          ),
        ),
      ),
    );
  }

  String _shortModelChipLabel(String name) {
    var clean = name.trim();
    clean = clean.replaceFirst(
      RegExp(r'^(Chat|Creation):\s*', caseSensitive: false),
      '',
    );
    clean = clean.replaceFirst(
      RegExp(r'^Hugging Face\s+', caseSensitive: false),
      'HF ',
    );
    if (clean.length <= 24) return clean;
    return '${clean.substring(0, 22)}…';
  }

  void _showModelPicker({bool creation = false}) {
    var query = '';
    var draftModelId = creation ? _creationModelId : _activeModelId;
    var draftThinkingEnabled = _thinkingEnabled;
    var draftReasoningEffort = _reasoningEffort;
    final modelScrollController = ScrollController();
    unawaited(
      showDialog<void>(
        context: context,
        builder: (dialogContext) {
          return StatefulBuilder(
            builder: (context, setDialogState) {
              final normalized = query.trim().toLowerCase();
              final options = _visibleModelCatalog.where((option) {
                if (normalized.isEmpty) return true;
                return option.name.toLowerCase().contains(normalized) ||
                    option.provider.toLowerCase().contains(normalized) ||
                    option.group.toLowerCase().contains(normalized);
              }).toList();
              final hasChanges =
                  draftModelId !=
                      (creation ? _creationModelId : _activeModelId) ||
                  draftThinkingEnabled != _thinkingEnabled ||
                  draftReasoningEffort != _reasoningEffort;
              final selectedOption = _modelOptionById(draftModelId);
              final compact =
                  MediaQuery.sizeOf(context).width < 720 ||
                  _effectiveInterfaceTextScale > 1.3;

              final modelList = Container(
                key: const Key('model-picker-list'),
                decoration: BoxDecoration(
                  color: const Color(0xff14151b),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(color: const Color(0xff393a42)),
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    TextField(
                      key: const Key('model-picker-search'),
                      autofocus: true,
                      onChanged: (value) => setDialogState(() => query = value),
                      style: const TextStyle(
                        color: Color(0xffededf2),
                        fontSize: 13,
                      ),
                      decoration: const InputDecoration(
                        hintText: 'Search models',
                        prefixIcon: Icon(Icons.search),
                        border: OutlineInputBorder(),
                      ),
                    ),
                    const SizedBox(height: 8),
                    Expanded(
                      child: options.isEmpty
                          ? const Center(
                              child: Padding(
                                padding: EdgeInsets.all(16),
                                child: Text('No models match this search.'),
                              ),
                            )
                          : Scrollbar(
                              controller: modelScrollController,
                              thumbVisibility: true,
                              child: ListView(
                                controller: modelScrollController,
                                padding: const EdgeInsets.fromLTRB(
                                  10,
                                  0,
                                  10,
                                  6,
                                ),
                                children: [
                                  for (final option in options)
                                    _modelPickerRow(
                                      option,
                                      creation: creation,
                                      selectedModelId: draftModelId,
                                      onSelected: () => setDialogState(
                                        () => draftModelId = option.id,
                                      ),
                                    ),
                                ],
                              ),
                            ),
                    ),
                    TextButton.icon(
                      key: const Key('model-picker-edit-models'),
                      onPressed: () {
                        Navigator.of(dialogContext).pop();
                        _showEditModelsDialog();
                      },
                      icon: const Icon(Icons.tune, size: 17),
                      label: const Text('Manage available models'),
                    ),
                  ],
                ),
              );

              final optionsEditor = _modelOptionsEditor(
                compact: compact,
                thinkingEnabled: draftThinkingEnabled,
                reasoningEffort: draftReasoningEffort,
                onThinkingChanged: (value) =>
                    setDialogState(() => draftThinkingEnabled = value),
                onEffortChanged: (value) =>
                    setDialogState(() => draftReasoningEffort = value),
              );

              return Dialog(
                insetPadding: const EdgeInsets.symmetric(
                  horizontal: 16,
                  vertical: 16,
                ),
                backgroundColor: Colors.transparent,
                child: ConstrainedBox(
                  constraints: const BoxConstraints(
                    maxWidth: 760,
                    maxHeight: 680,
                  ),
                  child: Container(
                    key: const Key('model-picker-dialog'),
                    decoration: BoxDecoration(
                      color: const Color(0xff101117),
                      borderRadius: BorderRadius.circular(12),
                      border: Border.all(color: const Color(0xff393a42)),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        Padding(
                          padding: const EdgeInsets.fromLTRB(18, 16, 10, 8),
                          child: Row(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Expanded(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text(
                                      creation
                                          ? 'Choose a creation model'
                                          : 'Choose a chat model',
                                      style: const TextStyle(
                                        color: Color(0xfff5f7ff),
                                        fontSize: 20,
                                        fontWeight: FontWeight.w800,
                                      ),
                                    ),
                                    const SizedBox(height: 4),
                                    const Text(
                                      'Your current choice stays active until you choose Apply.',
                                      style: TextStyle(
                                        color: Color(0xffaebbd1),
                                        fontSize: 13,
                                        height: 1.3,
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                              IconButton(
                                key: const Key('model-picker-close'),
                                tooltip: 'Cancel model changes',
                                onPressed: () =>
                                    Navigator.of(dialogContext).pop(),
                                icon: const Icon(Icons.close),
                              ),
                            ],
                          ),
                        ),
                        Expanded(
                          child: Padding(
                            padding: const EdgeInsets.fromLTRB(16, 4, 16, 12),
                            child: compact
                                ? Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.stretch,
                                    children: [
                                      Flexible(
                                        flex: 2,
                                        child: SingleChildScrollView(
                                          key: const Key(
                                            'model-picker-options-scroll',
                                          ),
                                          primary: false,
                                          child: optionsEditor,
                                        ),
                                      ),
                                      const SizedBox(height: 10),
                                      Expanded(flex: 3, child: modelList),
                                    ],
                                  )
                                : Row(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.stretch,
                                    children: [
                                      optionsEditor,
                                      const SizedBox(width: 12),
                                      Expanded(child: modelList),
                                    ],
                                  ),
                          ),
                        ),
                        const Divider(height: 1, color: Color(0xff31323a)),
                        Padding(
                          padding: const EdgeInsets.fromLTRB(16, 10, 16, 14),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.stretch,
                            children: [
                              if (!selectedOption.liveRoute)
                                const Padding(
                                  padding: EdgeInsets.only(bottom: 8),
                                  child: Text(
                                    'Setup is still required for this model. Engel will keep its verified fallback available.',
                                    key: Key('model-picker-setup-required'),
                                    style: TextStyle(
                                      color: Color(0xffffc857),
                                      fontSize: 12.5,
                                      height: 1.3,
                                    ),
                                  ),
                                ),
                              if (hasChanges)
                                const Padding(
                                  padding: EdgeInsets.only(bottom: 8),
                                  child: Text(
                                    'Not applied yet.',
                                    key: Key('model-picker-pending'),
                                    style: TextStyle(
                                      color: Color(0xff00e5ff),
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                ),
                              Wrap(
                                alignment: WrapAlignment.end,
                                spacing: 8,
                                runSpacing: 8,
                                children: [
                                  TextButton(
                                    key: const Key('model-picker-cancel'),
                                    onPressed: () =>
                                        Navigator.of(dialogContext).pop(),
                                    child: const Text('Cancel'),
                                  ),
                                  FilledButton.icon(
                                    key: const Key('model-picker-apply'),
                                    onPressed: !hasChanges || _modelRouterSaving
                                        ? null
                                        : () {
                                            Navigator.of(dialogContext).pop();
                                            if (!selectedOption.liveRoute) {
                                              setState(() {
                                                _output =
                                                    '${selectedOption.name} needs provider setup. Engel will keep using verified fallback routing until that provider is connected.';
                                              });
                                            }
                                            unawaited(
                                              _saveModelRouterConfig(
                                                activeModelId: creation
                                                    ? _activeModelId
                                                    : draftModelId,
                                                creationModelId: creation
                                                    ? draftModelId
                                                    : _creationModelId,
                                                thinkingEnabled:
                                                    draftThinkingEnabled,
                                                reasoningEffort:
                                                    draftReasoningEffort,
                                              ),
                                            );
                                          },
                                    icon: const Icon(Icons.check, size: 18),
                                    label: const Text('Apply'),
                                  ),
                                ],
                              ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              );
            },
          );
        },
      ).whenComplete(modelScrollController.dispose),
    );
  }

  Widget _modelPickerRow(
    EngelModelOption option, {
    required bool creation,
    required String selectedModelId,
    required VoidCallback onSelected,
  }) {
    final selected = option.id == selectedModelId;
    return Semantics(
      key: Key('model-picker-option-${option.id}'),
      button: true,
      selected: selected,
      label:
          '${creation ? 'Build model' : 'Chat model'}: ${option.name}${option.liveRoute ? '' : ', setup required'}',
      child: Material(
        color: selected ? const Color(0xff2b2b30) : Colors.transparent,
        borderRadius: BorderRadius.circular(6),
        child: InkWell(
          onTap: onSelected,
          child: Container(
            constraints: const BoxConstraints(minHeight: 52),
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 8),
            child: Row(
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        option.name,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: Color(0xfff1f1f4),
                          fontSize: 13,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                      const SizedBox(height: 2),
                      Text(
                        option.liveRoute
