  Widget _modelToggleRow(
    EngelModelOption option, {
    required StateSetter refreshDialog,
  }) {
    final enabled = _enabledModelIds.contains(option.id);
    return SizedBox(
      height: 28,
      child: Row(
        children: [
          Expanded(
            child: Text(
              option.name,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                color: Color(0xfff1f1f4),
                fontSize: 12,
                fontWeight: FontWeight.w700,
              ),
            ),
          ),
          Transform.scale(
            scale: .78,
            child: Switch(
              value: enabled,
              activeThumbColor: const Color(0xfff2f2f2),
              activeTrackColor: const Color(0xff0c0c0d),
              inactiveThumbColor: const Color(0xfff2f2f2),
              inactiveTrackColor: const Color(0xff303034),
              onChanged: (value) {
                setState(() {
                  if (value) {
                    _enabledModelIds.add(option.id);
                  } else {
                    _enabledModelIds.remove(option.id);
                  }
                  _modelRouterStatus = value
                      ? '${option.name} enabled'
                      : '${option.name} hidden from picker';
                });
                refreshDialog(() {});
                unawaited(_saveModelRouterConfig());
              },
            ),
          ),
        ],
      ),
    );
  }

