  Widget _providerAccountsSetupPanel({
    required BuildContext dialogContext,
    required VoidCallback openApiKeys,
    required StateSetter refreshDialog,
  }) {
    final chatGptBridge = _chatGptBrowserBridgeStatus();
    final xaiKeyStatus = _providerKeyStatus('xAI');
    final xaiStatus = xaiKeyStatus.label ?? 'Needs key';
    final xaiDetail = xaiKeyStatus.label == null
        ? 'Paste and save an xAI key under API keys, then tap to live-verify.'
        : 'Saved xAI lane is tracked. Tap to live-verify against api.x.ai.';
    final nvidiaKeyStatus = _providerKeyStatus('NVIDIA NIM');
    final nvidiaStatus = nvidiaKeyStatus.label ?? 'Needs key';
    final nvidiaDetail = nvidiaKeyStatus.label == null
        ? 'Engel AI Main fallback brain. Paste the NVIDIA NIM key under API keys (or run Install-EngelNvidiaNimApiBridgeKey.ps1). Never paste it in chat.'
        : 'Engel AI Main NVIDIA NIM lane. Local CT246 talks first; NIM is fallback after a proved local miss. Tap to open API keys.';
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Row(
          children: [
            const Icon(Icons.key_outlined, size: 16, color: Color(0xffa8a8b0)),
            const SizedBox(width: 9),
            const Expanded(
              child: Text(
                'Connect an account',
                style: TextStyle(
                  color: Color(0xfff2f2f5),
                  fontSize: 14,
                  fontWeight: FontWeight.w800,
                ),
              ),
            ),
            TextButton(
              onPressed: openApiKeys,
              child: const Text('Have an API key instead?'),
            ),
          ],
        ),
        const SizedBox(height: 8),
        Expanded(
          child: ListView(
            children: [
              const Text(
                'Every signed-in account is listed below. Scroll to see Grok, extra Codex slots, NVIDIA, and API lanes. Add account creates another sign-in for that provider. Engel AI Main and bots share one memory core and switch when usage runs out.',
                style: TextStyle(color: Color(0xff9c9ca3), fontSize: 12),
              ),
              const SizedBox(height: 12),
              _providerConnectCard(
                title: 'Engel Portal',
                status: 'Local setup',
                detail:
                    'One Engel setup surface for frontier models and local routes.',
                emphasized: true,
                onTap: () => _closeDialogAndRunRust(
                  dialogContext,
                  'accounts',
                  'connectors_account_status',
                ),
              ),
              _providerConnectCard(
                title: 'Engel AI Main · NVIDIA NIM',
                status: nvidiaStatus,
                detail: nvidiaDetail,
                emphasized: true,
                onTap: openApiKeys,
              ),
              const SizedBox(height: 16),
              const Text(
                'Provider links',
                style: TextStyle(
                  color: Color(0xff9c9ca3),
                  fontSize: 12,
                  fontWeight: FontWeight.w800,
                ),
              ),
              const SizedBox(height: 10),
              _providerConnectCard(
                title: 'OpenAI OAuth (ChatGPT)',
                status: chatGptBridge.status,
                detail: chatGptBridge.detail,
                onTap: () =>
                    _closeDialogAndCheckChatGptBrowserBridge(dialogContext),
              ),
              _providerConnectCard(
                title: 'xAI Grok API key',
                status: xaiStatus,
                detail: xaiDetail,
                onTap: () => _closeDialogAndVerifyXaiGrok(dialogContext),
              ),
              const SizedBox(height: 16),
              const Text(
                'CLI accounts',
                style: TextStyle(
                  color: Color(0xff9c9ca3),
                  fontSize: 12,
                  fontWeight: FontWeight.w800,
                ),
              ),
              const SizedBox(height: 4),
              const Text(
                'Grok Super CLI and ChatGPT Codex. Extra slots appear under each provider after Add account. Login opens a terminal + browser; finish there, then Check.',
                style: TextStyle(color: Color(0xff8b8b92), fontSize: 11),
              ),
              const SizedBox(height: 10),
              for (final account in _visibleCliAccounts())
                _cliAccountCard(account, refreshDialog),
              if (_apiProviderAccountCards(refreshDialog).isNotEmpty) ...[
                const SizedBox(height: 16),
                const Text(
                  'API key providers',
                  style: TextStyle(
                    color: Color(0xff9c9ca3),
