  Widget _providerApiKeysSetupPanel({
    required BuildContext dialogContext,
    required StateSetter refreshDialog,
  }) {
    const providers = [
      ['OpenAI API', 'Paste OpenAI API key'],
      ['NVIDIA NIM', 'Paste NVIDIA NIM key for Engel AI Main'],
      ['OpenRouter', 'Paste OpenRouter key'],
      ['xAI', 'Paste xAI key'],
      ['Gemini', 'Paste Gemini key'],
      ['DeepSeek', 'Paste DeepSeek key'],
      ['DashScope (Qwen)', 'Paste DashScope (Qwen) key'],
      ['GLM / Z.AI', 'Paste GLM / Z.AI key'],
      ['Kimi / Moonshot', 'Paste Kimi / Moonshot key'],
      ['Kimi (China)', 'Paste Kimi (China) key'],
      ['MiniMax', 'Paste MiniMax key'],
      ['MiniMax (China)', 'Paste MiniMax (China) key'],
      ['Mistral', 'Paste Mistral key'],
      ['Cohere', 'Paste Cohere key'],
      ['Groq', 'Paste Groq key'],
      ['Perplexity', 'Paste Perplexity key'],
      ['Hugging Face', 'Paste Hugging Face key'],
    ];
    return ListView(
      children: [
        const Text(
          'API keys',
          style: TextStyle(
            color: Color(0xfff2f2f5),
            fontSize: 14,
            fontWeight: FontWeight.w900,
          ),
        ),
        const SizedBox(height: 8),
        const Text(
          'Paste a provider key, save it to the Windows user environment, then verify the connector route. NVIDIA NIM also writes run/secrets/nvidia.env for Engel AI Main / CT246. Secret values are never printed in output.',
          style: TextStyle(color: Color(0xff9c9ca3), fontSize: 12),
        ),
        const SizedBox(height: 16),
        for (final provider in providers) ...[
          Builder(
            builder: (context) {
              final providerName = provider[0];
              final providerHint = provider[1];
              final widgetId = _providerKeyWidgetId(providerName);
              final controller = _providerKeyController(providerName);
              final envName = _providerEnvVarFor(providerName);
              final keyStatus = _providerKeyStatus(providerName);
              return Padding(
                padding: const EdgeInsets.only(bottom: 13),
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.center,
                  children: [
                    Icon(Icons.circle, color: keyStatus.color, size: 8),
                    const SizedBox(width: 10),
                    SizedBox(
                      width: 230,
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          Text(
                            providerName,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              color: Color(0xffd6d6dc),
                              fontSize: 13,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                          const SizedBox(height: 3),
                          Text(
                            envName,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              color: Color(0xff777984),
                              fontSize: 10,
                            ),
                          ),
                          if (keyStatus.label != null) ...[
                            const SizedBox(height: 3),
                            Text(
                              keyStatus.label!,
                              key: Key('provider-key-status-$widgetId'),
                              overflow: TextOverflow.ellipsis,
                              style: TextStyle(
                                color: keyStatus.color,
                                fontSize: 10,
                                fontWeight: FontWeight.w800,
                              ),
                            ),
                          ],
                        ],
                      ),
                    ),
                    const SizedBox(width: 14),
                    Expanded(
                      child: SizedBox(
                        height: 34,
                        child: TextField(
                          key: Key('provider-key-input-$widgetId'),
                          controller: controller,
                          obscureText: true,
                          enableSuggestions: false,
                          autocorrect: false,
                          style: const TextStyle(
                            color: Color(0xfff0f0f4),
                            fontSize: 12,
                          ),
                          decoration: InputDecoration(
                            hintText: providerHint,
                            hintStyle: const TextStyle(
                              color: Color(0xff8b8b92),
                              fontSize: 12,
                            ),
                            isDense: true,
                            filled: true,
                            fillColor: const Color(0xff171718),
                            contentPadding: const EdgeInsets.symmetric(
                              horizontal: 10,
                              vertical: 10,
                            ),
                            border: const OutlineInputBorder(
                              borderRadius: BorderRadius.zero,
                              borderSide: BorderSide(color: Color(0xff44444a)),
                            ),
                            enabledBorder: const OutlineInputBorder(
                              borderRadius: BorderRadius.zero,
                              borderSide: BorderSide(color: Color(0xff44444a)),
                            ),
                            focusedBorder: const OutlineInputBorder(
                              borderRadius: BorderRadius.zero,
                              borderSide: BorderSide(color: Color(0xff666a74)),
                            ),
                          ),
                          onSubmitted: (value) => unawaited(
                            _saveProviderApiKey(providerName, value),
                          ),
                        ),
                      ),
                    ),
                    const SizedBox(width: 8),
                    SizedBox(
                      height: 34,
                      child: OutlinedButton.icon(
                        key: Key('provider-key-save-$widgetId'),
                        onPressed: _running
                            ? null
                            : () => unawaited(
                                _saveProviderApiKey(
                                  providerName,
                                  controller.text,
                                ).then((_) {
                                  if (mounted) refreshDialog(() {});
                                }),
                              ),
                        icon: const Icon(Icons.save_outlined, size: 15),
                        label: const Text('Save key'),
                      ),
                    ),
                    const SizedBox(width: 8),
                    SizedBox(
                      height: 34,
                      child: OutlinedButton.icon(
                        key: Key('provider-key-verify-$widgetId'),
                        onPressed: _running
                            ? null
                            : () => unawaited(
                                _liveVerifyProviderKey(providerName).then((_) {
                                  if (mounted) refreshDialog(() {});
                                }),
                              ),
                        icon: const Icon(
                          Icons.verified_user_outlined,
                          size: 15,
                        ),
                        label: const Text('Verify'),
                      ),
                    ),
                  ],
                ),
              );
            },
          ),
        ],
      ],
    );
  }

  Widget _providerFunctionalSetupPanel(
    String page, {
    required BuildContext dialogContext,
    required StateSetter refreshDialog,
  }) {
    final title = page
        .split('_')
        .map(
          (part) => part.isEmpty
              ? part
              : '${part[0].toUpperCase()}${part.substring(1)}',
        )
        .join(' ');
    Widget titleRow() => Text(
      title,
      style: const TextStyle(
        color: Color(0xfff0f0f4),
        fontSize: 16,
        fontWeight: FontWeight.w900,
      ),
    );

    return ListView(
      children: [
        titleRow(),
        const SizedBox(height: 14),
        if (page == 'model') ...[
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              _modelPickerButton(compact: false),
              _modelPickerButton(compact: false, creation: true),
              OutlinedButton.icon(
                onPressed: _showEditModelsDialog,
                icon: const Icon(Icons.edit, size: 17),
                label: const Text('Edit Models'),
              ),
            ],
          ),
          const SizedBox(height: 14),
          _macSettingLine(
            label: 'Chat route',
            value: _activeModelName,
            icon: Icons.chat_bubble_outline,
          ),
          _macSettingLine(
            label: 'Creation route',
            value: _creationModelName,
            icon: Icons.construction,
          ),
        ] else if (page == 'chat') ...[
          _modelPickerButton(compact: false),
          SwitchListTile(
            value: _thinkingEnabled,
