  Widget _homeSessionRail() {
    return Container(
      padding: const EdgeInsets.all(12),
      decoration: _panelDecoration(),
      child: SingleChildScrollView(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                const Icon(Icons.add_circle_outline, color: Color(0xff00e87a)),
                const SizedBox(width: 8),
                const Expanded(
                  child: Text(
                    'Engel Sessions',
                    style: TextStyle(fontWeight: FontWeight.w800),
                  ),
                ),
                IconButton(
                  onPressed: _running ? null : _clearChat,
                  icon: const Icon(Icons.add_comment_outlined, size: 18),
                  tooltip: 'New chat',
                ),
                IconButton(
                  onPressed: _running
                      ? null
                      : () => _runRust(
                          rustCommands.firstWhere(
                            (c) => c.key == 'local_chat_persistent_status',
                          ),
                        ),
                  icon: const Icon(Icons.refresh, size: 18),
                  tooltip: 'Refresh sessions',
                ),
              ],
            ),
            const SizedBox(height: 10),
            const TextField(
              decoration: InputDecoration(
                isDense: true,
                prefixIcon: Icon(Icons.search, size: 18),
                border: OutlineInputBorder(),
                hintText: 'Search sessions',
              ),
            ),
            const SizedBox(height: 12),
            _sessionButton(
              icon: Icons.chat_bubble_outline,
              title: 'Main Chat',
              subtitle: 'Local chat, tools, phones, Sub-Engels',
              selected: true,
              onTap: () => _selectSectionById('main'),
            ),
            _sessionButton(
              icon: Icons.groups_outlined,
              title: 'Meeting Room',
              subtitle: 'Orders and agent roster',
              onTap: () => _selectSectionById('meeting'),
            ),
            _sessionButton(
