  Widget _agentWorkReviewNotice() {
    if (!_agentWorkReviewPending) return const SizedBox.shrink();
    final textScale = _effectiveInterfaceTextScale;
    return Semantics(
      key: const Key('agent-work-review-banner'),
      container: true,
      label:
          'Task ready to start. Review or edit the goal below. Start task sends it to Engel\'s safe agent workflow.',
      child: Container(
        width: double.infinity,
        padding: const EdgeInsets.fromLTRB(12, 10, 8, 10),
        decoration: BoxDecoration(
          color: const Color(0xff102c35),
          borderRadius: BorderRadius.circular(8),
          border: Border.all(color: const Color(0xff00e5ff)),
        ),
        child: LayoutBuilder(
          builder: (context, constraints) {
            final compact = constraints.maxWidth < 620 || textScale > 1.4;
            final details = Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Padding(
                  padding: EdgeInsets.only(top: 2),
                  child: Icon(
                    Icons.task_alt_rounded,
                    color: Color(0xff00e5ff),
                    size: 20,
                  ),
                ),
                const SizedBox(width: 9),
                const Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'Task ready to start',
                        style: TextStyle(
                          color: Color(0xffe8fbff),
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      SizedBox(height: 2),
                      Text(
                        'Review or edit the goal below. Engel will plan safe steps and show proof.',
                        style: TextStyle(
                          color: Color(0xffb8d8df),
                          fontSize: 12.5,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            );
            final useAsChat = TextButton(
              key: const Key('agent-work-use-as-chat'),
              onPressed: () {
                setState(() {
                  _agentWorkReviewPending = false;
                  _agentTaskState = '';
                  _agentTaskGoal = '';
                  _agentTaskStatus = '';
                  _agentTaskProofPath = '';
                  _agentTaskProofDetails = '';
                  _status = 'Chat message ready to review';
                });
                _chatInputFocus.requestFocus();
              },
              child: const Text('Use as chat'),
            );
            if (compact) {
              return Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  details,
                  const SizedBox(height: 4),
                  Align(alignment: Alignment.centerRight, child: useAsChat),
                ],
              );
            }
            return Row(
              children: [
                Expanded(child: details),
                const SizedBox(width: 8),
                useAsChat,
              ],
            );
          },
        ),
      ),
    );
  }

  void _reviewAgentTaskAgain() {
    if (_running || _agentTaskGoal.trim().isEmpty) return;
    final goal = _agentTaskGoal.trim();
    setState(() {
      _agentWorkReviewPending = true;
      _agentTaskState = 'review';
      _agentTaskStatus = 'Ready for your review';
      _agentTaskProofPath = '';
      _agentTaskProofDetails = '';
      _chatDraft = goal;
      _chatText.value = TextEditingValue(
        text: goal,
        selection: TextSelection.collapsed(offset: goal.length),
      );
      _status = 'Task ready to review again';
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _chatInputFocus.requestFocus();
    });
  }

  Future<void> _showAgentTaskProofDetails() async {
    final details = _agentTaskProofDetails.trim().isEmpty
        ? 'No final task proof details were returned.'
        : _agentTaskProofDetails.trim();
    final receipt = _agentTaskProofPath.trim();
    await showDialog<void>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Task proof'),
        content: SizedBox(
          width: 620,
          child: SingleChildScrollView(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  _agentTaskState == 'success'
                      ? 'Engel marked this task complete.'
                      : 'Engel returned the following task record.',
                  style: const TextStyle(fontWeight: FontWeight.w800),
                ),
                const SizedBox(height: 12),
                SelectableText(details),
                const SizedBox(height: 14),
                Text(
                  receipt.isEmpty
                      ? 'No final agent receipt path was returned.'
                      : 'Receipt saved at:\n$receipt',
                  key: const Key('agent-task-proof-path'),
                  style: const TextStyle(
                    color: Color(0xffaebbd0),
                    fontFamily: 'Consolas',
                    fontSize: 12,
                  ),
                ),
              ],
            ),
          ),
        ),
        actions: [
          FilledButton(
            onPressed: () => Navigator.of(dialogContext).pop(),
            child: const Text('Done'),
          ),
        ],
      ),
    );
  }

  Widget _agentTaskStatusCard() {
    final state = _agentTaskState;
    if (state.isEmpty || state == 'review') return const SizedBox.shrink();
    final running = state == 'running';
    final success = state == 'success';
    final stopped = state == 'stopped';
    final color = running
        ? const Color(0xff00e5ff)
        : success
        ? const Color(0xff47df91)
        : stopped
        ? const Color(0xffffc857)
        : const Color(0xffff6b7a);
    final background = running
        ? const Color(0xff102c35)
        : success
        ? const Color(0xff102b20)
        : stopped
        ? const Color(0xff302817)
        : const Color(0xff341c24);
    final title = running
        ? 'Engel is working on your task'
        : success
        ? 'Task completed'
        : stopped
        ? 'Task stopped'
        : 'Task needs attention';
    final explanation = running
        ? 'Engel is choosing safe tools and recording proof. You can stop the task below.'
        : success
        ? 'Engel finished the task. Review the answer below or open the proof details.'
        : stopped
        ? 'Nothing else will run. Review the goal before trying again.'
        : 'Engel did not mark this task complete. Review the answer, then try again safely.';
    final proofButton = OutlinedButton.icon(
      key: const Key('agent-task-proof'),
      onPressed: () => unawaited(_showAgentTaskProofDetails()),
      icon: const Icon(Icons.verified_outlined, size: 18),
      label: const Text('Proof details'),
    );
    final retryButton = FilledButton.icon(
      key: const Key('agent-task-retry'),
      onPressed: _running ? null : _reviewAgentTaskAgain,
      icon: const Icon(Icons.replay_rounded, size: 18),
      label: const Text('Review and try again'),
    );
    return Semantics(
      key: const Key('agent-task-status-card'),
      container: true,
      liveRegion: true,
      label: '$title. $explanation',
      child: Container(
        width: double.infinity,
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: background,
          borderRadius: BorderRadius.circular(8),
          border: Border.all(color: color),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Icon(
                  running
                      ? Icons.pending_actions_rounded
                      : success
                      ? Icons.check_circle_outline_rounded
                      : stopped
                      ? Icons.stop_circle_outlined
                      : Icons.error_outline_rounded,
                  color: color,
                  size: 21,
                ),
                const SizedBox(width: 9),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        title,
                        style: TextStyle(
                          color: color,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(height: 3),
                      Text(
                        explanation,
                        style: const TextStyle(
                          color: Color(0xffd5e0eb),
                          fontSize: 12.5,
                        ),
                      ),
                      if (_agentTaskGoal.trim().isNotEmpty) ...[
                        const SizedBox(height: 5),
                        Text(
                          _agentTaskGoal.trim(),
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            color: Color(0xffaebbd0),
                            fontStyle: FontStyle.italic,
                          ),
                        ),
                      ],
                      if (!running && _agentTaskStatus.trim().isNotEmpty) ...[
                        const SizedBox(height: 5),
                        Text(
                          'Result: ${_agentTaskStatus.trim()}',
                          style: const TextStyle(
                            color: Color(0xffd5e0eb),
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ],
                    ],
                  ),
                ),
              ],
            ),
            if (running) ...[
              const SizedBox(height: 10),
              LinearProgressIndicator(
                key: const Key('agent-task-progress'),
                minHeight: 3,
                color: color,
                backgroundColor: const Color(0xff28434b),
              ),
            ] else ...[
              const SizedBox(height: 10),
              Wrap(
                spacing: 8,
                runSpacing: 8,
                children: [proofButton, if (!success) retryButton],
              ),
            ],
          ],
        ),
      ),
    );
  }

