  Widget _chatStillImageStrip(String imagePath, {String keyId = 'still'}) {
    final paths = imagePath
        .split('|')
        .map((item) => item.trim())
        .where((item) => item.isNotEmpty)
        .toList();
    if (paths.isEmpty) return const SizedBox.shrink();
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        for (var index = 0; index < paths.length; index++)
          Padding(
            padding: const EdgeInsets.only(top: 8),
            child: ClipRRect(
              borderRadius: BorderRadius.circular(8),
              child: ConstrainedBox(
                constraints: const BoxConstraints(
                  maxWidth: 460,
                  maxHeight: 460,
                ),
                child: Image.file(
                  File(paths[index]),
                  key: Key('chat-still-image-$keyId-$index'),
                  fit: BoxFit.contain,
                  errorBuilder: (_, _, _) => const SizedBox.shrink(),
                ),
              ),
            ),
          ),
      ],
    );
  }

  Widget _chatStillThumbnail(EngelChatAttachment item, {double size = 42}) {
    Widget fallback = Icon(
      _chatAttachmentIcon(item.kind),
      size: 17,
      color: const Color(0xff00e5ff),
    );
    Widget image = fallback;
    if (item.path.trim().isNotEmpty) {
      image = Image.file(
        File(item.path),
        width: size,
        height: size,
        fit: BoxFit.cover,
        errorBuilder: (_, _, _) => fallback,
      );
    } else if (item.inlineBase64.isNotEmpty) {
      try {
        image = Image.memory(
          base64Decode(item.inlineBase64),
          width: size,
          height: size,
          fit: BoxFit.cover,
          errorBuilder: (_, _, _) => fallback,
        );
      } catch (_) {
        image = fallback;
      }
    }
    return ClipRRect(
      borderRadius: BorderRadius.circular(6),
      child: SizedBox(width: size, height: size, child: image),
    );
  }

  Widget _chatAttachmentPill(EngelChatAttachment item) {
    return Container(
