  static const String _meetingEventStreamTool =
      '$appRoot\\tools\\engel_meeting_room_event_stream.py';
  static const String _meetingRoomStatePath =
      '$appRoot\\reports\\meeting_room_event_stream\\room_state.json';

  Future<void> _loadMeetingEventState() async {
    try {
      final file = File(_meetingRoomStatePath);
      if (!await file.exists()) {
        if (!mounted) return;
        setState(() => _meetingEventStatus = 'no state file yet — tap Refresh');
        return;
      }
      final parsed = jsonDecode(await file.readAsString());
      if (!mounted) return;
      setState(() {
        _meetingEventState = parsed is Map<String, dynamic> ? parsed : null;
        _meetingEventStatus = _meetingEventState == null
            ? 'state file unreadable'
            : 'loaded ${(_meetingEventState!['event_count'] ?? 0)} evidence-backed events';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() => _meetingEventStatus = 'load error: $error');
    }
  }

  Future<void> _refreshMeetingEventState() async {
    if (_running) return;
    setState(() => _meetingEventStatus = 'refreshing real work events…');
    try {
      // Snapshot re-projects the real receipts and rewrites room_state.json.
      await Process.run(runtimePythonExe, [
        _meetingEventStreamTool,
        'snapshot',
      ], workingDirectory: appRoot);
    } catch (_) {
      // Even if the refresh process fails, still try to read whatever exists.
    }
    await _loadMeetingEventState();
  }

