  Future<void> _loadSelfUpgradeLoopState() async {
    final client = HttpClient()..connectionTimeout = const Duration(seconds: 3);
    try {
      final request = await client.getUrl(
        Uri.parse(engelMainSelfUpgradeStatusUrl),
      );
      final response = await request.close().timeout(
        const Duration(seconds: 15),
      );
      final body = await response.transform(utf8.decoder).join();
      final parsed = jsonDecode(body);
      if (response.statusCode < 200 ||
          response.statusCode >= 300 ||
          parsed is! Map<String, dynamic> ||
          parsed['ok'] != true ||
          parsed['state'] is! Map) {
        throw HttpException(
          parsed is Map
              ? (parsed['error'] ?? parsed['status'] ?? 'CT246 status failed')
                    .toString()
              : 'CT246 status returned invalid JSON',
        );
      }
      final state = Map<String, dynamic>.from(parsed['state'] as Map);
      if (!mounted) return;
      setState(() {
        _selfUpgradeLoopState = state;
        _selfUpgradeLoopStatus =
            'CT246 live: ${((state['cycles'] as List?) ?? const []).length} governed cycles';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _selfUpgradeLoopState = null;
        _selfUpgradeLoopStatus = 'CT246 self-upgrade unavailable: $error';
      });
    } finally {
      client.close(force: true);
    }
  }

  Future<void> _refreshSelfUpgradeLoopState() async {
    if (_selfUpgradeBusy) return;
    setState(
      () => _selfUpgradeLoopStatus =
          'Refreshing CT246 governed self-upgrade state...',
    );
    await _loadSelfUpgradeLoopState();
  }

  Future<Map<String, dynamic>> _postSelfUpgradeJson(
    String url,
    Map<String, dynamic> payload, {
    Duration timeout = const Duration(minutes: 3),
  }) async {
    final client = HttpClient()..connectionTimeout = const Duration(seconds: 5);
    try {
      final request = await client.postUrl(Uri.parse(url));
      request.headers.contentType = ContentType.json;
      request.write(jsonEncode(payload));
      final response = await request.close().timeout(timeout);
      final body = await response.transform(utf8.decoder).join();
      final parsed = jsonDecode(body);
      if (parsed is! Map) {
        throw const FormatException('CT246 returned a non-object response');
      }
      final result = Map<String, dynamic>.from(parsed);
      if (response.statusCode < 200 ||
          response.statusCode >= 300 ||
          result['ok'] != true) {
        throw HttpException(
          (result['error'] ?? result['status'] ?? 'CT246 request failed')
              .toString(),
        );
      }
      return result;
    } finally {
      client.close(force: true);
    }
  }

  Future<void> _planSelfUpgrade() async {
    final requestText = _selfUpgradeRequestDraft.trim();
    if (requestText.length < 12 || _selfUpgradeBusy) return;
    setState(() {
      _selfUpgradeBusy = true;
      _selfUpgradeLoopStatus =
          'CT246 local coder is preparing a bounded patch candidate...';
    });
    try {
      final result = await _postSelfUpgradeJson(engelMainSelfUpgradePlanUrl, {
        'request_text': requestText,
        'source': 'engel_flutter_main',
        'actor': 'owner_joshua',
        'severity': 'medium',
      }, timeout: const Duration(minutes: 5));
      final cycleRequest = result['cycle_request'];
      if (cycleRequest is! Map) {
        throw const FormatException('CT246 plan has no cycle request');
      }
      if (!mounted) return;
      setState(() {
        _selfUpgradePlan = Map<String, dynamic>.from(cycleRequest);
        final files =
            (_selfUpgradePlan?['files_to_change'] as List?) ?? const [];
        final operations =
            (_selfUpgradePlan?['operations'] as List?) ?? const [];
        _selfUpgradeLoopStatus =
            'Local candidate ready: ${files.length} file(s), '
            '${operations.length} exact operation(s).';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() => _selfUpgradeLoopStatus = 'Local planning failed: $error');
    } finally {
      if (mounted) setState(() => _selfUpgradeBusy = false);
    }
  }

  Future<void> _runSelfUpgradeDryReview() async {
    final plan = _selfUpgradePlan;
    if (plan == null || _selfUpgradeBusy) return;
    setState(() {
      _selfUpgradeBusy = true;
      _selfUpgradeLoopStatus =
          'Dispatching bounded review to Alpha, Beta, Gamma, and Sub-Engel...';
    });
    try {
      final result = await _postSelfUpgradeJson(engelMainSelfUpgradeCycleUrl, {
        'cycle_request': plan,
        'execute': false,
        'actor': 'owner_joshua',
      }, timeout: const Duration(minutes: 12));
      if (!mounted) return;
      setState(() {
        _selfUpgradeLoopStatus =
            'Review cycle: ${result['final_status'] ?? 'recorded'}';
      });
      await _loadSelfUpgradeLoopState();
    } catch (error) {
      if (!mounted) return;
      setState(() => _selfUpgradeLoopStatus = 'Review cycle failed: $error');
    } finally {
      if (mounted) setState(() => _selfUpgradeBusy = false);
    }
  }

  Future<void> _showSelfUpgradeApprovalDialog() async {
    if (_selfUpgradePlan == null || _selfUpgradeBusy) return;
    final fix = TextEditingController();
    final gate = TextEditingController();
    final apply = TextEditingController();
    final tokens = await showDialog<Map<String, String>>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Approve governed source update'),
        content: SizedBox(
          width: 520,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              TextField(
                key: const Key('self-upgrade-fix-token'),
                controller: fix,
                decoration: const InputDecoration(
                  labelText: 'Fix approval token',
                ),
              ),
              const SizedBox(height: 8),
              TextField(
                key: const Key('self-upgrade-gate-token'),
                controller: gate,
                decoration: const InputDecoration(
                  labelText: 'Risk-matched gate token',
                ),
              ),
              const SizedBox(height: 8),
              TextField(
                key: const Key('self-upgrade-apply-token'),
                controller: apply,
                decoration: const InputDecoration(
                  labelText: 'Risk-matched apply token',
                ),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Cancel'),
          ),
          FilledButton.icon(
            key: const Key('self-upgrade-confirm-apply'),
            onPressed: () => Navigator.pop(dialogContext, {
              'fix': fix.text.trim(),
              'gate': gate.text.trim(),
              'apply': apply.text.trim(),
            }),
            icon: const Icon(Icons.verified_user_outlined, size: 17),
            label: const Text('Run approved cycle'),
          ),
        ],
      ),
    );
    fix.dispose();
    gate.dispose();
    apply.dispose();
    if (tokens == null) return;
    await _runApprovedSelfUpgrade(tokens);
  }

  Future<void> _runApprovedSelfUpgrade(Map<String, String> tokens) async {
    final plan = _selfUpgradePlan;
    if (plan == null || _selfUpgradeBusy) return;
    setState(() {
      _selfUpgradeBusy = true;
      _selfUpgradeLoopStatus =
          'Running approved CT246 cycle with verification and rollback...';
    });
    try {
      final result = await _postSelfUpgradeJson(engelMainSelfUpgradeCycleUrl, {
        'cycle_request': plan,
        'execute': true,
        'actor': 'owner_joshua',
        'fix_approval_token': tokens['fix'] ?? '',
        'gate_token': tokens['gate'] ?? '',
        'apply_token': tokens['apply'] ?? '',
      }, timeout: const Duration(minutes: 20));
      if (!mounted) return;
      setState(() {
        _selfUpgradeLoopStatus =
            'Approved cycle: ${result['final_status'] ?? 'recorded'}';
      });
      await _loadSelfUpgradeLoopState();
    } catch (error) {
      if (!mounted) return;
      setState(() => _selfUpgradeLoopStatus = 'Approved cycle stopped: $error');
    } finally {
      if (mounted) setState(() => _selfUpgradeBusy = false);
    }
  }

  Color _cycleStatusColor(String status) {
    if (status == 'upgraded_verified' || status == 'dry_run_complete') {
      return const Color(0xff5fd0a8);
    }
    if (status == 'applied_then_rolled_back') return const Color(0xffe5c07b);
    return const Color(0xffe06c75);
  }

  Color _pipeStatusColor(String status) {
    if (status == 'up') return const Color(0xff5fd0a8);
    if (status == 'down' || status == 'responding_not_ok') {
      return const Color(0xffe06c75);
    }
    return const Color(0xff6f8497);
  }

  Widget _selfUpgradeLoopPanel() {
    final state = _selfUpgradeLoopState;
    final cycles = (state?['cycles'] as List?) ?? const [];
    final pipes = (state?['pipes'] as List?) ?? const [];
    final issues = (state?['issues'] as Map?) ?? const {};
    final selfModel = (state?['self_model'] as Map?) ?? const {};
    final quorum = (state?['quorum'] as Map?) ?? const {};
    final postDeploy = (state?['post_deploy'] as Map?) ?? const {};
    final broker = (state?['broker'] as Map?) ?? const {};
    final goalCompletion =
        (state?['primary_goal_completion'] as Map?) ?? const {};
    return _macToolPanel(
      key: const Key('self-upgrade-loop-panel'),
      title: 'Self-Upgrade Loop (governed)',
      icon: Icons.autorenew,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
