      ),
    );
  }

  Widget _meetingOrderComposer({required int minLines, required int maxLines}) {
    final draft = _meetingDraft.trim();
    final canSend = draft.isNotEmpty && !_running;
    final status = _lastMeetingOrder.isNotEmpty
        ? 'Sent to all connected workers. See Chat for replies: $_lastMeetingOrder'
        : draft.isEmpty
        ? 'Describe a task for the Meeting Room workers.'
        : 'Draft ready: ${draft.length} characters - review before sending to all workers.';
    return Container(
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: const Color(0xff101821),
        borderRadius: BorderRadius.circular(7),
        border: Border.all(color: const Color(0xff263241)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          TextField(
            key: const Key('meeting-order-input'),
            controller: _meetingText,
            minLines: minLines,
            maxLines: maxLines,
            onChanged: (value) => setState(() => _meetingDraft = value),
            decoration: const InputDecoration(
              border: OutlineInputBorder(),
              hintText: 'Describe the task and the result you want',
            ),
          ),
          const SizedBox(height: 8),
          Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              Expanded(
                child: Text(
                  status,
                  key: const Key('meeting-order-status'),
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: Color(0xff8ba4bc),
                    fontSize: 11,
                    height: 1.2,
                  ),
                ),
              ),
              const SizedBox(width: 8),
              FilledButton.icon(
                key: const Key('send-meeting-order'),
                onPressed: canSend ? _confirmMeetingOrder : null,
                icon: const Icon(Icons.send, size: 16),
                label: const Text('Review and send'),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _chatBubble(
    String label,
    String text, {
    String? keyId,
    String imagePath = '',
  }) {
    final labelSlug = label
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '-')
        .replaceAll(RegExp(r'^-|-$'), '');
    final keySuffix = keyId ?? text.hashCode.toString();
    final isOperator = label == 'Operator' || label == 'Draft';
    final isLongReply = text.length > 1800 || '\n'.allMatches(text).length > 36;
    final body = SelectableText(text, style: const TextStyle(height: 1.3));
    return Container(
      key: ValueKey('chat-bubble-$labelSlug-$keySuffix'),
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: isOperator
            ? const Color(0xff10231c)
            : label == 'proof'
            ? const Color(0xff0e1b24)
            : const Color(0xff121a24),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(
          color: isOperator ? const Color(0xff1fa96b) : const Color(0xff263241),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            label.toUpperCase(),
            style: const TextStyle(
              color: Color(0xff58c4ff),
              fontSize: 11,
              fontWeight: FontWeight.w800,
            ),
          ),
          const SizedBox(height: 5),
          if (isLongReply)
            ConstrainedBox(
              constraints: const BoxConstraints(maxHeight: 420),
              child: SingleChildScrollView(child: body),
            )
          else
            body,
          if (imagePath.trim().isNotEmpty)
            _chatStillImageStrip(imagePath, keyId: keySuffix),
        ],
      ),
    );
  }

