  // OpenClaw voice port — speak a finished Engel reply aloud via SAPI
  // (tools/engel_voice.py). Detached + best-effort: never blocks or breaks a turn.
  Future<void> _speakEngelReply(String text) async {
    final clean = text.trim();
    if (clean.isEmpty) return;
    final py = File(runtimePythonExe);
    if (!py.existsSync()) return;
    try {
      await Process.start(
        py.path,
        [r'tools\engel_voice.py', 'speak', '--text', clean],
        workingDirectory: appRoot,
        mode: ProcessStartMode.detached,
      );
    } catch (_) {
      // Voice-out is optional; a failure here must never disrupt the chat.
    }
  }

  // OpenClaw Canvas port — write a welcome doc, start the canvas HTTP server
  // (idempotent; a second bind just exits), then open it in the browser.
  Future<void> _openEngelCanvas() async {
    final py = File(runtimePythonExe);
    if (!py.existsSync()) {
      if (mounted && !_chatRunning) {
        setState(() => _status = 'canvas: runtime python not found');
      }
      return;
    }
    try {
      await Process.run(py.path, [
        r'tools\engel_canvas.py',
        'write',
        '--name',
        'welcome',
        '--kind',
        'markdown',
        '--content',
        '# Engel Canvas\n\nAgent-driven visual workspace (OpenClaw Canvas port). '
            'Engel writes HTML/Markdown here with `tools/engel_canvas.py write`. '
            'Canvas render is not proven live.',
      ], workingDirectory: appRoot);
      await Process.start(
        py.path,
        [r'tools\engel_canvas.py', 'serve', '--port', '8791'],
        workingDirectory: appRoot,
        mode: ProcessStartMode.detached,
      );
      await Future<void>.delayed(const Duration(milliseconds: 700));
      await Process.start('cmd', [
        '/c',
        'start',
        '',
        'http://127.0.0.1:8791/',
      ], mode: ProcessStartMode.detached);
      // (2026-07-07 audit F-2) don't clobber the live chat status line.
      if (mounted && !_chatRunning) {
        setState(() => _status = 'canvas start requested; not proven live');
      }
    } catch (e) {
      if (mounted && !_chatRunning) {
        setState(() => _status = 'canvas failed: $e');
      }
    }
  }

  Future<void> _openGraphLoopStudio({String newTitle = ''}) async {
    final studioRoot = r'D:\Graph_&_Loop_Studio';
    final pyw = File(
      '$studioRoot${Platform.pathSeparator}runtime${Platform.pathSeparator}python310${Platform.pathSeparator}pythonw.exe',
    );
    final pyFallback = File(
      runtimePythonExe.replaceAll('python.exe', 'pythonw.exe'),
    );
    final script = File(
      '$studioRoot${Platform.pathSeparator}engel_graph_loop_studio.py',
    );
    final packagedCandidates = <File>[
      File(
        '$studioRoot${Platform.pathSeparator}release-staged${Platform.pathSeparator}graph-loop-studio-1.8.5-tester${Platform.pathSeparator}dist${Platform.pathSeparator}EngelGraphLoopStudio${Platform.pathSeparator}EngelGraphLoopStudio.exe',
      ),
      File(
        '$appRoot${Platform.pathSeparator}EngelGraphLoopStudio${Platform.pathSeparator}EngelGraphLoopStudio.exe',
      ),
      File('$appRoot${Platform.pathSeparator}EngelGraphLoopStudio.exe'),
    ];
    final packaged = packagedCandidates
        .where((file) => file.existsSync())
        .firstOrNull;
    final python = pyw.existsSync()
        ? pyw
        : (pyFallback.existsSync() ? pyFallback : File(runtimePythonExe));
    if (packaged == null && (!python.existsSync() || !script.existsSync())) {
      if (mounted && !_chatRunning) {
        setState(() => _status = 'Graph & Loop Studio files are missing');
      }
      return;
    }
    try {
      final args = <String>['--profile', 'standalone'];
      if (newTitle.trim().isNotEmpty) {
        args.addAll(['--new', newTitle.trim()]);
      }
      await Process.start(
        packaged?.path ?? python.path,
        packaged == null ? <String>[script.path, ...args] : args,
        workingDirectory: packaged?.parent.path ?? studioRoot,
        mode: ProcessStartMode.detached,
      );
      if (mounted && !_chatRunning) {
        setState(
          () => _status = newTitle.trim().isEmpty
              ? 'Graph & Loop Studio opening'
              : 'New Engel graph opening: ${newTitle.trim()}',
        );
      }
    } catch (error) {
      if (mounted && !_chatRunning) {
        setState(() => _status = 'Graph & Loop Studio failed: $error');
      }
    }
  }

  // OpenClaw voice port — dedicated LIVE Voice panel. Push-to-talk records the
  // microphone (tools/engel_voice.py listen: sounddevice -> STT -> failover chat
  // -> SAPI speak) and shows what Engel HEARD and REPLIED. Distinct from the
  // volume toggle, which only speaks typed-chat answers.
  Future<void> _openVoicePanel() async {
    final py = File(runtimePythonExe);
    if (!py.existsSync()) {
      if (mounted) setState(() => _status = 'voice: runtime python not found');
      return;
    }
    await showDialog<void>(
      context: context,
      builder: (ctx) {
        var seconds = 5.0;
        var busy = false;
        var heard = '';
        var reply = '';
        var note =
            'Tap “Listen & reply”, then speak. Engel transcribes, answers, and speaks back.';
        return StatefulBuilder(
          builder: (ctx, setLocal) {
            Future<void> doListen() async {
              setLocal(() {
                busy = true;
                heard = '';
                reply = '';
                note = 'Listening for ${seconds.round()}s — speak now…';
              });
              try {
                final res = await Process.run(py.path, [
                  r'tools\engel_voice.py',
                  'listen',
                  '--seconds',
                  seconds.round().toString(),
                ], workingDirectory: appRoot);
                final out = (res.stdout ?? '').toString();
                final start = out.indexOf('{');
                var data = <String, dynamic>{};
                if (start >= 0) {
                  try {
                    data =
                        jsonDecode(out.substring(start))
                            as Map<String, dynamic>;
                  } catch (_) {}
                }
                if (data['ok'] == true) {
                  setLocal(() {
                    heard = (data['heard'] ?? '').toString();
                    reply = (data['reply'] ?? '').toString();
                    note = 'Answered via ${data['provider'] ?? 'Engel'}.';
                  });
                } else {
                  setLocal(
                    () => note =
                        'Voice turn failed: ${data['error'] ?? data['stage'] ?? 'no speech detected'}',
                  );
                }
              } catch (e) {
                setLocal(() => note = 'Voice error: $e');
              } finally {
                setLocal(() => busy = false);
              }
            }

            return AlertDialog(
              backgroundColor: const Color(0xff1a1f2e),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(14),
                side: const BorderSide(color: Color(0xff2f3a52)),
              ),
              title: Row(
                mainAxisSize: MainAxisSize.min,
                children: const [
                  Icon(Icons.mic, color: Color(0xff00e87a)),
                  SizedBox(width: 8),
                  Text(
                    'Engel Voice',
                    style: TextStyle(color: Color(0xfff7f7fb)),
                  ),
                ],
              ),
              content: SizedBox(
                width: 420,
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Row(
                      children: [
                        const Text(
                          'Listen',
                          style: TextStyle(color: Color(0xff8ba4bc)),
                        ),
                        Expanded(
                          child: Slider(
                            value: seconds,
                            min: 3,
                            max: 12,
                            divisions: 9,
                            activeColor: const Color(0xff00e87a),
                            label: '${seconds.round()}s',
                            onChanged: busy
                                ? null
                                : (v) => setLocal(() => seconds = v),
                          ),
                        ),
                        Text(
                          '${seconds.round()}s',
                          style: const TextStyle(color: Color(0xfff7f7fb)),
                        ),
                      ],
                    ),
                    const SizedBox(height: 6),
                    ElevatedButton.icon(
                      onPressed: busy ? null : doListen,
                      icon: busy
                          ? const SizedBox(
                              width: 16,
                              height: 16,
                              child: CircularProgressIndicator(strokeWidth: 2),
                            )
                          : const Icon(Icons.hearing),
                      label: Text(busy ? 'Listening…' : 'Listen & reply'),
                      style: ElevatedButton.styleFrom(
                        backgroundColor: const Color(0xff00e87a),
                        foregroundColor: Colors.black,
                      ),
                    ),
                    const SizedBox(height: 14),
                    if (heard.isNotEmpty) ...[
                      const Text(
                        'You said',
                        style: TextStyle(
                          color: Color(0xff8ba4bc),
                          fontSize: 12,
                        ),
                      ),
                      Text(
                        heard,
                        style: const TextStyle(color: Color(0xfff7f7fb)),
                      ),
                      const SizedBox(height: 10),
                    ],
                    if (reply.isNotEmpty) ...[
                      const Text(
                        'Engel',
                        style: TextStyle(
                          color: Color(0xff00e87a),
                          fontSize: 12,
                        ),
                      ),
                      Text(
                        reply,
                        style: const TextStyle(color: Color(0xfff7f7fb)),
                      ),
                      const SizedBox(height: 10),
                    ],
                    Text(
                      note,
                      style: const TextStyle(
                        color: Color(0xff8ba4bc),
                        fontSize: 12,
                      ),
                    ),
                    const SizedBox(height: 6),
                    Row(
                      children: [
                        const Icon(
                          Icons.volume_up,
                          size: 15,
                          color: Color(0xff8ba4bc),
                        ),
                        const SizedBox(width: 6),
                        Expanded(
                          child: Text(
                            _voiceReplies
                                ? 'Auto-speak typed replies: ON'
                                : 'Auto-speak typed replies: OFF',
                            style: const TextStyle(
                              color: Color(0xff8ba4bc),
                              fontSize: 12,
                            ),
                          ),
                        ),
                        Switch(
                          value: _voiceReplies,
                          activeThumbColor: const Color(0xff00e87a),
                          onChanged: (v) {
                            setState(() => _voiceReplies = v);
                            setLocal(() {});
                          },
                        ),
                      ],
                    ),
                  ],
                ),
              ),
              actions: [
                TextButton(
                  onPressed: busy ? null : () => Navigator.of(ctx).pop(),
                  child: const Text('Close'),
                ),
              ],
            );
          },
        );
      },
    );
  }

  // OpenClaw Canvas port — dedicated Canvas panel. Write a titled HTML/Markdown
  // doc into the canvas (tools/engel_canvas.py write) and/or open the live
  // canvas server, instead of the one-shot open button.
  Future<void> _openCanvasPanel() async {
    final py = File(runtimePythonExe);
    if (!py.existsSync()) {
      if (mounted) setState(() => _status = 'canvas: runtime python not found');
      return;
    }
    final nameCtl = TextEditingController(text: 'note');
    final bodyCtl = TextEditingController();
    await showDialog<void>(
      context: context,
      builder: (ctx) {
        var busy = false;
        var kind = 'markdown';
        var note =
            'Canvas is not proven live. Write a doc, or try to open the canvas server.';
        return StatefulBuilder(
          builder: (ctx, setLocal) {
            Future<void> writeDoc() async {
              final nm = nameCtl.text.trim().isEmpty
                  ? 'note'
                  : nameCtl.text.trim();
              if (bodyCtl.text.trim().isEmpty) {
                setLocal(() => note = 'Type some content first.');
                return;
              }
              setLocal(() {
                busy = true;
                note = 'Writing “$nm”…';
              });
              try {
                await Process.run(py.path, [
                  r'tools\engel_canvas.py',
                  'write',
                  '--name',
                  nm,
                  '--kind',
                  kind,
                  '--content',
                  bodyCtl.text,
                ], workingDirectory: appRoot);
                setLocal(
                  () =>
                      note = 'Wrote “$nm” ($kind). Open the canvas to view it.',
                );
              } catch (e) {
                setLocal(() => note = 'Write failed: $e');
              } finally {
                setLocal(() => busy = false);
              }
            }

            return AlertDialog(
              backgroundColor: const Color(0xff1a1f2e),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(14),
                side: const BorderSide(color: Color(0xff2f3a52)),
              ),
              title: Row(
                mainAxisSize: MainAxisSize.min,
                children: const [
                  Icon(Icons.brush, color: Color(0xff00e87a)),
                  SizedBox(width: 8),
                  Text(
                    'Engel Canvas',
                    style: TextStyle(color: Color(0xfff7f7fb)),
                  ),
                ],
              ),
              content: SizedBox(
                width: 440,
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: nameCtl,
                            style: const TextStyle(color: Color(0xfff7f7fb)),
                            decoration: const InputDecoration(
                              labelText: 'Doc name',
                              labelStyle: TextStyle(color: Color(0xff8ba4bc)),
                            ),
                          ),
                        ),
                        const SizedBox(width: 12),
                        DropdownButton<String>(
                          value: kind,
                          dropdownColor: const Color(0xff1a1f2e),
                          items: const [
                            DropdownMenuItem(
                              value: 'markdown',
                              child: Text(
                                'Markdown',
                                style: TextStyle(color: Color(0xfff7f7fb)),
                              ),
                            ),
                            DropdownMenuItem(
                              value: 'html',
                              child: Text(
                                'HTML',
                                style: TextStyle(color: Color(0xfff7f7fb)),
                              ),
                            ),
                          ],
                          onChanged: busy
                              ? null
                              : (v) => setLocal(() => kind = v ?? 'markdown'),
                        ),
                      ],
                    ),
                    const SizedBox(height: 8),
                    TextField(
                      controller: bodyCtl,
                      maxLines: 6,
                      style: const TextStyle(color: Color(0xfff7f7fb)),
                      decoration: const InputDecoration(
                        labelText: 'Content',
                        alignLabelWithHint: true,
                        labelStyle: TextStyle(color: Color(0xff8ba4bc)),
                      ),
                    ),
                    const SizedBox(height: 12),
                    Row(
                      children: [
                        ElevatedButton.icon(
                          onPressed: busy ? null : writeDoc,
                          icon: const Icon(Icons.save),
                          label: const Text('Write doc'),
                          style: ElevatedButton.styleFrom(
                            backgroundColor: const Color(0xff263241),
                            foregroundColor: const Color(0xfff7f7fb),
                          ),
                        ),
                        const SizedBox(width: 10),
                        ElevatedButton.icon(
                          onPressed: busy
                              ? null
                              : () => unawaited(_openEngelCanvas()),
                          icon: const Icon(Icons.open_in_browser),
                          label: const Text('Open canvas'),
                          style: ElevatedButton.styleFrom(
                            backgroundColor: const Color(0xff00e87a),
                            foregroundColor: Colors.black,
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 12),
                    Text(
                      note,
                      style: const TextStyle(
                        color: Color(0xff8ba4bc),
                        fontSize: 12,
                      ),
                    ),
                  ],
                ),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.of(ctx).pop(),
                  child: const Text('Close'),
                ),
              ],
            );
          },
        );
      },
    );
  }

  Widget _buildPreviewPanel() {
    final preview = _buildPreview;
    if (preview == null) return const SizedBox.shrink();
    final screenshot = preview.screenshotPath.isEmpty
        ? null
        : File(preview.screenshotPath);
    return Container(
      key: const Key('engel-build-preview-panel'),
      decoration: BoxDecoration(
        color: const Color(0xff11131b),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: const Color(0xff344158)),
        boxShadow: const [
          BoxShadow(
            color: Color(0x66000000),
            blurRadius: 22,
            offset: Offset(-6, 8),
          ),
        ],
      ),
      child: DefaultTabController(
        length: 3,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(14, 12, 8, 6),
              child: Row(
                children: [
