  Widget _chatComposerControls({
    required bool canSendChat,
    required bool isReviewingAgentWork,
    required bool largeTextLayout,
    required double textScale,
  }) {
    final largeControlHeight = textScale > 1.8 ? 80.0 : 72.0;
    final attachButton = SizedBox(
      width: largeTextLayout ? 176 : 116,
      height: largeTextLayout ? largeControlHeight : 44,
      child: OutlinedButton.icon(
        key: const Key('engel-chat-attach'),
        onPressed: _running ? null : () => unawaited(_pickChatAttachments()),
        icon: const Icon(Icons.attach_file, size: 18),
        label: const Text('Attach'),
        style: OutlinedButton.styleFrom(
          foregroundColor: const Color(0xff00e5ff),
          side: const BorderSide(color: Color(0xff00e5ff)),
          padding: const EdgeInsets.symmetric(horizontal: 10),
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(8)),
        ),
      ),
    );
    final folderButton = SizedBox(
      width: largeTextLayout ? 176 : 116,
      height: largeTextLayout ? largeControlHeight : 44,
      child: OutlinedButton.icon(
        key: const Key('engel-chat-folder-context'),
        onPressed: _running ? null : () => unawaited(_pickChatFolder()),
        icon: const Icon(Icons.create_new_folder_outlined, size: 18),
        label: const Text('Folder'),
        style: OutlinedButton.styleFrom(
          foregroundColor: const Color(0xffd5deeb),
          side: const BorderSide(color: Color(0xff4a5c79)),
          padding: const EdgeInsets.symmetric(horizontal: 10),
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(8)),
        ),
      ),
    );
    final toolbar = Row(
      mainAxisSize: MainAxisSize.min,
      children: [attachButton, const SizedBox(width: 8), folderButton],
    );
    final input = Focus(
      onKeyEvent: (node, event) {
        if (event is KeyDownEvent &&
            (event.logicalKey == LogicalKeyboardKey.enter ||
                event.logicalKey == LogicalKeyboardKey.numpadEnter) &&
            !HardwareKeyboard.instance.isShiftPressed) {
          if (canSendChat) _submitChatDraft();
          return KeyEventResult.handled;
        }
        return KeyEventResult.ignored;
      },
      child: TextField(
        key: const Key('engel-chat-input'),
        controller: _chatText,
        focusNode: _chatInputFocus,
        minLines: 1,
        maxLines: 4,
        contextMenuBuilder: _chatTextContextMenu,
        onChanged: (value) => setState(() => _chatDraft = value),
        onSubmitted: (_) => _submitChatDraft(),
        decoration: InputDecoration(
          hintText: isReviewingAgentWork
              ? 'Describe the result you want…'
              : 'Message Engel…',
          filled: false,
          border: InputBorder.none,
        ),
        style: const TextStyle(color: Color(0xfff7f7fb), fontSize: 18),
      ),
    );
    final actionButton = SizedBox(
      width: largeTextLayout
          ? double.infinity
          : isReviewingAgentWork || _chatRunning
          ? 188
          : 108,
      height: largeTextLayout ? largeControlHeight : 44,
      child: _chatRunning
          ? FilledButton(
              key: const Key('engel-chat-stop'),
              onPressed: _stopChat,
              style: FilledButton.styleFrom(
                padding: EdgeInsets.zero,
                backgroundColor: const Color(0xffb23246),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(22),
                ),
              ),
              child: const Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Icon(Icons.stop, color: Colors.white, size: 18),
                  SizedBox(width: 4),
                  Text('Stop'),
                ],
              ),
            )
          : FilledButton(
              key: const Key('engel-chat-send'),
              onPressed: canSendChat && !_running ? _submitChatDraft : null,
              style: FilledButton.styleFrom(
                padding: EdgeInsets.zero,
                backgroundColor: const Color(0xff00e5ff),
                disabledBackgroundColor: const Color(0xff565762),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(22),
                ),
              ),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Icon(
                    isReviewingAgentWork
                        ? Icons.play_arrow_rounded
                        : Icons.send,
                    color: const Color(0xff02060f),
                    size: 18,
                  ),
                  const SizedBox(width: 5),
                  Text(
                    isReviewingAgentWork ? 'Start task' : 'Send',
                    style: const TextStyle(
                      color: Color(0xff02060f),
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ],
              ),
            ),
    );
    if (largeTextLayout) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            child: toolbar,
          ),
          const SizedBox(height: 8),
          input,
          const SizedBox(height: 8),
          actionButton,
        ],
      );
    }
    return Row(
      children: [
        toolbar,
        const SizedBox(width: 6),
        Expanded(child: input),
        actionButton,
      ],
    );
  }

  Widget _chatRuntimePage() {
    final hasTypedDraft = _chatDraft.trim().isNotEmpty;
    final canSendChat = hasTypedDraft || _chatAttachments.isNotEmpty;
    final hasLastDraft = _lastChatDraft.trim().isNotEmpty;
    final isReviewingAgentWork = _agentWorkReviewPending;
    final textScale = _effectiveInterfaceTextScale;
    final largeTextLayout = textScale > 1.4;
    final compactChatHeight = MediaQuery.sizeOf(context).height < 700;
    bool hideTaskRuntimeMessage(List<String> message) {
      if (_agentTaskState != 'running' || message.isEmpty) return false;
      return const {
        'Thinking',
        'Engel Runtime',
        'Engel Thinking',
        'Engel Status',
      }.contains(message.first);
    }

    final chatThread = ListView(
      key: const Key('engel-chat-thread'),
      controller: _chatScroll,
      padding: const EdgeInsets.fromLTRB(12, 10, 12, 10),
      children: [
        if (_chatMessages.isEmpty) ...[
          _macChatBubble(
            text: 'Hello Joshua,\nhow can Engel assist you today?',
            incoming: true,
            keyId: 'intro',
          ),
          // (2026-07-12 Joshua) the blank 'empty' placeholder bubble read as a
          // BROKEN message on the fresh chat page — removed; tests updated.
        ],
        if (_chatMessages.isEmpty && hasLastDraft)
          _macChatBubble(
            text: _lastChatDraft.trim(),
            incoming: false,
            keyId: 'last-draft',
          ),
        for (var index = 0; index < _chatMessages.length; index++)
          if (!hideTaskRuntimeMessage(_chatMessages[index]))
            _macChatMessage(
              _chatMessages[index],
              keyId: 'thread-$index',
              announce: !_chatRunning && index == _chatMessages.length - 1,
            ),
      ],
    );
    final chatColumn = Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Row(
          children: [
            const Expanded(
              child: Text(
                'Chat with Engel',
                style: TextStyle(
                  color: EngelLiquidGlass.textPrimary,
                  fontSize: 20,
                  fontWeight: FontWeight.w800,
                  letterSpacing: -0.2,
                ),
              ),
            ),
            IconButton(
              key: const Key('chat-new-chat'),
              tooltip: 'New chat',
              onPressed: () => unawaited(_startNewChat()),
              icon: const Icon(Icons.add_comment_outlined, size: 20),
            ),
            IconButton(
              key: const Key('chat-talk'),
              tooltip: 'Talk',
              onPressed: () => unawaited(_openVoicePanel()),
              icon: const Icon(Icons.mic_none_rounded, size: 20),
            ),
            IconButton(
              key: const Key('chat-tools-button'),
              tooltip: 'Chat tools',
              onPressed: _showChatToolsDialog,
              icon: const Icon(Icons.tune_rounded, size: 20),
            ),
          ],
        ),
        if (_otherWorkRunning) ...[
          const SizedBox(height: 8),
          _otherWorkNotice('chat-other-work-notice'),
        ],
        if (isReviewingAgentWork) ...[
          const SizedBox(height: 8),
          _agentWorkReviewNotice(),
        ],
        if (_agentTaskState.isNotEmpty && _agentTaskState != 'review') ...[
          const SizedBox(height: 8),
          _agentTaskStatusCard(),
        ],
        if (_agentTaskState != 'running') _chatRunningNotice(),
        if (_chatTokenUsage != null) ...[
          const SizedBox(height: 8),
          TokenUsageWarning.fromSnapshot(_chatTokenUsage!),
        ],
        SizedBox(height: compactChatHeight ? 6 : 10),
        if (largeTextLayout)
          SizedBox(height: 260, child: chatThread)
        else
          Expanded(child: chatThread),
        const SizedBox(height: 10),
        Container(
          key: const Key('engel-chat-composer'),
          padding: const EdgeInsets.fromLTRB(12, 6, 6, 6),
          decoration: BoxDecoration(
            color: EngelLiquidGlass.surface,
            borderRadius: BorderRadius.circular(EngelLiquidGlass.radiusSm),
            border: Border.all(color: EngelLiquidGlass.rimStrong),
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              if (_chatAttachments.isNotEmpty) ...[
                _chatAttachmentTray(),
                const SizedBox(height: 8),
              ],
              _chatComposerControls(
                canSendChat: canSendChat,
                isReviewingAgentWork: isReviewingAgentWork,
                largeTextLayout: largeTextLayout,
                textScale: textScale,
              ),
              if (!compactChatHeight) ...[
                const SizedBox(height: 2),
                const Align(
                  alignment: Alignment.centerRight,
                  child: Text(
                    'Enter to send  •  Shift+Enter for a new line',
                    style: TextStyle(
                      color: EngelLiquidGlass.textMuted,
                      fontSize: 11,
                    ),
                  ),
                ),
              ],
            ],
          ),
        ),
      ],
    );
    final Widget chatPane = largeTextLayout
        ? SingleChildScrollView(
            key: const Key('engel-chat-large-text-scroll'),
            child: chatColumn,
          )
        : chatColumn;
    return _PageFrame(
      child: LayoutBuilder(
        builder: (context, constraints) {
          if (!_buildPreviewVisible || _buildPreview == null) return chatPane;
          final compact = constraints.maxWidth < 980;
          final panelWidth = (constraints.maxWidth * (compact ? 0.82 : 0.4))
              .clamp(340.0, 540.0)
              .toDouble();
          if (compact) {
            return Stack(
              children: [
                Positioned.fill(child: chatPane),
                Positioned(
                  top: 0,
                  right: 0,
                  bottom: 0,
                  width: panelWidth,
                  child: _buildPreviewPanel(),
                ),
              ],
            );
          }
          return Row(
            children: [
              Expanded(child: chatPane),
              const SizedBox(width: 12),
              SizedBox(width: panelWidth, child: _buildPreviewPanel()),
            ],
          );
        },
      ),
    );
  }

  Widget _macChatMessage(
    List<String> message, {
    required String keyId,
    bool announce = false,
  }) {
    final role = message.isNotEmpty ? message.first : '';
    final text = message.length > 1 ? message[1] : '';
    final imagePath = message.length > 2 ? message[2] : '';
    if (text.trim().isEmpty && imagePath.trim().isEmpty) {
      return const SizedBox.shrink();
    }
    if (role == 'Thinking' ||
        role == 'Engel Runtime' ||
        role == 'Engel Thinking' ||
        role == 'Engel Status') {
      return _macChatRuntimeStatus(text: text, keyId: keyId);
    }
    final bubble = _macChatBubble(
      text: text,
      incoming: role != 'Operator' && role != 'Draft',
      keyId: keyId,
      announce: announce,
    );
    if (imagePath.trim().isEmpty) return bubble;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        bubble,
        Padding(
          padding: const EdgeInsets.only(left: 8, bottom: 8),
          child: _chatStillImageStrip(imagePath, keyId: keyId),
        ),
      ],
    );
  }

  Widget _macChatRuntimeStatus({required String text, required String keyId}) {
    final lines = text.split('\n');
    final first = lines.isEmpty ? '' : lines.first.trim();
    final rest = lines.skip(1).join('\n').trim();
    final detail =
        (first == 'Engel runtime' || first.startsWith('Engel runtime')) &&
            rest.isNotEmpty
        ? rest
        : text;
    return Padding(
      key: ValueKey('mac-chat-status-$keyId'),
      padding: const EdgeInsets.only(left: 8, bottom: 16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text(
            'Engel runtime',
            style: TextStyle(
              color: Color(0xff8e96a8),
              fontSize: 13,
              fontWeight: FontWeight.w700,
            ),
          ),
          const SizedBox(height: 7),
          Container(
            constraints: const BoxConstraints(maxWidth: 560),
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
            decoration: BoxDecoration(
              color: const Color(0xff242632),
              borderRadius: BorderRadius.circular(8),
              border: Border.all(color: const Color(0xff333847)),
            ),
            child: SelectableText(
              detail,
              style: const TextStyle(
                color: Color(0xffd4d9e6),
                fontSize: 13,
                height: 1.35,
                fontWeight: FontWeight.w600,
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _macChatBubble({
    required String text,
    required bool incoming,
    required String keyId,
    bool announce = false,
  }) {
    final radius = BorderRadius.only(
      topLeft: const Radius.circular(20),
      topRight: const Radius.circular(20),
      bottomLeft: Radius.circular(incoming ? 4 : 20),
      bottomRight: Radius.circular(incoming ? 20 : 4),
    );
    return Semantics(
      key: ValueKey('mac-chat-semantics-$keyId'),
      container: true,
      liveRegion: announce,
      label: incoming ? 'Engel says: $text' : 'You said: $text',
      child: Align(
        alignment: incoming ? Alignment.centerLeft : Alignment.centerRight,
        child: Container(
          key: ValueKey('mac-chat-bubble-$keyId'),
          width: text.isEmpty ? 360 : null,
          constraints: const BoxConstraints(maxWidth: 430, minHeight: 62),
          margin: const EdgeInsets.only(bottom: 16),
          padding: const EdgeInsets.symmetric(horizontal: 22, vertical: 16),
          decoration: BoxDecoration(
            color: incoming
                ? EngelLiquidGlass.surfaceElevated
                : EngelLiquidGlass.accent.withValues(alpha: 0.88),
            borderRadius: radius,
            border: Border.all(
              color: incoming
                  ? EngelLiquidGlass.rim
                  : EngelLiquidGlass.accentStrong.withValues(alpha: 0.55),
            ),
          ),
          child: text.isEmpty
              ? const SizedBox.shrink()
              : ExcludeSemantics(
                  child: SelectableText(
                    text,
                    style: TextStyle(
                      color: incoming
                          ? EngelLiquidGlass.textPrimary
                          : EngelLiquidGlass.accentOn,
                      fontSize: 16,
                      height: 1.3,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ),
        ),
      ),
    );
  }

  Color get _connectionDoctorColor => switch (_connectionDoctorPhase) {
    _ConnectionDoctorPhase.checking ||
    _ConnectionDoctorPhase.repairing => const Color(0xff00e5ff),
    _ConnectionDoctorPhase.ready ||
    _ConnectionDoctorPhase.repaired => const Color(0xff18f28f),
    _ConnectionDoctorPhase.readyWithNotice => const Color(0xffffc857),
    _ConnectionDoctorPhase.partial => const Color(0xffffc857),
    _ConnectionDoctorPhase.setupRequired => const Color(0xffffc857),
    _ConnectionDoctorPhase.serverUnavailable => const Color(0xffff6b6b),
    _ConnectionDoctorPhase.repairFailed ||
    _ConnectionDoctorPhase.failure => const Color(0xffff6b6b),
    _ConnectionDoctorPhase.idle =>
      _mainServerOnline == false
          ? const Color(0xffffc857)
          : const Color(0xff00e5ff),
  };

  IconData get _connectionDoctorIcon => switch (_connectionDoctorPhase) {
    _ConnectionDoctorPhase.checking => Icons.manage_search,
    _ConnectionDoctorPhase.repairing => Icons.build_circle_outlined,
    _ConnectionDoctorPhase.ready ||
    _ConnectionDoctorPhase.repaired => Icons.check_circle_outline,
    _ConnectionDoctorPhase.readyWithNotice => Icons.info_outline,
    _ConnectionDoctorPhase.partial => Icons.warning_amber_rounded,
    _ConnectionDoctorPhase.setupRequired => Icons.vpn_key_outlined,
    _ConnectionDoctorPhase.serverUnavailable => Icons.cloud_off_outlined,
    _ConnectionDoctorPhase.repairFailed ||
    _ConnectionDoctorPhase.failure => Icons.error_outline,
    _ConnectionDoctorPhase.idle => Icons.health_and_safety_outlined,
  };

  Widget _connectionDoctorServiceRow({
    required Key key,
    required String name,
    required String description,
    required IconData icon,
    required bool? online,
    required bool busy,
  }) {
    final status = _connectionDoctorServiceText(online, busy: busy);
    final color = busy
        ? const Color(0xff00e5ff)
        : online == true
        ? const Color(0xff18f28f)
        : online == false
        ? const Color(0xffff6b6b)
        : const Color(0xffaebbd0);
    return Semantics(
      container: true,
      excludeSemantics: true,
      label: '$name status: $status. $description',
      child: Container(
        key: key,
        constraints: const BoxConstraints(minHeight: 56),
        margin: const EdgeInsets.only(bottom: 8),
        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
        decoration: BoxDecoration(
          color: const Color(0xff171821),
          borderRadius: BorderRadius.circular(8),
          border: Border.all(color: const Color(0xff343746)),
        ),
        child: Row(
          children: [
            Icon(icon, color: color, size: 22),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    name,
                    style: const TextStyle(
                      color: Color(0xfff7f7fb),
                      fontWeight: FontWeight.w800,
                    ),
                  ),
