  Widget _connectionDoctorActions() {
    final checking = _connectionDoctorPhase == _ConnectionDoctorPhase.checking;
    final repairing =
        _connectionDoctorPhase == _ConnectionDoctorPhase.repairing;
    final connected =
        _connectionDoctorPhase == _ConnectionDoctorPhase.ready ||
        _connectionDoctorPhase == _ConnectionDoctorPhase.readyWithNotice ||
        _connectionDoctorPhase == _ConnectionDoctorPhase.repaired;
    final repairRecommended =
        _connectionDoctorPhase == _ConnectionDoctorPhase.partial ||
        _connectionDoctorPhase == _ConnectionDoctorPhase.repairFailed ||
        (_connectionDoctorPhase == _ConnectionDoctorPhase.idle &&
            _mainServerOnline == false);
    final advancedHelpRecommended =
        _connectionDoctorPhase == _ConnectionDoctorPhase.setupRequired ||
        _connectionDoctorPhase == _ConnectionDoctorPhase.serverUnavailable;
    final checkLabel = checking
        ? 'Checking…'
        : _connectionDoctorPhase == _ConnectionDoctorPhase.idle
        ? 'Check connection'
        : 'Check again';
    final repairLabel = repairing
        ? 'Repairing…'
        : _connectionDoctorPhase == _ConnectionDoctorPhase.repairFailed
        ? 'Try repair again'
        : 'Repair connection';

    final checkButton = repairRecommended || advancedHelpRecommended
        ? OutlinedButton.icon(
            key: const Key('connection-doctor-check'),
            onPressed: _running
                ? null
                : () => unawaited(_runConnectionLoopDoctor(fix: false)),
            style: OutlinedButton.styleFrom(
              minimumSize: const Size(0, 48),
              padding: const EdgeInsets.symmetric(horizontal: 18),
            ),
            icon: const Icon(Icons.monitor_heart_outlined, size: 19),
            label: Text(checkLabel),
          )
        : FilledButton.icon(
            key: const Key('connection-doctor-check'),
            onPressed: _running
                ? null
                : () => unawaited(_runConnectionLoopDoctor(fix: false)),
            style: FilledButton.styleFrom(
              minimumSize: const Size(0, 48),
              padding: const EdgeInsets.symmetric(horizontal: 18),
            ),
            icon: const Icon(Icons.monitor_heart_outlined, size: 19),
            label: Text(checkLabel),
          );
    final secondaryButton = connected
        ? FilledButton.icon(
            key: const Key('connection-doctor-go-chat'),
            onPressed: _running
                ? null
                : () => _selectSectionById('chat_runtime'),
            style: FilledButton.styleFrom(
              minimumSize: const Size(0, 48),
              padding: const EdgeInsets.symmetric(horizontal: 18),
            ),
            icon: const Icon(Icons.chat_bubble_outline, size: 19),
            label: const Text('Go to Chat'),
          )
        : advancedHelpRecommended
        ? FilledButton.icon(
            key: const Key('connection-doctor-open-app-primary'),
            onPressed: _running
                ? null
                : () => unawaited(_openConnectionLoopDoctorGui()),
            style: FilledButton.styleFrom(
              minimumSize: const Size(0, 48),
              padding: const EdgeInsets.symmetric(horizontal: 18),
            ),
            icon: const Icon(Icons.open_in_new, size: 19),
            label: const Text('Open advanced doctor'),
          )
        : repairRecommended
        ? FilledButton.icon(
            key: const Key('connection-doctor-fix'),
            onPressed: _running
                ? null
                : () => unawaited(_confirmConnectionDoctorRepair()),
            style: FilledButton.styleFrom(
              minimumSize: const Size(0, 48),
              padding: const EdgeInsets.symmetric(horizontal: 18),
            ),
            icon: const Icon(Icons.build_circle_outlined, size: 19),
            label: Text(repairLabel),
          )
        : OutlinedButton.icon(
            key: const Key('connection-doctor-fix'),
            onPressed: _running
                ? null
                : () => unawaited(_confirmConnectionDoctorRepair()),
            style: OutlinedButton.styleFrom(
              minimumSize: const Size(0, 48),
              padding: const EdgeInsets.symmetric(horizontal: 18),
            ),
            icon: const Icon(Icons.build_circle_outlined, size: 19),
            label: Text(repairLabel),
          );

    return LayoutBuilder(
      builder: (context, constraints) {
        final stacked =
            constraints.maxWidth < 620 || _effectiveInterfaceTextScale > 1.3;
        if (stacked) {
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              SizedBox(width: double.infinity, child: checkButton),
              const SizedBox(height: 8),
              SizedBox(width: double.infinity, child: secondaryButton),
            ],
          );
        }
        return Wrap(
          spacing: 10,
          runSpacing: 10,
          children: [checkButton, secondaryButton],
        );
      },
    );
  }

