  Future<void> _refreshLiftedIntentReceipt() async {
    if (_liftedIntentRefreshing) return;
    if (mounted) {
      setState(() {
        _liftedIntentRefreshing = true;
        _liftedIntentReadError = '';
      });
    } else {
      _liftedIntentRefreshing = true;
    }
    try {
      final file = File(liftedIntentLatestReceiptPath);
      Map<String, dynamic>? receipt;
      if (await file.exists()) {
        final decoded = jsonDecode(await file.readAsString());
        if (decoded is Map &&
            decoded['schema'] == 'engel_lifted_intent_receipt_v1') {
          receipt = Map<String, dynamic>.from(decoded);
        } else {
          throw const FormatException(
            'latest intent receipt has an unknown schema',
          );
        }
      }
      if (!mounted) return;
      setState(() => _liftedIntentLatestReceipt = receipt);
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _liftedIntentReadError =
            'Engel could not read the latest intent receipt: $error';
      });
    } finally {
      if (mounted) {
        setState(() => _liftedIntentRefreshing = false);
      } else {
        _liftedIntentRefreshing = false;
      }
    }
  }

  Widget _intentBridgePage() {
    final receipt = _liftedIntentLatestReceipt;
    final contract = receipt?['contract'] is Map
        ? Map<String, dynamic>.from(receipt!['contract'] as Map)
        : const <String, dynamic>{};
    final hipl = contract['hipl'] is Map
        ? Map<String, dynamic>.from(contract['hipl'] as Map)
        : const <String, dynamic>{};
    final expression = hipl['expression'] is Map
        ? Map<String, dynamic>.from(hipl['expression'] as Map)
        : const <String, dynamic>{};
    final lifted = contract['lifted_intent'] is Map
        ? Map<String, dynamic>.from(contract['lifted_intent'] as Map)
        : const <String, dynamic>{};
    final mipl = contract['mipl'] is Map
        ? Map<String, dynamic>.from(contract['mipl'] as Map)
        : const <String, dynamic>{};
    final miplWire = mipl['wire'] is Map
        ? Map<String, dynamic>.from(mipl['wire'] as Map)
        : const <String, dynamic>{};
    final comprehension = receipt?['hipl_comprehension'] is Map
        ? Map<String, dynamic>.from(receipt!['hipl_comprehension'] as Map)
        : const <String, dynamic>{};
    final verification = receipt?['verification'] is Map
        ? Map<String, dynamic>.from(receipt!['verification'] as Map)
        : const <String, dynamic>{};
    final objective = '${lifted['objective'] ?? ''}'.trim();
    final effect = '${lifted['effect'] ?? ''}'.trim();
    final targets = lifted['targets'] is List
        ? List<Object?>.from(lifted['targets'] as List)
        : const <Object?>[];
    final proofPaths = comprehension['proof_paths'] is List
        ? List<Object?>.from(comprehension['proof_paths'] as List)
        : const <Object?>[];
    final auditComplete = verification['audit_complete'] == true;
    final miplVersion = '${mipl['version'] ?? 2}';
    final miplPackets = '${miplWire['packet_count'] ?? 0}';
    final miplBytes = '${miplWire['encoded_bytes'] ?? 0}';

    Widget stage({
      required IconData icon,
      required String title,
      required String subtitle,
      required Color color,
    }) {
      return Container(
        width: 230,
        constraints: const BoxConstraints(minHeight: 118),
        padding: const EdgeInsets.all(13),
        decoration: BoxDecoration(
          color: const Color(0xff111824),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: color.withValues(alpha: 0.75)),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Icon(icon, color: color, size: 22),
            const SizedBox(height: 8),
            Text(
              title,
              style: TextStyle(
                color: color,
                fontSize: 14,
                fontWeight: FontWeight.w900,
              ),
            ),
            const SizedBox(height: 4),
            Text(
              subtitle,
              style: const TextStyle(
                color: Color(0xffb7c3d8),
                fontSize: 12,
                height: 1.35,
              ),
            ),
          ],
        ),
      );
    }

    return _PageFrame(
      child: SingleChildScrollView(
        key: const Key('intent-bridge-page'),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Container(
              padding: const EdgeInsets.all(16),
