  Widget _launchCenterPage() {
    final commands = [
      rustCommands.firstWhere((c) => c.key == 'ui_shell_status'),
      rustCommands.firstWhere((c) => c.key == 'ui_shell_verify'),
      rustCommands.firstWhere((c) => c.key == 'workspace_verify'),
      rustCommands.firstWhere((c) => c.key == 'legacy_status_verify'),
      rustCommands.firstWhere((c) => c.key == 'gateway_status'),
      rustCommands.firstWhere((c) => c.key == 'workspace_verify_engel_parts'),
    ];
    final canonicalExists = File(flutterEngelMainExe).existsSync();
    final legacyExists = File(legacyEngelExe).existsSync();
    final stagedDistExists = File(stagedDistEngelMainExe).existsSync();
    final standaloneSourceExists = File(
      standaloneConnectionSourceExe,
    ).existsSync();
    final tauriExists = Directory(tauriSourceDir).existsSync();
    final rustExists = Directory(rustCoreRoot).existsSync();
    final cosmosExists = Directory(cosmosRoot).existsSync();
    final releaseDir = File(flutterEngelMainExe).parent.path;
    final releaseExe = File(flutterEngelMainExe);
    final appSo = File('$releaseDir\\data\\app.so');
    final nativeAssets = File('$releaseDir\\native_assets.json');
    final stagedDistDir = File(stagedDistEngelMainExe).parent.path;
    final stagedDistExe = File(stagedDistEngelMainExe);
    final stagedDistAppSo = File('$stagedDistDir\\data\\app.so');
    final shortcutMatchCount = _launchShortcuts
        .where((shortcut) => shortcut.matchesCanonical)
        .length;

    String state(bool exists, String path) =>
        '${exists ? 'FOUND' : 'MISSING'} - $path';
    String releaseState(File file) {
      if (!file.existsSync()) return 'MISSING - ${file.path}';
      final stat = file.statSync();
      final modified = stat.modified.toLocal().toString().split('.').first;
      return 'FOUND ${_formatBytes(stat.size)} modified $modified - ${file.path}';
    }

    return _PageFrame(
      child: Row(
        children: [
          Expanded(
            flex: 5,
