  String _deviceIssuePhrase(VisibleDeviceWorker worker) {
    return switch (worker.status.readiness) {
      EngelDeviceReadiness.offline => '${worker.name} needs connection',
      EngelDeviceReadiness.stale => '${worker.name} needs a new status check',
      EngelDeviceReadiness.unknown => '${worker.name} has not been checked',
      EngelDeviceReadiness.ready => '${worker.name} is ready',
    };
  }

  Widget _deviceOverviewCard(
    DeviceVisibilityInfo visible,
    List<EngelDeviceStatus> statuses,
  ) {
    final workers = <VisibleDeviceWorker>[
      ...visible.phoneWorkers,
      visible.subEngelWorker,
    ];
    final readyCount = statuses.where((status) => status.isReady).length;
    final checked = statuses.any(
      (status) => status.readiness != EngelDeviceReadiness.unknown,
    );
    final allReady = statuses.isNotEmpty && readyCount == statuses.length;
    final issues = workers
        .where((worker) => !worker.status.isReady)
        .toList(growable: false);
    final issueCount = issues.length;

    late final String title;
    late final String detail;
    late final String actionLabel;
    late final IconData actionIcon;
    late final VoidCallback? action;
    late final Color accent;
    if (!checked) {
      title = 'Check your device connections';
      detail =
          'Read the latest phone and Sub-Engel status. This check does not '
          'change any device.';
      actionLabel = 'Check connections';
      actionIcon = Icons.refresh;
      action = _deviceVisibilityRefreshing
          ? null
          : () => unawaited(_refreshDeviceVisibilityFromUi());
      accent = const Color(0xff58c4ff);
    } else if (allReady) {
      // Keep the concise all-ready summary in the page status pill.  The
      // overview card gets a distinct heading so the same sentence is not
      // announced twice to screen readers or duplicated in the visual page.
      title = 'Workers ready';
      detail =
          'All $readyCount workers are ready. Your connected workers can receive a reviewed task when you are ready.';
      actionLabel = 'Send a worker task';
      actionIcon = Icons.assignment_outlined;
      action = () => _selectSectionById('worker_dispatch');
      accent = const Color(0xff00e87a);
    } else {
      title = issueCount == 1
          ? '1 worker needs attention'
          : '$issueCount workers need attention';
      final issueSummary = issues.take(2).map(_deviceIssuePhrase).join('. ');
      final remaining = issueCount > 2
          ? ' ${issueCount - 2} more need help.'
          : '';
      final readySummary = readyCount == 0
          ? ''
          : ' $readyCount ${readyCount == 1 ? 'worker is' : 'workers are'} ready.';
      detail = '$issueSummary.$remaining$readySummary';
      actionLabel = 'Open guided connection help';
      actionIcon = Icons.health_and_safety_outlined;
      action = () => _selectSectionById('connection_doctor');
      accent = const Color(0xffffc857);
    }

    return Semantics(
      key: const Key('device-overview'),
      container: true,
      label: '$title. $detail',
      child: Container(
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: accent.withValues(alpha: 0.07),
          borderRadius: BorderRadius.circular(9),
          border: Border.all(color: accent.withValues(alpha: 0.55)),
        ),
        child: LayoutBuilder(
          builder: (context, constraints) {
            final stack =
                constraints.maxWidth < 650 ||
                _effectiveInterfaceTextScale > 1.3;
            final message = Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Icon(
                  !checked
                      ? Icons.device_unknown_outlined
                      : allReady
                      ? Icons.check_circle_outline
                      : Icons.error_outline,
                  color: accent,
                  size: 23,
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        title,
                        style: const TextStyle(
                          color: Color(0xfff4f7fb),
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      const SizedBox(height: 3),
                      Text(
                        detail,
                        key: const Key('device-overview-detail'),
                        style: const TextStyle(
                          color: Color(0xffb8c6d9),
                          fontSize: 12,
                          height: 1.35,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            );
            final actions = Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                FilledButton.icon(
                  key: const Key('device-recommended-action'),
                  onPressed: action,
                  icon: Icon(actionIcon, size: 17),
                  label: Text(actionLabel),
                ),
                if (checked)
                  OutlinedButton.icon(
                    key: const Key('device-check-again'),
                    onPressed: _deviceVisibilityRefreshing
                        ? null
                        : () => unawaited(_refreshDeviceVisibilityFromUi()),
                    icon: const Icon(Icons.refresh, size: 17),
                    label: const Text('Check again'),
                  ),
              ],
            );
            if (stack) {
              return Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  message,
                  const SizedBox(height: 10),
                  Align(alignment: Alignment.centerLeft, child: actions),
                ],
              );
            }
            return Row(
              children: [
                Expanded(child: message),
                const SizedBox(width: 16),
                actions,
              ],
            );
          },
        ),
      ),
    );
  }

