  Widget _swarmMetricStrip(List<SwarmDeviceNode> devices) {
    final operational = devices
        .where(
          (device) =>
              device.classification == 'cluster_member' ||
              device.classification == 'logical_runtime',
        )
        .toList(growable: false);
    final online = operational
        .where(
          (d) =>
              d.status == 'verified_live' ||
              d.status.toLowerCase().contains('online') ||
              d.status.toLowerCase().contains('ready'),
        )
        .length;
    final waiting = operational
        .where(
          (d) =>
              d.status.toLowerCase().contains('standby') ||
              d.status.toLowerCase().contains('draft') ||
              d.status.toLowerCase().contains('scan') ||
              d.status.toLowerCase().contains('not checked') ||
              d.status.toLowerCase().contains('out of date'),
        )
        .length;
    final problem = operational
        .where(
          (d) =>
              d.status.toLowerCase().contains('stale') ||
              d.status.toLowerCase().contains('offline') ||
              d.status.toLowerCase().contains('needs connection') ||
              d.status.toLowerCase().contains('error') ||
              d.status.toLowerCase().contains('failed'),
        )
        .length;
    final avgSignal = operational.isEmpty
        ? 0
        : (operational.map((d) => d.signal).reduce((a, b) => a + b) /
                  operational.length)
              .round();
    return Wrap(
      spacing: 7,
      runSpacing: 7,
      children: [
        _glowingTag(
          'ONLINE $online',
          color: const Color(0xff00e87a),
          compact: true,
        ),
        _glowingTag(
          'STANDBY $waiting',
          color: const Color(0xffffc857),
          compact: true,
        ),
        _glowingTag(
          'ISSUES $problem',
          color: const Color(0xffff4d6d),
          compact: true,
        ),
        _glowingTag(
          'SIGNAL $avgSignal%',
          color: const Color(0xff58c4ff),
          compact: true,
        ),
        _glowingTag(
          'MANUAL ${_swarmManualDevices.length}',
          color: const Color(0xffa78bfa),
          compact: true,
        ),
        _glowingTag(
          'QUEUE ${_subEngelSharedRoomQueue.workOrderCount}',
          color: const Color(0xfff472b6),
          compact: true,
        ),
      ],
    );
  }

  Widget _deviceSwarmViewport(List<SwarmDeviceNode> devices) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final size = Size(
          constraints.maxWidth.isFinite ? constraints.maxWidth : 800,
          constraints.maxHeight.isFinite ? constraints.maxHeight : 520,
        );
        final projected = _projectSwarmNodes(devices, size);
        return Container(
          decoration: BoxDecoration(
            color: const Color(0xff050a14),
            borderRadius: BorderRadius.circular(14),
            border: Border.all(color: const Color(0xff24324f), width: 1.5),
            boxShadow: const [
              BoxShadow(
                color: Color(0x44000000),
                blurRadius: 24,
                offset: Offset(0, 10),
              ),
            ],
          ),
          clipBehavior: Clip.antiAlias,
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onPanUpdate: (details) {
              setState(() {
                _swarmYaw += details.delta.dx * 0.008;
                _swarmPitch = (_swarmPitch + details.delta.dy * 0.006).clamp(
                  -0.95,
                  0.95,
                );
              });
            },
            onDoubleTap: () {
              setState(() {
                _swarmYaw = -0.55;
                _swarmPitch = 0.48;
                _swarmZoom = 1.0;
              });
            },
            onTapUp: (details) =>
                _selectNearestSwarmNode(projected, details.localPosition),
            child: Stack(
              children: [
                CustomPaint(
                  size: size,
                  painter: _SwarmScenePainter(
                    nodes: projected,
                    selectedId: _swarmSelectedId,
                    showWifi: _swarmShowWifi,
                    animPhase: _swarmAnimPhase,
                  ),
                ),
                Positioned(
                  left: 12,
                  top: 10,
                  child: _Tag('drag orbit / tap node / double-click reset'),
                ),
                Positioned(
                  right: 12,
                  top: 10,
                  child: SizedBox(
                    width: 230,
                    child: Row(
                      children: [
                        const Icon(
                          Icons.zoom_in,
                          color: Color(0xff8ba4bc),
                          size: 18,
                        ),
                        Expanded(
                          child: Slider(
                            min: 0.62,
                            max: 1.55,
                            value: _swarmZoom,
                            onChanged: (value) =>
                                setState(() => _swarmZoom = value),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  List<_SwarmProjectedNode> _projectSwarmNodes(
    List<SwarmDeviceNode> devices,
    Size size,
  ) {
    final center = Offset(size.width / 2, size.height / 2 + 20);
    final scale = math.min(size.width, size.height) * 0.075 * _swarmZoom;
    final yawCos = math.cos(_swarmYaw);
    final yawSin = math.sin(_swarmYaw);
    final pitchCos = math.cos(_swarmPitch);
    final pitchSin = math.sin(_swarmPitch);
    final projected = <_SwarmProjectedNode>[];
    for (final device in devices) {
      final yawX = device.x * yawCos - device.z * yawSin;
      final yawZ = device.x * yawSin + device.z * yawCos;
      final pitchY = device.y * pitchCos - yawZ * pitchSin;
      final depth = device.y * pitchSin + yawZ * pitchCos;
      final perspective = 1.0 / (1.0 + ((depth + 12) * 0.028));
      final radius =
          switch (device.type) {
            'wifi' => 15.0,
            'server' => 13.0,
            'llm' => 13.0,
            'windows' => 12.0,
            'sub_engel' => 12.0,
            'android' => 10.5,
            _ => 10.0,
          } *
          perspective;
      projected.add(
        _SwarmProjectedNode(
          device: device,
          position:
              center +
              Offset(yawX * scale * perspective, -pitchY * scale * perspective),
          depth: depth,
          radius: radius,
        ),
      );
    }
    projected.sort((a, b) => a.depth.compareTo(b.depth));
    return projected;
  }

  void _selectNearestSwarmNode(
    List<_SwarmProjectedNode> nodes,
    Offset position,
  ) {
    _SwarmProjectedNode? nearest;
    var nearestDistance = double.infinity;
    for (final node in nodes) {
      final distance = (node.position - position).distance;
      if (distance < nearestDistance) {
        nearestDistance = distance;
        nearest = node;
      }
    }
    if (nearest == null || nearestDistance > nearest.radius + 24) return;
    setState(() => _swarmSelectedId = nearest!.device.id);
  }

