  String _swarmIdentityLine(SwarmDeviceNode node) {
    final parts = <String>[
      if (node.hostName.isNotEmpty) node.hostName,
      node.ip,
      node.classification == 'unclassified' ? node.role : node.classification,
      if (node.macAddress.isNotEmpty) 'MAC ${node.macAddress}',
      if (node.interfaceName.isNotEmpty) node.interfaceName,
      if (node.openPorts.isNotEmpty) 'ports ${node.openPorts}',
    ];
    return parts.join(' / ');
  }

  Widget _swarmCandidateTile(SwarmDeviceNode node) {
    final alreadyAdded = _swarmClusterContains(node);
    final canRegister = node.canJoinCluster && !alreadyAdded;
    final identityLine = _swarmIdentityLine(node);
    final summary = node.deviceSummary.trim();
    return Material(
      color: Colors.transparent,
      child: InkWell(
        borderRadius: BorderRadius.circular(8),
        onTap: () => setState(() => _swarmSelectedId = node.id),
        child: Container(
          padding: const EdgeInsets.all(9),
          decoration: BoxDecoration(
            color: const Color(0xff111827),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(color: const Color(0xff263241)),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Row(
                children: [
                  Icon(
                    _swarmTypeIcon(node.type),
                    size: 16,
                    color: _swarmStatusColor(node.status),
                  ),
                  const SizedBox(width: 7),
                  Expanded(
                    child: Text(
                      node.name,
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(fontWeight: FontWeight.w900),
                    ),
                  ),
                  _Tag(alreadyAdded ? 'added' : node.status),
                ],
              ),
              const SizedBox(height: 5),
              Text(
                identityLine.isEmpty
                    ? '${node.ip} / ${node.role}'
                    : identityLine,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(color: Color(0xffaab8c6), fontSize: 12),
              ),
              if (summary.isNotEmpty)
                Text(
                  summary,
                  maxLines: 3,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: Color(0xffaab8c6),
                    fontSize: 12,
                  ),
                ),
              Text(
                node.evidence.isEmpty ? node.detail : node.evidence,
                maxLines: 3,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(color: Color(0xff7f92a7), fontSize: 11),
              ),
              const SizedBox(height: 7),
              Row(
                children: [
                  Expanded(
                    child: FilledButton.icon(
                      onPressed: canRegister
                          ? () => unawaited(_addSwarmNodeToCluster(node))
                          : null,
                      icon: const Icon(Icons.add_link, size: 15),
                      label: Text(
                        alreadyAdded
                            ? 'Registered'
                            : canRegister
                            ? 'Register'
                            : 'Not an Engel worker',
                      ),
                    ),
                  ),
                  const SizedBox(width: 7),
                  OutlinedButton(
                    onPressed: () => setState(() => _swarmSelectedId = node.id),
                    child: const Text('Select'),
                  ),
                ],
              ),
            ],
          ),
        ),
      ),
    );
  }

