            _swarmStatLine('Aliases', selected.aliases.join(', ')),
          if (selected.lastSeenUtc.isNotEmpty)
            _swarmStatLine('Last seen', selected.lastSeenUtc),
          _swarmStatLine('Workers', selected.workers.toString()),
          _swarmStatLine('Signal', selected.signal.round().toString()),
          _swarmStatLine('Source', selected.source),
          _swarmStatLine('Evidence', primaryEvidence),
          if (identifyEvidence.isNotEmpty)
            _swarmStatLine('Identify', identifyEvidence),
          const SizedBox(height: 8),
          Wrap(
            spacing: 7,
            runSpacing: 7,
            children: [
              FilledButton.icon(
                onPressed:
                    selected.canJoinCluster && !_swarmClusterContains(selected)
                    ? () => unawaited(_addSwarmNodeToCluster(selected))
                    : null,
                icon: const Icon(Icons.add_link, size: 15),
                label: const Text('Add selected'),
              ),
              OutlinedButton.icon(
                onPressed: _running
                    ? null
                    : () => unawaited(_identifySwarmDevice(selected)),
                icon: const Icon(Icons.manage_search, size: 15),
                label: const Text('Identify'),
              ),
              OutlinedButton.icon(
                onPressed: () => unawaited(_saveSwarmDeviceSettings(selected)),
                icon: const Icon(Icons.save_outlined, size: 15),
                label: const Text('Save'),
              ),
            ],
          ),
        ],
      ),
    );
  }

  bool _swarmClusterContains(SwarmDeviceNode node) {
    final auditedMember = _auditedSwarmDevices.any(
      (existing) =>
          existing.id == node.id &&
          (existing.classification == 'cluster_member' ||
              existing.classification == 'logical_runtime' ||
              existing.classification == 'network_infrastructure'),
    );
    return auditedMember ||
        _swarmManualDevices.any(
          (existing) =>
              existing.id == node.id ||
              (existing.ip == node.ip && existing.name == node.name),
        );
  }

  Future<void> _addSwarmNodeToCluster(SwarmDeviceNode node) async {
    if (!node.canJoinCluster) {
      setState(() {
        _swarmSelectedId = node.id;
        _status = 'device is not eligible for registration';
        _output =
            '${node.name} is classified as ${node.classification}. LAN sightings, TVs, routers, and unauthenticated endpoints cannot be registered as Engel workers.';
      });
      return;
    }
    if (_swarmClusterContains(node)) {
      setState(() {
        _swarmSelectedId = node.id;
        _status = 'device already in swarm cluster';
        _output = '${node.name} is already in the local swarm cluster view.';
      });
      return;
    }
    final index = _swarmManualDevices.length + 1;
    final angle = 1.15 + (index * 0.88);
    final clusterNode = node.copyWith(
      id: 'cluster-${_safeFileToken(node.id)}-${DateTime.now().millisecondsSinceEpoch}',
      status: node.status == 'discovered' ? 'clustered' : node.status,
      source: '${node.source} -> swarm cluster',
      detail: 'Added from Swarm 3D discovery panel. ${node.detail}'.trim(),
      x: node.x == 0 ? math.cos(angle) * 7.2 : node.x,
      y: node.y == 0 ? 0.9 + (index % 3) * 0.45 : node.y,
      z: node.z == 0 ? math.sin(angle) * 5.4 : node.z,
      trusted: true,
    );
    setState(() {
      _swarmManualDevices.add(clusterNode);
      _swarmSelectedId = clusterNode.id;
    });
    await _writeSwarmAddDraft(clusterNode);
  }

