  Widget _proofResultSummaryCard(EngelProofResultSummary summary) {
    final (color, icon) = switch (summary.tone) {
      EngelProofResultTone.passed => (
        const Color(0xff47df91),
        Icons.check_circle_outline,
      ),
      EngelProofResultTone.attention => (
        const Color(0xffffc857),
        Icons.warning_amber_rounded,
      ),
      EngelProofResultTone.unavailable => (
        const Color(0xffff6b7a),
        Icons.error_outline,
      ),
    };
    return Semantics(
      key: const Key('proof-result-summary'),
      container: true,
      liveRegion: true,
      label: '${summary.title}. ${summary.detail}',
      excludeSemantics: true,
      child: Container(
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: color.withValues(alpha: 0.08),
          borderRadius: BorderRadius.circular(8),
          border: Border.all(color: color.withValues(alpha: 0.55)),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Icon(icon, color: color, size: 21),
            const SizedBox(width: 10),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    summary.title,
                    style: TextStyle(color: color, fontWeight: FontWeight.w900),
                  ),
                  const SizedBox(height: 3),
                  Text(
                    summary.detail,
                    style: const TextStyle(
                      color: Color(0xffc4cede),
                      height: 1.35,
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

