        .where((artifact) => artifact.kind == 'receipt')
        .take(18)
        .toList();
    final liveScreenshots = _artifacts
        .where(
          (artifact) =>
              artifact.kind == 'screenshot' &&
              artifact.name.startsWith('engel_') &&
              artifact.name.endsWith('_live.png'),
        )
        .take(8)
        .toList();
    final loadedReceiptCount = _artifacts
        .where((artifact) => artifact.kind == 'receipt')
