  Widget _toolLibraryPage() {
    final normalizedQuery = _toolRouteQuery.trim().toLowerCase();
    final matchingRoutes = rustCommands.where((command) {
      if (normalizedQuery.isEmpty) return false;
      return command.key.toLowerCase().contains(normalizedQuery) ||
          command.label.toLowerCase().contains(normalizedQuery) ||
          command.args.join(' ').toLowerCase().contains(normalizedQuery);
    }).toList();
    final visibleRoutes = matchingRoutes.take(6).toList();
    final finderRows = normalizedQuery.isEmpty
        ? const [
            'Type what you need, such as phone, memory, meeting, model, or verify.',
            'Search finds Engel capabilities without starting anything.',
          ]
        : visibleRoutes.isEmpty
        ? const ['No Engel tool matches that search. Try a shorter name.']
        : [
            for (final command in visibleRoutes)
              '${command.label}${command.needsText ? ' — needs details before it can run' : ''}',
            if (matchingRoutes.length > visibleRoutes.length)
              '${matchingRoutes.length - visibleRoutes.length} more matches — narrow the search to see them.',
          ];
    final technicalRows = normalizedQuery.isEmpty
        ? const [
            'Search above to reveal matching internal routes.',
            'Route details are diagnostic information; everyday tool checks are above.',
          ]
        : visibleRoutes.isEmpty
        ? const ['No matching internal route.']
        : [
            for (final command in visibleRoutes)
              '${command.key} -> ${command.args.join(' ')}',
          ];
