  // Historical tool catalog retained only for receipt compatibility.
  // ignore: unused_element
  Widget _legacyToolLibraryPage() {
    final commands = [
      rustCommands.firstWhere((c) => c.key == 'minor_tools_list'),
      rustCommands.firstWhere((c) => c.key == 'minor_tools_verify'),
      rustCommands.firstWhere((c) => c.key == 'bundled_tools_list'),
      rustCommands.firstWhere((c) => c.key == 'bundled_tools_verify'),
      rustCommands.firstWhere((c) => c.key == 'runtime_wsl_tools'),
      rustCommands.firstWhere((c) => c.key == 'runtime_engel3d_status'),
      rustCommands.firstWhere((c) => c.key == 'feature_search_developer'),
      rustCommands.firstWhere((c) => c.key == 'workspace_verify_engel_parts'),
    ];
    final toolRoots = [
      '$appRoot\\engel_ai_gallery_main',
      '$appRoot\\engel_airllm_main',
      '$appRoot\\engel_claw3d_main',
      '$appRoot\\engel_cli_anything_main',
      '$appRoot\\engel_cubesandbox_main',
      '$appRoot\\engel_evolution_engine_main',
      '$appRoot\\engel_git_nexus_main',
      '$appRoot\\engel_gstack_main',
      '$appRoot\\engel_humanizer_main',
      '$appRoot\\engel_knowledge_graph_v2_main',
      '$appRoot\\engel_lan_main',
      '$appRoot\\engel_lfm2_code_review_main',
      '$appRoot\\engel_localsend_main',
      '$appRoot\\engel_agent_main',
      '$appRoot\\engel_main',
      '$appRoot\\engel_octogent_main',
      '$appRoot\\engel_open_agents_main',
      '$appRoot\\engel3d_office_main',
      '$appRoot\\engelcode_main',
      '$appRoot\\engelsandbox_main',
      '$appRoot\\memory',
      '$appRoot\\models',
      '$appRoot\\tools',
    ];
    final rootRows = toolRoots.map((path) {
      final dir = Directory(path);
      final name = path.split(r'\').last;
      if (!dir.existsSync()) return '$name: missing - $path';
      final modified = dir
          .statSync()
          .modified
          .toLocal()
          .toString()
          .split('.')
          .first;
      return '$name: present, modified $modified';
    }).toList();
    final commandFamilies = <String, int>{};
    for (final command in rustCommands) {
      final family = command.key.split('_').first;
      commandFamilies[family] = (commandFamilies[family] ?? 0) + 1;
    }
    final commandFamilyRows = commandFamilies.entries.toList()
      ..sort((a, b) {
        final countCompare = b.value.compareTo(a.value);
        if (countCompare != 0) return countCompare;
        return a.key.compareTo(b.key);
      });
    final commandSurfaceRows = [
      'Registered Rust commands in Engel GUI: ${rustCommands.length}',
      'Tool Library proof buttons: ${commands.length}',
      'Bundled/local app roots tracked: ${toolRoots.length}',
      'Rust source modules scanned: ${_rustSource.sourceFiles}',
      'Route coverage receipt: ${_routeCoverageReceiptExists ? 'loaded' : 'missing'}',
      'Unreferenced registered commands: ${_routeCoverageUnreferencedCommands ?? 'not parsed'}',
      for (final entry in commandFamilyRows.take(12))
        '${entry.key} command family: ${entry.value}',
    ];
    final commandKeys = rustCommands.map((command) => command.key).toList();
    final uniqueCommandKeys = commandKeys.toSet().length;
    final duplicateCommandKeys = rustCommands.length - uniqueCommandKeys;
    final textGatedCommands = rustCommands
        .where((command) => command.needsText)
        .length;
    final normalizedToolRouteQuery = _toolRouteQuery.trim().toLowerCase();
    final filteredToolRoutes = rustCommands.where((command) {
      if (normalizedToolRouteQuery.isEmpty) return true;
      return command.key.toLowerCase().contains(normalizedToolRouteQuery) ||
          command.label.toLowerCase().contains(normalizedToolRouteQuery) ||
          command.args
              .join(' ')
              .toLowerCase()
              .contains(normalizedToolRouteQuery);
    }).toList();
    final visibleToolRoutes = filteredToolRoutes.take(8).toList();
    final catalogPreviewCount = rustCommands.length < 24
        ? rustCommands.length
        : 24;
    final commandCatalogRows = [
      'Catalog entries scanned: ${rustCommands.length}',
      'Unique command keys: $uniqueCommandKeys / duplicate command keys: $duplicateCommandKeys',
      'Text-gated commands: $textGatedCommands',
      'Preview rows shown: $catalogPreviewCount / ${rustCommands.length}',
      for (final command in rustCommands.take(catalogPreviewCount))
        '${command.key} -> ${command.args.join(' ')}',
    ];
    final toolRouteOwnershipRows = [
      'Engel-owned route count: ${rustCommands.length} Rust command constructors.',
      'Ownership rule: use through Engel Rust routes, not external imported shells.',
      'Imported tool lanes: Jarvis, Octogent, GitNexus, OpenAgents, CLI Anything, and imported desktop patterns.',
      'Bundled tool lanes: Code Companion, CubeSandbox, Claw3D, Engel3D, EngelCode, LocalSend, AirLLM, and vision tools.',
      'Runtime lanes: WSL tools, LAN tools, sandbox tools, graph/knowledge tools, drive/model tools.',
      'Guard policy: install/start/stop/build/run actions stay approval-gated; inventory and verify routes are read-only.',
    ];
    final toolRouteFinderRows = [
      normalizedToolRouteQuery.isEmpty
          ? '${filteredToolRoutes.length}/${rustCommands.length} routes visible; type to filter by key, label, or args.'
          : '${filteredToolRoutes.length}/${rustCommands.length} routes match "$_toolRouteQuery"; first: ${visibleToolRoutes.isEmpty ? 'none' : visibleToolRoutes.first.key}.',
      if (visibleToolRoutes.isEmpty)
        'No Engel Rust route matches this query.'
      else
        for (final command in visibleToolRoutes)
          '${command.key}${command.needsText ? ' <text>' : ''} -> ${command.label} / ${command.args.join(' ')}',
      if (filteredToolRoutes.length > visibleToolRoutes.length)
        'Showing ${visibleToolRoutes.length}; refine search for the remaining ${filteredToolRoutes.length - visibleToolRoutes.length}.',
    ];
    return _PageFrame(
      child: Row(
        children: [
          Expanded(
            flex: 5,
            child: Container(
              padding: const EdgeInsets.all(14),
              decoration: _panelDecoration(),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Row(
                    children: [
                      const Icon(Icons.construction, color: Color(0xff00e87a)),
                      const SizedBox(width: 8),
                      const Expanded(
                        child: Text(
                          'Engel Tool Library',
                          style: TextStyle(
                            fontSize: 20,
                            fontWeight: FontWeight.w800,
                          ),
