  Widget _toolGatesPage() {
    final commands = [
      rustCommands.firstWhere((c) => c.key == 'bundled_git_nexus_install'),
      rustCommands.firstWhere((c) => c.key == 'bundled_jarvis_install'),
      rustCommands.firstWhere((c) => c.key == 'bundled_jarvis_start'),
