      rustCommands.firstWhere((c) => c.key == 'bundled_cubesandbox_install'),
      rustCommands.firstWhere(
        (c) => c.key == 'bundled_engelBridge_agent_start',
      ),
      rustCommands.firstWhere((c) => c.key == 'bundled_localsend_install'),
      rustCommands.firstWhere((c) => c.key == 'bundled_darwinian_run'),
      rustCommands.firstWhere((c) => c.key == 'minor_humanizer_invoke'),
      rustCommands.firstWhere((c) => c.key == 'minor_native_agent_dashboard'),
      rustCommands.firstWhere((c) => c.key == 'minor_ide_install'),
      rustCommands.firstWhere((c) => c.key == 'minor_kg_build'),
      rustCommands.firstWhere((c) => c.key == 'minor_evolution_run'),
      rustCommands.firstWhere((c) => c.key == 'bundled_tools_verify'),
    ];
    return _PageFrame(
      child: Row(
        children: [
          Expanded(
            flex: 5,
            child: Container(
              padding: const EdgeInsets.all(14),
              decoration: _panelDecoration(),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Row(
                    children: [
                      const Icon(Icons.lock, color: Color(0xff00e87a)),
                      const SizedBox(width: 8),
                      const Expanded(
                        child: Text(
                          'Engel Tool Gates',
                          style: TextStyle(
                            fontSize: 20,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                      ),
                      _Tag('manual gates'),
                    ],
                  ),
                  const SizedBox(height: 12),
                  Expanded(
                    child: Builder(
                      builder: (context) {
                        _ensureToolGatesLoaded();
                        final entries = gatedToolCommands.entries.toList();
                        return ListView.separated(
                          itemCount: entries.length,
                          separatorBuilder: (_, _) => const SizedBox(height: 6),
                          itemBuilder: (context, index) {
                            final entry = entries[index];
                            final command = rustCommands.firstWhere(
                              (c) => c.key == entry.key,
                            );
                            final allowed = _toolGateAllowed(entry.key);
                            return Container(
                              decoration: _panelDecoration(),
                              child: SwitchListTile(
                                dense: true,
                                title: Text(entry.value),
                                subtitle: Text(
                                  allowed
                                      ? 'Allowed - Run executes the real route now.'
                                      : 'Blocked - the route refuses until allowed.',
                                  style: const TextStyle(fontSize: 11),
                                ),
                                value: allowed,
                                onChanged: (v) => _setToolGate(entry.key, v),
                                secondary: IconButton(
                                  tooltip: 'Run ${entry.value} now',
                                  icon: const Icon(Icons.play_arrow),
                                  onPressed: (!allowed || _running)
                                      ? null
                                      : () => _runRust(command),
                                ),
                              ),
                            );
                          },
                        );
                      },
                    ),
                  ),
                  const SizedBox(height: 8),
                  Row(
                    children: [
                      OutlinedButton.icon(
                        icon: const Icon(Icons.verified_user, size: 16),
                        label: const Text('Verify gates'),
                        onPressed: _running
                            ? null
                            : () => _runRust(commands[15]),
                      ),
                      const SizedBox(width: 10),
                      const Expanded(
                        child: Text(
                          'Switches persist to the gate policy file and are enforced when the route runs - off means blocked.',
                          style: TextStyle(fontSize: 11, color: Colors.white54),
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(width: 12),
          Expanded(
            flex: 4,
            child: Column(children: [Expanded(child: _outputPanel())]),
          ),
        ],
      ),
    );
  }

