  Widget _workerDispatchPage() {
    final commands = [
      rustCommands.firstWhere(
        (c) => c.key == 'remote_workers_assignment_status',
      ),
      rustCommands.firstWhere((c) => c.key == 'remote_workers_prepared_jobs'),
      rustCommands.firstWhere(
        (c) => c.key == 'remote_workers_result_intake_status',
      ),
      rustCommands.firstWhere(
        (c) => c.key == 'remote_workers_result_intake_list',
      ),
      rustCommands.firstWhere(
        (c) => c.key == 'remote_workers_communication_queen',
      ),
      rustCommands.firstWhere((c) => c.key == 'remote_workers_claim_next'),
      rustCommands.firstWhere((c) => c.key == 'remote_workers_return_result'),
      rustCommands.firstWhere((c) => c.key == 'remote_workers_verify'),
      rustCommands.firstWhere(
        (c) => c.key == 'remote_workers_state_machine_verify',
      ),
      rustCommands.firstWhere((c) => c.key == 'android_workers_latest_result'),
      rustCommands.firstWhere((c) => c.key == 'android_workers_pull_results'),
      rustCommands.firstWhere((c) => c.key == 'android_workers_push_jobs'),
      rustCommands.firstWhere((c) => c.key == 'feature_search_status'),
    ];
    final dispatchDraft = _dispatchDraft.trim();
    final dispatchLower = dispatchDraft.toLowerCase();
    final dispatchLane = dispatchDraft.isEmpty
        ? 'No dispatch drafted'
        : dispatchLower.contains('phone') ||
              dispatchLower.contains('lan') ||
              dispatchLower.contains('android')
        ? 'Phone / Android worker lane'
        : dispatchLower.contains('sub-engel') ||
              dispatchLower.contains('sub engel') ||
              dispatchLower.contains('windows')
        ? 'Windows Sub-Engel lane'
        : dispatchLower.contains('meeting') ||
              dispatchLower.contains('agent') ||
              dispatchLower.contains('planner')
        ? 'Meeting Room agent lane'
        : dispatchLower.contains('remote') ||
              dispatchLower.contains('result') ||
              dispatchLower.contains('claim')
        ? 'Remote worker queue lane'
        : 'Local Engel verifier lane';
    final dispatchRoute = switch (dispatchLane) {
      'Phone / Android worker lane' =>
        'android_workers_push_jobs + lan_link_status',
      'Windows Sub-Engel lane' => 'device_cluster_verify + shared_room_tail',
      'Meeting Room agent lane' => 'meeting_agents + meeting_submit',
      'Remote worker queue lane' =>
        'remote_workers_assignment_status + remote_workers_claim_next',
      'Local Engel verifier lane' => 'workspace_verifiers_verify',
      _ => 'type a dispatch to classify',
    };
    final dispatchRows = [
      dispatchDraft.isEmpty
          ? 'Draft status: empty. Type a job for Engel to classify.'
          : 'Draft status: ${dispatchDraft.length} chars ready for review.',
      'Recommended lane: $dispatchLane',
      'Rust route gate: $dispatchRoute',
      'Execution rule: this panel classifies only; use guarded Rust buttons for claim, push, return, or verify.',
    ];
    return _PageFrame(
      child: Row(
        children: [
          Expanded(
            flex: 5,
            child: Container(
              padding: const EdgeInsets.all(14),
              decoration: _panelDecoration(),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Row(
                    children: [
                      const Icon(
                        Icons.assignment_turned_in,
                        color: Color(0xff00e87a),
                      ),
                      const SizedBox(width: 8),
                      const Expanded(
                        child: Text(
                          'Engel Worker Dispatch',
                          style: TextStyle(
                            fontSize: 20,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                      ),
                      _Tag('claim / return'),
                    ],
                  ),
                  const SizedBox(height: 12),
                  Expanded(
                    child: ListView(
                      children: [
                        const Text(
                          'Worker status',
                          style: TextStyle(fontWeight: FontWeight.w800),
                        ),
                        const SizedBox(height: 8),
                        _compactActionGrid([
                          _ControlAction(
                            key: const Key('dispatch-assignment-status'),
                            icon: Icons.assignment,
                            title: 'Assignment status',
                            subtitle: 'See queued, claimed, and returned work.',
                            onPressed: _running
                                ? null
                                : () => _runRust(commands[0]),
                          ),
                          _ControlAction(
                            key: const Key('dispatch-prepared-jobs'),
                            icon: Icons.work_history,
                            title: 'Prepared jobs',
                            subtitle: 'Read prepared worker jobs.',
                            onPressed: _running
                                ? null
                                : () => _runRust(commands[1]),
                          ),
                          _ControlAction(
                            key: const Key('dispatch-result-status'),
                            icon: Icons.inbox,
                            title: 'Returned work status',
