  Widget _connectorTargetRow(EngelConnectorTarget target) {
    final icon = target.isChannel
        ? _iconForStandaloneChannel(target.id)
        : _iconForIntegrationCategory(target.category);
    final selected = _isSelectedConnectorTarget(target);
    final profileExists = _connectorProfileExists(target);
    final connectionState = _connectorProfileState(target);
    return Material(
      key: Key('connector-row-${target.kind}-${target.id}'),
      color: selected ? const Color(0xff162337) : Colors.transparent,
      child: InkWell(
        onTap: () => _selectConnectorTarget(target),
        child: SizedBox(
          height: 54,
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 12),
            child: Row(
              children: [
                SizedBox(
                  width: 34,
                  child: Icon(
                    icon,
                    color: selected
                        ? const Color(0xff58c4ff)
                        : const Color(0xff00e87a),
                    size: 18,
                  ),
                ),
                Expanded(
                  flex: 4,
                  child: Text(
                    target.name,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(fontWeight: FontWeight.w800),
                  ),
                ),
                Expanded(
                  flex: 3,
                  child: Text(
                    target.category,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                      color: Color(0xffb8c4d6),
                      fontSize: 12,
                    ),
                  ),
                ),
                Expanded(
                  flex: 5,
                  child: Text(
                    connectionState,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                      color: Color(0xff9fb4cc),
                      fontSize: 12,
                    ),
                  ),
                ),
                SizedBox(
                  width: 112,
                  child: TextButton.icon(
                    key: Key('connector-connect-${target.kind}-${target.id}'),
                    onPressed: _running
                        ? null
                        : () {
                            _selectConnectorTarget(target);
                            if (_connectorAuthMode(target) ==
                                _ConnectorAuthMode.browserSession) {
                              unawaited(_openConnectorBrowserSetup(target));
                            }
                          },
                    icon: Icon(
                      profileExists ? Icons.settings : Icons.link,
                      size: 16,
                    ),
                    label: Text(profileExists ? 'Manage' : 'Connect'),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Widget _connectorSetupPanel() {
    final target = _selectedConnectorTarget;
    final requestPath = _connectorRequestPath(target);
    final requestFile = File(requestPath);
    final requestExists = requestFile.existsSync();
    final requestState = _connectorRequestState(target);
    final profilePath = _connectorProfilePath(target);
    final profileState = _connectorProfileState(target);
    final browserPath = _connectorBrowserRequestPath(target);
    final setupUrl = _connectorSetupUrl(target);
    final authMode = _connectorAuthMode(target);
    final browserSession = authMode == _ConnectorAuthMode.browserSession;
    final secretHint = browserSession
        ? 'No token needed - use browser sign-in'
        : authMode == _ConnectorAuthMode.botToken
        ? 'Paste ${target.name} bot token'
        : 'Paste ${target.name} API key or access token';
    return Container(
      key: const Key('connector-setup-panel'),
      padding: const EdgeInsets.all(14),
      decoration: _panelDecoration(),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              const Icon(Icons.route, color: Color(0xff00e87a)),
              const SizedBox(width: 8),
              const Expanded(
                child: Text(
                  'Connection Setup',
                  style: TextStyle(fontSize: 16, fontWeight: FontWeight.w800),
                ),
              ),
              _Tag(target.category),
            ],
          ),
          const SizedBox(height: 14),
          Text(
            target.name,
            key: const Key('connector-setup-title'),
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(fontSize: 24, fontWeight: FontWeight.w900),
          ),
          const SizedBox(height: 6),
          Text(
            target.detail,
            maxLines: 2,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(color: Color(0xffaab7ca), fontSize: 12),
          ),
          const SizedBox(height: 16),
          _connectorSetupLine(
            icon: Icons.account_tree,
            label: 'Route',
            value: target.isChannel ? 'Channel connector' : target.category,
          ),
          _connectorSetupLine(
            icon: Icons.vpn_key_outlined,
            label: 'Credential',
            value: _connectorCredentialMode(target),
          ),
          _connectorSetupLine(
            icon: Icons.badge_outlined,
            label: 'Profile',
            value: profileState,
          ),
          _connectorSetupLine(
            icon: Icons.travel_explore,
            label: 'Browser',
            value: setupUrl,
          ),
          _connectorSetupLine(
            icon: Icons.folder_open,
            label: 'Saved at',
            value: profilePath,
          ),
          const SizedBox(height: 12),
          TextField(
            key: const Key('connector-secret-input'),
            controller: _connectorSecretText,
            obscureText: true,
            enableSuggestions: false,
            autocorrect: false,
            style: const TextStyle(color: Color(0xfff4f7fb), fontSize: 13),
            decoration: InputDecoration(
              prefixIcon: const Icon(Icons.key, size: 18),
              hintText: secretHint,
              helperText: browserSession
                  ? 'Engel saves the browser session profile, not your password.'
                  : 'Secret is saved to Windows user environment, not JSON.',
              helperStyle: const TextStyle(
                color: Color(0xff8ba4bc),
                fontSize: 11,
              ),
              isDense: true,
              border: const OutlineInputBorder(),
            ),
            onSubmitted: (_) => unawaited(_saveConnectorConnection(target)),
          ),
          const SizedBox(height: 12),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              OutlinedButton.icon(
                key: const Key('connector-open-setup'),
                onPressed: _running
                    ? null
                    : () => unawaited(_openConnectorBrowserSetup(target)),
                icon: const Icon(Icons.travel_explore, size: 16),
                label: Text(
                  browserSession ? 'Open browser sign-in' : 'Open setup',
                ),
              ),
              OutlinedButton.icon(
                key: const Key('connector-save-connection'),
                onPressed: _running
                    ? null
                    : () => unawaited(_saveConnectorConnection(target)),
                icon: const Icon(Icons.save_outlined, size: 16),
                label: Text(browserSession ? 'Save session' : 'Save token'),
              ),
              OutlinedButton.icon(
                key: const Key('connector-test-connection'),
                onPressed: _running
                    ? null
                    : () => unawaited(_liveVerifyConnector(target)),
                icon: const Icon(Icons.verified_user_outlined, size: 16),
                label: Text(browserSession ? 'Test sign-in' : 'Test token'),
              ),
              OutlinedButton.icon(
                key: const Key('connector-open-engel-setup'),
                onPressed: () {
                  _selectConnectorTarget(target);
                  _showProviderSetupDialog(
                    initialPage: target.isChannel ? 'accounts' : 'api_keys',
                  );
                },
                icon: const Icon(Icons.manage_accounts, size: 16),
                label: const Text('Engel setup'),
              ),
              OutlinedButton.icon(
                key: const Key('connector-stage-selected'),
                onPressed: _running
                    ? null
                    : () => unawaited(_stageConnectorAndSelect(target)),
                icon: Icon(
                  requestExists ? Icons.refresh : Icons.link,
                  size: 16,
                ),
                label: Text(
                  requestExists ? 'Restage request' : 'Stage request',
                ),
              ),
              OutlinedButton.icon(
                key: const Key('connector-open-request'),
                onPressed: _running
                    ? null
                    : () => unawaited(_stageAndRevealConnectorRequest(target)),
                icon: const Icon(Icons.folder_open, size: 16),
                label: const Text('Open request'),
              ),
              OutlinedButton.icon(
                key: const Key('connector-show-receipt'),
                onPressed: _running
                    ? null
                    : () => unawaited(_showConnectorReceipt(target)),
                icon: const Icon(Icons.terminal, size: 16),
                label: const Text('Show receipt'),
              ),
            ],
          ),
          const SizedBox(height: 14),
          const Divider(color: Color(0xff303645), height: 1),
          const SizedBox(height: 14),
          Expanded(
            child: _connectorReceiptExpanded
                ? SingleChildScrollView(
                    key: const Key('connector-receipt-scroll'),
                    child: SelectableText(
                      _output,
                      key: const Key('connector-receipt-text'),
                      style: const TextStyle(
                        color: Color(0xffd7e4ef),
                        fontFamily: 'Consolas',
                        fontSize: 12,
                        height: 1.28,
                      ),
                    ),
                  )
                : ListView(
                    children: [
                      _connectorStepRow(
                        1,
                        browserSession
                            ? 'Open browser sign-in'
                            : 'Open provider setup',
                        browserSession
                            ? 'Opens an Engel-owned persistent browser window for $setupUrl and saves the session for later use.'
                            : 'Opens $setupUrl and writes a browser-control handoff at $browserPath.',
                      ),
                      _connectorStepRow(
                        2,
                        browserSession ? 'Save session' : 'Save token',
                        browserSession
                            ? 'No password or token is stored. The connector profile points Engel at the saved browser session.'
                            : 'Stores the secret in ${_connectorEnvVarForTarget(target)} and writes a non-secret connector profile.',
                      ),
                      _connectorStepRow(
                        3,
                        browserSession ? 'Test sign-in' : 'Test token',
                        browserSession
                            ? 'Checks whether the Engel browser profile can open the provider without a sign-in wall.'
                            : 'Live-verifies the saved secret against the real provider endpoint (falls back to a local profile check when no live endpoint is known), then marks the lane connected.',
                      ),
                      _connectorStepRow(
                        4,
                        'Optional request packet',
                        requestExists
                            ? 'Standalone request is ready at $requestPath.'
                            : 'Stage request only when a fallback packet is needed for the imported standalone bridge.',
                      ),
                      _connectorStepRow(
                        5,
                        'Current state',
                        '$profileState / $requestState',
                      ),
                    ],
                  ),
          ),
        ],
      ),
    );
  }

