  Widget _drivesPage() {
    final commands = {for (final command in rustCommands) command.key: command};
    final requiredRootLabels = const {
      'CT fast SSD': r'/opt/engel',
      'PowerEdge HDD archive': r'/mnt/engel-hdd-vault',
      'ROG workspace': appRoot,
    };
    final driveByLabel = {for (final drive in _drives) drive.label: drive};
    final rootsChecked = _drives.isNotEmpty;
    final requiredRootRows = [
      for (final entry in requiredRootLabels.entries)
        if (driveByLabel[entry.key] case final drive?)
          '${drive.exists ? 'FOUND' : 'MISSING'} ${drive.label}: ${drive.path} / ${drive.topLevelCount} top-level items / ${drive.directoryCount} dirs / ${drive.fileCount} files${drive.error.isEmpty ? '' : ' / ${drive.error}'}'
        else
          'NOT CHECKED ${entry.key}: ${entry.value} / use Rescan roots or the matching live route',
    ];
    final liveRootRows = [
      'CT 246 health: run CT status or Runtime readiness.',
      'Dell PowerEdge HDD mount: run Storage boundary verify; CT245 offline-vault routes remain disabled.',
      'ROG controller: run Workspace verify after local file changes.',
      for (final entry in requiredRootLabels.entries)
        if (driveByLabel[entry.key] case final drive?)
          '${drive.exists ? 'ONLINE' : 'OFFLINE'} ${drive.label}: ${drive.directoryCount} dirs, ${drive.fileCount} files, ${drive.topLevelCount} total / ${drive.path}'
        else
          'Awaiting live check for ${entry.key}: ${entry.value}',
    ];
    final driveOwnershipRows = [
      r'CT fast SSD owner: active runtime, chat, models, services / /opt/engel',
      r'PowerEdge HDD owner: archive and transferred external-drive capture / /mnt/engel-hdd-vault',
      'ROG owner: controller UI and desktop launcher / $appRoot',
      'Former laptop external drives are not required for active Engel operation after verified transfer.',
    ];
    final requiredRootsOnline = requiredRootLabels.keys
        .where((label) => driveByLabel[label]?.exists ?? false)
        .length;
    final missingRequiredRoots = [
      for (final entry in requiredRootLabels.entries)
        if (rootsChecked && !(driveByLabel[entry.key]?.exists ?? false))
          entry.key,
    ];
    final rootGateRows = [
      for (final entry in requiredRootLabels.entries)
        (
          label: entry.key,
          path: entry.value,
          owner: switch (entry.key) {
            'CT fast SSD' => 'Active runtime',
            'PowerEdge HDD archive' => 'Archive storage',
            'ROG workspace' => 'Controller UI',
            _ => 'Required root',
          },
          drive: driveByLabel[entry.key],
        ),
    ];
    String proofKeyForDrive(String label) {
      return switch (label) {
        'CT fast SSD' => 'engel_main_status',
        'PowerEdge HDD archive' => 'storage_boundary_paths',
        'ROG workspace' => 'workspace_verify',
        _ => 'external_memory_status',
      };
    }

    return _PageFrame(
      child: Row(
        children: [
          Expanded(
            flex: 5,
            child: Container(
              padding: const EdgeInsets.all(14),
              decoration: _panelDecoration(),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Row(
                    children: [
                      const Icon(Icons.folder_copy, color: Color(0xff00e87a)),
                      const SizedBox(width: 8),
                      const Expanded(
                        child: Text(
                          'Workspace storage',
                          style: TextStyle(
                            fontSize: 20,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                      ),
                      _Tag(
                        '${_drives.where((d) => d.exists).length}/${_drives.length} online',
                      ),
                    ],
                  ),
                  const SizedBox(height: 6),
                  const Text(
                    'See where Engel keeps active files, models, and archives.',
                    style: TextStyle(color: Color(0xffaebbd0), height: 1.35),
                  ),
                  const SizedBox(height: 12),
                  const Text(
                    'Common actions',
                    style: TextStyle(fontWeight: FontWeight.w800),
                  ),
                  const SizedBox(height: 8),
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    children: [
                      ActionChip(
                        avatar: const Icon(Icons.refresh, size: 18),
                        label: const Text('Refresh storage'),
                        onPressed: _drivesBusy ? null : _scanDrives,
                      ),
                      ActionChip(
                        avatar: const Icon(Icons.verified, size: 18),
                        label: const Text('Check workspace'),
                        onPressed: _running
                            ? null
                            : () => _runRust(commands['workspace_verify']!),
                      ),
                      ActionChip(
                        avatar: const Icon(Icons.memory, size: 18),
                        label: const Text('Rescan models'),
                        onPressed: () => unawaited(_rescanAllModels()),
                      ),
                      ActionChip(
                        avatar: const Icon(Icons.view_in_ar, size: 18),
                        label: const Text('Open 3D room'),
                        onPressed: _running
                            ? null
                            : () => unawaited(_openAgentMeetingRoomOffice()),
                      ),
                    ],
                  ),
                  const SizedBox(height: 4),
                  ExpansionTile(
                    key: const Key('storage-more-checks'),
                    tilePadding: EdgeInsets.zero,
                    childrenPadding: const EdgeInsets.only(bottom: 6),
                    title: const Text(
                      'More storage checks',
                      style: TextStyle(fontWeight: FontWeight.w800),
                    ),
                    subtitle: const Text(
                      'Server runtime and archive-path diagnostics.',
                    ),
                    children: [
                      Wrap(
                        spacing: 8,
                        runSpacing: 8,
                        children: [
                          ActionChip(
                            avatar: const Icon(Icons.monitor_heart, size: 18),
                            label: const Text('Check runtime readiness'),
                            onPressed: _running
                                ? null
                                : () => _runRust(
                                    rustCommands.firstWhere(
                                      (c) =>
                                          c.key == 'runtime_readiness_verify',
                                    ),
                                  ),
                          ),
                          ActionChip(
                            avatar: const Icon(Icons.storage, size: 18),
                            label: const Text('Check server storage'),
                            onPressed: _running
                                ? null
                                : () =>
                                      _runRust(commands['engel_main_status']!),
                          ),
                          ActionChip(
                            avatar: const Icon(Icons.sd_storage, size: 18),
                            label: const Text('Show archive paths'),
                            onPressed: _running
                                ? null
                                : () => _runRust(
                                    commands['storage_boundary_paths']!,
                                  ),
                          ),
                          ActionChip(
                            avatar: const Icon(Icons.security, size: 18),
                            label: const Text('Verify archive boundary'),
                            onPressed: _running
                                ? null
                                : () => _runRust(
                                    commands['storage_boundary_verify']!,
                                  ),
                          ),
                        ],
                      ),
                    ],
                  ),
                  const SizedBox(height: 12),
                  _requiredRootGate(
                    online: requiredRootsOnline,
                    total: requiredRootLabels.length,
                    missing: missingRequiredRoots,
                    rows: rootGateRows,
                  ),
                  const SizedBox(height: 12),
                  Expanded(
                    child: GridView.builder(
                      gridDelegate:
                          const SliverGridDelegateWithMaxCrossAxisExtent(
                            maxCrossAxisExtent: 380,
                            mainAxisExtent: 188,
                            mainAxisSpacing: 10,
                            crossAxisSpacing: 10,
                          ),
                      itemCount: _drives.length,
                      itemBuilder: (context, index) {
                        final drive = _drives[index];
                        return _DriveCard(
                          info: drive,
                          onProof: _running
                              ? null
                              : () => _runRust(
                                  commands[proofKeyForDrive(drive.label)]!,
                                ),
                        );
                      },
                    ),
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(width: 12),
          Expanded(
            flex: 4,
            child: Column(
              children: [
                Expanded(child: _outputPanel()),
                const SizedBox(height: 12),
                SizedBox(
                  height: 190,
                  child: _catalogPanel('Required Root Coverage', [
                    rootsChecked
                        ? 'Required roots online: $requiredRootsOnline/${requiredRootLabels.length}'
                        : 'Required roots online: not checked yet',
                    !rootsChecked
                        ? 'Missing required roots: not checked'
                        : missingRequiredRoots.isEmpty
                        ? 'Missing required roots: none'
                        : 'Missing required roots: ${missingRequiredRoots.join(', ')}',
                    ...requiredRootRows,
                  ], icon: Icons.folder_copy),
                ),
                const SizedBox(height: 12),
                SizedBox(
                  height: 178,
                  child: _catalogPanel(
                    'Live Root Check Routes',
                    liveRootRows,
                    icon: Icons.fact_check,
                  ),
                ),
                const SizedBox(height: 12),
                SizedBox(
                  height: 190,
                  child: _catalogPanel(
                    'Agentic Drive Ownership Matrix',
                    driveOwnershipRows,
                    icon: Icons.account_tree,
                  ),
                ),
                const SizedBox(height: 12),
                SizedBox(
                  height: 190,
                  child: _catalogPanel('Server Runtime Storage', [
                    r'/opt/engel must stay mounted on CT 246 fast SSD for active Engel AI Main runtime.',
                    r'/mnt/engel-hdd-vault is archive/storage only; CT245 offline-vault routes are disabled.',
                    '$appRoot stays the ROG controller workspace.',
                    for (final drive in _drives)
                      '${drive.label}: ${drive.exists ? 'online' : 'missing'} / ${drive.topLevelCount} top-level items / ${drive.path}',
                    'Free/local model folders: ${_freeModels.length}',
                    'Artifact files loaded: ${_artifacts.length}',
                  ], icon: Icons.storage),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _requiredRootGate({
    required int online,
    required int total,
    required List<String> missing,
    required List<({String label, String path, String owner, DriveInfo? drive})>
    rows,
  }) {
    final checked = rows.any((row) => row.drive != null);
    return Container(
      key: const Key('required-root-gate'),
      height: 316,
      padding: const EdgeInsets.all(12),
      decoration: _panelDecoration(),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              const Icon(Icons.account_tree, color: Color(0xff58c4ff)),
              const SizedBox(width: 8),
              const Expanded(
                child: Text(
                  'Required Root Gate Matrix',
                  style: TextStyle(fontSize: 16, fontWeight: FontWeight.w800),
                ),
              ),
              _Tag('$online/$total online'),
              const SizedBox(width: 6),
              _Tag(
                !checked
                    ? 'not checked'
                    : missing.isEmpty
                    ? 'all required roots online'
                    : 'missing ${missing.length}',
              ),
            ],
          ),
          const SizedBox(height: 10),
          Expanded(
            child: GridView.builder(
              key: const Key('required-root-gate-list'),
              physics: const NeverScrollableScrollPhysics(),
              gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
                maxCrossAxisExtent: 214,
                mainAxisExtent: 118,
                mainAxisSpacing: 8,
                crossAxisSpacing: 8,
              ),
              itemCount: rows.length,
              itemBuilder: (context, index) {
                final row = rows[index];
                final drive = row.drive;
                final checked = drive != null;
                final exists = drive?.exists ?? false;
                final cardColor = !checked
                    ? const Color(0xff58c4ff)
                    : exists
                    ? const Color(0xff00e87a)
                    : const Color(0xffff5c70);
                return Container(
                  key: Key('required-root-${row.label}'),
                  padding: const EdgeInsets.all(10),
                  decoration: BoxDecoration(
                    color: const Color(0xff101821),
                    borderRadius: BorderRadius.circular(7),
                    border: Border.all(color: cardColor),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Icon(
                            !checked
                                ? Icons.pending_actions
                                : exists
                                ? Icons.check_circle
                                : Icons.error_outline,
                            size: 16,
                            color: cardColor,
                          ),
                          const SizedBox(width: 6),
                          Expanded(
                            child: Text(
                              row.label,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                fontWeight: FontWeight.w800,
                                fontSize: 12,
                              ),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 6),
                      Text(
                        !checked
                            ? 'NOT CHECKED'
                            : exists
                            ? 'ONLINE'
                            : 'MISSING',
                        style: TextStyle(
                          color: cardColor,
                          fontSize: 11,
                          fontWeight: FontWeight.w900,
                          letterSpacing: 0,
                        ),
                      ),
                      const SizedBox(height: 4),
                      Text(
                        row.owner,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: Color(0xffd7e4ef),
                          fontSize: 11,
                        ),
                      ),
                      const SizedBox(height: 4),
                      Text(
                        drive == null
                            ? 'scan pending / ${row.path}'
                            : '${drive.topLevelCount} items / ${drive.path}',
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: Color(0xff8ba4bc),
                          fontSize: 10,
                          height: 1.18,
                        ),
                      ),
                    ],
                  ),
                );
              },
            ),
          ),
        ],
      ),
    );
  }

