  Widget _terminalFilesPage() {
    final commands = [
      rustCommands.firstWhere((c) => c.key == 'feature_search_terminal'),
      rustCommands.firstWhere((c) => c.key == 'feature_search_files'),
      rustCommands.firstWhere((c) => c.key == 'feature_search_preview'),
      rustCommands.firstWhere((c) => c.key == 'feature_search_logs'),
      rustCommands.firstWhere((c) => c.key == 'workspace_inventory_short'),
      rustCommands.firstWhere((c) => c.key == 'workspace_inventory_report'),
      rustCommands.firstWhere((c) => c.key == 'runtime_wsl_status'),
      rustCommands.firstWhere((c) => c.key == 'runtime_sandbox_status'),
      rustCommands.firstWhere((c) => c.key == 'patch_plan_preview'),
    ];
    final recentArtifacts = _artifacts.take(6).toList();
    final rootDirs = <String>[];
    // A portable EXE can be opened directly from ``app`` instead of through
    // the launcher.  Resolve the sibling workspace in that case so the page
    // still shows the real File Search/Terminal roots rather than an empty
    // ``workspace`` path relative to the caller's current directory.
    final workspaceRoot = _portableWorkspaceRoot();
    try {
      final dirs =
          workspaceRoot
              .listSync(followLinks: false)
              .whereType<Directory>()
              .toList()
            ..sort((a, b) => a.path.compareTo(b.path));
      for (final dir in dirs.take(10)) {
        rootDirs.add(dir.uri.pathSegments.where((s) => s.isNotEmpty).last);
      }
    } catch (_) {
      rootDirs.add('Workspace root scan unavailable');
    }

    return _PageFrame(
      child: Row(
        children: [
          Expanded(
            flex: 5,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Container(
                  padding: const EdgeInsets.all(14),
                  decoration: _panelDecoration(),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Row(
                        children: [
                          const Icon(Icons.terminal, color: Color(0xff00e87a)),
                          const SizedBox(width: 8),
                          const Expanded(
                            child: Text(
                              'Terminal & Files',
                              style: TextStyle(
                                fontSize: 20,
                                fontWeight: FontWeight.w800,
                              ),
                            ),
                          ),
                          _Tag('${_artifacts.length} artifacts'),
                          const SizedBox(width: 6),
                          _Tag('${rootDirs.length} root dirs'),
                        ],
                      ),
                      const SizedBox(height: 6),
                      const Text(
                        'Find files, receipts, previews, and the system tools that support them.',
                        style: TextStyle(
                          color: Color(0xffaebbd0),
                          height: 1.35,
                        ),
                      ),
                      const SizedBox(height: 12),
                      const Text(
                        'Common actions',
                        style: TextStyle(fontWeight: FontWeight.w800),
                      ),
                      const SizedBox(height: 8),
                      _compactActionGrid([
                        _ControlAction(
                          key: const Key('terminal-find-files'),
                          icon: Icons.folder_copy_outlined,
                          title: 'Find files',
                          subtitle: 'Find file and browser surfaces.',
                          onPressed: _running
                              ? null
                              : () => _runRust(commands[1]),
                        ),
                        _ControlAction(
                          key: const Key('terminal-find-receipts'),
                          icon: Icons.receipt_long_outlined,
                          title: 'Find receipts & logs',
                          subtitle: 'Find proof, receipt, and log routes.',
                          onPressed: _running
                              ? null
                              : () => _runRust(commands[3]),
                        ),
                        _ControlAction(
                          key: const Key('terminal-check-workspace'),
                          icon: Icons.inventory_2_outlined,
                          title: 'Check workspace',
                          subtitle: 'Read a quick workspace inventory.',
                          onPressed: _running
                              ? null
