  Widget _legacyBuildPipelinePage() {
    final commands = [
      rustCommands.firstWhere((c) => c.key == 'engel_main_status'),
      rustCommands.firstWhere((c) => c.key == 'engel_main_binaries'),
      rustCommands.firstWhere((c) => c.key == 'engel_main_bring_up'),
      rustCommands.firstWhere((c) => c.key == 'engel_main_install'),
      rustCommands.firstWhere((c) => c.key == 'engel_main_build'),
      rustCommands.firstWhere((c) => c.key == 'engel_main_dev_start'),
      rustCommands.firstWhere((c) => c.key == 'engel_main_dev_stop'),
      rustCommands.firstWhere((c) => c.key == 'engel_main_tauri_build'),
      rustCommands.firstWhere((c) => c.key == 'engel_main_verify'),
      rustCommands.firstWhere((c) => c.key == 'ui_shell_status'),
      rustCommands.firstWhere((c) => c.key == 'ui_shell_verify'),
      rustCommands.firstWhere((c) => c.key == 'rewrite_audit_verify'),
    ];
    final releaseDir = File(flutterEngelMainExe).parent.path;
    final appData = File('$releaseDir\\data\\app.so');
    final nativeAssets = File('$releaseDir\\native_assets.json');
    final releaseExe = File(flutterEngelMainExe);
    final stagedDistDir = File(stagedDistEngelMainExe).parent.path;
    final stagedDistExe = File(stagedDistEngelMainExe);
    final stagedDistData = File('$stagedDistDir\\data\\app.so');
    final stagedDistShortcut = File(
      '$appRoot\\dist\\EngelAI-Main-Flutter-Desktop-Shortcut-Placeholder.lnk',
    );
    String artifactState(File file) {
      if (!file.existsSync()) return 'MISSING - ${file.path}';
      final stat = file.statSync();
      return 'FOUND ${_formatBytes(stat.size)} modified ${stat.modified} - ${file.path}';
    }

    return _PageFrame(
      child: Row(
        children: [
          Expanded(
            flex: 5,
            child: Container(
              padding: const EdgeInsets.all(14),
