  @override
  Widget _outputPanel() {
    final routeId = _visibleRouteId;
    _routesWithResultsPanel.add(routeId);
    final routeLabel = _routeLabel(routeId);
    final displayOutput = _outputByRoute[routeId] ?? _idleOutputMessage;
    final workingHere = _running && _activeOutputRouteId == routeId;
    final idle = !workingHere && displayOutput == _idleOutputMessage;
    final activeOtherRoute =
        _running &&
            _activeOutputRouteId != null &&
            _activeOutputRouteId != routeId &&
            _routesWithResultsPanel.contains(_activeOutputRouteId)
        ? _activeOutputRouteId
        : null;
    final activeOtherLabel = activeOtherRoute == null
        ? null
        : _routeLabel(activeOtherRoute);
    final latestOtherRoute = _latestOtherResultsRoute(routeId);
    final latestOtherLabel = latestOtherRoute == null
        ? null
        : _routeLabel(latestOtherRoute);
    return Container(
      padding: const EdgeInsets.all(14),
      decoration: _panelDecoration(glow: _running),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          _sectionHeader(
            workingHere ? 'Working in $routeLabel' : 'Results for $routeLabel',
            icon: workingHere ? Icons.sync : Icons.task_alt_outlined,
            actions: [
              if (workingHere)
                const SizedBox(
                  width: 16,
                  height: 16,
                  child: CircularProgressIndicator(
                    strokeWidth: 2,
                    color: Color(0xff00e5ff),
                  ),
                ),
              if (!idle && !workingHere)
                IconButton(
                  tooltip: 'Clear $routeLabel result',
                  onPressed: _clearVisibleOutput,
                  icon: const Icon(Icons.close, size: 18),
                ),
            ],
          ),
          const SizedBox(height: 10),
          Expanded(
            child: idle
                ? LayoutBuilder(
                    builder: (context, constraints) {
                      return SingleChildScrollView(
                        child: ConstrainedBox(
                          constraints: BoxConstraints(
                            minHeight: constraints.maxHeight,
                          ),
                          child: Center(
                            child: Padding(
                              padding: const EdgeInsets.all(12),
                              child: Column(
                                mainAxisSize: MainAxisSize.min,
                                children: [
                                  Text(
                                    'No result on $routeLabel yet.',
                                    key: const Key('output-empty'),
                                    textAlign: TextAlign.center,
                                    style: const TextStyle(
                                      color: Color(0xffc4cede),
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                  const SizedBox(height: 6),
                                  const Text(
                                    'Choose an action on this page to see its result here.',
                                    textAlign: TextAlign.center,
                                    style: TextStyle(color: Color(0xff94a3b8)),
                                  ),
                                  if (activeOtherRoute != null &&
                                      activeOtherLabel != null) ...[
                                    const SizedBox(height: 14),
                                    Text(
                                      'Engel is working in $activeOtherLabel.',
                                      key: const Key(
                                        'output-active-work-location',
                                      ),
                                      textAlign: TextAlign.center,
                                      style: const TextStyle(
                                        color: Color(0xffaebbd0),
                                      ),
                                    ),
                                    const SizedBox(height: 8),
                                    OutlinedButton.icon(
                                      key: const Key('output-open-active-work'),
                                      onPressed: () =>
                                          _selectSectionById(activeOtherRoute),
                                      icon: const Icon(
                                        Icons.sync_rounded,
                                        size: 17,
                                      ),
                                      label: Text(
                                        'Open $activeOtherLabel progress',
                                      ),
                                    ),
                                  ] else if (latestOtherRoute != null &&
                                      latestOtherLabel != null) ...[
                                    const SizedBox(height: 14),
                                    Text(
                                      'The latest result is in $latestOtherLabel.',
                                      key: const Key(
