  });

  final SwarmDeviceNode device;
  final Offset position;
  final double depth;
  final double radius;
}

class _SwarmScenePainter extends CustomPainter {
  const _SwarmScenePainter({
    required this.nodes,
    required this.selectedId,
    required this.showWifi,
    this.animPhase = 0.0,
  });

  final List<_SwarmProjectedNode> nodes;
  final String selectedId;
  final bool showWifi;
  final double
  animPhase; // drives live graphics: pulse, particles, motion beyond static limits

  @override
  void paint(Canvas canvas, Size size) {
    // Rich cosmic background with subtle nebula gradient (Grok expert polish)
    final bg = Paint()
      ..shader = const LinearGradient(
        begin: Alignment.topLeft,
        end: Alignment.bottomRight,
        colors: [
          Color(0xff01040a),
          Color(0xff050c1f),
          Color(0xff081528),
          Color(0xff02060f),
        ],
      ).createShader(Offset.zero & size);
    canvas.drawRect(Offset.zero & size, bg);

    // Animated starfield for depth - phase shifts stars for live "cosmic" motion
    final starPaint = Paint()..color = const Color(0x55e0f0ff);
    final phase = animPhase;
    for (int i = 0; i < 110; i++) {
      final sx = ((i * 17.3 + phase * 12) % (size.width + 40)) - 20;
      final sy =
          (i * 29.1 + (i % 5) * 3 + math.sin(phase * 0.8 + i) * 1.5) %
          (size.height * 0.98);
      final r = ((i % 3) + 1) * (0.65 + math.sin(phase * 2 + i) * 0.15);
      canvas.drawCircle(Offset(sx, sy), r, starPaint);
      if (i % 7 == 0) {
        // extra bright twinkles
        canvas.drawCircle(
          Offset(sx, sy),
          r * 1.8,
          Paint()..color = const Color(0x22ffffff),
        );
      }
    }

    // Dramatic perspective grid
    final gridPaint = Paint()
      ..color = const Color(0x22a8d8ff)
      ..strokeWidth = 0.9;
    final horizon = size.height * 0.54;
    for (var i = -11; i <= 11; i++) {
      final x = size.width / 2 + i * size.width / 17;
      canvas.drawLine(
        Offset(x, horizon),
        Offset(size.width / 2 + i * size.width / 5.5, size.height * 0.99),
        gridPaint,
      );
    }
    for (var i = 0; i < 11; i++) {
      final y = horizon + i * (size.height - horizon) / 10;
      canvas.drawLine(Offset(4, y), Offset(size.width - 4, y), gridPaint);
    }

    // Enhanced WiFi / cluster connections + discovery highlights
    if (showWifi && nodes.isNotEmpty) {
      final hubs = nodes
          .where((n) => n.device.type == 'wifi' || n.device.type == 'android')
          .toList();
      final hub = hubs.isNotEmpty
          ? hubs.first
          : nodes.firstWhere(
              (n) => n.device.id == 'engel-main-pc',
              orElse: () => nodes.first,
            );
      for (final node in nodes) {
        if (node.device.id == hub.device.id) continue;
        final signal = node.device.signal.clamp(18.0, 100.0).toDouble();
        final isDiscovered =
            node.device.status.toLowerCase().contains('discovered') ||
            node.device.status == 'added-to-cluster';
        final baseAlpha = isDiscovered ? 0.55 : 0.28;
        final paint = Paint()
          ..color = _signalColor(
            signal,
          ).withValues(alpha: baseAlpha + signal / 280)
          ..strokeWidth = (isDiscovered ? 2.4 : 1.1) + signal / 88
          ..style = PaintingStyle.stroke;
        canvas.drawLine(hub.position, node.position, paint);
      }
      // Special glow rings for wifi/discovered hubs
      for (final wifi in hubs) {
        final isDisc = wifi.device.status.toLowerCase().contains('discovered');
        for (var ring = 1; ring <= (isDisc ? 5 : 3); ring++) {
          final rPhase = phase * (0.9 + ring * 0.2);
          final rScale =
              (2.6 + ring * (isDisc ? 1.15 : 1.0)) + math.sin(rPhase) * 0.25;
          final paint = Paint()
            ..style = PaintingStyle.stroke
            ..strokeWidth = (isDisc ? 1.8 : 1.0) + math.sin(rPhase * 1.3) * 0.3
            ..color =
                (isDisc
                        ? const Color(0xff00e5ff)
                        : _signalColor(wifi.device.signal))
                    .withValues(alpha: (isDisc ? 0.38 : 0.18) / ring);
          canvas.drawCircle(wifi.position, wifi.radius * rScale, paint);
        }
      }
    }

    // Draw nodes with premium layered graphics
    final sorted = [...nodes]..sort((a, b) => a.depth.compareTo(b.depth));
    for (final node in sorted) {
      final device = node.device;
      final selected = device.id == selectedId;
      final isDiscovered =
          device.status.toLowerCase().contains('discovered') ||
          device.status == 'added-to-cluster';
      final color = _swarmTypeColor(device);

      // Strong outer glow / halo - pulsing for discovered (live graphics)
      final pulse = isDiscovered
          ? (1.0 + math.sin(phase * 3.2 + (node.device.hashCode % 10)) * 0.18)
          : 1.0;
      final outerGlow = Paint()
        ..color = (isDiscovered ? const Color(0xff00e5ff) : color).withValues(
          alpha: isDiscovered ? 0.22 : 0.09,
        )
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 22);
      canvas.drawCircle(
        node.position,
        node.radius * (isDiscovered ? 2.35 : 1.85) * pulse,
        outerGlow,
      );

      // Shadow
      final shadow = Paint()
        ..color = Colors.black.withValues(alpha: 0.55)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 11);
      canvas.drawCircle(
        node.position + const Offset(0, 6),
        node.radius * 0.92,
        shadow,
      );

      // Live particle swarm around discovered / high-signal nodes (first choice for graphics beyond basic Canvas)
      if (isDiscovered || device.signal > 75) {
        final pCount = isDiscovered ? 7 : 4;
        for (int p = 0; p < pCount; p++) {
          final pa = phase * (1.6 + p * 0.3) + (p * 2.1);
          final pr = node.radius * (1.4 + math.sin(pa * 0.7) * 0.3);
          final px = node.position.dx + math.cos(pa) * pr;
          final py = node.position.dy + math.sin(pa * 1.1) * (pr * 0.6);
          final pp = Paint()
            ..color = (isDiscovered ? const Color(0xff00e5ff) : color)
                .withValues(alpha: 0.65 + math.sin(pa * 2) * 0.25);
          canvas.drawCircle(Offset(px, py), 1.8 + math.sin(pa) * 0.6, pp);
        }
      }

      // Selection rings (dramatic for Grok quality)
      if (selected) {
        for (int r = 0; r < 3; r++) {
          final ring = Paint()
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1.6 + r * 0.6
            ..color = const Color(0xff00e5ff).withValues(alpha: 0.9 - r * 0.28);
          canvas.drawCircle(node.position, node.radius + 11 + r * 5.5, ring);
        }
      }

      // Main body
      final fill = Paint()..color = color;
      final border = Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = selected ? 2.8 : 1.4
        ..color = selected ? const Color(0xffd4f0ff) : const Color(0xff3a475f);

      if (device.type == 'android') {
        final rect = Rect.fromCenter(
          center: node.position,
          width: node.radius * 1.42,
          height: node.radius * 2.2,
        );
        canvas.drawRRect(
          RRect.fromRectAndRadius(rect, Radius.circular(node.radius * 0.38)),
          fill,
        );
        canvas.drawRRect(
          RRect.fromRectAndRadius(rect, Radius.circular(node.radius * 0.38)),
          border,
        );
      } else if (device.type == 'windows' || device.type == 'server') {
        final rect = Rect.fromCenter(
          center: node.position,
          width: node.radius * 2.35,
          height: node.radius * 1.42,
        );
        canvas.drawRRect(
          RRect.fromRectAndRadius(rect, const Radius.circular(7)),
          fill,
        );
        canvas.drawRRect(
          RRect.fromRectAndRadius(rect, const Radius.circular(7)),
          border,
        );
      } else {
        canvas.drawCircle(node.position, node.radius, fill);
        canvas.drawCircle(node.position, node.radius, border);
      }

      // Inner highlight
      final highlight = Paint()..color = Colors.white.withValues(alpha: 0.22);
      canvas.drawCircle(
        node.position + Offset(-node.radius * 0.28, -node.radius * 0.32),
        node.radius * 0.42,
        highlight,
      );

      // Status indicator (larger + neon for discovered)
      final statusColor = _swarmStatusColor(device.status);
      final statusPaint = Paint()
        ..color = isDiscovered ? const Color(0xff00e5ff) : statusColor;
      canvas.drawCircle(
        node.position + Offset(node.radius * 0.78, -node.radius * 0.78),
        math.max(4.2, node.radius * (isDiscovered ? 0.48 : 0.36)),
        statusPaint,
      );
      if (isDiscovered) {
        final ring = Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.2
          ..color = const Color(0xff00e5ff).withValues(alpha: 0.7);
        canvas.drawCircle(
          node.position + Offset(node.radius * 0.78, -node.radius * 0.78),
          node.radius * 0.58,
          ring,
        );
      }

      // Premium label pill
      final label = device.name.length > 20
          ? '${device.name.substring(0, 18)}…'
          : device.name;
      final textPainter = TextPainter(
        text: TextSpan(
          text: label,
          style: TextStyle(
            color: selected || isDiscovered
                ? const Color(0xffd4f0ff)
                : const Color(0xffe8f0ff),
            fontSize: selected ? 12.5 : 11,
            fontWeight: selected || isDiscovered
                ? FontWeight.w900
                : FontWeight.w700,
            shadows: const [Shadow(color: Color(0x66000000), blurRadius: 3)],
          ),
        ),
        maxLines: 1,
        textDirection: TextDirection.ltr,
      )..layout(maxWidth: 190);
      final labelOffset =
          node.position + Offset(-textPainter.width / 2, node.radius + 9);
      final labelRect = Rect.fromLTWH(
        labelOffset.dx - 8,
        labelOffset.dy - 4,
        textPainter.width + 16,
        textPainter.height + 8,
      );
      canvas.drawRRect(
        RRect.fromRectAndRadius(labelRect, const Radius.circular(6)),
        Paint()..color = const Color(0xcc050a14),
      );
      if (isDiscovered) {
        canvas.drawRRect(
          RRect.fromRectAndRadius(
            labelRect.inflate(1),
            const Radius.circular(7),
          ),
          Paint()
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1
            ..color = const Color(0x6600e5ff),
        );
      }
      textPainter.paint(canvas, labelOffset);
    }
  }

  @override
  bool shouldRepaint(covariant _SwarmScenePainter oldDelegate) {
    return oldDelegate.nodes != nodes ||
        oldDelegate.selectedId != selectedId ||
        oldDelegate.showWifi != showWifi ||
        (animPhase - oldDelegate.animPhase).abs() >
            0.01; // trigger on animation
  }
}

Color _swarmStatusColor(String status) {
  final lower = status.toLowerCase();
  if (lower == 'verified_live' ||
      lower.contains('online') ||
      lower.contains('ready')) {
    return const Color(0xff00e87a);
  }
  if (lower.contains('stale') ||
      lower.contains('offline') ||
      lower.contains('needs connection') ||
      lower.contains('error') ||
      lower.contains('failed')) {
    return const Color(0xffff4d6d);
  }
  if (lower.contains('standby') ||
      lower.contains('draft') ||
      lower.contains('scan') ||
      lower.contains('out of date') ||
      lower.contains('reachable') ||
      lower.contains('lan_seen')) {
    return const Color(0xffffc857);
  }
  return const Color(0xff7d8995);
}

Color _swarmTypeColor(SwarmDeviceNode device) {
  return switch (device.type) {
    'android' => const Color(0xff22c55e),
    'windows' => const Color(0xff00e5ff),
    'sub_engel' => const Color(0xff58c4ff),
    'wifi' => const Color(0xffffc857),
    'server' => const Color(0xff8b5cf6),
    'llm' => const Color(0xff00e87a),
    'display' => const Color(0xffffc857),
    'network' => const Color(0xff94a3b8),
    _ => const Color(0xff64748b),
  };
}

Color _signalColor(double signal) {
  if (signal >= 80) return const Color(0xff00e87a);
  if (signal >= 55) return const Color(0xffffc857);
  return const Color(0xffff7a3d);
}

class _StatusPill extends StatelessWidget {
  const _StatusPill({required this.label, required this.busy, this.healthy});

  final String label;
  final bool busy;
  final bool? healthy;

  @override
  Widget build(BuildContext context) {
    final color = busy
        ? const Color(0xffffc857)
        : healthy == true
        ? const Color(0xff00e87a)
        : healthy == false
        ? const Color(0xffff5d73)
        : const Color(0xff94a3b8);
    final background = busy
        ? const Color(0xff33250d)
        : healthy == true
        ? const Color(0xff102217)
        : healthy == false
        ? const Color(0xff2b1218)
        : const Color(0xff17202b);
    return Container(
      height: 30,
      padding: const EdgeInsets.symmetric(horizontal: 10),
      decoration: BoxDecoration(
        color: background,
        borderRadius: BorderRadius.circular(15),
        border: Border.all(color: color),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(
            busy
                ? Icons.sync
                : healthy == true
                ? Icons.check_circle_outline
                : healthy == false
                ? Icons.error_outline
                : Icons.info_outline,
            size: 15,
            color: color,
          ),
          const SizedBox(width: 6),
          Text(label, overflow: TextOverflow.ellipsis),
        ],
      ),
    );
  }
}

