BoxDecoration _panelDecoration({bool prominent = false, bool glow = false}) {
  return BoxDecoration(
    color: prominent ? const Color(0xff1c2436) : const Color(0xff1a1f2e),
    borderRadius: BorderRadius.circular(14),
    border: Border.all(
      color: glow
          ? const Color(0xff00e5ff).withValues(alpha: 0.25)
          : const Color(0xff2f3a52),
      width: glow ? 1.5 : 1,
    ),
    gradient: LinearGradient(
      begin: Alignment.topLeft,
      end: Alignment.bottomRight,
      colors: prominent
          ? [const Color(0xff1f2a42), const Color(0xff1a1f2e)]
          : [const Color(0xff1d2533), const Color(0xff181d2b)],
      stops: const [0.0, 1.0],
    ),
    boxShadow: [
      const BoxShadow(
        color: Color(0x66000000),
        blurRadius: 28,
        offset: Offset(0, 14),
      ),
      if (glow)
        BoxShadow(
          color: const Color(0x3300e5ff),
          blurRadius: 18,
          offset: const Offset(0, 4),
        ),
    ],
  );
}

