}

String _formatBytes(int bytes) {
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  var value = bytes.toDouble();
  var unit = 0;
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024;
    unit++;
  }
  return '${value.toStringAsFixed(unit == 0 ? 0 : 1)} ${units[unit]}';
}

// ---------------------------------------------------------------------------
// 12 AI TERMS — animated glossary grid (page id `ai_terms`, a tab of the
// Training window). One repeating controller drives all twelve glyphs; it only
// exists while the tab is on screen, because _pageFor builds the active page
// alone and disposing the State stops the ticker.
// ---------------------------------------------------------------------------

enum _TermGlyph {
  llm,
  hallucination,
  token,
  trainInfer,
  fineTune,
  rlhf,
  distillation,
  rag,
  chainOfThought,
  weights,
  validationLoss,
  codingAgent,
}

