class _NmapReconGrid extends StatefulWidget {
  const _NmapReconGrid({required this.onOpenSurface});

  final ValueChanged<String> onOpenSurface;

  @override
  State<_NmapReconGrid> createState() => _NmapReconGridState();
}

class _NmapReconGridState extends State<_NmapReconGrid>
    with SingleTickerProviderStateMixin {
  var _disableAnimations = false;

  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 3),
  );

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _disableAnimations = MediaQuery.disableAnimationsOf(context);
    if (_disableAnimations) {
      _controller
        ..stop()
        ..value = 0;
    } else if (!_controller.isAnimating) {
      _controller.repeat();
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(18, 26, 18, 28),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            const Text(
              'NMAP RECON',
              textAlign: TextAlign.center,
              style: TextStyle(
                color: Color(0xfff4f4f6),
                fontSize: 32,
                fontWeight: FontWeight.w800,
                fontFamily: 'Consolas',
                letterSpacing: 7,
              ),
            ),
            const SizedBox(height: 10),
            const Text(
              'EIGHT NSE SCRIPTS.  ONE FIREWALL LESSON.',
              textAlign: TextAlign.center,
              style: TextStyle(
                color: Color(0xff8a8a94),
                fontSize: 12,
                fontFamily: 'Consolas',
                letterSpacing: 4,
              ),
            ),
            const SizedBox(height: 22),
            const _NmapAuthBanner(),
            const SizedBox(height: 22),
            TickerMode(
              key: const Key('nmap-recon-motion'),
              enabled: !_disableAnimations,
              child: LayoutBuilder(
                builder: (context, box) {
                  const gap = 16.0;
                  final twoUp = box.maxWidth >= 780;
                  final cardWidth = twoUp
                      ? (box.maxWidth - gap) / 2
                      : box.maxWidth;
                  return Wrap(
                    spacing: gap,
                    runSpacing: gap,
                    children: [
                      for (final script in _nmapScripts)
                        SizedBox(
                          width: cardWidth,
                          child: _NmapScriptCard(
                            script: script,
                            animation: _controller,
                            reduceMotion: _disableAnimations,
                          ),
                        ),
                    ],
                  );
                },
              ),
            ),
            const SizedBox(height: 24),
            _NmapEvasionPanel(
              onOpenSwarm: () => widget.onOpenSurface('device_swarm_3d'),
            ),
            const SizedBox(height: 24),
            const Text(
              'SCAN WHAT YOU OWN.  LEARN WHAT IT EXPOSES.',
              textAlign: TextAlign.center,
              style: TextStyle(
                color: Color(0xff8a8a94),
                fontSize: 12,
                fontFamily: 'Consolas',
                letterSpacing: 3,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

