class _NmapEyePainter extends CustomPainter {
  _NmapEyePainter({required this.color, required this.t});

  final Color color;
  final double t;

  @override
  void paint(Canvas canvas, Size size) {
    final cx = size.width / 2;
    final cy = size.height / 2;
    final halfW = size.width * 0.46;
    final halfH = size.height * 0.42;
    final outline = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.6
      ..color = color.withValues(alpha: 0.9);

    // almond eye = two mirrored quadratic arcs
    final eye = Path()
      ..moveTo(cx - halfW, cy)
      ..quadraticBezierTo(cx, cy - halfH * 2, cx + halfW, cy)
      ..quadraticBezierTo(cx, cy + halfH * 2, cx - halfW, cy)
      ..close();
    canvas.drawPath(eye, outline);

    // iris sweeps side to side like a scan, pupil pulses
    final sweep = math.sin(t * math.pi * 2) * (halfW * 0.38);
    final irisCenter = Offset(cx + sweep, cy);
    canvas.drawCircle(irisCenter, halfH * 0.92, outline);
    final pulse = 0.5 + 0.5 * math.sin(t * math.pi * 2);
    canvas.drawCircle(
      irisCenter,
      halfH * (0.32 + pulse * 0.18),
      Paint()..color = color.withValues(alpha: 0.95),
    );
    // catch-light
    canvas.drawCircle(
      irisCenter + Offset(-halfH * 0.28, -halfH * 0.28),
      1.3,
      Paint()..color = Colors.white.withValues(alpha: 0.9),
    );
  }

  @override
  bool shouldRepaint(covariant _NmapEyePainter old) =>
      old.t != t || old.color != color;
}

class _AiTermsGrid extends StatefulWidget {
  const _AiTermsGrid({required this.onOpenSurface});

  final ValueChanged<String> onOpenSurface;

  @override
  State<_AiTermsGrid> createState() => _AiTermsGridState();
}

class _AiTermsGridState extends State<_AiTermsGrid>
    with SingleTickerProviderStateMixin {
  var _selectedIndex = 0;
  var _disableAnimations = false;
  final _detailAnchorKey = GlobalKey();
  final _scrollController = ScrollController();
  Map<String, dynamic>? _systemsStatus;
  var _systemsLoading = false;
  var _systemsError = '';

  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 6),
  );

  @override
  void initState() {
    super.initState();
    unawaited(_refreshSystemsStatus());
  }

  Map<String, dynamic>? _systemFor(String number) {
    final raw = _systemsStatus?['systems'];
    if (raw is! List) return null;
    for (final item in raw) {
      if (item is Map && item['id']?.toString() == number) {
        return Map<String, dynamic>.from(item);
      }
    }
    return null;
  }

  Future<void> _refreshSystemsStatus() async {
    if (_systemsLoading) return;
    if (mounted) {
      setState(() {
        _systemsLoading = true;
        _systemsError = '';
      });
    }
    final client = HttpClient()
      ..connectionTimeout = const Duration(seconds: 4)
      ..idleTimeout = const Duration(seconds: 12);
    try {
      final request = await client.getUrl(
        Uri.parse(engelMainAiSystemsStatusUrl),
      );
      request.headers.set(HttpHeaders.acceptHeader, 'application/json');
      final response = await request.close().timeout(
        const Duration(seconds: 15),
      );
      final body = await response.transform(utf8.decoder).join();
      final parsed = jsonDecode(body);
      if (parsed is! Map<String, dynamic>) {
        throw const FormatException(
          'AI systems service returned a non-object payload',
        );
      }
      if (!mounted) return;
      setState(() {
        _systemsStatus = parsed;
        if (response.statusCode < 200 || response.statusCode >= 300) {
          _systemsError =
              (parsed['status'] ?? 'AI systems proof needs attention')
                  .toString();
        }
      });
    } catch (error) {
      if (!mounted) return;
      setState(() => _systemsError = error.toString());
    } finally {
      client.close(force: true);
      if (mounted) setState(() => _systemsLoading = false);
    }
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _disableAnimations = MediaQuery.disableAnimationsOf(context);
    if (_disableAnimations) {
      _controller
        ..stop()
        ..value = 0;
    } else if (!_controller.isAnimating) {
      _controller.repeat();
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    _scrollController.dispose();
    super.dispose();
  }

  void _selectTerm(int index, {required bool compactLayout}) {
    if (index < 0 || index >= _aiTerms.length) return;
    if (index != _selectedIndex) {
      setState(() => _selectedIndex = index);
    }
    if (!compactLayout) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      if (!_scrollController.hasClients) return;
      unawaited(
        _scrollController.animateTo(
          0,
          duration: _disableAnimations
              ? Duration.zero
              : const Duration(milliseconds: 220),
          curve: Curves.easeOutCubic,
        ),
      );
    });
  }

  void _selectRelatedTerm(String termNumber, {required bool compactLayout}) {
    final index = _aiTerms.indexWhere((term) => term.number == termNumber);
    _selectTerm(index, compactLayout: compactLayout);
  }

  Widget _termCards(double maxWidth, {required bool compactLayout}) {
    const gap = 16.0;
    final twoUp = maxWidth >= 760;
    final cardWidth = twoUp ? (maxWidth - gap) / 2 : maxWidth;
    return Wrap(
      spacing: gap,
      runSpacing: gap,
      children: [
        for (var index = 0; index < _aiTerms.length; index++)
          SizedBox(
            width: cardWidth,
            child: _AiTermCard(
              term: _aiTerms[index],
              systemState: _systemFor(_aiTerms[index].number),
              animation: _controller,
              reduceMotion: _disableAnimations,
              selected: index == _selectedIndex,
              onTap: () => _selectTerm(index, compactLayout: compactLayout),
            ),
          ),
      ],
    );
  }

  Widget _detail(_AiTerm term, {required bool compactLayout}) {
    return KeyedSubtree(
      key: _detailAnchorKey,
      child: AnimatedSwitcher(
        duration: _disableAnimations
            ? Duration.zero
            : const Duration(milliseconds: 180),
        child: _AiTermDetail(
          key: ValueKey(term.number),
          term: term,
          systemState: _systemFor(term.number),
          onSelectRelated: (termNumber) =>
              _selectRelatedTerm(termNumber, compactLayout: compactLayout),
          onOpenSurface: () => widget.onOpenSurface(term.surfaceId),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      controller: _scrollController,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(18, 26, 18, 28),
        child: Column(
          children: [
            const Text(
              '12 AI TERMS',
              textAlign: TextAlign.center,
              style: TextStyle(
                color: Color(0xfff4f4f6),
                fontSize: 34,
                fontWeight: FontWeight.w800,
                fontFamily: 'Consolas',
                letterSpacing: 7,
              ),
            ),
            const SizedBox(height: 12),
            const Text(
              'ALL IN MOTION.  ALL IN ONE PLACE.',
              textAlign: TextAlign.center,
              style: TextStyle(
                color: Color(0xff8a8a94),
                fontSize: 12,
                fontFamily: 'Consolas',
                letterSpacing: 5,
              ),
            ),
            const SizedBox(height: 14),
            Wrap(
              alignment: WrapAlignment.center,
              spacing: 8,
              runSpacing: 8,
              crossAxisAlignment: WrapCrossAlignment.center,
              children: [
                Container(
                  key: const Key('ai-systems-live-status'),
                  padding: const EdgeInsets.symmetric(
                    horizontal: 10,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    color:
                        (_systemsStatus?['ok'] == true
                                ? _aiTermGreen
                                : _systemsLoading
                                ? _aiTermAmber
                                : _aiTermRed)
                            .withValues(alpha: 0.1),
                    border: Border.all(
                      color:
                          (_systemsStatus?['ok'] == true
                                  ? _aiTermGreen
                                  : _systemsLoading
                                  ? _aiTermAmber
                                  : _aiTermRed)
                              .withValues(alpha: 0.6),
                    ),
                    borderRadius: BorderRadius.circular(6),
                  ),
                  child: Text(
                    _systemsStatus?['ok'] == true
                        ? '${_systemsStatus?['ready_count'] ?? 0} / ${_systemsStatus?['system_count'] ?? 12} SYSTEMS VERIFIED'
                        : _systemsLoading
                        ? 'CHECKING REAL SYSTEMS'
                        : '${_systemsStatus?['ready_count'] ?? 0} / ${_systemsStatus?['system_count'] ?? 12} VERIFIED',
                    style: TextStyle(
                      color: _systemsStatus?['ok'] == true
                          ? _aiTermGreen
                          : _systemsLoading
                          ? _aiTermAmber
                          : _aiTermRed,
                      fontSize: 10,
                      fontFamily: 'Consolas',
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                ),
                IconButton(
                  key: const Key('ai-systems-refresh'),
                  onPressed: _systemsLoading
                      ? null
                      : () => unawaited(_refreshSystemsStatus()),
                  tooltip: 'Refresh operational AI system proof',
                  icon: _systemsLoading
                      ? const SizedBox(
                          width: 18,
                          height: 18,
                          child: CircularProgressIndicator(strokeWidth: 2),
                        )
                      : const Icon(Icons.refresh, size: 19),
                ),
              ],
            ),
            if (_systemsError.isNotEmpty) ...[
              const SizedBox(height: 7),
              Text(
                _systemsError,
                key: const Key('ai-systems-status-error'),
                textAlign: TextAlign.center,
                style: const TextStyle(color: _aiTermRed, fontSize: 11),
              ),
            ],
            const SizedBox(height: 30),
            TickerMode(
              key: const Key('ai-terms-motion'),
              enabled: !_disableAnimations,
              child: LayoutBuilder(
                builder: (context, box) {
                  final selected = _aiTerms[_selectedIndex];
                  final compactLayout = box.maxWidth < 1180;
                  if (!compactLayout) {
                    const detailWidth = 390.0;
                    const gap = 18.0;
                    return Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Expanded(
                          child: _termCards(
                            box.maxWidth - detailWidth - gap,
                            compactLayout: false,
                          ),
                        ),
                        const SizedBox(width: gap),
                        SizedBox(
                          width: detailWidth,
                          child: _detail(selected, compactLayout: false),
                        ),
                      ],
                    );
                  }
                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      _detail(selected, compactLayout: true),
                      const SizedBox(height: 18),
                      _termCards(box.maxWidth, compactLayout: true),
                    ],
                  );
                },
              ),
            ),
            const SizedBox(height: 30),
            const Text(
              'WATCH THE SYSTEM.  LEARN THE LANGUAGE.',
              textAlign: TextAlign.center,
              style: TextStyle(
                color: Color(0xff8a8a94),
                fontSize: 12,
                fontFamily: 'Consolas',
                letterSpacing: 4,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

