  Widget _relatedControl(String related) {
    final parts = related.trim().split(RegExp(r'\s+'));
    final termNumber = parts.first;
    final termTitle = parts.skip(1).join(' ');
    void activate() => onSelectRelated(termNumber);
    return Semantics(
      button: true,
      label: 'View related AI term $termNumber: $termTitle',
      hint: 'Shows $termTitle in the glossary',
      onTap: activate,
      excludeSemantics: true,
      child: OutlinedButton(
        key: Key('ai-term-related-${term.number}-$termNumber'),
        onPressed: activate,
        style: OutlinedButton.styleFrom(
          foregroundColor: const Color(0xffe1e4eb),
          backgroundColor: term.color.withValues(alpha: 0.08),
          side: BorderSide(color: term.color.withValues(alpha: 0.5)),
          minimumSize: const Size(0, 48),
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
          tapTargetSize: MaterialTapTargetSize.padded,
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(7)),
