          ),
        ],
      ),
    );
  }
}

class _TermGlyphPainter extends CustomPainter {
  _TermGlyphPainter({
    required this.glyph,
    required this.color,
    required this.t,
  });

  final _TermGlyph glyph;
  final Color color;
  final double t;

  Paint _stroke([double alpha = 0.85, double width = 1.4]) => Paint()
    ..style = PaintingStyle.stroke
    ..strokeWidth = width
    ..color = color.withValues(alpha: alpha.clamp(0.0, 1.0));

  Paint _fill([double alpha = 1.0]) => Paint()
    ..style = PaintingStyle.fill
    ..color = color.withValues(alpha: alpha.clamp(0.0, 1.0));

  void _label(
    Canvas canvas,
    String text,
    Offset center, {
    required Color textColor,
    double size = 9,
    bool bold = false,
  }) {
    final painter = TextPainter(
      text: TextSpan(
        text: text,
        style: TextStyle(
          color: textColor,
          fontSize: size,
          fontFamily: 'Consolas',
          fontWeight: bold ? FontWeight.w700 : FontWeight.w400,
          letterSpacing: 0.6,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    painter.paint(
      canvas,
      center - Offset(painter.width / 2, painter.height / 2),
    );
  }

  /// Pixel-art helper shared by RLHF and Coding Agent.
  void _creature(Canvas canvas, Offset center) {
    const rows = <String>[
      '00111100',
      '01111110',
      '11111111',
      '11011011',
      '11111111',
      '00100100',
      '01011010',
    ];
    const cell = 4.0;
    final originX = center.dx - rows.first.length * cell / 2;
    final originY = center.dy - rows.length * cell / 2;
    final paint = Paint()..color = _aiTermCreature;
    for (var r = 0; r < rows.length; r++) {
      for (var c = 0; c < rows[r].length; c++) {
        if (rows[r][c] != '1') continue;
        canvas.drawRect(
          Rect.fromLTWH(originX + c * cell, originY + r * cell, cell, cell),
          paint,
        );
      }
    }
  }

  @override
  void paint(Canvas canvas, Size size) {
    switch (glyph) {
      case _TermGlyph.llm:
        _paintLlm(canvas, size);
      case _TermGlyph.hallucination:
        _paintHallucination(canvas, size);
      case _TermGlyph.token:
        _paintToken(canvas, size);
      case _TermGlyph.trainInfer:
        _paintTrainInfer(canvas, size);
      case _TermGlyph.fineTune:
        _paintFineTune(canvas, size);
      case _TermGlyph.rlhf:
        _paintRlhf(canvas, size);
      case _TermGlyph.distillation:
        _paintDistillation(canvas, size);
      case _TermGlyph.rag:
        _paintRag(canvas, size);
      case _TermGlyph.chainOfThought:
        _paintChainOfThought(canvas, size);
      case _TermGlyph.weights:
        _paintWeights(canvas, size);
      case _TermGlyph.validationLoss:
        _paintValidationLoss(canvas, size);
      case _TermGlyph.codingAgent:
        _paintCodingAgent(canvas, size);
    }
  }

  void _paintLlm(Canvas canvas, Size size) {
    final cx = size.width / 2;
    final cy = size.height / 2;
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        Rect.fromCenter(center: Offset(cx, cy), width: 60, height: 56),
        const Radius.circular(6),
      ),
      _stroke(),
    );
    final leftX = cx - 62;
    final rightX = cx + 62;
    for (var i = 0; i < 3; i++) {
      final y = cy - 20 + i * 20;
      canvas.drawCircle(Offset(leftX, y), 3, _fill(0.9));
      canvas.drawCircle(Offset(rightX, y), 3, _fill(0.9));
      canvas.drawLine(Offset(leftX + 5, y), Offset(cx - 30, y), _stroke(0.3));
      canvas.drawLine(Offset(cx + 30, y), Offset(rightX - 5, y), _stroke(0.3));
    }
    final pulse = 0.5 + 0.5 * math.sin(t * math.pi * 2);
    canvas.drawCircle(Offset(cx, cy), 4 + pulse * 3, _fill(0.9));
    final travel = (t * 2) % 1.0;
    canvas.drawCircle(
      Offset(leftX + (rightX - leftX) * travel, cy),
      2.5,
      _fill(0.95),
    );
  }

  void _paintHallucination(Canvas canvas, Size size) {
    final cx = size.width / 2;
    final cy = size.height / 2;
    final flicker = 0.5 + 0.5 * math.sin(t * math.pi * 4).abs();
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        Rect.fromCenter(center: Offset(cx, cy - 4), width: 112, height: 48),
        const Radius.circular(10),
      ),
      _stroke(flicker),
    );
    final tail = Path()
      ..moveTo(cx + 22, cy + 20)
      ..lineTo(cx + 34, cy + 34)
      ..lineTo(cx + 34, cy + 19);
    canvas.drawPath(tail, _stroke(flicker));
    _label(
      canvas,
      '?!',
      Offset(cx, cy - 4),
      textColor: color.withValues(alpha: flicker),
      size: 17,
      bold: true,
    );
  }

  void _paintToken(Canvas canvas, Size size) {
    const labels = ['UN', 'BELIEV', 'ABLE'];
    const widths = [38.0, 62.0, 46.0];
    final active = (t * 3).floor() % 3;
    var x = size.width - (widths[0] + widths[1] + widths[2] + 12) - 4;
    for (var i = 0; i < 3; i++) {
      final on = i == active;
      final rect = RRect.fromRectAndRadius(
        Rect.fromLTWH(x, size.height / 2 - 17, widths[i], 34),
        const Radius.circular(5),
      );
      if (on) canvas.drawRRect(rect, _fill(0.16));
      canvas.drawRRect(rect, _stroke(on ? 1.0 : 0.4));
      _label(
        canvas,
        labels[i],
        Offset(x + widths[i] / 2, size.height / 2),
        textColor: color.withValues(alpha: on ? 1.0 : 0.6),
        size: 9,
        bold: on,
      );
      x += widths[i] + 6;
    }
  }

  void _paintTrainInfer(Canvas canvas, Size size) {
    final cy = size.height / 2;
    final loop = Offset(size.width * 0.26, cy);
    canvas.drawCircle(loop, 22, _stroke(0.8));
    final angle = t * math.pi * 2;
    canvas.drawCircle(
      loop + Offset(math.cos(angle) * 22, math.sin(angle) * 22),
      4,
      _fill(),
    );
    canvas.drawLine(
      Offset(size.width * 0.52, cy - 32),
      Offset(size.width * 0.52, cy + 32),
      _stroke(0.45),
    );
    final triX = size.width * 0.64;
    final triangle = Path()
      ..moveTo(triX, cy - 18)
      ..lineTo(triX + 30, cy)
      ..lineTo(triX, cy + 18)
      ..close();
    canvas.drawPath(triangle, _stroke(0.9));
    final travel = (t * 1.5) % 1.0;
    canvas.drawCircle(Offset(triX + 36 + travel * 20, cy), 3.5, _fill(0.95));
  }

  void _paintFineTune(Canvas canvas, Size size) {
    final cx = size.width / 2;
    final top = size.height / 2 - 24;
    final funnel = Path()
      ..moveTo(cx - 44, top)
      ..lineTo(cx + 44, top)
      ..lineTo(cx, top + 52)
      ..close();
    canvas.drawPath(funnel, _stroke(0.85));
    for (var i = 0; i < 3; i++) {
      final p = (t + i / 3) % 1.0;
      canvas.drawCircle(
        Offset(cx - 36 + p * 36, top - 20 + p * 72),
        2.8 + p * 4,
        _fill(0.45 + p * 0.55),
      );
    }
  }

  void _paintRlhf(Canvas canvas, Size size) {
    _creature(canvas, Offset(size.width * 0.34, size.height / 2));
    final plusActive = (t % 1.0) < 0.5;
    for (var i = 0; i < 2; i++) {
      final on = i == 0 ? plusActive : !plusActive;
      final rect = RRect.fromRectAndRadius(
        Rect.fromLTWH(size.width - 54, size.height / 2 - 31 + i * 34, 46, 27),
        const Radius.circular(6),
      );
      if (on) canvas.drawRRect(rect, _fill(0.18));
      canvas.drawRRect(rect, _stroke(on ? 1.0 : 0.4));
      _label(
        canvas,
        i == 0 ? '+' : '−',
        Offset(size.width - 31, size.height / 2 - 18 + i * 34),
        textColor: color.withValues(alpha: on ? 1.0 : 0.55),
        size: 13,
        bold: true,
      );
    }
  }

  void _paintDistillation(Canvas canvas, Size size) {
    final cy = size.height / 2;
    final teacherX = size.width * 0.16;
    for (var r = 0; r < 3; r++) {
      for (var c = 0; c < 2; c++) {
        canvas.drawCircle(
          Offset(teacherX + c * 17, cy - 18 + r * 18),
          5,
          _fill(0.9),
        );
      }
    }
    final studentX = size.width * 0.84;
    canvas.drawCircle(Offset(studentX, cy - 13), 6.5, _fill(0.9));
    canvas.drawCircle(Offset(studentX, cy + 15), 6.5, _fill(0.9));
    final from = teacherX + 26;
    final to = studentX - 14;
    canvas.drawLine(Offset(from, cy), Offset(to, cy), _stroke(0.45));
    canvas.drawCircle(Offset(from + (to - from) * (t % 1.0), cy), 4, _fill());
  }

  void _paintRag(Canvas canvas, Size size) {
    final cy = size.height / 2;
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        Rect.fromLTWH(6, cy - 26, 40, 52),
        const Radius.circular(4),
      ),
      _stroke(0.8),
    );
    for (var i = 0; i < 4; i++) {
      canvas.drawLine(
        Offset(13, cy - 15 + i * 10),
        Offset(39, cy - 15 + i * 10),
        _stroke(0.3, 1.0),
      );
    }
    final dbX = size.width * 0.55;
    for (var i = 0; i < 3; i++) {
      canvas.drawOval(
        Rect.fromCenter(
          center: Offset(dbX, cy - 15 + i * 15),
          width: 54,
          height: 18,
        ),
        _stroke(0.7),
      );
    }
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        Rect.fromLTWH(size.width - 32, cy - 26, 28, 52),
        const Radius.circular(12),
      ),
      _stroke(0.8),
    );
    final p = t % 1.0;
    final pos = p < 0.5
        ? Offset.lerp(Offset(50, cy), Offset(dbX - 28, cy), p / 0.5)!
        : Offset.lerp(
            Offset(dbX + 28, cy),
            Offset(size.width - 36, cy),
            (p - 0.5) / 0.5,
          )!;
    canvas.drawCircle(pos, 3.5, _fill());
  }

  void _paintChainOfThought(Canvas canvas, Size size) {
    final cy = size.height / 2;
    final active = (t * 4).floor() % 4;
    final startX = size.width - 3 * 36 - 18;
    for (var i = 0; i < 4; i++) {
      final center = Offset(startX + i * 36, cy);
      final on = i == active;
      if (on) canvas.drawCircle(center, 13, _fill(0.16));
      canvas.drawCircle(center, on ? 13 : 11, _stroke(on ? 1.0 : 0.45));
      _label(
        canvas,
        '${i + 1}',
        center,
        textColor: color.withValues(alpha: on ? 1.0 : 0.55),
        size: 10,
        bold: on,
      );
      if (i < 3) {
        canvas.drawLine(
          Offset(center.dx + 13, cy),
          Offset(center.dx + 23, cy),
          _stroke(0.35),
        );
      }
    }
  }

  void _paintWeights(Canvas canvas, Size size) {
    const layout = <Offset>[
      Offset(0.08, 0.26),
      Offset(0.44, 0.12),
      Offset(0.92, 0.22),
      Offset(0.08, 0.78),
      Offset(0.5, 0.9),
      Offset(0.94, 0.74),
    ];
    final nodes = [
      for (final p in layout) Offset(p.dx * size.width, p.dy * size.height),
    ];
    const edges = <List<int>>[
      [0, 1],
      [1, 2],
      [0, 4],
      [1, 4],
      [2, 5],
      [3, 4],
      [4, 5],
      [3, 1],
      [0, 3],
      [2, 4],
    ];
    for (var i = 0; i < edges.length; i++) {
      final phase = (t + i / edges.length) % 1.0;
      final wave = 0.5 + 0.5 * math.sin(phase * math.pi * 2);
      canvas.drawLine(
        nodes[edges[i][0]],
        nodes[edges[i][1]],
        _stroke(0.12 + 0.38 * wave, 1.0),
      );
    }
    for (var i = 0; i < nodes.length; i++) {
      final pulse = 0.5 + 0.5 * math.sin((t + i / nodes.length) * math.pi * 2);
      canvas.drawCircle(nodes[i], 4 + pulse * 2, _fill(0.85));
    }
  }

  void _paintValidationLoss(Canvas canvas, Size size) {
    const left = 14.0;
    const top = 12.0;
    final right = size.width - 8;
    final bottom = size.height - 12;
    canvas.drawLine(
      const Offset(left, top),
      Offset(left, bottom),
      _stroke(0.45, 1.0),
    );
    canvas.drawLine(
      Offset(left, bottom),
      Offset(right, bottom),
      _stroke(0.45, 1.0),
    );
    double yAt(double u) =>
        top +
        (bottom - top) *
            (0.08 + 0.74 * (1 - math.exp(-2.9 * u)) + 0.028 * math.sin(u * 13));
    final curve = Path()..moveTo(left, yAt(0));
    for (var i = 1; i <= 64; i++) {
      final u = i / 64;
      curve.lineTo(left + (right - left) * u, yAt(u));
    }
    canvas.drawPath(curve, _stroke(0.9));
    final u = t % 1.0;
    canvas.drawCircle(
      Offset(left + (right - left) * u, yAt(u)),
      4.5,
      _fill(0.95),
    );
  }

  void _paintCodingAgent(Canvas canvas, Size size) {
    _creature(canvas, Offset(size.width * 0.17, size.height / 2));
    final panelLeft = size.width * 0.38;
    final panelWidth = size.width - panelLeft - 6;
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        Rect.fromLTWH(panelLeft, size.height / 2 - 30, panelWidth, 60),
        const Radius.circular(6),
      ),
      _stroke(0.75),
    );
    const rowCount = 5;
    final typed = (t * rowCount) % rowCount;
    for (var i = 0; i < rowCount; i++) {
      if (i > typed) continue;
      final ratio = 0.45 + 0.5 * math.sin(i * 2.1).abs();
      final y = size.height / 2 - 19 + i * 10.5;
      canvas.drawLine(
        Offset(panelLeft + 11, y),
        Offset(panelLeft + 11 + (panelWidth - 22) * ratio, y),
        _stroke(0.5, 1.6),
      );
    }
  }

  @override
  bool shouldRepaint(covariant _TermGlyphPainter old) =>
      old.t != t || old.glyph != glyph || old.color != color;
}

// ---------------------------------------------------------------------------
// RAG VISUAL LAB - ten production CT246 routes and their shared five-stage
// pipeline. The screen never infers readiness from its own constants: live
// labels come only from /rag/status, and every Run action calls /rag/query.
// ---------------------------------------------------------------------------

enum _RagView { strategies, pipeline }

