class _RagVisualLab extends StatefulWidget {
  const _RagVisualLab({required this.onOpenSurface});

  final ValueChanged<String> onOpenSurface;

  @override
  State<_RagVisualLab> createState() => _RagVisualLabState();
}

class _RagVisualLabState extends State<_RagVisualLab>
    with SingleTickerProviderStateMixin {
  final _queryController = TextEditingController(
    text: 'How does CT246 connect Engel AI Main, memory, and worker devices?',
  );
  final _modalContextController = TextEditingController();

  late final AnimationController _animation = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 6),
  )..repeat();

  _RagView _view = _RagView.strategies;
  var _selectedIndex = 0;
  var _topK = 4;
  var _statusLoading = false;
  var _running = false;
  var _statusError = '';
  var _runError = '';
  Map<String, dynamic>? _status;
  Map<String, dynamic>? _result;

  _RagStrategy get _selected => _ragStrategies[_selectedIndex];

  bool get _productionReady =>
      _status?['ok'] == true && _status?['production_route_count'] == 10;

  @override
  void initState() {
    super.initState();
    unawaited(_refreshStatus());
  }

  @override
  void dispose() {
    _animation.dispose();
    _queryController.dispose();
    _modalContextController.dispose();
    super.dispose();
  }

  Future<Map<String, dynamic>> _getJson(String url) async {
    final client = HttpClient()
      ..connectionTimeout = const Duration(seconds: 4)
      ..idleTimeout = const Duration(seconds: 8);
    try {
      final request = await client.getUrl(Uri.parse(url));
      request.headers.set(HttpHeaders.acceptHeader, 'application/json');
      final response = await request.close().timeout(
        const Duration(seconds: 8),
      );
      final body = await response.transform(utf8.decoder).join();
      final parsed = jsonDecode(body);
      if (parsed is! Map<String, dynamic>) {
        throw const FormatException(
          'RAG service returned a non-object payload',
        );
      }
      if (response.statusCode < 200 || response.statusCode >= 300) {
        throw HttpException(
          (parsed['status'] ?? parsed['error'] ?? 'RAG status failed')
              .toString(),
        );
      }
      return parsed;
    } finally {
      client.close(force: true);
    }
  }

  Future<Map<String, dynamic>> _postJson(
    String url,
    Map<String, dynamic> payload,
  ) async {
    final client = HttpClient()
      ..connectionTimeout = const Duration(seconds: 5)
      ..idleTimeout = const Duration(seconds: 45);
    try {
      final request = await client.postUrl(Uri.parse(url));
      request.headers.contentType = ContentType.json;
      request.headers.set(HttpHeaders.acceptHeader, 'application/json');
      request.write(jsonEncode(payload));
      final response = await request.close().timeout(
        const Duration(seconds: 50),
      );
      final body = await response.transform(utf8.decoder).join();
      final parsed = jsonDecode(body);
      if (parsed is! Map<String, dynamic>) {
        throw const FormatException(
          'RAG service returned a non-object payload',
        );
      }
      if (response.statusCode < 200 || response.statusCode >= 300) {
        throw HttpException(
          (parsed['status'] ?? parsed['error'] ?? 'RAG route failed')
              .toString(),
        );
      }
      return parsed;
    } finally {
      client.close(force: true);
    }
  }

  Future<void> _refreshStatus() async {
    if (_statusLoading) return;
    setState(() {
      _statusLoading = true;
      _statusError = '';
    });
    try {
      final payload = await _getJson(engelMainRagStatusUrl);
      if (!mounted) return;
      setState(() => _status = payload);
    } catch (error) {
      if (!mounted) return;
      setState(() => _statusError = error.toString());
    } finally {
      if (mounted) setState(() => _statusLoading = false);
    }
  }

  Future<void> _runSelected() async {
    final query = _queryController.text.trim();
    if (query.length < 3 || _running) {
      if (query.length < 3) {
        setState(() => _runError = 'Enter at least three characters.');
      }
      return;
    }
    setState(() {
      _running = true;
      _runError = '';
      _result = null;
    });
    try {
      final payload = await _postJson(engelMainRagQueryUrl, {
        'query': query,
        'strategy': _selected.id,
        'top_k': _topK,
        'modal_context': _selected.id == 'multimodal'
            ? _modalContextController.text.trim()
            : '',
      });
      if (!mounted) return;
      setState(() => _result = payload);
      unawaited(_refreshStatus());
    } catch (error) {
      if (!mounted) return;
      setState(() => _runError = error.toString());
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  bool _routeReportedLive(String id) {
    final raw = _status?['strategies'];
    if (raw is! List) return false;
    for (final item in raw) {
      if (item is Map &&
          item['id']?.toString() == id &&
          item['support']?.toString() == 'live') {
        return _productionReady;
      }
    }
    return false;
  }

