  String _ragRouteProofSummary(Map<String, dynamic> meta) {
    final queries = meta['route_queries'] is List
        ? (meta['route_queries'] as List).length
        : 0;
    final steps = meta['local_model_steps'] is List
        ? (meta['local_model_steps'] as List).join(', ')
        : '';
    final graph = meta['graph'] is Map ? meta['graph'] as Map : const {};
    final edges = graph['edges'] is List ? (graph['edges'] as List).length : 0;
    return [
      '$queries retrieval ${queries == 1 ? 'query' : 'queries'}',
      if (steps.isNotEmpty) 'local steps: $steps',
      if (edges > 0) '$edges graph edges',
      if (meta['correction_applied'] == true) 'corrective retry applied',
      if (meta['modal_context_present'] == true) 'media context hashed',
    ].join(' / ');
  }

  Widget _pipelineView() {
    final raw = _status?['pipeline'];
    final liveStages = raw is List
        ? [
            for (final item in raw)
              if (item is Map) Map<String, dynamic>.from(item),
          ]
        : <Map<String, dynamic>>[];
    const fallbackStages = [
      {
        'id': 'ingest',
        'label': 'INGEST',
        'status': 'unverified',
        'detail': 'CT246 source intake',
      },
      {
        'id': 'embed',
        'label': 'EMBED',
        'status': 'unverified',
        'detail': 'semantic vectors',
      },
      {
        'id': 'retrieve',
        'label': 'RETRIEVE',
        'status': 'unverified',
        'detail': 'strategy route',
      },
      {
        'id': 'rerank',
        'label': 'RERANK',
        'status': 'unverified',
        'detail': 'evidence ordering',
      },
      {
        'id': 'generate',
        'label': 'GENERATE',
        'status': 'unverified',
        'detail': 'local cited answer',
      },
    ];
    final stages = liveStages.length == 5 ? liveStages : fallbackStages;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Container(
          constraints: const BoxConstraints(minHeight: 240),
          decoration: BoxDecoration(
            color: const Color(0xff07080b),
            border: Border.all(color: const Color(0xff343847)),
            borderRadius: BorderRadius.circular(8),
          ),
          child: AnimatedBuilder(
            animation: _animation,
            builder: (context, _) => CustomPaint(
              key: const Key('rag-pipeline-canvas'),
              painter: _RagPipelinePainter(
                t: _animation.value,
                allLive: _productionReady,
              ),
              child: const SizedBox(height: 240),
            ),
          ),
        ),
        const SizedBox(height: 14),
        LayoutBuilder(
          builder: (context, box) {
            const gap = 10.0;
            final columns = box.maxWidth >= 900
                ? 5
                : box.maxWidth >= 560
                ? 2
                : 1;
            final width = (box.maxWidth - gap * (columns - 1)) / columns;
            return Wrap(
              spacing: gap,
              runSpacing: gap,
              children: [
                for (var index = 0; index < stages.length; index++)
                  SizedBox(
                    width: width,
                    child: _RagPipelineStage(
                      key: Key('rag-pipeline-${stages[index]['id'] ?? index}'),
                      number: '${index + 1}'.padLeft(2, '0'),
                      label: (stages[index]['label'] ?? '').toString(),
                      detail: (stages[index]['detail'] ?? '').toString(),
                      live: stages[index]['status'] == 'live',
                      color: _ragStrategies[index * 2].color,
                    ),
                  ),
              ],
            );
          },
        ),
        const SizedBox(height: 18),
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: [
            OutlinedButton.icon(
              onPressed: () => widget.onOpenSurface('memory_guard'),
              icon: const Icon(Icons.shield_outlined, size: 17),
              label: const Text('Memory Guard'),
            ),
            OutlinedButton.icon(
              onPressed: () => widget.onOpenSurface('local_llm'),
              icon: const Icon(Icons.memory, size: 17),
              label: const Text('Local LLM'),
            ),
          ],
        ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(18, 24, 18, 30),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            _header(),
            const SizedBox(height: 24),
            if (_view == _RagView.strategies) ...[
              LayoutBuilder(
                builder: (context, box) => _strategyGrid(box.maxWidth),
              ),
              const SizedBox(height: 18),
              _routeDetail(),
            ] else
              _pipelineView(),
          ],
        ),
      ),
    );
  }
}

