              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: Text(
                            strategy.title,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              color: Color(0xfff0f0f3),
                              fontSize: 14,
                              fontFamily: 'Consolas',
                              fontWeight: FontWeight.w800,
                              letterSpacing: 0,
                            ),
                          ),
                        ),
                        Container(
                          width: 7,
                          height: 7,
                          decoration: BoxDecoration(
                            color: live
                                ? _aiTermGreen
                                : const Color(0xff515666),
                            shape: BoxShape.circle,
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 4),
                    Text(
                      strategy.subtitle.toUpperCase(),
                      style: TextStyle(
                        color: strategy.color.withValues(alpha: 0.8),
                        fontSize: 9.5,
                        fontFamily: 'Consolas',
                        fontWeight: FontWeight.w700,
                        letterSpacing: 0,
                      ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      strategy.useCase,
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: Color(0xff858998),
                        fontSize: 10.5,
                        height: 1.25,
                        letterSpacing: 0,
                      ),
                    ),
                    const Spacer(),
                    SizedBox(
                      height: 61,
                      child: AnimatedBuilder(
                        animation: animation,
                        builder: (context, _) => CustomPaint(
                          painter: _RagStrategyPainter(
                            strategy: strategy.id,
                            color: strategy.color,
                            t: animation.value,
                          ),
                          child: const SizedBox.expand(),
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

