class _RagStrategyPainter extends CustomPainter {
  const _RagStrategyPainter({
    required this.strategy,
    required this.color,
    required this.t,
  });

  final String strategy;
  final Color color;
  final double t;

  Paint _stroke([double alpha = 0.7, double width = 1.2]) => Paint()
    ..style = PaintingStyle.stroke
    ..strokeWidth = width
    ..color = color.withValues(alpha: alpha.clamp(0, 1));

  Paint _fill([double alpha = 0.9]) => Paint()
    ..style = PaintingStyle.fill
    ..color = color.withValues(alpha: alpha.clamp(0, 1));

  void _node(Canvas canvas, Offset point, {double radius = 5}) {
    canvas.drawCircle(point, radius, _fill(0.85));
    canvas.drawCircle(point, radius + 3, _stroke(0.2));
  }

  void _line(Canvas canvas, Offset a, Offset b, [double alpha = 0.42]) {
    canvas.drawLine(a, b, _stroke(alpha));
  }

  void _box(Canvas canvas, Rect rect, [double alpha = 0.65]) {
    canvas.drawRRect(
      RRect.fromRectAndRadius(rect, const Radius.circular(5)),
      _stroke(alpha),
    );
  }

  void _travel(Canvas canvas, Offset a, Offset b, [double phase = 0]) {
    final p = (t + phase) % 1;
    canvas.drawCircle(Offset.lerp(a, b, p)!, 3, _fill());
  }

  void _label(Canvas canvas, String value, Offset center) {
    final painter = TextPainter(
      text: TextSpan(
        text: value,
        style: TextStyle(
          color: color.withValues(alpha: 0.8),
          fontSize: 8,
          fontFamily: 'Consolas',
          fontWeight: FontWeight.w700,
          letterSpacing: 0,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    painter.paint(
      canvas,
      center - Offset(painter.width / 2, painter.height / 2),
    );
  }

  @override
  void paint(Canvas canvas, Size size) {
    final cy = size.height / 2;
    final left = Offset(14, cy);
    final right = Offset(size.width - 14, cy);
    switch (strategy) {
      case 'simple':
        _box(canvas, Rect.fromCenter(center: left, width: 24, height: 24));
        _box(
          canvas,
          Rect.fromCenter(
            center: Offset(size.width / 2, cy),
            width: 32,
            height: 42,
          ),
        );
        _node(canvas, right, radius: 7);
        _line(canvas, Offset(27, cy), Offset(size.width / 2 - 17, cy));
        _line(
          canvas,
          Offset(size.width / 2 + 17, cy),
          Offset(right.dx - 8, cy),
        );
        _label(canvas, '?', left);
        _label(canvas, 'OK', right);
        _travel(canvas, Offset(27, cy), Offset(size.width / 2 - 17, cy));
      case 'memory':
        _box(canvas, Rect.fromCenter(center: left, width: 30, height: 25));
        for (var i = 0; i < 3; i++) {
          canvas.drawOval(
            Rect.fromCenter(
              center: Offset(size.width / 2, cy - 9 + i * 9),
              width: 38,
              height: 12,
            ),
            _stroke(0.5),
          );
        }
        _box(canvas, Rect.fromCenter(center: right, width: 27, height: 29));
        _line(canvas, Offset(30, cy), Offset(size.width / 2 - 20, cy));
        _line(
          canvas,
          Offset(size.width / 2 + 20, cy),
          Offset(right.dx - 15, cy),
        );
        _travel(
          canvas,
          Offset(size.width / 2 + 20, cy),
          Offset(right.dx - 15, cy),
        );
        _label(canvas, '...', left);
        _label(canvas, 'A', right);
      case 'multi_query':
        _node(canvas, left, radius: 7);
        _node(canvas, right, radius: 7);
        final mids = [
          Offset(size.width / 2, cy - 22),
          Offset(size.width / 2, cy),
          Offset(size.width / 2, cy + 22),
        ];
        for (var i = 0; i < mids.length; i++) {
          _node(canvas, mids[i], radius: 4);
          _line(canvas, left, mids[i]);
          _line(canvas, mids[i], right);
          _travel(canvas, left, mids[i], i / 3);
        }
      case 'hyde':
        _node(canvas, left, radius: 7);
        _box(
          canvas,
          Rect.fromCenter(
            center: Offset(size.width * 0.43, cy),
            width: 34,
            height: 40,
          ),
        );
        _node(canvas, Offset(size.width * 0.72, cy), radius: 8);
        _node(canvas, right, radius: 6);
        _line(canvas, Offset(22, cy), Offset(size.width * 0.43 - 18, cy));
        _line(
          canvas,
          Offset(size.width * 0.43 + 18, cy),
          Offset(size.width * 0.72 - 9, cy),
        );
        _line(
          canvas,
          Offset(size.width * 0.72 + 9, cy),
          Offset(right.dx - 7, cy),
        );
        _travel(
          canvas,
          Offset(size.width * 0.43 + 18, cy),
          Offset(size.width * 0.72 - 9, cy),
        );
        _label(canvas, 'H', Offset(size.width * 0.43, cy));
      case 'adaptive':
        final center = Offset(size.width * 0.33, cy);
        final diamond = Path()
          ..moveTo(center.dx, cy - 16)
          ..lineTo(center.dx + 18, cy)
          ..lineTo(center.dx, cy + 16)
          ..lineTo(center.dx - 18, cy)
          ..close();
        canvas.drawPath(diamond, _stroke(0.8));
        final targets = [
          Offset(size.width * 0.78, cy - 22),
          Offset(size.width * 0.78, cy),
          Offset(size.width * 0.78, cy + 22),
        ];
        for (var i = 0; i < targets.length; i++) {
          _node(canvas, targets[i], radius: 5);
          _line(canvas, Offset(center.dx + 18, cy), targets[i]);
        }
        _travel(
          canvas,
          Offset(center.dx + 18, cy),
          targets[(t * 3).floor() % 3],
        );
      case 'corrective':
        _box(
          canvas,
          Rect.fromCenter(
            center: Offset(size.width * 0.28, cy),
            width: 34,
            height: 43,
          ),
        );
        final cross = Offset(size.width * 0.58, cy);
        canvas.drawLine(
          cross - const Offset(7, 7),
          cross + const Offset(7, 7),
          _stroke(0.9, 2),
        );
        canvas.drawLine(
          cross + const Offset(-7, 7),
          cross + const Offset(7, -7),
          _stroke(0.9, 2),
        );
        _node(canvas, right, radius: 7);
        _line(
          canvas,
          Offset(size.width * 0.3, cy + 23),
          Offset(size.width * 0.3, cy + 28),
        );
        _line(
          canvas,
          Offset(size.width * 0.3, cy + 28),
          Offset(size.width * 0.82, cy + 28),
        );
        _line(
          canvas,
          Offset(size.width * 0.82, cy + 28),
          Offset(size.width * 0.82, cy + 8),
        );
        _line(
          canvas,
          Offset(size.width * 0.3 + 18, cy),
          Offset(cross.dx - 9, cy),
        );
        _line(canvas, Offset(cross.dx + 9, cy), Offset(right.dx - 8, cy));
        _travel(
          canvas,
          Offset(size.width * 0.3, cy + 28),
          Offset(size.width * 0.82, cy + 28),
        );
      case 'self_rag':
        _box(
          canvas,
          Rect.fromCenter(
            center: Offset(size.width * 0.35, cy),
            width: 38,
            height: 46,
          ),
        );
        _box(
          canvas,
          Rect.fromCenter(
            center: Offset(size.width * 0.72, cy),
            width: 48,
            height: 48,
          ),
        );
        for (var i = 0; i < 3; i++) {
          final y = cy - 13 + i * 13;
          canvas.drawCircle(Offset(size.width * 0.63, y), 2.5, _fill());
          _line(
            canvas,
            Offset(size.width * 0.66, y),
            Offset(size.width * 0.82, y),
            0.5,
          );
        }
        _line(
          canvas,
          Offset(size.width * 0.35 + 20, cy),
          Offset(size.width * 0.72 - 25, cy),
        );
        _travel(
          canvas,
          Offset(size.width * 0.35 + 20, cy),
          Offset(size.width * 0.72 - 25, cy),
        );
      case 'agentic':
        final center = Offset(size.width / 2, cy);
        _box(
          canvas,
          Rect.fromCenter(center: center, width: 38, height: 34),
          0.85,
        );
        final nodes = [
          Offset(center.dx, cy - 28),
          Offset(center.dx, cy + 28),
          Offset(center.dx - 54, cy),
          Offset(center.dx + 54, cy),
        ];
        for (var i = 0; i < nodes.length; i++) {
          _node(canvas, nodes[i], radius: 5);
          _line(canvas, center, nodes[i]);
          _travel(canvas, center, nodes[i], i / 4);
        }
      case 'multimodal':
        final sources = [
          Offset(size.width * 0.18, cy - 19),
          Offset(size.width * 0.18, cy),
          Offset(size.width * 0.18, cy + 19),
        ];
        final merge = Offset(size.width * 0.6, cy);
        for (var i = 0; i < sources.length; i++) {
          _box(
            canvas,
            Rect.fromCenter(center: sources[i], width: 24, height: 15),
          );
          _line(canvas, Offset(sources[i].dx + 13, sources[i].dy), merge);
          _travel(
            canvas,
            Offset(sources[i].dx + 13, sources[i].dy),
            merge,
            i / 3,
          );
        }
        _node(canvas, merge, radius: 9);
        _node(canvas, right, radius: 7);
        _line(canvas, Offset(merge.dx + 10, cy), Offset(right.dx - 8, cy));
      case 'graph':
        final nodes = [
          Offset(size.width * 0.16, cy - 17),
          Offset(size.width * 0.16, cy + 18),
          Offset(size.width * 0.46, cy),
          Offset(size.width * 0.72, cy - 20),
          Offset(size.width * 0.84, cy + 17),
        ];
        const edges = [
          [0, 2],
          [1, 2],
          [2, 3],
          [2, 4],
          [3, 4],
        ];
        for (var i = 0; i < edges.length; i++) {
          _line(canvas, nodes[edges[i][0]], nodes[edges[i][1]]);
          _travel(
            canvas,
            nodes[edges[i][0]],
            nodes[edges[i][1]],
            i / edges.length,
          );
        }
        for (final node in nodes) {
          _node(canvas, node, radius: 5);
        }
    }
  }

  @override
  bool shouldRepaint(covariant _RagStrategyPainter oldDelegate) =>
      oldDelegate.t != t ||
      oldDelegate.strategy != strategy ||
      oldDelegate.color != color;
}

class _RagPipelinePainter extends CustomPainter {
  const _RagPipelinePainter({required this.t, required this.allLive});

  final double t;
  final bool allLive;

  @override
  void paint(Canvas canvas, Size size) {
    const colors = [
      _aiTermGreen,
      _aiTermBlue,
      _aiTermTeal,
      _aiTermPurple,
      _aiTermOrange,
    ];
    const labels = ['INGEST', 'EMBED', 'RETRIEVE', 'RERANK', 'GENERATE'];
    final y = size.height * 0.5;
    final usable = size.width - 80;
    final nodes = [for (var i = 0; i < 5; i++) Offset(40 + usable * i / 4, y)];
    final linePaint = Paint()
      ..color = const Color(0xff3a3f50)
      ..strokeWidth = 1.5;
    for (var i = 0; i < nodes.length - 1; i++) {
      canvas.drawLine(
        nodes[i] + const Offset(23, 0),
        nodes[i + 1] - const Offset(23, 0),
        linePaint,
      );
    }
    for (var i = 0; i < nodes.length; i++) {
      final pulse = 0.5 + 0.5 * math.sin((t + i / 5) * math.pi * 2);
      final fill = Paint()
        ..color = colors[i].withValues(
          alpha: allLive ? 0.14 + pulse * 0.08 : 0.05,
        );
      final stroke = Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = allLive ? 1.7 : 1
        ..color = colors[i].withValues(alpha: allLive ? 0.9 : 0.35);
      canvas.drawCircle(nodes[i], 22, fill);
      canvas.drawCircle(nodes[i], 22, stroke);
      final number = TextPainter(
        text: TextSpan(
          text: '${i + 1}',
          style: TextStyle(
            color: colors[i].withValues(alpha: allLive ? 1 : 0.45),
            fontSize: 13,
            fontFamily: 'Consolas',
            fontWeight: FontWeight.w800,
          ),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      number.paint(
        canvas,
        nodes[i] - Offset(number.width / 2, number.height / 2),
      );
      final label = TextPainter(
        text: TextSpan(
          text: labels[i],
          style: const TextStyle(
            color: Color(0xffc6c8d0),
            fontSize: 9,
            fontFamily: 'Consolas',
            fontWeight: FontWeight.w700,
            letterSpacing: 0,
          ),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      label.paint(canvas, Offset(nodes[i].dx - label.width / 2, y + 35));
    }
    final progress = t * 4;
    final segment = progress.floor().clamp(0, 3);
    final local = progress - segment;
    final dot = Offset.lerp(nodes[segment], nodes[segment + 1], local)!;
    canvas.drawCircle(
      dot,
      4,
      Paint()..color = allLive ? colors[segment + 1] : const Color(0xff6b7080),
    );
    final answer = TextPainter(
      text: TextSpan(
        text: allLive ? 'CITED LOCAL ANSWER' : 'AWAITING CT246 PROOF',
        style: TextStyle(
          color: allLive ? _aiTermOrange : const Color(0xff777c8b),
          fontSize: 11,
          fontFamily: 'Consolas',
          fontWeight: FontWeight.w800,
          letterSpacing: 0,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    answer.paint(
      canvas,
      Offset(size.width / 2 - answer.width / 2, size.height - 43),
    );
  }

  @override
  bool shouldRepaint(covariant _RagPipelinePainter oldDelegate) =>
      oldDelegate.t != t || oldDelegate.allLive != allLive;
}
